// ── Mission Deck — backend ────────────────────────────────────────────────
// Single-file Node server (no framework). Sections are marked with `// ── Name ──`
// headers; the file is meant to be read top-to-bottom.
//
// Usage: node server.js [port]        (port arg is a fallback only — see PORT below)
// Test/embedded mode: NODE_ENV=test or COCKPIT_EMBEDDED=1.

// ── Load .env file (no dotenv dependency — plain fs parse) ──────────────────
// Reads key=value pairs from .env in the project root. Skips comments and
// empty lines. Does NOT override variables already set in the environment
// (so CI / shell exports take precedence).
(function loadDotEnv() {
  const envPath = require('path').join(__dirname, '.env');
  try {
    const lines = require('fs').readFileSync(envPath, 'utf8').split(/\r?\n/);
    for (const raw of lines) {
      const line = raw.trim();
      if (!line || line.startsWith('#')) continue;
      const eq = line.indexOf('=');
      if (eq < 1) continue;
      const key = line.slice(0, eq).trim();
      const val = line.slice(eq + 1).trim();
      if (!(key in process.env)) process.env[key] = val;
    }
  } catch { /* .env absent — fine */ }
})();

// Corporate SSL-inspection proxies (Zscaler, Netskope) re-sign HTTPS traffic
// with their own CA. Node rejects the proxy CA with UNABLE_TO_GET_ISSUER_CERT_LOCALLY.
// Preferred fix: NODE_EXTRA_CA_CERTS pointing at the proxy CA bundle.
// Escape hatch: VERIFY_SSL=false (or COCKPIT_SKIP_TLS_VERIFY=1) in .env.
if (process.env.COCKPIT_SKIP_TLS_VERIFY === '1'
    || /^(false|0|no)$/i.test(String(process.env.VERIFY_SSL || '').trim())) {
  process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';
  console.warn('[security] TLS certificate validation DISABLED (VERIFY_SSL=false) — prefer NODE_EXTRA_CA_CERTS');
}

// ── Timestamped console output ──────────────────────────────────────────────
// Prefix every console.log/warn/error with [HH:MM:SS] so all server logs
// have a consistent, grep-friendly timestamp.
{
  const _origLog = console.log.bind(console);
  const _origWarn = console.warn.bind(console);
  const _origErr = console.error.bind(console);
  const _ts = () => {
    const d = new Date();
    return `[${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}]`;
  };
  console.log = (...args) => _origLog(_ts(), ...args);
  console.warn = (...args) => _origWarn(_ts(), ...args);
  console.error = (...args) => _origErr(_ts(), ...args);
}

