// ── WebSocket (ws) + node-pty — Claude Terminal ──────────────────────────────
// Both deps are optional: the server boots normally if native bindings are
// missing. The upgrade handler refuses connections with HTTP 503 in that case.
let WebSocketServer = null;
try {
  WebSocketServer = require('ws').WebSocketServer;
} catch (_e) {
  console.warn('[claude-terminal] ws module not available — WebSocket terminal disabled');
}
const wss = WebSocketServer ? new WebSocketServer({ noServer: true }) : null;

let pty = null;
try {
  pty = require('node-pty');
} catch (_e) {
  console.warn('[claude-terminal] node-pty module not available — WebSocket terminal disabled');
}

/** Map of active PTY sessions keyed by sessionId string.
 * Each value is { pty, buffer, timer, ws, lastCols, lastRows }.
 * Access is restricted to browser connections from localhost (Origin check in
 * the upgrade handler). No persistence across server restarts. */
const _claudeTerminalSessions = new Map();

/** Ring buffer capacity in bytes — oldest chars are dropped when exceeded. */
const RING_BUFFER_CAP = 256 * 1024;

/** Grace period before a PTY is killed after the WS disconnects (ms). */
const GRACE_PERIOD_MS = 30 * 1000;

/** The Claude Code CLI binary. Windows ships a .cmd shim. */
const CLAUDE_CMD = process.platform === 'win32' ? 'claude.cmd' : 'claude';
// Which Claude CLI this machine really has. On Windows the npm distribution
// installs a `claude.cmd` shim, while the native installer drops a
// `claude.exe` and no shim at all, so a hardcoded `.cmd` reads a working
// native install as "not installed". `where` answers which one is on PATH: a
// `.exe` runs without a shell and a `.cmd` needs one (CVE-2024-27980) - and
// with a shell Node joins command and args UNQUOTED, which is why the shim is
// returned as the bare name and never as a path that could carry a space.
// Resolved per call, not at boot: the "Install" button in Tools can add
// the CLI while this process runs.
function _claudeCli() {
  if (process.platform !== 'win32') return { cmd: CLAUDE_CMD, shell: false };
  try {
    const r = spawnSync('where', ['claude'], { encoding: 'utf8', timeout: 5000 });
    const lines = String(r.stdout || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    const exe = lines.find(l => /\.exe$/i.test(l));
    if (exe) return { cmd: exe, shell: false };
  } catch (_e) { /* fall through to the shim */ }
  return { cmd: CLAUDE_CMD, shell: true };
}

function _generateClaudeTermSessionId() {
  return crypto.randomUUID ? crypto.randomUUID() : 'ct-' + Date.now() + '-' + Math.random().toString(36).slice(2, 10);
}

/**
 * Append a PTY output chunk to the session ring buffer. When the buffer exceeds
 * RING_BUFFER_CAP the oldest characters are dropped by slicing from the front.
 * xterm.js re-parses ANSI sequences correctly even when the buffer is sliced
 * mid-sequence, so losing colour on the oldest line is acceptable.
 */
function _appendToRing(session, chunk) {
  session.buffer += String(chunk);
  if (session.buffer.length > RING_BUFFER_CAP) {
    session.buffer = session.buffer.slice(session.buffer.length - RING_BUFFER_CAP);
  }
}

