// POST /api/data-tier-0/clear-dir - clears ONLY a leftover non-git directory
// from a failed clone (the `dir-exists` status). Never touches a working clone.
async function _repoClearDirRoute(d, req, res) {
  if (!checkOrigin(req, res)) return;
  return d.lockFn(() => withRepoFileLock(d.dir, res, async () => {
    const r = await _dataTier0ClearDirOp(d);
    return jsonResponse(res, 200, r);
  }));
}

async function handleDataTier0ClearDir(req, res) { return _repoClearDirRoute(DATA_REPOS[0], req, res); }

// POST /api/data-tier-0/clear-plaintext ("End of day") - empties d.plainDir
// once its content is fully covered by the encrypted mirror. The check and
// the delete both happen inside _repoClearPlaintextOp, under the SAME
// d.lockFn + withRepoFileLock pair as every other write route here - never
// split across two requests.
async function _repoClearPlaintextRoute(d, req, res) {
  if (!checkOrigin(req, res)) return;
  return d.lockFn(() => withRepoFileLock(d.dir, res, async () => {
    const r = await _repoClearPlaintextOp(d);
    return jsonResponse(res, 200, r);
  }));
}

async function handleDataTier0ClearPlaintext(req, res) { return _repoClearPlaintextRoute(DATA_REPOS[0], req, res); }

// -- Stage B: /api/data/<repoId>/<op> registry -------------------------------
// Backward-compat alias family over the 19 handlers above. repoId and op are
// NEVER concatenated into a filesystem path or a function name - both are
// looked up in a table, so an unknown value always ends in a 404 instead of
// touching disk. The 19 /api/data-tier-0/* arms below stay forever; this is
// the shape every future repo in DATA_REPOS reaches instead of getting its
// own 19 dispatch arms.
// `generic` is what decides whether an op serves a repoId other than
// data-tier-0, and it is an EXPLICIT per-row flag, never inferred: an op is
// generic only once its whole chain - the handler, the driver under it and
// every helper they call - reads the descriptor passed in rather than
// DATA_TIER_0_CFG/DATA_REPOS[0]. `repoHandler` is that descriptor-taking
// entry point; the `handler` next to it is the data-tier-0 wrapper the 19
// legacy /api/data-tier-0/* arms still dispatch to unchanged.
//
// The line is NOT read-vs-write, it is: does this op call `encryptFn`.
// encryptTree walks the PLAINTEXT tree and unlinks every `.enc` in the mirror
// it cannot find a plaintext source for - it has no destructive-ratio guard,
// unlike decryptTree - so running it against a source whose plaintext tree is
// empty or only half-decrypted deletes that source's whole mirror. That makes
// `local-changes` dangerous despite reading like a listing: it re-encrypts
// first, so `git status` on the mirror can see plaintext edits. data-tier-0
// cannot reach the empty-plaintext state because its plaintext directory IS
// the app's own working tree; an additional source has nothing but a
// successful decrypt filling its own.
//
// So `generic: true` marks exactly the ops that do not encrypt FOR A SOURCE
// THAT CANNOT PUSH: clone and clear-dir never encrypt at all, and pull's
// pre-encrypt is itself gated on _repoServesOperation(d, 'push-stream') - it
// exists to save unpushed local work, which a read-only source has none of.
// Everything else - pull-overwrite, local-changes, the conflict and rebase
// repairs - stays data-tier-0 only.
//
// `writable: true` marks push/push-stream, the two ops _repoServesOperation
// also opens for a non-data-tier-0 row when THAT row carries
// `pushEnabled: true` (see DATA_REPO_DEFS). Format is
// a property of the SOURCE, not of this table: `_repoEncrypt` reads
// `d.mirrorFormat` ('v1' or 'v2', the default) and picks the matching writer
// (encryptBufferV1/encryptBuffer) - see the block comment above
// DATA_REPO_DEFS.
//
// Adding a row here is therefore not a judgement call: follow every path the
// handler reaches (`grep -n encryptFn server.js`) and route it only if none
// of them encrypts for a source with canPush false.
const DATA_REPO_OPERATIONS = {
  'status': { method: 'GET', handler: handleDataTier0Status },
  'check-update': { method: 'GET', handler: handleDataTier0CheckUpdate },
  'pull-stream': { method: 'GET', handler: handleDataTier0PullStream, generic: true, repoHandler: _repoPullStreamRoute },
  'clone-stream': { method: 'GET', handler: handleDataTier0CloneStream, generic: true, repoHandler: _repoCloneStreamRoute },
  'clone': { method: 'POST', handler: handleDataTier0Clone, generic: true, repoHandler: _repoCloneRoute },
  'decrypt': { method: 'POST', handler: handleDataTier0Decrypt, generic: true, repoHandler: _repoDecryptRoute },
  'pull': { method: 'POST', handler: handleDataTier0Pull, generic: true, repoHandler: _repoPullRoute },
  'push': { method: 'POST', handler: handleDataTier0Push, writable: true, repoHandler: _repoPushRoute },
  'push-stream': { method: 'GET', handler: handleDataTier0PushStream, writable: true, repoHandler: _repoPushStreamRoute },
  'pull-overwrite-stream': { method: 'GET', handler: handleDataTier0PullOverwriteStream },
  'pull-overwrite': { method: 'POST', handler: handleDataTier0PullOverwrite },
  'local-changes': { method: 'GET', handler: handleDataTier0LocalChanges },
  'conflict-diff': { method: 'POST', handler: handleDataTier0ConflictDiff },
  'resolve-conflicts': { method: 'POST', handler: handleDataTier0ResolveConflicts },
  'write-resolved': { method: 'POST', handler: handleDataTier0WriteResolved },
  'discard-local-changes': { method: 'POST', handler: handleDataTier0DiscardLocalChanges },
  'rebase-abort': { method: 'POST', handler: handleDataTier0RebaseAbort },
  'recover-rebase': { method: 'POST', handler: handleDataTier0RecoverRebase },
  'repair-detached-head': { method: 'POST', handler: handleDataTier0RepairDetachedHead },
  // Encrypts nothing, but it only ever has work on a source whose pull
  // pre-encrypts (a push-enabled one) - so it is opened exactly where push is.
  'resolve-autostash': { method: 'POST', handler: handleDataTier0ResolveAutostash, writable: true, repoHandler: _repoResolveAutostashRoute },
  'clear-dir': { method: 'POST', handler: handleDataTier0ClearDir, generic: true, repoHandler: _repoClearDirRoute },
  // Never calls encryptFn - it only reads through plaintextAheadOfMirror and
  // unlinks plaintext (see _repoClearPlaintextOp), so it qualifies as generic
  // by the same test every other row here follows: does this op encrypt for a
  // source that cannot push. Destructiveness toward the plaintext tree is
  // guarded inside the op itself (wrapUpClearEligibility), not by this flag.
  'clear-plaintext': { method: 'POST', handler: handleDataTier0ClearPlaintext, generic: true, repoHandler: _repoClearPlaintextRoute },
};

const DATA_REPO_PATH_RE = /^\/api\/data\/([^/]+)\/([^/]+)$/;

/** @returns {{repoId: string, op: string}|null} null when the shape does not match. */
function _parseDataRepoPath(urlPath) {
  const m = DATA_REPO_PATH_RE.exec(urlPath);
  return m ? { repoId: m[1], op: m[2] } : null;
}

// GET/POST /api/data/<repoId>/<op> - table lookup, never a path join. `repoId`
// resolves through _findDataRepo to a DATA_REPOS descriptor or to a 404; `op`
// resolves through DATA_REPO_OPERATIONS, so neither string is ever
// concatenated into a filesystem path or a function name.
//
// For data-tier-0 every op dispatches to its original handler, unchanged. For
// any other repo the op must carry `generic: true`, and then it is
// `repoHandler` - the descriptor-taking driver - that runs, never the
// data-tier-0 wrapper. Dropping the descriptor here is what would silently
// pull or clone data-tier-0 under another source's name, so `repo` is passed
// explicitly rather than being reachable from a module-level default.
function handleDataRepoRoute(method, urlPath, req, res) {
  const parsed = _parseDataRepoPath(urlPath);
  const repo = parsed && _findDataRepo(parsed.repoId);
  if (!repo) {
    return jsonResponse(res, 404, { error: 'unknown-repo', message: 'Unknown data source.' });
  }
  if (parsed.op === 'status') {
    if (method !== 'GET') {
      return jsonResponse(res, 404, { error: 'unknown-operation', message: 'Unknown sync operation.' });
    }
    return dispatch(async (_req, res2) => {
      jsonResponse(res2, 200, await _repoStatusPayload(repo));
    }, req, res);
  }
  const opEntry = DATA_REPO_OPERATIONS[parsed.op];
  if (repo.id !== 'data-tier-0') {
    if (!opEntry || opEntry.method !== method || !_repoServesOperation(repo, parsed.op)) {
      return jsonResponse(res, 404, { error: 'unknown-operation', message: 'Unknown sync operation.' });
    }
    return dispatch((req2, res2) => opEntry.repoHandler(repo, req2, res2), req, res);
  }
  if (!opEntry || opEntry.method !== method) {
    return jsonResponse(res, 404, { error: 'unknown-operation', message: 'Unknown sync operation.' });
  }
  return dispatch(opEntry.handler, req, res);
}
// ── JSON self-heal ──────────────────────────────────────────────────────────
// A git autostash/merge race can leave a JSON file in the data repo with
// conflict markers or truncated content. Reading those crashes every consumer,
// so a startup scan restores the last good copy from git.

const JSON_HEAL_MAX_BYTES = 8 * 1024 * 1024;

function _isCorruptJson(text) {
  if (/^<{7} |^={7}$|^>{7} /m.test(text)) return 'conflict-markers';
  try { JSON.parse(text); return null; }
  catch { return 'parse-error'; }
}

// Walks the data repo (depth-limited) and restores every unparseable .json file
// from HEAD. Returns a summary; never throws.
async function _healSubRepoJson() {
  if (!dataTier0Exists()) return { scanned: 0, healed: 0, failed: 0 };
  let scanned = 0, healed = 0, failed = 0;
  const walk = (dir, depth) => {
    if (depth > 6) return [];
    let entries = [];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return []; }
    const out = [];
    for (const e of entries) {
      if (e.name === '.git' || e.name === 'node_modules') continue;
      const abs = path.join(dir, e.name);
      if (e.isDirectory()) out.push(...walk(abs, depth + 1));
      else if (e.isFile() && e.name.endsWith('.json')) out.push(abs);
    }
    return out;
  };

  for (const abs of walk(DATA_TIER_0_DIR, 0)) {
    let text;
    try {
      if (fs.statSync(abs).size > JSON_HEAL_MAX_BYTES) continue;
      text = fs.readFileSync(abs, 'utf8');
    } catch { continue; }
    scanned++;
    const reason = _isCorruptJson(text);
    if (!reason) continue;
    const rel = path.relative(DATA_TIER_0_DIR, abs).split(path.sep).join('/');
    const restore = await gitExecDataTier0(['checkout', 'HEAD', '--', rel]);
    if (restore.code === 0) {
      healed++;
      console.warn(`[json-guard] healed ${rel} (${reason}) from HEAD`);
    } else {
      failed++;
      console.warn(`[json-guard] could NOT heal ${rel} (${reason}):`, _redactGitStderr(restore.stderr));
    }
  }
  if (healed || failed) console.log(`[json-guard] scan: ${scanned} files, ${healed} healed, ${failed} failed`);
  return { scanned, healed, failed };
}

// ── Auto-sync background loop ───────────────────────────────────────────────
// Every AUTO_SYNC_INTERVAL_MIN: pull --rebase --autostash, and push when the
// working tree is dirty or local commits are ahead. Three separate timer
// signals on purpose — conflating them yields two live timer chains.
//   _autoSyncRunCycle    the cycle body; null means the loop was never started
//   _autoSyncTimer       a PENDING setTimeout handle, null while a cycle runs
//   _autoSyncRunning     true while a cycle is in flight
let _autoSyncTimer = null;
let _autoSyncRunCycle = null;
let _autoSyncRunning = false;
// True while the 30 s startup delay is pending. _rescheduleAutoSyncLoop must
// leave that timer alone: replacing it with a full period would postpone the
// FIRST cycle for a user who picks an interval right after boot.
let _autoSyncStartupPending = false;

async function _runAutoSyncCycle() {
  // Defence in depth: the gate lives here, not on _startAutoSyncLoop, so the
  // loop keeps ticking and picks up a hot-applied AUTO_SYNC_ENABLED=1.
  if (!isAutoSyncEnabled()) return { repo: DATA_TIER_0_NAME, skipped: 'auto-sync-disabled' };
  if (!dataTier0Exists()) return { repo: DATA_TIER_0_NAME, skipped: 'not-configured' };
  if (!DATA_TIER_0_TOKEN) return { repo: DATA_TIER_0_NAME, skipped: 'no-token' };
  // An "End of day" wrap-up emptied the plaintext tree on purpose - without
  // this gate every cycle would try to push an empty tree, encryptTree would
  // refuse encrypt-destructive, and the log would warn on a loop until the
  // morning decrypt clears the marker. No `error` key here on purpose:
  // _autoSyncTick only warns when a skip carries one (see that function).
  if (_dayCycleRead().repos?.['data-tier-0']) return { repo: DATA_TIER_0_NAME, skipped: 'wrapped-up' };

  // Non-blocking attempt: another process (a second server, or a manual sync in
  // flight) holds the lock. Auto-sync prefers to skip a cycle over waiting.
  const fileLock = await _acquireRepoFileLock(DATA_TIER_0_GIT_DIR, { maxWaitMs: 0 });
  if (!fileLock.ok) return { repo: DATA_TIER_0_NAME, skipped: 'locked-other-process' };

  try {
    return await withDataTierLock(async () => {
      // A previous cycle may have left a half-finished rebase wedged on disk.
      if (_isRebaseInProgress(DATA_TIER_0_GIT_DIR)) {
        await gitExecDataTier0(['rebase', '--abort']);
        console.warn('[auto-sync] aborted a stuck rebase before syncing');
      }
      const pull = await _dataTier0Pull();
      if (!pull.ok) return { repo: DATA_TIER_0_NAME, skipped: 'pull-error', error: pull.error };
      writeRefreshTimestamp('_data-tier-0-autopull');

      // Sampling `git status` BEFORE the pull was blind: the mirror is git's
      // only view of the data, and it is _repoPull's own `preEnc` step -
      // inside _dataTier0Pull, ahead of the fetch - that turns a plaintext-only
      // edit into a mirror-visible diff. A `git status` taken earlier than
      // that never sees a fresh edit in THIS cycle; it took a whole extra
      // interval to notice. Sampling here, after `--autostash` has restored
      // the working tree, sees the edit in the same cycle that pulled it.
      const statusResult = await gitExecDataTier0(['status', '--porcelain']);
      if (statusResult.code !== 0) return { repo: DATA_TIER_0_NAME, skipped: 'status-error' };
      const isDirty = statusResult.stdout.trim().length > 0;

      const { ahead } = await _dataTier0AheadBehind();
      if (!isDirty && ahead === 0) return { repo: DATA_TIER_0_NAME, result: 'pull' };

      const push = await _dataTier0Push();
      if (!push.ok) return { repo: DATA_TIER_0_NAME, skipped: 'push-error', error: push.error };
      writeRefreshTimestamp('_data-tier-0-autopush');

      const counts = _syncLogFileCount(statusResult.stdout);
      _syncLogAppend({
        user: _syncLogUser(), device_id: SYNC_DEVICE_ID, repo: DATA_TIER_0_NAME,
        action: 'push+pull', trigger: 'auto',
        ...counts, lines_added: 0, lines_removed: 0, files: [], commits: [],
        timestamp: new Date().toISOString(),
      });
      return { repo: DATA_TIER_0_NAME, result: 'push+pull' };
    });
  } finally {
    if (!fileLock.noop) _releaseRepoFileLock(DATA_TIER_0_GIT_DIR);
  }
}

async function _autoSyncTick() {
  _autoSyncStartupPending = false;
  _autoSyncRunning = true;
  _autoSyncTimer = null; // nothing pending while the cycle runs
  try {
    const r = await _autoSyncRunCycle();
    if (r && r.result) console.log('[auto-sync] cycle:', r.repo + '=' + r.result);
    else if (r && r.skipped && r.error) console.warn('[auto-sync] cycle:', r.repo + '=' + r.skipped, r.error);
  } catch (err) {
    console.warn('[auto-sync] cycle error:', err && err.message);
  } finally {
    // MUST be `finally`: a self-rescheduling setTimeout that never re-arms kills
    // auto-sync silently until the next server restart.
    _autoSyncRunning = false;
    // Re-read the period every tick so an interval change lands even without an
    // explicit reschedule.
    _autoSyncTimer = setTimeout(_autoSyncTick, autoSyncIntervalMs());
  }
}

// Re-arms the pending timer against the CURRENT autoSyncIntervalMs(). Called
// from handleSettingsEnvSave: without it a 60 -> 10 switch would still wait out
// the already-scheduled hour.
function _rescheduleAutoSyncLoop() {
  if (!_autoSyncRunCycle) return;       // loop never started - must not arm one here
  if (_autoSyncRunning) return;         // the tick's finally re-arms at the fresh period
  if (_autoSyncStartupPending) return;  // keep the short startup delay
  if (_autoSyncTimer === null) return;
  clearTimeout(_autoSyncTimer);
  _autoSyncTimer = setTimeout(_autoSyncTick, autoSyncIntervalMs());
}

// Starts the loop. The first run is delayed 30 s so it does not race the rest of
// server startup. Never started in test mode.
function _startAutoSyncLoop() {
  if (IS_TEST_MODE) return;
  _autoSyncRunCycle = _runAutoSyncCycle;
  _autoSyncStartupPending = true;
  _autoSyncTimer = setTimeout(_autoSyncTick, 30 * 1000);
}

// ── Confluence integration ──────────────────────────────────────────────────

/** Resolve the Confluence token + base URL from .env / process.env. */
function _confluenceConfig() {
  const { values: envValues } = readEnvFile();
  const token = resolveToken(envValues.get('CONFLUENCE_TOKEN') || process.env.CONFLUENCE_TOKEN || '');
  const baseUrl = (envValues.get('CONFLUENCE_BASE_URL') || process.env.CONFLUENCE_BASE_URL || 'https://confluence.example.com').replace(/\/$/, '');
  return { token, baseUrl };
}

// Accepts a bare page id, a /pages/<id> URL, or a ?pageId=<id> URL.
function _extractConfluencePageId(raw) {
  if (!raw) return raw;
  const urlPageMatch = String(raw).match(/\/pages\/(\d+)/);
  if (urlPageMatch) return urlPageMatch[1];
  const queryMatch = String(raw).match(/[?&]pageId=(\d+)/);
  if (queryMatch) return queryMatch[1];
  return String(raw);
}

// Sentinel thrown when Confluence is unreachable — almost always a VPN that is
// off. Without VPN the host either fails to connect, or an SSO/proxy returns an
// HTML interstitial that JSON.parse chokes on with a cryptic "Unexpected token
// '<'". Callers map this to a clear "turn on the VPN" message.
const CONFLUENCE_UNREACHABLE = 'confluence-unreachable';

/**
 * Fetch JSON from the Confluence REST API with VPN-aware error handling.
 * Throws Error(CONFLUENCE_UNREACHABLE) for network failures and HTML responses;
 * throws Error("Confluence HTTP <n>: ...") for real API errors.
 */
async function _confluenceFetchJson(url, token, timeoutMs, init) {
  let resp;
  try {
    resp = await fetch(url, {
      ...(init || {}),
      headers: { Authorization: `Bearer ${token}`, Accept: 'application/json', ...((init && init.headers) || {}) },
      signal: AbortSignal.timeout(timeoutMs),
    });
  } catch {
    // DNS unresolvable / connection refused / timeout — host unreachable.
    throw new Error(CONFLUENCE_UNREACHABLE);
  }
  const ctype = (resp.headers.get('content-type') || '').toLowerCase();
  // An HTML body (regardless of status) is the no-VPN SSO interstitial signature.
  if (ctype.includes('text/html')) throw new Error(CONFLUENCE_UNREACHABLE);
  if (!resp.ok) {
    let errMsg = `Confluence HTTP ${resp.status}`;
    try { errMsg += `: ${(await resp.text()).slice(0, 200)}`; } catch { /* ignore */ }
    const err = new Error(errMsg);
    err.status = resp.status;
    throw err;
  }
  try {
    return await resp.json();
  } catch {
    // 2xx but not JSON (captive portal without an HTML content-type) — same
    // connectivity failure.
    throw new Error(CONFLUENCE_UNREACHABLE);
  }
}

/** Page metadata only (version + space), for confluence-check. */
function _confluenceFetchMeta(baseUrl, token, pageId) {
  return _confluenceFetchJson(`${baseUrl}/rest/api/content/${encodeURIComponent(pageId)}?expand=version,history,space`, token, 20000);
}

/** Full page including the rendered body. */
function _confluenceFetchFull(baseUrl, token, pageId) {
  return _confluenceFetchJson(`${baseUrl}/rest/api/content/${encodeURIComponent(pageId)}?expand=body.export_view,version,history,space`, token, 30000);
}

/** Strip all HTML tags and decode the basic entities. */
function _stripHtmlTags(html) {
  if (!html) return '';
  return String(html).replace(/<[^>]*>/g, '')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ');
}

/** Convert inline HTML elements to Markdown. */
function _inlineHtmlToMd(html) {
  if (!html) return '';
  let s = String(html);
  s = s.replace(/<a[^>]+href=["']([^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi, (_m, href, inner) => {
    const text = _stripHtmlTags(inner).trim();
    return text ? `[${text}](${href})` : href;
  });
  s = s.replace(/<(?:strong|b)[^>]*>([\s\S]*?)<\/(?:strong|b)>/gi, (_m, inner) => `**${_stripHtmlTags(inner).trim()}**`);
  s = s.replace(/<(?:em|i)[^>]*>([\s\S]*?)<\/(?:em|i)>/gi, (_m, inner) => `_${_stripHtmlTags(inner).trim()}_`);
  s = s.replace(/<code[^>]*>([\s\S]*?)<\/code>/gi, (_m, inner) => '`' + _stripHtmlTags(inner) + '`');
  s = s.replace(/<br\s*\/?>/gi, '\n');
  return _stripHtmlTags(s);
}

/**
 * Minimal HTML -> Markdown converter for Confluence export_view HTML.
 * Handles headings, paragraphs, lists, tables, links, strong, em, code, pre;
 * strips macro placeholders and the auto-generated table of contents.
 */
function _confluenceHtmlToMd(html) {
  if (!html) return '';

  // Strip CDATA blocks (inline CSS injected by Confluence macros).
  let s = String(html).replace(/<!\[CDATA\[[\s\S]*?\]\]>/g, '');

  // Images: emit a marker for attachment images, drop everything else.
  s = s.replace(/<img[^>]+src=["']([^"']+)["'][^>]*>/gi, (_m, src) => {
    if (!/\/download\/(attachments|thumbnails)\//.test(src)) return '';
    // Confluence percent-encodes attachment filenames; decode so the marker is
    // human-readable.
    let fname = src.split('/').pop().split('?')[0];
    try { fname = decodeURIComponent(fname); } catch { /* malformed escape - keep raw */ }
    return `\n> [image: ${fname}](${src})\n\n`;
  });

  // Tables -> Markdown tables (row by row).
  s = s.replace(/<table[^>]*>([\s\S]*?)<\/table>/gi, (_m, inner) => {
    const rows = [];
    for (const row of inner.match(/<tr[^>]*>([\s\S]*?)<\/tr>/gi) || []) {
      const cells = [];
      const cellRe = /<t[dh][^>]*>([\s\S]*?)<\/t[dh]>/gi;
      let cm;
      while ((cm = cellRe.exec(row)) !== null) {
        cells.push(_stripHtmlTags(cm[1]).replace(/\|/g, '\\|').trim());
      }
      rows.push('| ' + cells.join(' | ') + ' |');
    }
    if (rows.length >= 2) {
      const cols = (rows[0].match(/\|/g) || []).length - 1;
      rows.splice(1, 0, '|' + ' --- |'.repeat(cols));
    }
    return '\n' + rows.join('\n') + '\n\n';
  });

  s = s.replace(/<pre[^>]*>([\s\S]*?)<\/pre>/gi, (_m, inner) => '\n```\n' + _stripHtmlTags(inner).trim() + '\n```\n\n');
  s = s.replace(/<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi, (_m, level, inner) => '\n' + '#'.repeat(Number(level)) + ' ' + _stripHtmlTags(inner).trim() + '\n\n');
  s = s.replace(/<p[^>]*>([\s\S]*?)<\/p>/gi, (_m, inner) => {
    const text = _inlineHtmlToMd(inner).trim();
    return text ? text + '\n\n' : '';
  });
  s = s.replace(/<ul[^>]*>([\s\S]*?)<\/ul>/gi, (_m, inner) => {
    const items = [];
    const liRe = /<li[^>]*>([\s\S]*?)<\/li>/gi;
    let lm;
    while ((lm = liRe.exec(inner)) !== null) items.push('- ' + _inlineHtmlToMd(lm[1]).trim());
    return '\n' + items.join('\n') + '\n\n';
  });
  s = s.replace(/<ol[^>]*>([\s\S]*?)<\/ol>/gi, (_m, inner) => {
    const items = [];
    const liRe = /<li[^>]*>([\s\S]*?)<\/li>/gi;
    let n = 1;
    let lm;
    while ((lm = liRe.exec(inner)) !== null) { items.push(`${n}. ` + _inlineHtmlToMd(lm[1]).trim()); n++; }
    return '\n' + items.join('\n') + '\n\n';
  });

  s = _inlineHtmlToMd(s);
  // Remove whitespace-only headings (anchor-only headings).
  s = s.replace(/^[ \t]*#{1,6}[ \t]*\n/gm, '');
  // Confluence ToC anchor-link lines (with or without a list prefix).
  s = s.replace(/(^|\n)[ \t]*-? ?\[[^\]]*\]\(#id-[^)]+\)[ \t]*/g, '$1');
  s = s.replace(/\n{3,}/g, '\n\n');
  return s.trim() + '\n';
}

// Escapes text for the Confluence storage format (XHTML).
function _confluenceEscapeXml(s) {
  return String(s || '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}

/**
 * GET /api/knowledge-base/confluence-configured
 */
function handleConfluenceConfigured(_req, res) {
  const { token, baseUrl } = _confluenceConfig();
  jsonResponse(res, 200, { configured: !!token, baseUrl });
}

/**
 * POST /api/knowledge-base/confluence-check
 * Body: { pages: ["12345", "https://.../pages/67890"] }
 * Response: { pages: [{ id, title, remoteVersion, updated, space, ok } | { id, ok:false, error }] }
 */
async function handleConfluenceCheck(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try { body = await readBody(req, 64 * 1024); } catch {
    return jsonResponse(res, 400, { error: 'bad-request', message: 'Invalid JSON' });
  }
  const { pages } = body || {};
  if (!Array.isArray(pages) || pages.length === 0) {
    return jsonResponse(res, 400, { error: 'bad-request', message: 'pages must be a non-empty array' });
  }
  const { token, baseUrl } = _confluenceConfig();
  if (!token) return jsonResponse(res, 200, { error: 'no-confluence-token', message: 'CONFLUENCE_TOKEN is missing' });

  const results = await Promise.all(pages.slice(0, 50).map(async (rawId) => {
    const id = _extractConfluencePageId(String(rawId).trim());
    try {
      const page = await _confluenceFetchMeta(baseUrl, token, id);
      return {
        id,
        title: page.title || null,
        remoteVersion: ((page.version || {}).number) || null,
        updated: ((page.version || {}).when || '').slice(0, 10) || null,
        space: ((page.space || {}).key) || null,
        ok: true,
      };
    } catch (e) {
      const unreachable = e.message === CONFLUENCE_UNREACHABLE;
      return { id, ok: false, unreachable, error: unreachable ? 'No connection to Confluence - check the VPN' : e.message };
    }
  }));

  // Every page failed because the host was unreachable -> one clear top-level
  // signal so the UI shows a VPN banner instead of N cryptic rows.
  if (results.length && results.every(r => r.unreachable)) {
    return jsonResponse(res, 200, {
      error: 'confluence-unreachable',
      message: 'No connection to Confluence. Turn on the VPN and try again.',
      pages: results,
    });
  }
  return jsonResponse(res, 200, { pages: results });
}

/**
 * POST /api/knowledge-base/confluence-fetch
 * Body: { pages: [...] }
 * Response: { pages: [{ id, title, remoteVersion, updated, contentMd, sourceUrl }] }
 */
async function handleConfluenceFetch(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try { body = await readBody(req, 64 * 1024); } catch {
    return jsonResponse(res, 400, { error: 'bad-request', message: 'Invalid JSON' });
  }
  const { pages } = body || {};
  if (!Array.isArray(pages) || pages.length === 0) {
    return jsonResponse(res, 400, { error: 'bad-request', message: 'pages must be a non-empty array' });
  }
  const { token, baseUrl } = _confluenceConfig();
  if (!token) return jsonResponse(res, 200, { error: 'no-confluence-token', message: 'CONFLUENCE_TOKEN is missing' });

  const results = await Promise.all(pages.slice(0, 20).map(async (rawId) => {
    const id = _extractConfluencePageId(String(rawId).trim());
    try {
      const page = await _confluenceFetchFull(baseUrl, token, id);
      return {
        id,
        title: page.title || null,
        remoteVersion: ((page.version || {}).number) || null,
        updated: ((page.version || {}).when || '').slice(0, 10) || null,
        contentMd: _confluenceHtmlToMd(((page.body || {}).export_view || {}).value || ''),
        sourceUrl: `${baseUrl}/pages/viewpage.action?pageId=${encodeURIComponent(id)}`,
      };
    } catch (e) {
      const unreachable = e.message === CONFLUENCE_UNREACHABLE;
      return { id, ok: false, unreachable, error: unreachable ? 'No connection to Confluence - check the VPN' : e.message };
    }
  }));

  if (results.length && results.every(r => r.unreachable)) {
    return jsonResponse(res, 200, {
      error: 'confluence-unreachable',
      message: 'No connection to Confluence. Turn on the VPN and try again.',
      pages: results,
    });
  }
  return jsonResponse(res, 200, { pages: results });
}

/**
 * POST /api/confluence/page — create a page.
 * Body: { spaceKey, title, body (storage XHTML or plain text), parentId? }
 */
async function handleConfluencePageCreate(req, res) {
  if (!checkOrigin(req, res)) return;
  let payload;
  try { payload = await readBody(req, 1024 * 1024); } catch {
    return jsonResponse(res, 400, { error: 'bad-request', message: 'Invalid JSON' });
  }
  const spaceKey = String((payload && payload.spaceKey) || '').trim();
  const title = String((payload && payload.title) || '').trim();
  const storage = typeof (payload && payload.body) === 'string' ? payload.body : '';
  const parentId = String((payload && payload.parentId) || '').trim();

  if (!spaceKey || !/^[A-Za-z0-9_~-]{1,64}$/.test(spaceKey)) {
    return jsonResponse(res, 400, { error: 'invalid_space_key' });
  }
  if (!title || title.length > 255) return jsonResponse(res, 400, { error: 'invalid_title' });
  if (!storage) return jsonResponse(res, 400, { error: 'invalid_body' });
  if (parentId && !/^\d+$/.test(parentId)) return jsonResponse(res, 400, { error: 'invalid_parent_id' });

  const { token, baseUrl } = _confluenceConfig();
  if (!token) return jsonResponse(res, 503, { error: 'token_missing', message: 'CONFLUENCE_TOKEN is missing' });

  const doc = {
    type: 'page',
    title,
    space: { key: spaceKey },
    body: { storage: { value: storage, representation: 'storage' } },
  };
  if (parentId) doc.ancestors = [{ id: parentId }];

  try {
    const created = await _confluenceFetchJson(`${baseUrl}/rest/api/content`, token, 30000, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(doc),
    });
    return jsonResponse(res, 200, {
      ok: true,
      id: created.id,
      title: created.title,
      version: ((created.version || {}).number) || 1,
      url: `${baseUrl}/pages/viewpage.action?pageId=${encodeURIComponent(created.id)}`,
    });
  } catch (e) {
    if (e.message === CONFLUENCE_UNREACHABLE) {
      return jsonResponse(res, 502, { error: 'confluence-unreachable', message: 'No connection to Confluence - check the VPN' });
    }
    return jsonResponse(res, e.status === 401 || e.status === 403 ? 503 : 502, { error: 'confluence_error', message: e.message });
  }
}

/**
 * PUT /api/confluence/page/:id — replace the storage body of an existing page.
 * Confluence requires the NEXT version number, so the current one is read first.
 * Body: { title?, body }
 */
async function handleConfluencePageUpdate(req, res, pageId) {
  if (!checkOrigin(req, res)) return;
  if (!/^\d+$/.test(String(pageId || ''))) return jsonResponse(res, 400, { error: 'invalid_page_id' });
  let payload;
  try { payload = await readBody(req, 1024 * 1024); } catch {
    return jsonResponse(res, 400, { error: 'bad-request', message: 'Invalid JSON' });
  }
  const storage = typeof (payload && payload.body) === 'string' ? payload.body : '';
  if (!storage) return jsonResponse(res, 400, { error: 'invalid_body' });

  const { token, baseUrl } = _confluenceConfig();
  if (!token) return jsonResponse(res, 503, { error: 'token_missing', message: 'CONFLUENCE_TOKEN is missing' });

  try {
    const current = await _confluenceFetchMeta(baseUrl, token, pageId);
    const nextVersion = (((current.version || {}).number) || 0) + 1;
    const title = String((payload && payload.title) || current.title || '').trim();
    if (!title || title.length > 255) return jsonResponse(res, 400, { error: 'invalid_title' });

    const updated = await _confluenceFetchJson(`${baseUrl}/rest/api/content/${encodeURIComponent(pageId)}`, token, 30000, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        id: String(pageId),
        type: 'page',
        title,
        version: { number: nextVersion },
        body: { storage: { value: storage, representation: 'storage' } },
      }),
    });
    return jsonResponse(res, 200, {
      ok: true,
      id: updated.id,
      title: updated.title,
      version: ((updated.version || {}).number) || nextVersion,
      url: `${baseUrl}/pages/viewpage.action?pageId=${encodeURIComponent(updated.id)}`,
    });
  } catch (e) {
    if (e.message === CONFLUENCE_UNREACHABLE) {
      return jsonResponse(res, 502, { error: 'confluence-unreachable', message: 'No connection to Confluence - check the VPN' });
    }
    if (e.status === 404) return jsonResponse(res, 404, { error: 'not_found' });
    return jsonResponse(res, e.status === 401 || e.status === 403 ? 503 : 502, { error: 'confluence_error', message: e.message });
  }
}

// ── Jira (write endpoints + single-issue read) ──────────────────────────────
// All requests go to JIRA_BASE_URL (one const — SRC repeated the literal 28x).
// Jira Server / Data Center REST v2 with a personal Bearer token.

const _JIRA_ISSUE_KEY_RE = /^[A-Z][A-Z0-9_]*-\d+$/;
const _JIRA_COMMENT_MAX_BODY_LEN = 32000;
const _JIRA_COMMENT_RATE_LIMIT_WINDOW_MS = 60000;
const _JIRA_COMMENT_RATE_LIMIT_MAX = 30;
// In-memory sliding window shared by every write endpoint (same Jira API).
let _jiraWriteRateLog = [];

function _jiraRateLimited(res) {
  const now = Date.now();
  _jiraWriteRateLog = _jiraWriteRateLog.filter(t => now - t < _JIRA_COMMENT_RATE_LIMIT_WINDOW_MS);
  if (_jiraWriteRateLog.length >= _JIRA_COMMENT_RATE_LIMIT_MAX) {
    jsonResponse(res, 429, { error: 'rate_limited', window_ms: _JIRA_COMMENT_RATE_LIMIT_WINDOW_MS });
    return true;
  }
  _jiraWriteRateLog.push(now);
  return false;
}

// Resolve the token: .env file first, then process.env (Bitwarden-loaded).
function _jiraToken() {
  const { values } = readEnvFile();
  return _resolveJiraToken(values);
}

function _jiraAuthHeaders() {
  return { 'Authorization': `Bearer ${_jiraToken()}`, 'Accept': 'application/json' };
}

// Maps a fetch/HTTP failure onto the shared error vocabulary the frontend knows.
function _jiraHttpError(res, status, text) {
  if (status === 401) return jsonResponse(res, 503, { error: 'token_missing' });
  if (status === 403) return jsonResponse(res, 503, { error: 'token_unauthorized' });
  if (status === 404) return jsonResponse(res, 404, { error: 'not_found' });
  return jsonResponse(res, 502, { error: 'jira_error', status, message: String(text || '').slice(0, 500) });
}

// ── GET /api/jira/whoami ────────────────────────────────────────────────────
// Connection test. Answers 4xx JSON WITHOUT any network call when no token is
// configured, so a fresh install never hangs on an unreachable corporate host.
async function handleJiraWhoami(_req, res) {
  const token = _jiraToken();
  if (!token) {
    return jsonResponse(res, 401, { ok: false, error: 'token_missing', url: JIRA_BASE_URL, message: 'Jira token is missing (JIRA_TOKEN or JIRA_TECH_TOKEN).' });
  }
  let r;
  try {
    r = await fetch(`${JIRA_BASE_URL}/rest/api/2/myself`, {
      headers: _jiraAuthHeaders(), signal: AbortSignal.timeout(15000),
    });
  } catch (err) {
    return jsonResponse(res, 502, { ok: false, error: 'jira_unreachable', url: JIRA_BASE_URL, message: String(err.message).slice(0, 200) });
  }
  if (r.status === 401) return jsonResponse(res, 401, { ok: false, error: 'token_invalid', url: JIRA_BASE_URL });
  if (r.status === 403) return jsonResponse(res, 403, { ok: false, error: 'token_unauthorized', url: JIRA_BASE_URL });
  if (!r.ok) return jsonResponse(res, 502, { ok: false, error: 'jira_error', status: r.status, url: JIRA_BASE_URL });
  let me;
  try { me = await r.json(); } catch { return jsonResponse(res, 502, { ok: false, error: 'jira_bad_response', url: JIRA_BASE_URL }); }
  return jsonResponse(res, 200, {
    ok: true,
    displayName: me.displayName || me.name || null,
    name: me.name || null,
    email: me.emailAddress || null,
    url: JIRA_BASE_URL,
  });
}

// ── GET /api/jira/issue-title?key= ──────────────────────────────────────────

const _jiraIssueTitleCache = new Map();
const JIT_CACHE_TTL_MS = 60000;

async function handleJiraIssueTitle(req, res) {
  const key = (new URL(req.url, 'http://localhost').searchParams.get('key') || '').trim().toUpperCase();
  if (!_JIRA_ISSUE_KEY_RE.test(key)) return jsonResponse(res, 400, { error: 'invalid_key' });

  const now = Date.now();
  const cached = _jiraIssueTitleCache.get(key);
  if (cached && (now - cached.ts) < JIT_CACHE_TTL_MS) {
    return jsonResponse(res, 200, { key, summary: cached.summary });
  }
  const token = _jiraToken();
  if (!token) return jsonResponse(res, 503, { error: 'token_missing' });

  let r;
  try {
    r = await fetch(`${JIRA_BASE_URL}/rest/api/2/issue/${encodeURIComponent(key)}?fields=summary`, {
      headers: _jiraAuthHeaders(), signal: AbortSignal.timeout(15000),
    });
  } catch (err) {
    return jsonResponse(res, 502, { error: 'jira_unreachable', message: String(err.message).slice(0, 200) });
  }
  // 404 is deliberately NOT cached — the issue may appear later.
  if (!r.ok) return _jiraHttpError(res, r.status, await r.text().catch(() => ''));

  let parsed;
  try { parsed = await r.json(); } catch { return jsonResponse(res, 502, { error: 'jira_bad_response' }); }
  const summary = parsed.fields?.summary || '';
  _jiraIssueTitleCache.set(key, { summary, ts: now });
  return jsonResponse(res, 200, { key, summary });
}

// ── GET /api/jira/issue-detail?key= ─────────────────────────────────────────
// Full single-issue read: fields, comments, worklogs, changelog.

const _JIRA_ISSUE_CACHE = new Map();
const _JIRA_ISSUE_CACHE_TTL_MS = 60000;
// Jira serializes the WHOLE changelog on `expand=changelog` (no paging on
// Data Center): a long-lived ticket with ~20k history entries (PROJ-8779,
// 8 MB) takes ~16 s cold, so a 20 s budget answered 502 for a real issue
// whenever Jira was under any load - and a module's remote stage,
// which waits up to 90 s per key, could never get that ticket into its cache.
const _JIRA_ISSUE_DETAIL_TIMEOUT_MS = 60000;

async function handleJiraIssueDetail(req, res) {
  const key = (new URL(req.url, 'http://localhost').searchParams.get('key') || '').trim().toUpperCase();
  if (!_JIRA_ISSUE_KEY_RE.test(key)) {
    return jsonResponse(res, 400, { status: 'error', message: 'key must match PROJECT-NNN' });
  }
  const now = Date.now();
  const cached = _JIRA_ISSUE_CACHE.get(key);
  if (cached && (now - cached.ts) < _JIRA_ISSUE_CACHE_TTL_MS) return jsonResponse(res, 200, cached.data);

  const token = _jiraToken();
  if (!token) return jsonResponse(res, 503, { status: 'error', error: 'token_missing' });

  const headers = _jiraAuthHeaders();
  const issueUrl = `${JIRA_BASE_URL}/rest/api/2/issue/${encodeURIComponent(key)}`
    + '?expand=changelog&fields=summary,description,status,assignee,reporter,priority,'
    + 'issuetype,labels,components,fixVersions,created,updated,resolutiondate,'
    + 'comment,worklog,parent,subtasks,issuelinks,timetracking';
  const wlUrl = `${JIRA_BASE_URL}/rest/api/2/issue/${encodeURIComponent(key)}/worklog?maxResults=1000`;

  let issueRaw, wlRaw;
  try {
    [issueRaw, wlRaw] = await Promise.all([
      fetch(issueUrl, { headers, signal: AbortSignal.timeout(_JIRA_ISSUE_DETAIL_TIMEOUT_MS) }),
      fetch(wlUrl, { headers, signal: AbortSignal.timeout(_JIRA_ISSUE_DETAIL_TIMEOUT_MS) }),
    ]);
  } catch (err) {
    return jsonResponse(res, 502, { status: 'error', error: 'jira_unreachable', message: String(err.message).slice(0, 200) });
  }
  if (!issueRaw.ok) return _jiraHttpError(res, issueRaw.status, await issueRaw.text().catch(() => ''));

  let issue, wlData;
  try {
    [issue, wlData] = await Promise.all([issueRaw.json(), wlRaw.ok ? wlRaw.json() : Promise.resolve({ worklogs: [] })]);
  } catch {
    return jsonResponse(res, 502, { status: 'error', error: 'jira_bad_response' });
  }

  const f = issue.fields || {};
  const fields = {
    summary: f.summary || '',
    description: f.description || null,
    status: f.status?.name || null,
    status_category: f.status?.statusCategory?.name || null,
    assignee: f.assignee ? { name: f.assignee.displayName, email: f.assignee.emailAddress } : null,
    reporter: f.reporter ? { name: f.reporter.displayName, email: f.reporter.emailAddress } : null,
    priority: f.priority?.name || null,
    issue_type: f.issuetype?.name || null,
    labels: f.labels || [],
    components: (f.components || []).map(c => ({ id: String(c.id || ''), name: c.name || '' })),
    fix_versions: (f.fixVersions || []).map(v => v.name),
    parent: f.parent ? { key: f.parent.key, summary: f.parent.fields?.summary || '' } : null,
    subtasks: (f.subtasks || []).map(s => ({ key: s.key, summary: s.fields?.summary || '', status: s.fields?.status?.name || null })),
    issue_links: (f.issuelinks || []).map(l => ({
      type: l.type?.name || '',
      direction: l.inwardIssue ? 'inward' : 'outward',
      key: (l.inwardIssue || l.outwardIssue)?.key || '',
      summary: (l.inwardIssue || l.outwardIssue)?.fields?.summary || '',
    })),
    created: f.created || null,
    updated: f.updated || null,
    resolution_date: f.resolutiondate || null,
    time_estimate_s: f.timetracking?.originalEstimateSeconds ?? null,
    time_remaining_s: f.timetracking?.remainingEstimateSeconds ?? null,
    time_spent_s: f.timetracking?.timeSpentSeconds ?? null,
  };

  const comments = (f.comment?.comments || []).map(c => ({
    id: c.id, author: c.author?.displayName || null, body: c.body || '',
    created: c.created || null, updated: c.updated || null,
  }));

  const worklogs = (wlData.worklogs || []).map(w => ({
    id: w.id, author: w.author?.displayName || null, started: w.started || null,
    time_spent_s: w.timeSpentSeconds ?? 0, comment: w.comment || null,
  }));

  // Jira returns changelog.histories oldest-first; reverse to newest-first.
  const changelog = (issue.changelog?.histories || []).slice().reverse().map(h => ({
    id: h.id, author: h.author?.displayName || null, created: h.created || null,
    items: (h.items || []).map(i => ({ field: i.field, from_str: i.fromString || null, to_str: i.toString || null })),
  }));

  const data = {
    key,
    url: `${JIRA_BASE_URL}/browse/${key}`,
    fields,
    comments,
    worklogs: { total_time_spent_s: worklogs.reduce((sum, w) => sum + w.time_spent_s, 0), entries: worklogs },
    changelog,
    _fetched_at: new Date(now).toISOString(),
  };
  _JIRA_ISSUE_CACHE.set(key, { data, ts: now });
  return jsonResponse(res, 200, data);
}

// ── POST /api/jira/worklog ──────────────────────────────────────────────────

const JWL_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const JWL_MAX_ENTRIES = 200;
const JWL_MAX_COMMENT_LEN = 2000;
const JWL_MIN_SECONDS = 60;
const JWL_MAX_SECONDS = 86400;

// Jira "started" timestamp. The +0200 offset is deliberate and fixed: DST
// handling is out of scope, and Jira only uses this to bucket the day.
function formatStartedISOServer(dateISO) {
  return `${dateISO}T09:00:00.000+0200`;
}

async function handleJiraWorklog(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try { body = await readBody(req, 256 * 1024); } catch { return jsonResponse(res, 400, { error: 'invalid_body' }); }
  if (!body || !Array.isArray(body.entries)) return jsonResponse(res, 400, { error: 'invalid_body' });

  const { entries } = body;
  if (entries.length < 1 || entries.length > JWL_MAX_ENTRIES) return jsonResponse(res, 400, { error: 'invalid_body' });

  for (let i = 0; i < entries.length; i++) {
    const e = entries[i];
    if (!e || typeof e !== 'object') return jsonResponse(res, 400, { error: 'invalid_entry', index: i, field: 'entry' });
    if (typeof e.issueKey !== 'string' || !_JIRA_ISSUE_KEY_RE.test(e.issueKey)) return jsonResponse(res, 400, { error: 'invalid_entry', index: i, field: 'issueKey' });
    if (typeof e.date !== 'string' || !JWL_DATE_RE.test(e.date)) return jsonResponse(res, 400, { error: 'invalid_entry', index: i, field: 'date' });
    if (!Number.isInteger(e.timeSpentSeconds) || e.timeSpentSeconds < JWL_MIN_SECONDS || e.timeSpentSeconds > JWL_MAX_SECONDS) {
      return jsonResponse(res, 400, { error: 'invalid_entry', index: i, field: 'timeSpentSeconds' });
    }
    if (typeof e.comment !== 'string' || e.comment.length > JWL_MAX_COMMENT_LEN) return jsonResponse(res, 400, { error: 'invalid_entry', index: i, field: 'comment' });
  }

  const token = _jiraToken();
  if (!token) return jsonResponse(res, 503, { error: 'token_missing' });
  if (_jiraRateLimited(res)) return;

  // Sequential on purpose — a burst of parallel worklog POSTs gets rate-limited
  // by Jira itself.
  const results = [];
  for (const entry of entries) {
    let r;
    try {
      r = await fetch(`${JIRA_BASE_URL}/rest/api/2/issue/${encodeURIComponent(entry.issueKey)}/worklog`, {
        method: 'POST',
        headers: { ..._jiraAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({
          started: formatStartedISOServer(entry.date),
          timeSpentSeconds: entry.timeSpentSeconds,
          comment: entry.comment,
        }),
        signal: AbortSignal.timeout(15000),
      });
    } catch (err) {
      results.push({ issueKey: entry.issueKey, date: entry.date, success: false, error: 'jira_unreachable', message: String(err.message).slice(0, 200) });
      continue;
    }
    if (r.ok) {
      let data;
      try { data = await r.json(); } catch { data = {}; }
      results.push({ issueKey: entry.issueKey, date: entry.date, success: true, worklogId: data.id });
    } else {
      results.push({ issueKey: entry.issueKey, date: entry.date, success: false, error: 'jira_error', status: r.status });
    }
  }
  // Always 200 — per-entry failures are reported in results[].success.
  return jsonResponse(res, 200, { results });
}

// ── POST /api/jira/create-issue-poc ─────────────────────────────────────────
// Creates an issue. The project defaults to JIRA_PROJECT_KEY.

const JCP_TYPE_MAP = {
  'historia': 'Story',
  'user-story': 'Story',
  'story': 'Story',
  'zadanie': 'Task',
  'task': 'Task',
  'blad': 'Bug',
  'bug': 'Bug',
};
const JCP_MAX_TITLE = 255;
const JCP_MAX_BODY = 256 * 1024;
const JCP_PROJECT_RE = /^[A-Z][A-Z0-9_]{1,20}$/;

async function handleJiraCreateIssue(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try { body = await readBody(req, JCP_MAX_BODY + 4096); } catch { return jsonResponse(res, 400, { error: 'invalid_body' }); }
  if (!body || typeof body !== 'object') return jsonResponse(res, 400, { error: 'invalid_body' });

  const title = typeof body.title === 'string' ? body.title.trim() : '';
  const content = typeof body.body === 'string' ? body.body : '';
  const issueTypeRaw = (typeof body.issueType === 'string' ? body.issueType : '').trim().toLowerCase();
  const defaultProject = (process.env.JIRA_PROJECT_KEY || '').trim().toUpperCase();
  const project = (typeof body.project === 'string' && body.project.trim())
    ? body.project.trim().toUpperCase()
    : defaultProject;
  const descriptionFormat = (typeof body.descriptionFormat === 'string' ? body.descriptionFormat : 'wiki').toLowerCase();
  const epicLinkRaw = typeof body.epicLink === 'string' ? body.epicLink.trim().toUpperCase() : '';

  // Jira labels cannot contain spaces — coerce silently rather than reject.
  let labels = [];
  if (Array.isArray(body.labels)) {
    const seen = new Set();
    for (const lbl of body.labels) {
      if (typeof lbl !== 'string') continue;
      const t = lbl.trim();
      if (!t || t.length > 100) continue;
      const safe = t.replace(/\s+/g, '_');
      if (seen.has(safe)) continue;
      seen.add(safe);
      labels.push(safe);
    }
    if (labels.length > 20) labels = labels.slice(0, 20);
  }

  if (!title || title.length > JCP_MAX_TITLE) return jsonResponse(res, 400, { error: 'invalid_title' });
  if (!content || content.length > JCP_MAX_BODY) return jsonResponse(res, 400, { error: 'invalid_body_content' });
  if (!JCP_TYPE_MAP[issueTypeRaw]) return jsonResponse(res, 400, { error: 'invalid_issue_type', allowed: Object.keys(JCP_TYPE_MAP) });
  if (!project) return jsonResponse(res, 400, { error: 'missing_project', message: 'Set JIRA_PROJECT_KEY or pass project in the body.' });
  if (!JCP_PROJECT_RE.test(project)) return jsonResponse(res, 400, { error: 'invalid_project', value: project });
  if (epicLinkRaw && !_JIRA_ISSUE_KEY_RE.test(epicLinkRaw)) return jsonResponse(res, 400, { error: 'invalid_epic_link', value: epicLinkRaw });

  const issueTypeName = JCP_TYPE_MAP[issueTypeRaw];
  // Jira Server v2 expects wiki markup in `description`; raw markdown would
  // render as plain text.
  const description = descriptionFormat === 'raw' ? content : mdToJiraWiki(content);

  const token = _jiraToken();
  if (!token) return jsonResponse(res, 503, { error: 'token_missing' });
  if (_jiraRateLimited(res)) return;

  const authHeader = _jiraAuthHeaders();

  // Step 1 — resolve the current user's `name` for the reporter field.
  let reporterName;
  try {
    const meRes = await fetch(`${JIRA_BASE_URL}/rest/api/2/myself`, { headers: authHeader, signal: AbortSignal.timeout(15000) });
    if (!meRes.ok) return _jiraHttpError(res, meRes.status, await meRes.text().catch(() => ''));
    const meJson = await meRes.json();
    reporterName = meJson.name || meJson.key || meJson.accountId;
    if (!reporterName) return jsonResponse(res, 502, { error: 'jira_myself_no_name' });
  } catch (err) {
    return jsonResponse(res, 502, { error: 'jira_unreachable', message: String(err.message).slice(0, 200) });
  }

  const createFields = {
    project: { key: project },
    summary: title,
    issuetype: { name: issueTypeName },
    reporter: { name: reporterName },
  };
  // Some issue types (e.g. a "Bug" type) have no description on the create
  // screen; 'omit' leaves it out so the caller can post the text as a comment.
  if (descriptionFormat !== 'omit') createFields.description = description;
  // Per-instance required fields (e.g. a "Bug" type: customfield_15301/15302).
  // Only customfield_NNNNN keys pass, same rule as update-fields.
  if (body.customFields && typeof body.customFields === 'object' && !Array.isArray(body.customFields)) {
    for (const [k, v] of Object.entries(body.customFields)) {
      if (!/^customfield_\d+$/.test(k)) return jsonResponse(res, 400, { error: 'field_not_allowed', field: k });
      createFields[k] = v;
    }
  }
  if (labels.length) createFields.labels = labels;
  // Epic Link is GreenHopper's gh-epic-link custom field; the value is a plain
  // issue key string.
  if (epicLinkRaw) createFields.customfield_10001 = epicLinkRaw;

  let createRes;
  try {
    createRes = await fetch(`${JIRA_BASE_URL}/rest/api/2/issue`, {
      method: 'POST',
      headers: { ...authHeader, 'Content-Type': 'application/json' },
      body: JSON.stringify({ fields: createFields }),
      signal: AbortSignal.timeout(30000),
    });
  } catch (err) {
    return jsonResponse(res, 502, { error: 'jira_unreachable', message: String(err.message).slice(0, 200) });
  }
  if (!createRes.ok) {
    const t = await createRes.text().catch(() => '');
    if (createRes.status === 401 || createRes.status === 403) return _jiraHttpError(res, createRes.status, t);
    return jsonResponse(res, createRes.status, { error: 'jira_create_failed', status: createRes.status, message: t.slice(0, 1000) });
  }

  let data;
  try { data = await createRes.json(); } catch { data = {}; }
  const key = data.key || '';
  return jsonResponse(res, 200, {
    key,
    url: key ? `${JIRA_BASE_URL}/browse/${key}` : '',
    reporter: reporterName,
    issueType: issueTypeName,
    project,
    labels,
    epicLink: epicLinkRaw || null,
  });
}

// ── POST /api/jira/comment ──────────────────────────────────────────────────

async function handleJiraComment(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try { body = await readBody(req, _JIRA_COMMENT_MAX_BODY_LEN + 4096); } catch {
    return jsonResponse(res, 400, { error: 'invalid_payload' });
  }
  if (!body || typeof body !== 'object') return jsonResponse(res, 400, { error: 'invalid_payload' });

  const key = typeof body.key === 'string' ? body.key.trim().toUpperCase() : '';
  const text = typeof body.body === 'string' ? body.body : '';
  if (!_JIRA_ISSUE_KEY_RE.test(key)) return jsonResponse(res, 400, { error: 'invalid_key' });
  if (text.length < 1 || text.length > _JIRA_COMMENT_MAX_BODY_LEN) {
    return jsonResponse(res, 400, { error: 'invalid_body_length', max: _JIRA_COMMENT_MAX_BODY_LEN });
  }

  const token = _jiraToken();
  if (!token) return jsonResponse(res, 503, { error: 'token_missing' });
  if (_jiraRateLimited(res)) return;

  let r;
  try {
    r = await fetch(`${JIRA_BASE_URL}/rest/api/2/issue/${encodeURIComponent(key)}/comment`, {
      method: 'POST',
      headers: { ..._jiraAuthHeaders(), 'Content-Type': 'application/json' },
      body: JSON.stringify({ body: text }),
      signal: AbortSignal.timeout(15000),
    });
  } catch (err) {
    return jsonResponse(res, 502, { error: 'jira_unreachable', message: String(err.message).slice(0, 200) });
  }
  if (!r.ok) return _jiraHttpError(res, r.status, await r.text().catch(() => ''));

  let data;
  try { data = await r.json(); } catch { data = {}; }
  const id = data.id || '';
  return jsonResponse(res, 200, {
    status: 'ok',
    id,
    jira_url: id ? `${JIRA_BASE_URL}/browse/${key}?focusedCommentId=${id}` : `${JIRA_BASE_URL}/browse/${key}`,
  });
}

// ── POST /api/jira/update-fields ────────────────────────────────────────────
// Generic field update. `fields` is passed through to the Jira REST API as-is;
// only the keys listed in JUF_ALLOWED_FIELDS are accepted, so a typo cannot
// silently wipe an unrelated field.

const JUF_ALLOWED_FIELDS = new Set([
  'summary', 'description', 'labels', 'duedate', 'priority', 'assignee', 'components', 'fixVersions',
]);

async function handleJiraUpdateFields(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try { body = await readBody(req, JCP_MAX_BODY + 4096); } catch { return jsonResponse(res, 400, { error: 'invalid_payload' }); }
  if (!body || typeof body !== 'object') return jsonResponse(res, 400, { error: 'invalid_payload' });

  const key = typeof body.key === 'string' ? body.key.trim().toUpperCase() : '';
  if (!_JIRA_ISSUE_KEY_RE.test(key)) return jsonResponse(res, 400, { error: 'invalid_key' });

  const requested = (body.fields && typeof body.fields === 'object' && !Array.isArray(body.fields)) ? body.fields : null;
  if (!requested) return jsonResponse(res, 400, { error: 'invalid_payload', error_detail: 'fields must be an object' });

  const fields = {};
  for (const [k, v] of Object.entries(requested)) {
    // customfield_NNNNN is allowed explicitly — those are per-instance and
    // cannot be enumerated here.
    if (!JUF_ALLOWED_FIELDS.has(k) && !/^customfield_\d+$/.test(k)) {
      return jsonResponse(res, 400, { error: 'field_not_allowed', field: k, allowed: [...JUF_ALLOWED_FIELDS] });
    }
    fields[k] = v;
  }
  if (Object.keys(fields).length === 0) {
    return jsonResponse(res, 400, { error: 'invalid_payload', error_detail: 'no_fields_to_update' });
  }

  const token = _jiraToken();
  if (!token) return jsonResponse(res, 503, { error: 'token_missing' });
  if (_jiraRateLimited(res)) return;

  let r;
  try {
    r = await fetch(`${JIRA_BASE_URL}/rest/api/2/issue/${encodeURIComponent(key)}`, {
      method: 'PUT',
      headers: { ..._jiraAuthHeaders(), 'Content-Type': 'application/json' },
      body: JSON.stringify({ fields }),
      signal: AbortSignal.timeout(15000),
    });
  } catch (err) {
    return jsonResponse(res, 502, { error: 'jira_unreachable', message: String(err.message).slice(0, 200) });
  }
  // A successful Jira field update answers 204 No Content.
  if (!r.ok && r.status !== 204) return _jiraHttpError(res, r.status, await r.text().catch(() => ''));

  _JIRA_ISSUE_CACHE.delete(key);
  _jiraIssueTitleCache.delete(key);
  return jsonResponse(res, 200, { status: 'ok', key, updated: Object.keys(fields), url: `${JIRA_BASE_URL}/browse/${key}` });
}

// ── Plug & play modules ─────────────────────────────────────────────────────
// Discovers installed modules at startup and mounts their server-side routes
// under /api/m/<id>/. Static client assets are served from /modules/<id>/client/.
//
//   GET  /api/modules/manifest  -> { modules: [...], errors: [...], modulesDir }
//   *    /api/m/<id>/<path>     -> delegated to the module's registered routes
//   GET  /modules/<id>/client/  -> static files from MODULES_DIR/<id>/client/
//
// "Modules: management" below adds the management surface behind Settings >
// Modules:
//   GET  /api/modules/installed -> live disk scan, incl. disabled/invalid, git
//   POST /api/modules/toggle    -> enable/disable a module in the registry
//   POST /api/modules/remove    -> delete modules/<id>/ (optionally its data)
//   POST /api/modules/git-init  -> git init + first commit (scripts/_module-git.js)
//   POST /api/modules/git-commit -> "Save version": git add -A + commit
//   GET  /api/modules/git-log    -> recent commits of one module (the "History" list)
//   GET  /api/modules/export    -> download modules/<id>/ as a .zip
//   POST /api/modules/import    -> upload a .zip and install it
//
// A second static root serves BUILT module apps: /modules-data/<id>/public/...
// resolves against MODULES_DATA_DIR (see serveStatic), so a module's build
// output never lives inside the module's own git tree.

const MODULES_DIR = process.env.MODULES_DIR || path.join(ROOT, 'modules');
const MODULES_DATA_DIR = process.env.MODULES_DATA_DIR || path.join(ROOT, 'data', 'modules');
const MODULES_REGISTRY_FILE = process.env.MODULES_REGISTRY_FILE || path.join(ROOT, 'data', 'modules-registry.json');
// Provenance of an installed copy - where it came from and at what version -
// gitignored runtime data, never module.json (that file is published, so a
// provenance field would travel to the catalog and mix with the next
// publisher's manifest). One object keyed by module id: { source, version, at }.
const MODULES_ORIGIN_FILE = process.env.MODULES_ORIGIN_FILE || path.join(ROOT, 'data', 'modules-origin.json');

const MODULE_ID_RE = /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/;
// 'assets' is the one core HUB (js/sidebar-flyout-config.js): a module
// claiming that id would collide with its rail item and its four views.
// The rail's hubs. SECOND copy of js/core-hubs.mjs, which is the declaration -
// this file is CJS and validateModuleManifest is sync, so it cannot import an
// ESM module the way js/sidebar-flyout-config.js does. tests/test_core_hubs.mjs
// is the gate that keeps the two identical, the same arrangement the two copies
// of RESERVED_MODULE_IDS below have always had.
const CORE_HUB_IDS = new Set(['team', 'activity', 'finance', 'initiatives', 'support', 'knowledge', 'assets', 'apps']);

// A hub id is spread in rather than listed twice: a module directory named
// after a hub would shadow the rail item and take over its hash route.
const RESERVED_MODULE_IDS = new Set([
  'dashboard', 'settings', 'api', 'modules', 'm', 'onboarding-wizard', 'academy',
  ...CORE_HUB_IDS,
]);

// A module's maturity - the ONE list behind module.json `status`, the catalog
// curation's `status` and the publish modal's select. Mirrored by
// MATURITY_BADGE in js/module-card.mjs, which is the only renderer of it.
const MODULE_STATUSES = ['stable', 'beta', 'deprecated'];

// A module's business area (Product, Engineering, Operations, ...) - an OPEN
// list, unlike MODULE_STATUSES: these three are suggestions offered to a
// person filling the field, never a closed dictionary enforced at validation
// time. Independent of sidebar.hub - area is the business domain, hub is the
// place in the navigation. Mirrored in scripts/new-module.js the same way
// MODULE_ID_RE is (see the comment there); tests/test_new_module.mjs is the
// gate that keeps the two identical.
const MODULE_AREA_MAX = 40;
const MODULE_AREA_SUGGESTIONS = ['Product', 'Engineering', 'Operations'];

/**
 * Trims and collapses runs of plain spaces. Pure, and deliberately narrow:
 * this function NEVER strips control characters - validateModuleArea rejects
 * a control character on the RAW value before this runs, so a value with a
 * tab or a newline never reaches here "fixed" into something that looks
 * clean. Normalizing first would let exactly that value pass validation.
 * @param {unknown} v
 * @returns {string}
 */
function normalizeModuleArea(v) {
  return String(v === null || v === undefined ? '' : v).trim().replace(/ {2,}/g, ' ');
}

// Unicode letters/digits, space and a short list of punctuation that shows up
// in a real business area name ("Field Operations", "R&D", "Sales B2B/B2C").
const MODULE_AREA_CHARS_RE = /^[\p{L}\p{N} \-.&+/]+$/u;

/**
 * Validate a module's business area. Pure - no side effects.
 * Order matters (see plan Risks): a control character is rejected on the RAW
 * value FIRST, before normalizeModuleArea ever runs - otherwise a value
 * carrying a tab or a newline would be silently "repaired" by the trim/collapse
 * step and then pass as if it had always been clean.
 * @param {unknown} v
 * @returns {{ok: true, value: string} | {ok: false, error: string}}
 */
function validateModuleArea(v) {
  if (typeof v !== 'string') return { ok: false, error: 'area must be a string' };
  if (/[\u0000-\u001f\u007f]/.test(v)) return { ok: false, error: 'area must not contain control characters' };
  const value = normalizeModuleArea(v);
  if (value.length < 2 || value.length > MODULE_AREA_MAX) {
    return { ok: false, error: 'area must be 2..' + MODULE_AREA_MAX + ' characters' };
  }
  if (!MODULE_AREA_CHARS_RE.test(value)) {
    return { ok: false, error: 'area contains characters that are not letters, digits, space or - . & + /' };
  }
  return { ok: true, value };
}

// -- Dashboard widgets: contract helpers --
// A module MAY declare widgets[] in module.json (tiles on the dashboard).
// Absent field = valid (the core derives a shortcut widget). Sizes are a
// closed set because styles.css only has classes for these spans.
const WIDGET_COLS = [2, 3, 6];
const WIDGET_ROWS = [1, 2];
const WIDGETS_MAX = 6;
const WIDGET_VARIANTS_MAX = 6; // one per scaffold preset: s, s2, m, m2, l, xl
const DASHBOARD_LAYOUT_MAX = 40;
const WIDGET_EXPORT_RE = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const WIDGET_CLIENT_RE = /^client\/(?:[A-Za-z0-9_-][A-Za-z0-9_.-]*\/)*[A-Za-z0-9_-][A-Za-z0-9_.-]*\.js$/;

/**
 * Validate the optional widgets[] of a module manifest. Pure.
 * @param {unknown} widgets
 * @param {string} [moduleId]
 * @returns {string[]} error messages (empty = valid or absent)
 */
function validateModuleWidgets(widgets, moduleId) {
  void moduleId;
  const errors = [];
  if (widgets === undefined) return errors;
  if (!Array.isArray(widgets)) return ['widgets must be an array'];
  if (widgets.length > WIDGETS_MAX) errors.push('widgets must have at most ' + WIDGETS_MAX + ' entries');
  const seen = new Set();
  widgets.forEach((w, i) => {
    const at = 'widgets[' + i + ']';
    if (!w || typeof w !== 'object' || Array.isArray(w)) { errors.push(at + ' must be an object'); return; }
    if (typeof w.id !== 'string' || !MODULE_ID_RE.test(w.id)) errors.push(at + '.id must be a slug');
    else if (seen.has(w.id)) errors.push(at + '.id "' + w.id + '" is duplicated');
    else seen.add(w.id);
    if (typeof w.label !== 'string' || !w.label.trim()) errors.push(at + '.label must be a non-empty string');
    if (w.description !== undefined && typeof w.description !== 'string') errors.push(at + '.description must be a string');
    const c = w.client;
    // Allowlist, not a blocklist: the browser's URL parser turns `%2e%2e` into
    // `..` before the request leaves, so no `%`, `?`, `#` or dot-led segment.
    const clientOk = typeof c === 'string' && WIDGET_CLIENT_RE.test(c);
    if (!clientOk) errors.push(at + '.client must be a relative path "client/....js" of [A-Za-z0-9_.-] segments');
    if (w.export !== undefined && (typeof w.export !== 'string' || !WIDGET_EXPORT_RE.test(w.export))) {
      errors.push(at + '.export must be an identifier');
    }
    const ids = new Set();
    if (!Array.isArray(w.variants) || w.variants.length === 0) {
      errors.push(at + '.variants must be a non-empty array');
    } else {
      if (w.variants.length > WIDGET_VARIANTS_MAX) errors.push(at + '.variants must have at most ' + WIDGET_VARIANTS_MAX + ' entries');
      w.variants.forEach((v, j) => {
        const vat = at + '.variants[' + j + ']';
        if (!v || typeof v !== 'object' || Array.isArray(v)) { errors.push(vat + ' must be an object'); return; }
        if (typeof v.id !== 'string' || !MODULE_ID_RE.test(v.id)) errors.push(vat + '.id must be a slug');
        else if (ids.has(v.id)) errors.push(vat + '.id "' + v.id + '" is duplicated');
        else ids.add(v.id);
        if (typeof v.label !== 'string' || !v.label.trim()) errors.push(vat + '.label must be a non-empty string');
        if (!WIDGET_COLS.includes(v.cols)) errors.push(vat + '.cols must be one of ' + WIDGET_COLS.join(', '));
        if (!WIDGET_ROWS.includes(v.rows)) errors.push(vat + '.rows must be one of ' + WIDGET_ROWS.join(', '));
      });
    }
    if (typeof w.defaultVariant !== 'string' || !ids.has(w.defaultVariant)) {
      errors.push(at + '.defaultVariant must be one of the variant ids');
    }
  });
  return errors;
}

/**
 * Widget catalog entry of one module: declared widgets pass through, a module
 * without widgets[] gets one core-built shortcut widget. Pure.
 * @param {object} manifest a validated module manifest
 */
function moduleWidgets(manifest) {
  const m = manifest || {};
  const views = Array.isArray(m.views) ? m.views : [];
  const declared = Array.isArray(m.widgets) ? m.widgets : [];
  const widgets = declared.length > 0
    ? declared.map((w) => ({
      id: w.id,
      label: w.label,
      description: typeof w.description === 'string' ? w.description : '',
      client: w.client,
      export: w.export || 'renderWidget',
      variants: w.variants.map((v) => ({ id: v.id, label: v.label, cols: v.cols, rows: v.rows })),
      defaultVariant: w.defaultVariant,
      builtin: false,
    }))
    : [{
      id: 'shortcut',
      label: 'Shortcut',
      description: m.description || '',
      client: null,
      export: null,
      variants: [{ id: 's', label: 'Small', cols: 2, rows: 1 }],
      defaultVariant: 's',
      builtin: true,
    }];
  return {
    module: m.id,
    name: m.name,
    icon: m.icon || null,
    description: m.description || '',
    entryView: views[0] ? views[0].id : null,
    widgets,
  };
}

/**
 * Sanitise a stored dashboard layout against the widget catalog. Pure and
 * tolerant: any input shape yields a valid { version, items }. An unknown
 * variant falls back to the widget's defaultVariant; unknown module/widget is
 * dropped; duplicates keep the first; capped at DASHBOARD_LAYOUT_MAX.
 */
function normalizeDashboardLayout(raw, available) {
  const items = [];
  const list = Array.isArray(available) ? available : [];
  const src = raw && typeof raw === 'object' && Array.isArray(raw.items) ? raw.items : [];
  const seen = new Set();
  for (const it of src) {
    if (items.length >= DASHBOARD_LAYOUT_MAX) break;
    if (!it || typeof it !== 'object' || typeof it.module !== 'string' || typeof it.widget !== 'string') continue;
    const mod = list.find((a) => a && a.module === it.module);
    if (!mod) continue;
    const w = mod.widgets.find((x) => x.id === it.widget);
    if (!w) continue;
    const key = it.module + '/' + it.widget;
    if (seen.has(key)) continue;
    seen.add(key);
    const variant = typeof it.variant === 'string' && w.variants.some((v) => v.id === it.variant)
      ? it.variant : w.defaultVariant;
    items.push({ module: it.module, widget: it.widget, variant });
  }
  return { version: 1, items };
}

// Local, remote-less git repository per module (docs/architecture/modules.md).
// Shared with scripts/new-module.js so the scaffold's first commit and this
// server's git-init/git-commit routes can never drift into two implementations.
const MG = require('./scripts/_module-git.js');

/** Env for every module-git call this server spawns - the same askpass-proof env every other git call here uses. */
function _moduleGitOpts(extra = {}) {
  return { env: _gitNoPromptEnv(), ...extra };
}

/**
 * Reduces a manifest version string to a git-safe commit-message fragment:
 * printable ASCII only (a commit message is an id, not copy), capped at 40
 * characters so a hostile manifest cannot inflate the commit body.
 * @param {unknown} version
 * @returns {string}
 */
function _moduleAsciiVersion(version) {
  const raw = version === null || version === undefined ? '' : String(version);
  const ascii = raw.replace(/[^\x20-\x7e]/g, '');
  return ascii.slice(0, 40) || 'unknown';
}

/**
 * Validate a parsed module.json manifest. Pure — no side effects.
 *
 * `opts.strict` is a TEMPORARY compatibility boundary for the `area` field
 * only, not a general strictness switch: with `strict: true`, a missing or
 * invalid `area` is an error; without it, a missing `area` is not an error but
 * the returned object carries `warnings: ['area-missing']` (an invalid VALUE
 * is still always an error, in both modes). Soft mode exists ONLY for
 * artifacts that already exist and that a person cannot fix in place right
 * now - the disk scan (scanModulesDir) and the remote catalog manifest read
 * (handleModulesCatalog). Install and import get `strict: true` because, after
 * the area-required gate in handleModulesInstall/handleModuleImport, they
 * always have something to fill the field with before this function ever
 * runs. The boundary closes once scripts/migrate-module-areas.js has run: no
 * module on disk is without an area after that, and soft mode then only
 * matters for older remote catalog entries, which get an area at install time
 * regardless.
 * @param {object} manifest
 * @param {string} dirId the directory name used as the expected module id
 * @param {{strict?: boolean}} [opts]
 * @returns {{ valid: true, manifest: object, warnings?: string[] } | { valid: false, errors: string[] }}
 */
function validateModuleManifest(manifest, dirId, opts = {}) {
  const strict = !!(opts && opts.strict === true);
  const errors = [];
  if (!manifest || typeof manifest !== 'object') {
    return { valid: false, errors: ['manifest is not an object'] };
  }
  const { schemaVersion, id, name, version, sidebar, views } = manifest;
  if (schemaVersion !== 1) {
    errors.push('unknown schemaVersion: ' + schemaVersion + ' (expected 1)');
  }
  if (typeof id !== 'string' || !id) errors.push('id is required and must be a string');
  if (typeof name !== 'string' || !name) errors.push('name is required and must be a string');
  if (typeof version !== 'string' || !version) errors.push('version is required and must be a string');
  if (!sidebar || typeof sidebar !== 'object') {
    errors.push('sidebar is required and must be an object');
  } else {
    if (!['hub', 'item', 'page'].includes(sidebar.kind)) {
      errors.push('sidebar.kind must be "hub", "item" or "page"');
    }
    // "page" is the shape that puts a module's views into a CORE hub's flyout
    // instead of giving the module a rail item of its own (js/core-hubs.mjs).
    // The hub has to exist here and not merely look like a slug: an unknown id
    // means js/module-host.js drops the module's menu entry silently, and the
    // one place that can still say so out loud is the install.
    if (sidebar.kind === 'page') {
      if (typeof sidebar.hub !== 'string' || !sidebar.hub) {
        errors.push('sidebar.hub is required when sidebar.kind is "page"');
      } else if (!CORE_HUB_IDS.has(sidebar.hub)) {
        errors.push('sidebar.hub "' + sidebar.hub + '" is not a core hub (one of: '
          + [...CORE_HUB_IDS].join(', ') + ')');
      }
    } else if (sidebar.hub !== undefined) {
      errors.push('sidebar.hub is only allowed when sidebar.kind is "page"');
    }
  }
  if (!Array.isArray(views) || views.length === 0) {
    errors.push('views is required and must be a non-empty array');
  }
  if (errors.length > 0) return { valid: false, errors };

  // id format checks
  if (!MODULE_ID_RE.test(id)) errors.push('id format invalid (must match /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/)');
  if (RESERVED_MODULE_IDS.has(id)) errors.push('id "' + id + '" is reserved');
  if (dirId && id !== dirId) errors.push('id "' + id + '" does not match directory name "' + dirId + '"');

  // view id checks
  if (Array.isArray(views)) {
    for (const v of views) {
      if (!v || typeof v.id !== 'string') {
        errors.push('each view must have a string id');
      } else if (!MODULE_ID_RE.test(v.id)) {
        // A view id becomes an element id (#view-<id>), a hash route and a
        // VIEW_REGISTRY key, so it has to be a slug - not merely prefixed.
        errors.push('view id "' + v.id + '" format invalid (must match /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/)');
      } else if (!v.id.startsWith(id + '-')) {
        errors.push('view id "' + v.id + '" must start with module id + "-" ("' + id + '-")');
      }
    }
  }

  // Optional self-description. `author` and `tags` exist so that EVERY section
  // the Modules cards render has a home in module.json - before they were added,
  // an installed module could never show an author or a tag because those two
  // lived only in the catalog's curation file, which a local module has no
  // entry in. catalog.json still overrides both; see mergeModulesCatalog.
  if (manifest.author !== undefined && typeof manifest.author !== 'string') {
    errors.push('author must be a string');
  }
  if (manifest.tags !== undefined
    && (!Array.isArray(manifest.tags) || manifest.tags.some(t => typeof t !== 'string'))) {
    errors.push('tags must be an array of strings');
  }
  // `status` (stable / beta / deprecated) is the module's maturity. It used to
  // live ONLY in the catalog's curation entry, which the publish modal asked
  // for and then forgot: the installed card could not show it and the modal
  // reopened on "beta" every time. The manifest is its home now - the publish
  // handler writes the chosen value back here, and catalog.json still wins
  // for a catalog module, same as author and tags.
  if (manifest.status !== undefined && !MODULE_STATUSES.includes(manifest.status)) {
    errors.push('status must be one of: ' + MODULE_STATUSES.join(', '));
  }

  // `area` (business domain, independent of sidebar.hub - see the file header
  // comment on strict/soft above). A bad VALUE is always an error; an ABSENT
  // field is only an error in strict mode, and otherwise turns into a warning
  // below so the caller can still show "Area not set" instead of
  // silently defaulting to one.
  let areaWarning = null;
  if (manifest.area !== undefined) {
    const areaCheck = validateModuleArea(manifest.area);
    if (!areaCheck.ok) errors.push('area is invalid');
  } else if (strict) {
    errors.push('area is required (module business area, e.g. "Product")');
  } else {
    areaWarning = 'area-missing';
  }

  // envKeys was documented in modules-template/README.md long before
  // anything read it, and an unvalidated field is exactly the one that must
  // not reach the card. An envKeys entry takes the SAME two
  // forms as a dataRepos entry - a bare name, or an object with `name` plus an
  // optional `description` - so ONE renderer draws both badge rows in
  // js/module-card.mjs. An env variable name is an identifier, not copy:
  // uppercase ASCII only.
  if (manifest.envKeys !== undefined) {
    if (!Array.isArray(manifest.envKeys)) {
      errors.push('envKeys must be an array');
    } else {
      manifest.envKeys.forEach((entry, i) => {
        const isObj = !!entry && typeof entry === 'object';
        const name = typeof entry === 'string' ? entry : (isObj ? entry.name : null);
        if (typeof name !== 'string' || !/^[A-Z][A-Z0-9_]*$/.test(name)) {
          errors.push('envKeys[' + i + '] must be an uppercase ASCII env name, or an object with such a "name"');
          return;
        }
        if (isObj && entry.description !== undefined && typeof entry.description !== 'string') {
          errors.push('envKeys[' + i + '].description must be a string');
        }
      });
    }
  }

  // widgets[] (dashboard tiles): optional - an absent field adds no error.
  for (const e of validateModuleWidgets(manifest.widgets, dirId)) errors.push(e);

  // dataRepos: still a DECLARATION, not enforced against the real DATA_REPOS
  // registry - see modules-template/README.md. Only the shape is validated
  // here. Each entry is a bare repo name/id string, or an object carrying at
  // least `name`; `paths` on that object is the one field GET /api/sync-
  // modules actually reads (via _syncModuleScopes), so a malformed one would
  // silently misfile a module's changes into "Cockpit Core" - hence a hard
  // validation instead of a soft warning. `name` may be either the route id
  // (e.g. "data-tier-0") or the remote name (e.g. "ds-data-tier-0") - both
  // are resolved server-side, see _resolveDataRepoId.
  if (manifest.dataRepos !== undefined) {
    if (!Array.isArray(manifest.dataRepos)) {
      errors.push('dataRepos must be an array');
    } else {
      manifest.dataRepos.forEach((entry, i) => {
        if (typeof entry === 'string') return;
        if (!entry || typeof entry !== 'object' || typeof entry.name !== 'string' || !entry.name) {
          errors.push('dataRepos[' + i + '] must be a string or an object with a string "name"');
          return;
        }
        if (entry.paths !== undefined) {
          // Three forms only: "file.json" (exact), "dir/" (prefix, exact dir
          // match too) and "prefix*" (literal prefix, "*" ONLY as the last
          // character - never in the middle, never alone). The glob never
          // reaches git: _syncEntryMatches matches it in JS against a path
          // list, so a malformed entry here is the only place this is caught.
          const pathsValid = Array.isArray(entry.paths) && entry.paths.every((p) => (
            typeof p === 'string' && p.length > 0
            && /^[\x20-\x7e]+$/.test(p)
            && !p.startsWith('/')
            && !p.includes('\\')
            && !p.split('/').includes('..')
            && (p.indexOf('*') === -1 || (p.indexOf('*') === p.length - 1 && p.length >= 2))
          ));
          if (!pathsValid) {
            errors.push('dataRepos[' + i + '].paths entries must be "file", "dir/" or "prefix*" ("*" only as the last character)');
          }
        }
        // `access` (optional, default 'write'): 'read' makes the entry a VIEW on
        // the module's sync row - never ownership - and so needs explicit
        // paths: an assumed `<id>/` read names nothing the module reads.
        if (entry.access !== undefined) {
          if (entry.access !== 'write' && entry.access !== 'read') {
            errors.push('dataRepos[' + i + '].access must be "write" or "read"');
          } else if (entry.access === 'read' && !(Array.isArray(entry.paths) && entry.paths.length > 0)) {
            errors.push('dataRepos[' + i + '].access "read" requires non-empty paths');
          }
        }
      });
    }
  }

  if (errors.length > 0) return { valid: false, errors };
  return areaWarning ? { valid: true, manifest, warnings: [areaWarning] } : { valid: true, manifest };
}

/**
 * Fresh, side-effect-free scan of MODULES_DIR — readdir + parse + validate,
 * no require() of any server entry, no mkdirSync. Used both by loadModules()
 * (the boot-time snapshot) and by GET /api/modules/installed (a live scan the
 * Settings > Modules tab needs because disabled modules never reach
 * _loadedModules and a module dropped in after boot needs to be visible
 * before the "requires restart" callout would tell anyone to restart).
 * @returns {{ installed: Array, invalid: Array, disabled: string[] }}
 */
function scanModulesDir() {
  let dirs = [];
  try {
    dirs = fs.readdirSync(MODULES_DIR, { withFileTypes: true })
      // The leading-dot filter is load-bearing: POST /api/modules/import
      // extracts into a ".import-<pid>-<ts>" directory INSIDE MODULES_DIR so
      // the final move is a same-filesystem renameSync; this filter is what
      // keeps that in-flight directory from appearing as a broken module.
      .filter(e => e.isDirectory() && !e.name.startsWith('.'))
      .map(e => e.name);
  } catch {
    return { installed: [], invalid: [], disabled: [] };
  }

  let registry = { disabled: [] };
  try {
    registry = JSON.parse(fs.readFileSync(MODULES_REGISTRY_FILE, 'utf8'));
  } catch { /* no registry = all enabled */ }
  const disabledList = Array.isArray(registry.disabled) ? registry.disabled : [];
  const disabled = new Set(disabledList);

  const installed = [];
  const invalid = [];

  for (const dirId of dirs) {
    let manifest;
    try {
      manifest = JSON.parse(fs.readFileSync(path.join(MODULES_DIR, dirId, 'module.json'), 'utf8'));
    } catch (e) {
      invalid.push({ id: dirId, kind: 'read-error', errors: ['cannot read module.json: ' + e.message] });
      continue;
    }

    const result = validateModuleManifest(manifest, dirId);
    if (!result.valid) {
      invalid.push({ id: dirId, kind: 'invalid-manifest', errors: result.errors });
      continue;
    }

    installed.push({
      id: dirId,
      manifest,
      enabled: !disabled.has(dirId),
      hasServer: Boolean(manifest.server && manifest.server.entry),
    });
  }

  return { installed, invalid, disabled: disabledList };
}

/**
 * Suggestions for the "Assign area" prompt (409 area-required): every
 * area already used by an installed module, plus the three starter names,
 * deduplicated. Never a default value - only a list to pick from.
 * @returns {string[]}
 */
function _moduleAreaSuggestions() {
  const areas = new Set(MODULE_AREA_SUGGESTIONS);
  for (const m of scanModulesDir().installed) {
    if (m.manifest && typeof m.manifest.area === 'string') {
      const norm = normalizeModuleArea(m.manifest.area);
      if (norm) areas.add(norm);
    }
  }
  return [...areas];
}

// Loaded modules registry: populated in the if(require.main===module) boot
// path. Under require() (unit tests) this stays as an empty stub.
let _loadedModules = { modules: [], errors: [] };

// -- Data snapshot for a module (captureDataSnapshot) ------------------------
// A module that BAKES team data into an artifact (e.g. a static build) needs
// a frozen copy of its inputs, taken while no pull or decrypt is rewriting the
// plaintext tree underneath it. The plaintext ds-data-* directories are not git
// repositories (git -C there walks up and answers for mission-deck), so a module
// cannot ask them for a revision, and its own chain lock does not serialize
// against this file's pull/decrypt. This service is the one door: it takes
// repo IDS (validated against DATA_REPOS), copies the requested relative paths
// from each repo's PLAINTEXT directory under that repo's real lockFn plus the
// mirror's file lock, in the fixed DATA_REPOS order, into a destination that
// must lie inside the calling module's own dataDir, and records the mirror's
// HEAD plus a sha256 per copied file. A local edit that lands mid-copy shows up
// as a before/after hash mismatch; one retry, then `snapshot-unstable`. The
// snapshot carries a revision VECTOR (one per source) - it promises a stable
// copy, not a common business instant across sources. Injected `repos`,
// `dataDir` and lock helpers keep tests/test_data_snapshot.mjs off the real
// data repositories.
const _SNAPSHOT_MAX_ATTEMPTS = 2;

function _snapshotHashFile(file) {
  return crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
}

/** Relative file list (posix separators, sorted) under `abs`, files only, dotfiles skipped. */
function _snapshotListFiles(abs, rel, out) {
  let entries;
  try { entries = fs.readdirSync(abs, { withFileTypes: true }); } catch { return out; }
  for (const ent of entries) {
    if (ent.name.startsWith('.')) continue;
    const childAbs = path.join(abs, ent.name);
    const childRel = rel ? rel + '/' + ent.name : ent.name;
    if (ent.isDirectory()) _snapshotListFiles(childAbs, childRel, out);
    else if (ent.isFile()) out.push(childRel);
  }
  return out;
}

/** `{ 'rel/path': sha256 }` for every selected path (a file or a directory) under plainDir. */
function _snapshotHashSelection(plainDir, selections) {
  const hashes = {};
  for (const sel of selections) {
    const abs = path.join(plainDir, sel);
    let st;
    try { st = fs.statSync(abs); } catch { continue; }
    if (st.isDirectory()) {
      for (const rel of _snapshotListFiles(abs, sel === '.' ? '' : sel, []).sort()) {
        try { hashes[rel] = _snapshotHashFile(path.join(plainDir, rel)); } catch { /* vanished mid-walk */ }
      }
    } else if (st.isFile()) {
      try { hashes[sel] = _snapshotHashFile(abs); } catch { /* vanished */ }
    }
  }
  return hashes;
}

/** A relative selection may not escape plainDir nor be absolute; '.' selects the whole tree. */
function _snapshotSelectionSafe(rel) {
  if (typeof rel !== 'string' || !rel || path.isAbsolute(rel)) return false;
  const norm = path.posix.normalize(rel.replace(/\\/g, '/'));
  return norm !== '..' && !norm.startsWith('../') && !norm.startsWith('/');
}

function _snapshotCopy(plainDir, destDir, hashes) {
  for (const rel of Object.keys(hashes)) {
    const src = path.join(plainDir, rel);
    const dest = path.join(destDir, rel);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.copyFileSync(src, dest);
  }
}

function _snapshotHashesEqual(a, b) {
  const ka = Object.keys(a).sort();
  const kb = Object.keys(b).sort();
  if (ka.length !== kb.length) return false;
  for (let i = 0; i < ka.length; i += 1) {
    if (ka[i] !== kb[i] || a[ka[i]] !== b[kb[i]]) return false;
  }
  return true;
}

/**
 * The service behind ctx.captureDataSnapshot. Everything that touches the
 * real registry, locks and directories is injected so a test can drive it
 * against throwaway repositories.
 * @param {{repoIds: string[], selections: Object<string,string[]>, destination: string}} req
 * @param {{repos: Array<object>, dataDir: string, acquireFileLock?: Function,
 *   releaseFileLock?: Function, log?: Function}} env
 * @returns {Promise<{ok: boolean, error?: string, message?: string, snapshot?: object}>}
 */
async function _captureDataSnapshotImpl(req, env) {
  const repoIds = Array.isArray(req && req.repoIds) ? req.repoIds : [];
  const selections = req && req.selections && typeof req.selections === 'object' ? req.selections : {};
  const destination = req && typeof req.destination === 'string' ? req.destination : '';
  const repos = env.repos;
  const acquireFileLock = env.acquireFileLock || _acquireRepoFileLock;
  const releaseFileLock = env.releaseFileLock || _releaseRepoFileLock;
  const log = typeof env.log === 'function' ? env.log : () => {};

  const dataDirReal = _realPathOfExisting(env.dataDir);
  const destReal = destination ? _realPathOfExisting(destination) : '';
  if (!destination || !_pathWithin(destReal, dataDirReal) || destReal === dataDirReal) {
    return { ok: false, error: 'snapshot-destination', message: 'The snapshot destination must lie inside the module data directory.' };
  }
  const unknown = repoIds.filter((id) => !repos.some((d) => d.id === id));
  if (unknown.length) {
    return { ok: false, error: 'snapshot-unknown-repo', message: 'Unknown data source: ' + unknown.join(', ') };
  }
  for (const id of repoIds) {
    const list = selections[id];
    if (!Array.isArray(list) || list.some((rel) => !_snapshotSelectionSafe(rel))) {
      return { ok: false, error: 'snapshot-selection', message: 'Invalid path list for source ' + id };
    }
  }

  // Fixed order: the registry's, never the caller's.
  const ordered = repos.filter((d) => repoIds.includes(d.id));
  const sources = {};
  for (const d of ordered) {
    const plainDir = d.plainDir;
    if (!plainDir || !fs.existsSync(plainDir)) {
      return { ok: false, error: 'snapshot-source-missing', message: 'Source ' + d.id + ' is not cloned.', repoId: d.id };
    }
    const destDir = path.join(destination, d.id);
    const result = await d.lockFn(async () => {
      const fileLock = await acquireFileLock(d.dir);
      if (!fileLock.ok) return { ok: false, error: 'locked', message: 'Another process is syncing ' + d.id + ' - try again in a moment', repoId: d.id };
      try {
        let head = null;
        try {
          const r = await d.gitExecFn(['rev-parse', 'HEAD']);
          if (r && r.code === 0) head = String(r.stdout || '').trim() || null;
        } catch { head = null; }
        let hashes = null;
        for (let attempt = 1; attempt <= _SNAPSHOT_MAX_ATTEMPTS; attempt += 1) {
          const before = _snapshotHashSelection(plainDir, selections[d.id]);
          fs.rmSync(destDir, { recursive: true, force: true });
          fs.mkdirSync(destDir, { recursive: true });
          _snapshotCopy(plainDir, destDir, before);
          const after = _snapshotHashSelection(plainDir, selections[d.id]);
          if (_snapshotHashesEqual(before, after)) { hashes = before; break; }
          log('snapshot ' + d.id + ': input changed during the copy (attempt ' + attempt + ')');
        }
        if (!hashes) {
          fs.rmSync(destDir, { recursive: true, force: true });
          return { ok: false, error: 'snapshot-unstable', message: 'Source ' + d.id + ' kept changing during the copy - repeat once the sync has finished.', repoId: d.id };
        }
        return { ok: true, source: { id: d.id, head, dir: destDir, files: hashes, fileCount: Object.keys(hashes).length } };
      } finally {
        if (!fileLock.noop) releaseFileLock(d.dir);
      }
    });
    if (!result.ok) return result;
    sources[d.id] = result.source;
  }
  return { ok: true, snapshot: { capturedAt: new Date().toISOString(), destination, sources } };
}

/** The bound service one module receives in its ctx. */
function _makeCaptureDataSnapshot(moduleDataDir, log) {
  return (req) => _captureDataSnapshotImpl(req, { repos: DATA_REPOS, dataDir: moduleDataDir, log });
}

function loadModules() {
  const scan = scanModulesDir();
  const disabled = new Set(scan.disabled);

  const modules = [];
  const errors = [];

  // Reproduce the exact pre-refactor error shape: a disabled module that also
  // fails to parse or validate never reaches `errors` — the toggle-back-on
  // affordance lives in scanModulesDir()/handleModulesInstalled instead.
  for (const entry of scan.invalid) {
    if (disabled.has(entry.id)) continue;
    if (entry.kind === 'read-error') {
      errors.push({ id: entry.id, error: entry.errors[0] });
    } else {
      errors.push({ id: entry.id, error: 'invalid manifest: ' + entry.errors.join('; ') });
    }
  }

  for (const item of scan.installed) {
    if (!item.enabled) continue;
    const dirId = item.id;
    const manifest = item.manifest;
    const loaded = { id: dirId, manifest, routes: [] };

    if (manifest.server && manifest.server.entry) {
      try {
        const dataDir = path.join(MODULES_DATA_DIR, dirId);
        fs.mkdirSync(dataDir, { recursive: true });
        const ctx = {
          moduleId: dirId,
          jsonResponse,
          readBody,
          checkOrigin,
          makeLock: _makeChainLock,
          dataDir,
          rootDir: ROOT,
          // The team directory's root (plaintext ds-data, honouring
          // DATA_TIER_0_DIR) and the one frozen-copy service - see
          // _captureDataSnapshotImpl above. Both exist because a module must
          // not re-derive core paths or fake core locks.
          dataTier0Dir: DATA_TIER_0_DIR,
          // Plaintext dir of a repo this module declares in dataRepos[], or
          // null (undeclared, unknown). See _moduleDataRepoDir. For an
          // `access: 'read'` entry the dir is READ-ONLY by contract, and ctx
          // carries no repo lock, so a write here can race clear-plaintext.
          dataRepoDir: (name) => _moduleDataRepoDir(manifest, name),
          captureDataSnapshot: _makeCaptureDataSnapshot(dataDir, (...args) => console.log('[module:' + dirId + ']', ...args)),
          log: (...args) => console.log('[module:' + dirId + ']', ...args),
        };
        const reg = require(path.join(MODULES_DIR, dirId, manifest.server.entry));
        const regResult = reg(ctx);
        if (regResult && Array.isArray(regResult.routes)) {
          loaded.routes = regResult.routes;
        }
      } catch (e) {
        errors.push({ id: dirId, error: 'server entry failed: ' + e.message });
        continue;
      }
    }

    modules.push(loaded);
    console.log('[modules] loaded:', dirId);
  }

  return { modules, errors };
}

function handleModulesManifest(_req, res) {
  const out = _loadedModules.modules.map(m => ({
    id: m.id,
    manifest: m.manifest,
  }));
  jsonResponse(res, 200, {
    modules: out,
    errors: _loadedModules.errors,
    modulesDir: MODULES_DIR,
  });
}

function handleModuleRoute(req, res, urlPath) {
  const withoutPrefix = urlPath.slice('/api/m/'.length); // e.g. "fixture-mod/ping"
  const slashIdx = withoutPrefix.indexOf('/');
  const moduleId = slashIdx === -1 ? withoutPrefix : withoutPrefix.slice(0, slashIdx);
  const subPath = slashIdx === -1 ? '/' : withoutPrefix.slice(slashIdx); // e.g. "/ping"
  const method = req.method;

  const loaded = _loadedModules.modules.find(m => m.id === moduleId);
  if (!loaded) {
    jsonResponse(res, 404, { error: 'not-found', message: 'Unknown module: ' + moduleId });
    return;
  }

  // CSRF check for non-GET/HEAD requests.
  if (method !== 'GET' && method !== 'HEAD') {
    if (!checkOrigin(req, res)) return;
  }

  // Exact match wins over prefix routes.
  let route = loaded.routes.find(r => r.method === method && r.path === subPath);

  // Prefix match: a route with path ending in `/*` where the prefix (without the `*`)
  // is a prefix of subPath. e.g. route.path="/x/*" matches subPath="/x/a/b".
  // The LONGEST prefix wins, never the registration order: a module that
  // registers "/*" before "/files/*" must still reach the second for /files/a.
  if (!route) {
    const prefixRoutes = loaded.routes
      .filter(r => typeof r.path === 'string' && r.path.endsWith('/*'))
      .sort((a, b) => b.path.length - a.path.length);
    for (const r of prefixRoutes) {
      if (r.method !== method) continue;
      if (typeof r.path !== 'string' || !r.path.endsWith('/*')) continue;
      const pfx = r.path.slice(0, -1); // strip trailing `*`, keeps the slash e.g. "/x/"
      if (subPath === pfx.slice(0, -1) || subPath.startsWith(pfx)) {
        // Remainder after the prefix slash, e.g. subPath="/x/a/b" pfx="/x/" -> rest="a/b"
        const rest = subPath.startsWith(pfx) ? subPath.slice(pfx.length) : '';
        // Reject path-traversal attempts. Backslash counts as a separator too:
        // a module handler may path.join() the rest on Windows.
        let decoded;
        try { decoded = decodeURIComponent(rest); } catch { decoded = rest; }
        if (decoded.split(/[\\/]/).some(seg => seg === '..')) {
          jsonResponse(res, 400, { error: 'invalid-path', message: 'Path traversal not allowed' });
          return;
        }
        req.moduleRest = decoded;
        route = r;
        break;
      }
    }
  }

  if (!route) {
    jsonResponse(res, 404, { error: 'not-found', message: 'No route ' + method + ' ' + subPath + ' in module ' + moduleId });
    return;
  }

  dispatch(route.handler, req, res);
}

// ── Modules: management ──────────────────────────────────────────────────────
// Settings > Modules backs onto these five routes. See the header comment
// above for the endpoint list. All writes go through withModulesLock so
// toggle/remove/import (registry + tree) never interleave.

// -- Module catalog (local folder or GitLab API) -------------------------------
// A curated catalog of installable modules: catalog.json + modules/<id>/,
// same shape as modules-template/ (contract: catalog-repo-template/README.md).
// By default it is the local folder catalog/ in this repository
// (MODULES_CATALOG_DIR); a team that hosts a shared catalog on GitLab sets
// MODULES_CATALOG_REPO_URL and it is then read through the REST API only -
// never cloned, never pushed to (publishing opens a merge request).
//
//   GET  /api/modules/catalog[?force=1] -> curated + scanned entries
//   POST /api/modules/catalog/migrate-areas -> backfills `area` (curl only; an MR on GitLab)
//   POST /api/modules/install           -> copies one module into modules/<id>/

const MODULES_CATALOG_REF = process.env.MODULES_CATALOG_REF || 'main';
const MODULES_CATALOG_TTL_MS = 5 * 60 * 1000;
// A local catalog is a folder on this disk: re-reading it costs a few
// milliseconds, so its snapshot is kept just long enough to absorb a burst of
// readers (the Catalog section, the update banner, the publish gate).
const MODULES_CATALOG_LOCAL_TTL_MS = 2000;
const MODULES_CATALOG_TIMEOUT_MS = 8000;
// Writes carry the whole module in one commit action (up to
// MODULES_PUBLISH_MAX_BYTES), so they get their own budget: the 8 s read
// timeout answered HTTP 0 on a 214-file module after GitLab
// had already started processing the commit. Reads keep the short one so a
// machine with no network still fails fast.
const MODULES_CATALOG_WRITE_TIMEOUT_MS = 90000;

// Limits are checked BEFORE anything reaches disk - an unbounded install
// could otherwise fill the disk from a single hostile (or merely huge) entry.
// The file COUNT is the looser of the two guards on purpose: a module that
// ships its test fixtures (e.g. 214 files, 135 of them fixtures)
// is a normal module, and the byte limits below are what actually bound the
// disk. Publish and install share one number (MODULES_PUBLISH_MAX_FILES
// below) - a module the catalog accepts must be one every machine can install.
const MODULES_INSTALL_MAX_FILES = 400;
const MODULES_INSTALL_MAX_FILE_BYTES = 2 * 1024 * 1024;
const MODULES_INSTALL_MAX_TOTAL_BYTES = 20 * 1024 * 1024;

// The configured catalog repo, or the canonical one - same pattern as
// dataTier0RemoteUrl(). A DEFAULT rather than a required setting because the
// URL is the same for the whole team; MODULES_CATALOG_REPO_URL still wins, so
// a fork can point elsewhere. Declared as a function (hoisted), so the
// 'modules' row in GITLAB_TOKEN_TARGETS above can call it from resolveUrl().
function modulesCatalogRepoUrl() {
  const raw = String(process.env.MODULES_CATALOG_REPO_URL || '').trim();
  return _sshToHttps(raw || MODULES_CATALOG_CANONICAL_URL);
}

function modulesCatalogProjectPath() {
  return _gitlabPathFromRemote(modulesCatalogRepoUrl());
}

/** GitLab wants the file path fully percent-encoded, slashes included. */
function _modulesCatalogFileRawUrl(filePath, ref = MODULES_CATALOG_REF) {
  return `${_gitlabApiBase()}/projects/${encodeURIComponent(modulesCatalogProjectPath())}` +
    `/repository/files/${encodeURIComponent(filePath)}/raw?ref=${encodeURIComponent(ref)}`;
}

/**
 * The project itself, not a resource inside it - the visibility probe below
 * asks this URL once whenever a resource read answered 404.
 */
function _modulesCatalogProjectUrl() {
  return `${_gitlabApiBase()}/projects/${encodeURIComponent(modulesCatalogProjectPath())}`;
}

/** @param {{recursive?: boolean, page?: number, ref?: string}} [opts] */
function _modulesCatalogTreeUrl(dirPath, opts) {
  const recursive = opts && opts.recursive ? '&recursive=true' : '';
  const page = (opts && opts.page) || 1;
  return `${_gitlabApiBase()}/projects/${encodeURIComponent(modulesCatalogProjectPath())}` +
    `/repository/tree?path=${encodeURIComponent(dirPath)}&per_page=100` +
    `&ref=${encodeURIComponent((opts && opts.ref) || MODULES_CATALOG_REF)}${recursive}&page=${page}`;
}

// -- Catalog source: local folder (default) or GitLab REST (opt-in) ---------
// Mission Deck keeps its module catalog "under one roof": `catalog/` next to
// this file holds catalog.json and modules/<id>/, and that folder is the
// DEFAULT source. A team that hosts a shared catalog on GitLab opts in by
// setting MODULES_CATALOG_REPO_URL; only then does any read leave this disk.
//
// The two sources share one contract. Every catalog read in this file builds
// a GitLab REST URL (_modulesCatalogFileRawUrl, _modulesCatalogTreeUrl,
// _modulesCatalogCommitsUrl, the project probe, the branch head) and hands it
// to _modulesCatalogGet / _modulesCatalogGetBinary. In local mode those two
// getters answer the SAME URL from the folder, in the same
// {ok, status, text, headers} shape GitLab would give - so the crawl, the
// install, the drift scan, the reconcile and the publish tree read run
// unchanged, and their unit tests (which inject their own getFn) do not care
// which source is live. Local specifics:
//   - there is one revision: `ref` is ignored, the commit list of a path is
//     one pseudo-commit (LOCAL_CATALOG_COMMIT) and the branch head is unknown
//     (404 -> _modulesCatalogHeadSha answers null, nothing is pinned);
//   - there are no merge requests: every merge_requests list is empty, so the
//     MR chip and "pending publishes" answer an empty list;
//   - writes never go through _modulesCatalogPostJson: a local publish copies
//     the module into catalog/modules/<id>/ and upserts catalog.json
//     (_modulesPublishLocal), which the person then commits or PRs normally.

const LOCAL_CATALOG_COMMIT = 'local';

/** 'gitlab' when MODULES_CATALOG_REPO_URL is set, 'local' otherwise. Read live, .env reloads apply. */
function modulesCatalogMode() {
  return String(process.env.MODULES_CATALOG_REPO_URL || '').trim() ? 'gitlab' : 'local';
}

function _modulesCatalogIsLocal() {
  return modulesCatalogMode() === 'local';
}

/** Absolute path of the local catalog folder (MODULES_CATALOG_DIR, default <repo>/catalog). */
function modulesCatalogDir() {
  const raw = String(process.env.MODULES_CATALOG_DIR || '').trim();
  return path.resolve(raw ? path.resolve(ROOT, raw) : path.join(ROOT, 'catalog'));
}

/**
 * The value every catalog cache is keyed by: the token in GitLab mode (a vault
 * unlock is a cache miss), the folder in local mode. Never empty in local
 * mode, which is also what makes `_modulesCatalogReady()` true there.
 */
function _modulesCatalogCredential() {
  return _modulesCatalogIsLocal() ? 'local:' + modulesCatalogDir() : MODULES_CATALOG_TOKEN;
}

/** True when the catalog can be read at all: always in local mode, with a token in GitLab mode. */
function _modulesCatalogReady() {
  return Boolean(_modulesCatalogCredential());
}

function _modulesCatalogTtlMs() {
  return _modulesCatalogIsLocal() ? MODULES_CATALOG_LOCAL_TTL_MS : MODULES_CATALOG_TTL_MS;
}

/** Where the catalog comes from, for the UI: `{ mode, location }` (a repo-relative folder or the repo URL). */
function modulesCatalogSourceInfo() {
  if (_modulesCatalogIsLocal()) {
    const dir = modulesCatalogDir();
    const rel = path.relative(ROOT, dir);
    const location = (rel && !rel.startsWith('..') && !path.isAbsolute(rel) ? rel : dir).split(path.sep).join('/') + '/';
    return { mode: 'local', location };
  }
  return { mode: 'gitlab', location: modulesCatalogRepoUrl() };
}

/**
 * A repo path ('catalog.json', 'modules/<id>/...') resolved inside the local
 * catalog folder, or null when it would escape it. Pure apart from path math.
 * @param {string} repoPath
 * @param {string} [root]
 * @returns {string|null}
 */
function _localCatalogResolve(repoPath, root = modulesCatalogDir()) {
  const rel = String(repoPath || '').replace(/^\/+|\/+$/g, '');
  if (rel.includes('\0') || rel.includes('\\')) return null;
  if (rel.split('/').some((s) => s === '..')) return null;
  const abs = path.resolve(root, rel);
  if (abs !== root && !abs.startsWith(root + path.sep)) return null;
  return abs;
}

/**
 * GitLab-shaped tree rows for one folder of the local catalog. Entries a
 * publish never sends (_isModuleJunkEntry: dotfiles, node_modules, caches)
 * are left out, so the local tree is exactly what a publish wrote and an
 * install may copy. A symbolic link is listed with git's link mode so that
 * sanitizeModuleTreePath refuses it, as it would on GitLab.
 * @returns {object[]|null} null when the folder does not exist
 */
function _localCatalogTree(root, dirPath, recursive) {
  const absDir = _localCatalogResolve(dirPath, root);
  if (!absDir) return null;
  let st;
  try { st = fs.statSync(absDir); } catch { return null; }
  if (!st.isDirectory()) return null;
  const base = String(dirPath || '').replace(/^\/+|\/+$/g, '');
  const items = [];
  (function walk(abs, rel) {
    let list;
    try { list = fs.readdirSync(abs, { withFileTypes: true }); } catch { return; }
    list.sort((a, b) => (a.name < b.name ? -1 : (a.name > b.name ? 1 : 0)));
    for (const e of list) {
      if (_isModuleJunkEntry(e.name)) continue;
      const repoPath = rel ? rel + '/' + e.name : e.name;
      const absPath = path.join(abs, e.name);
      let lst;
      try { lst = fs.lstatSync(absPath); } catch { continue; }
      if (lst.isSymbolicLink()) {
        items.push({ id: '', name: e.name, type: 'blob', path: repoPath, mode: '120000' });
      } else if (lst.isDirectory()) {
        items.push({ id: '', name: e.name, type: 'tree', path: repoPath, mode: '040000' });
        if (recursive) walk(absPath, repoPath);
      } else if (lst.isFile()) {
        let id = '';
        try { id = gitBlobSha(_moduleFileLf(repoPath, fs.readFileSync(absPath))); } catch { /* unreadable: no id */ }
        items.push({ id, name: e.name, type: 'blob', path: repoPath, mode: (lst.mode & 0o111) ? '100755' : '100644' });
      }
    }
  })(absDir, base);
  return items;
}

function _localCatalogAnswer(status, body, headers) {
  const text = typeof body === 'string' ? body : JSON.stringify(body);
  // The one Headers method every catalog reader calls, case-insensitive like the real one.
  const map = new Map(Object.entries(headers || {}).map(([k, v]) => [k.toLowerCase(), String(v)]));
  const headerView = { get: (name) => (map.has(String(name).toLowerCase()) ? map.get(String(name).toLowerCase()) : null) };
  return { ok: status >= 200 && status < 300, status, text, headers: headerView };
}

/**
 * Answers one catalog REST URL from the local folder. The URL is the one the
 * GitLab builders above produce; only its path after `/projects/<project>`
 * and its query matter. Pure apart from reading the folder; never throws.
 * @param {string} url
 * @param {{binary?: boolean, root?: string}} [opts]
 * @returns {{ok: boolean, status: number, text: string, headers: {get: Function}, buffer?: Buffer}}
 */
function localCatalogRead(url, opts = {}) {
  const root = opts.root || modulesCatalogDir();
  let parsed;
  try { parsed = new URL(String(url)); } catch { return _localCatalogAnswer(400, { message: 'bad url' }); }
  const p = parsed.pathname;
  const at = p.indexOf('/projects/');
  if (at === -1) return _localCatalogAnswer(404, { message: '404 Not Found' });
  const afterProject = p.slice(at + '/projects/'.length);
  const slash = afterProject.indexOf('/');
  const rest = slash === -1 ? '' : afterProject.slice(slash + 1);
  let rootOk = false;
  try { rootOk = fs.statSync(root).isDirectory(); } catch { rootOk = false; }

  if (rest === '') return rootOk ? _localCatalogAnswer(200, { id: 0, path_with_namespace: 'local/catalog' }) : _localCatalogAnswer(404, { message: '404 Project Not Found' });
  if (!rootOk) return _localCatalogAnswer(404, { message: '404 Not Found' });

  if (rest.startsWith('merge_requests')) return _localCatalogAnswer(200, [], { 'x-total': '0' });
  if (rest === 'repository/branches') return _localCatalogAnswer(200, []);

  const raw = rest.match(/^repository\/files\/([^/]+)\/raw$/);
  if (raw) {
    let filePath;
    try { filePath = decodeURIComponent(raw[1]); } catch { return _localCatalogAnswer(404, { message: '404 File Not Found' }); }
    const abs = _localCatalogResolve(filePath, root);
    if (!abs) return _localCatalogAnswer(404, { message: '404 File Not Found' });
    let st;
    try { st = fs.lstatSync(abs); } catch { return _localCatalogAnswer(404, { message: '404 File Not Found' }); }
    if (!st.isFile()) return _localCatalogAnswer(404, { message: '404 File Not Found' });
    let buf;
    try { buf = _moduleFileLf(filePath, fs.readFileSync(abs)); } catch { return _localCatalogAnswer(500, { message: 'read failed' }); }
    const answer = _localCatalogAnswer(200, opts.binary ? '' : buf.toString('utf8'));
    if (opts.binary) answer.buffer = buf;
    return answer;
  }

  if (rest === 'repository/tree') {
    const page = parseInt(parsed.searchParams.get('page') || '1', 10) || 1;
    const items = _localCatalogTree(root, parsed.searchParams.get('path') || '', parsed.searchParams.get('recursive') === 'true');
    if (items === null) return _localCatalogAnswer(404, { message: '404 Tree Not Found' });
    // One page holds everything; a later page (never asked for) is empty.
    return _localCatalogAnswer(200, page === 1 ? items : [], { 'x-total': String(items.length) });
  }

  if (rest === 'repository/commits') {
    const abs = _localCatalogResolve(parsed.searchParams.get('path') || '', root);
    if (!abs || !fs.existsSync(abs)) return _localCatalogAnswer(200, []);
    return _localCatalogAnswer(200, [{ id: LOCAL_CATALOG_COMMIT, title: 'local catalog' }]);
  }

  return _localCatalogAnswer(404, { message: '404 Not Found' });
}

/**
 * One text-mode fetch against the catalog repo. Never throws, never puts the
 * token's value into the returned object - only the fields on this explicit
 * shape leave the function, same discipline as _activityFetchProjectTokens.
 * In local mode the same URL is answered from the catalog folder.
 * @returns {Promise<{ok: boolean, status: number, text: string, headers?: Headers}>}
 */
async function _modulesCatalogGet(url) {
  if (_modulesCatalogIsLocal()) return localCatalogRead(url);
  try {
    const r = await fetch(url, {
      headers: { 'PRIVATE-TOKEN': MODULES_CATALOG_TOKEN },
      signal: AbortSignal.timeout(MODULES_CATALOG_TIMEOUT_MS),
    });
    _infraNoteFetch(null, 'catalog', r.status);
    const text = await r.text().catch(() => '');
    return { ok: r.ok, status: r.status, text, headers: r.headers };
  } catch (e) {
    _infraNoteFetch(e, 'catalog');
    return { ok: false, status: 0, text: '' };
  }
}

/**
 * What a GitLab 404 on a catalog resource really means, decided from ONE
 * follow-up request: `GET /projects/<encoded-path>` with the same token.
 * GitLab hides a private project from a caller that may not see it (a
 * request from outside the group's IP allowlist - no VPN - or a token
 * without access) by answering 404, not 403, so a 404 on `catalog.json` or
 * on the `modules/` tree is ambiguous between "the repo has nothing there
 * yet" and "this caller cannot see the repo at all". The probe resolves it:
 *   200        -> 'empty'     the project is visible, the resource is absent.
 *   403, 404   -> 'no-access' the project itself is invisible to this token.
 *   anything   -> 'unknown'   401 (the token was rejected outright), 0
 *                             (timeout / network), 429, 5xx: the probe did
 *                             not answer, so neither promise nor empty list.
 * A 401 says nothing about WHY the token was rejected: with the group's IP
 * allowlist on, a missing VPN gets one too. That ambiguity is not resolved
 * here - it is carried by the register's `refused` state (_infraNoteFetch)
 * and named in the copy, VPN first and token second.
 * Pure: no I/O, no fetch - the caller hands in the probe's status.
 * @param {number} probeStatus HTTP status of the project probe (0 = no answer)
 * @returns {{ verdict: 'empty' | 'no-access' | 'unknown' }}
 */
function classifyGitlab404(probeStatus) {
  if (probeStatus === 200) return { verdict: 'empty' };
  if (probeStatus === 403 || probeStatus === 404) return { verdict: 'no-access' };
  return { verdict: 'unknown' };
}

const MODULES_CATALOG_NO_ACCESS_MESSAGE =
  'No access to the module catalog repository - most often the VPN is off. If the VPN is on, check the permissions of the COCKPIT_MODULES_TOKEN token.';

/**
 * The visibility probe: one request on _modulesCatalogProjectUrl(), classified
 * by classifyGitlab404. Same discipline as _modulesCatalogGet - nothing is
 * logged and only the verdict leaves; no text, no headers, no status.
 *
 * THE RULE for where this is called: only where a 404 is the FIRST answer
 * GitLab gave in the current call. Once a read in the same call has answered
 * 200 (the tree listing before the per-module `module.json` reads in
 * _modulesCatalogRefresh, the tree read before the binary downloads in
 * handleModulesInstall, the tree read before `catalog.json` in
 * handleModulesPublish), the project is proven visible and a later 404
 * really is "absent" - do not add a fourth probe there.
 * @param {(url: string) => Promise<{ok: boolean, status: number}>} [getFn]
 *   defaults to _modulesCatalogGet; injectable so tests can stub GitLab.
 * @returns {Promise<{ verdict: 'empty' | 'no-access' | 'unknown' }>}
 */
async function _modulesCatalogProbeVerdict(getFn = _modulesCatalogGet) {
  const r = await getFn(_modulesCatalogProjectUrl());
  return classifyGitlab404(r ? r.status : 0);
}

/**
 * All pages of a catalog repo tree listing, or a clear failure — never a
 * partial list mistaken for a complete one. Shared by publish (which computes
 * existingPaths and therefore deletes from it) and install (which downloads
 * exactly this list): an incomplete page 2+, a non-array body or a page count
 * that disagrees with `x-total` all collapse to `ok: false`, because
 * create/update/delete all depend on this being the WHOLE tree. A 404 on
 * page 1 is ambiguous - "the module is new" or "this caller cannot see the
 * project" - and is resolved by _modulesCatalogProbeVerdict (through the same
 * injected getFn): `empty` keeps the ok:true empty list, `no-access` answers
 * `reason: 'no-access'`, `unknown` falls into `tree-incomplete`. A 404 on a
 * later page means the listing broke mid-walk on a project that was visible
 * a moment ago, so it gets no probe and must refuse rather than silently
 * truncate.
 * @param {string} dirPath repo path, e.g. 'modules/<id>'
 * @param {(url: string) => Promise<{ok: boolean, status: number, text: string, headers?: {get: Function}}>} [getFn]
 *   defaults to _modulesCatalogGet; injectable so tests can stub GitLab.
 * @returns {Promise<{ok: true, status: number, items: object[]} | {ok: false, status: number, reason: string}>}
 */
async function _modulesCatalogTreeAll(dirPath, getFn = _modulesCatalogGet, opts = {}) {
  const items = [];
  let page = 1;
  for (;;) {
    const r = await getFn(_modulesCatalogTreeUrl(dirPath, { recursive: true, page, ref: opts && opts.ref }));
    if (r.status === 404) {
      if (page === 1) {
        const { verdict } = await _modulesCatalogProbeVerdict(getFn);
        if (verdict === 'empty') return { ok: true, status: r.status, items: [] };
        if (verdict === 'no-access') return { ok: false, status: r.status, reason: 'no-access' };
      }
      return { ok: false, status: r.status, reason: 'tree-incomplete' };
    }
    if (!r.ok) return { ok: false, status: r.status, reason: 'tree-incomplete' };
    let pageItems;
    try { pageItems = JSON.parse(r.text); } catch { return { ok: false, status: r.status, reason: 'tree-incomplete' }; }
    if (!Array.isArray(pageItems)) return { ok: false, status: r.status, reason: 'tree-incomplete' };
    items.push(...pageItems);
    const headerGet = (name) => (r.headers && r.headers.get ? r.headers.get(name) : null);
    const next = headerGet('x-next-page');
    const nextPage = next ? parseInt(next, 10) : 0;
    if (!nextPage) {
      const totalHeader = headerGet('x-total');
      if (totalHeader) {
        const totalNum = parseInt(totalHeader, 10);
        if (Number.isFinite(totalNum) && totalNum !== items.length) {
          return { ok: false, status: r.status, reason: 'tree-incomplete' };
        }
      }
      return { ok: true, status: r.status, items };
    }
    page = nextPage;
  }
}

/** Commits that touched one catalog file, newest first (GitLab REST). */
function _modulesCatalogCommitsUrl(filePath, ref = MODULES_CATALOG_REF) {
  return `${_gitlabApiBase()}/projects/${encodeURIComponent(modulesCatalogProjectPath())}` +
    `/repository/commits?ref_name=${encodeURIComponent(ref)}&path=${encodeURIComponent(filePath)}&per_page=100`;
}

const MODULES_RECONCILE_MAX_COMMITS = 100;

/**
 * The commit the catalog branch points at right now (GitLab REST), so one
 * install reads its tree AND every file at that one sha - `main` may move
 * during a two-minute download - and can record exactly what it installed.
 * Never throws; null when the branch cannot be read (the caller then falls
 * back to the branch name, the behaviour before this pin).
 * @returns {Promise<string|null>}
 */
async function _modulesCatalogHeadSha(getFn = _modulesCatalogGet) {
  try {
    const r = await getFn(`${_modulesCatalogProjectUrl()}/repository/branches/${encodeURIComponent(MODULES_CATALOG_REF)}`);
    if (!r || !r.ok) return null;
    const doc = JSON.parse(r.text);
    const sha = doc && doc.commit && doc.commit.id;
    return typeof sha === 'string' && /^[0-9a-f]{40,64}$/.test(sha) ? sha : null;
  } catch {
    return null;
  }
}

/**
 * The catalog commit whose modules/<id>/module.json carries `version`.
 * Newest first, so a version published twice resolves to the latest.
 * @returns {Promise<{ok: true, sha: string, manifestText: string} | {ok: false, reason: 'not-in-catalog'|'version-not-found'|'gitlab-unreachable'}>}
 */
async function _modulesCatalogCommitForVersion(id, version, getFn = _modulesCatalogGet) {
  const manifestPath = 'modules/' + id + '/module.json';
  let r;
  try { r = await getFn(_modulesCatalogCommitsUrl(manifestPath)); } catch { return { ok: false, reason: 'gitlab-unreachable' }; }
  if (r.status === 404) return { ok: false, reason: 'not-in-catalog' };
  if (!r.ok) return { ok: false, reason: 'gitlab-unreachable' };
  let commits;
  try { commits = JSON.parse(r.text); } catch { return { ok: false, reason: 'gitlab-unreachable' }; }
  if (!Array.isArray(commits)) return { ok: false, reason: 'gitlab-unreachable' };
  if (commits.length === 0) return { ok: false, reason: 'not-in-catalog' };
  const want = String(version).trim();
  for (const c of commits.slice(0, MODULES_RECONCILE_MAX_COMMITS)) {
    if (!c || typeof c.id !== 'string') continue;
    let m;
    try { m = await getFn(_modulesCatalogFileRawUrl(manifestPath, c.id)); } catch { return { ok: false, reason: 'gitlab-unreachable' }; }
    if (!m.ok) {
      if (m.status === 404) continue;
      return { ok: false, reason: 'gitlab-unreachable' };
    }
    let doc;
    try { doc = JSON.parse(m.text); } catch { continue; }
    if (doc && String(doc.version === undefined || doc.version === null ? '' : doc.version).trim() === want) {
      // nextSha: the newer module.json commit that moved the version on (null
      // when this version is still current) - the upper bound of the range in
      // which the catalog may have changed OTHER files without a version bump.
      const prev = commits[commits.indexOf(c) - 1];
      return { ok: true, sha: c.id, manifestText: m.text, nextSha: prev && typeof prev.id === 'string' ? prev.id : null };
    }
  }
  return { ok: false, reason: 'version-not-found' };
}

const MODULES_RECONCILE_MAX_TREES = 6;

/**
 * Catalog commits that may hold the tree of one version, newest first: the
 * commits touching modules/<id>/ after `found.sha` (where module.json got the
 * version) and before `found.nextSha` (where it moved on). A publish that
 * fixed a file without bumping the version (e.g. line endings, catalog
 * commit 30c556e for one module's 0.8.3) lands there, and an install made
 * after it carries THAT tree - comparing only with `found.sha` reported a
 * file the person never touched as a local change. Never throws.
 * @returns {Promise<string[]>} shas, excluding found.sha itself
 */
async function _modulesCatalogVersionRangeShas(id, found, getFn = _modulesCatalogGet) {
  try {
    const r = await getFn(_modulesCatalogCommitsUrl('modules/' + id));
    if (!r || !r.ok) return [];
    const commits = JSON.parse(r.text);
    if (!Array.isArray(commits)) return [];
    const ids = commits.map((c) => (c && typeof c.id === 'string' ? c.id : null));
    const end = ids.indexOf(found.sha);
    if (end <= 0) return [];
    const start = found.nextSha ? ids.indexOf(found.nextSha) + 1 : 0;
    if (found.nextSha && start === 0) return [];
    return ids.slice(start, end).filter(Boolean);
  } catch {
    return [];
  }
}

/** Binary variant for downloading a module's files during install. */
async function _modulesCatalogGetBinary(url) {
  if (_modulesCatalogIsLocal()) {
    const r = localCatalogRead(url, { binary: true });
    return r.ok ? { ok: true, status: r.status, buffer: r.buffer } : { ok: false, status: r.status };
  }
  try {
    const r = await fetch(url, {
      headers: { 'PRIVATE-TOKEN': MODULES_CATALOG_TOKEN },
      signal: AbortSignal.timeout(MODULES_CATALOG_TIMEOUT_MS),
    });
    if (!r.ok) return { ok: false, status: r.status };
    const buffer = Buffer.from(await r.arrayBuffer());
    return { ok: true, status: r.status, buffer };
  } catch {
    return { ok: false, status: 0 };
  }
}

const MODULES_CATALOG_STATUSES = new Set(MODULE_STATUSES);

/**
 * Validate + normalize a parsed catalog.json. Pure - no I/O.
 * @param {string} text raw file contents
 * @returns {{ok: true, modules: object[]} | {ok: false, error: string}}
 */
function parseModulesCatalog(text) {
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    return { ok: false, error: 'invalid JSON: ' + e.message };
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return { ok: false, error: 'catalog is not an object' };
  }
  if (parsed.schemaVersion !== 1) {
    return { ok: false, error: 'unknown schemaVersion: ' + parsed.schemaVersion + ' (expected 1)' };
  }
  if (!Array.isArray(parsed.modules)) {
    return { ok: false, error: 'modules must be an array' };
  }

  const modules = [];
  for (const entry of parsed.modules) {
    if (!entry || typeof entry !== 'object') continue;
    if (typeof entry.id !== 'string' || !MODULE_ID_RE.test(entry.id)) continue;
    const status = entry.status === undefined ? 'stable' : entry.status;
    if (!MODULES_CATALOG_STATUSES.has(status)) continue;
    if (entry.featured !== undefined && typeof entry.featured !== 'boolean') continue;
    if (entry.order !== undefined && typeof entry.order !== 'number') continue;
    if (entry.author !== undefined && typeof entry.author !== 'string') continue;
    if (entry.tags !== undefined && (!Array.isArray(entry.tags) || entry.tags.some(t => typeof t !== 'string'))) continue;
    if (entry.summary !== undefined && typeof entry.summary !== 'string') continue;
    // area is OPTIONAL in the curation, unlike everywhere else it appears: a
    // bad type is a field to DROP, never a reason to `continue` and drop the
    // whole entry (see plan Risks - that pattern here would delete every
    // older remote catalog entry the moment area started being checked).
    const area = typeof entry.area === 'string' ? normalizeModuleArea(entry.area) : '';
    modules.push({
      id: entry.id,
      featured: entry.featured === true,
      order: typeof entry.order === 'number' ? entry.order : 0,
      status,
      author: entry.author || '',
      tags: Array.isArray(entry.tags) ? entry.tags : [],
      summary: entry.summary || '',
      area,
    });
  }
  return { ok: true, modules };
}

/**
 * Combines the curation (catalog.json) with what actually exists in the
 * catalog repo's modules/ tree. Pure - no I/O.
 * @param {object[]} curated output of parseModulesCatalog().modules
 * @param {string[]} treeDirs directory names found under modules/ in the tree
 * @param {Object<string, {ok: true, manifest: object} | {ok: false, error: string}>} manifests
 *        keyed by directory name
 * @returns {{entries: object[], errors: {id: string, error: string}[]}}
 */
function mergeModulesCatalog(curated, treeDirs, manifests) {
  const curatedList = Array.isArray(curated) ? curated : [];
  const dirSet = new Set(Array.isArray(treeDirs) ? treeDirs : []);
  const curatedIds = new Set(curatedList.map(c => c.id));
  const errors = [];

  const curatedEntries = [];
  for (const c of curatedList) {
    if (!dirSet.has(c.id)) {
      errors.push({ id: c.id, error: 'missing-in-modules' });
      continue;
    }
    const m = manifests && manifests[c.id];
    if (!m || !m.ok) {
      errors.push({ id: c.id, error: 'invalid-manifest: ' + ((m && m.error) || 'unknown error') });
      continue;
    }
    // catalog.json is CURATION and wins; the manifest is what the module says
    // about itself and fills the gaps. Curation owns featured/order/status;
    // author, tags and summary exist in both places, so they fall back.
    curatedEntries.push({
      id: c.id,
      curated: true,
      featured: !!c.featured,
      order: c.order || 0,
      status: c.status,
      author: c.author || m.manifest.author || '',
      tags: (c.tags && c.tags.length ? c.tags : m.manifest.tags) || [],
      summary: c.summary || '',
      area: c.area || m.manifest.area || '',
      manifest: m.manifest,
    });
  }
  curatedEntries.sort((a, b) => {
    if (a.featured !== b.featured) return a.featured ? -1 : 1;
    if (a.order !== b.order) return a.order - b.order;
    return a.id < b.id ? -1 : (a.id > b.id ? 1 : 0);
  });

  const uncuratedEntries = [];
  for (const dirId of dirSet) {
    if (curatedIds.has(dirId)) continue;
    const m = manifests && manifests[dirId];
    if (!m || !m.ok) {
      errors.push({ id: dirId, error: 'invalid-manifest: ' + ((m && m.error) || 'unknown error') });
      continue;
    }
    uncuratedEntries.push({
      id: dirId, curated: false, featured: false, order: 0,
      status: MODULE_STATUSES.includes(m.manifest.status) ? m.manifest.status : 'stable',
      author: m.manifest.author || '', tags: m.manifest.tags || [], summary: '',
      area: m.manifest.area || '',
      manifest: m.manifest,
    });
  }

  return { entries: [...curatedEntries, ...uncuratedEntries], errors };
}

/**
 * Whether a single GitLab tree entry may become a file under a module's
 * install directory. An ALLOW-list, not a deny-list: a tree entry is HOSTILE
 * input (a symlink has mode '120000', a submodule has type 'commit', a path
 * can carry '..', '\\' or a null byte). Pure - no I/O; the final path.resolve
 * guard against the real destination directory lives in handleModulesInstall,
 * because only that function knows the temp directory it is writing into.
 * @param {{type?: string, mode?: string, path?: string}} entry a GitLab tree row
 * @param {string} moduleId
 * @returns {{ok: true, relPath: string} | {ok: false, reason: string}}
 */
function sanitizeModuleTreePath(entry, moduleId) {
  if (!entry || entry.type !== 'blob') return { ok: false, reason: 'not-a-file' };
  if (entry.mode !== '100644' && entry.mode !== '100755') return { ok: false, reason: 'unsafe-mode' };
  const fullPath = String(entry.path || '');
  const prefix = 'modules/' + moduleId + '/';
  if (!fullPath.startsWith(prefix)) return { ok: false, reason: 'wrong-prefix' };
  const relPath = fullPath.slice(prefix.length);
  if (!relPath || relPath.startsWith('/') || relPath.includes('\\') || relPath.includes('\0')) {
    return { ok: false, reason: 'unsafe-path' };
  }
  const segments = relPath.split('/');
  if (segments.some(s => s === '..' || s === '.' || s === '')) return { ok: false, reason: 'unsafe-path' };
  if (segments[0].startsWith('.')) return { ok: false, reason: 'dotfile' };
  return { ok: true, relPath };
}

// In-memory cache, one entry, keyed by the token - same pattern as
// _gitlabIdentityCache: a Bitwarden unlock mid-run must never serve a stale
// answer for a different credential. ERRORS are cached too, otherwise a
// machine with no network pays the full MODULES_CATALOG_TIMEOUT_MS on every
// tab open instead of once per TTL window. `data` never carries a `source`
// field - the field is added at response time, once per call site, so a
// cache HIT and a cache MISS can never both claim `source: 'gitlab'`.
let _modulesCatalogCache = { token: null, at: 0, data: null };

const MODULES_CATALOG_NO_TOKEN_MESSAGE =
  'The GitLab module catalog needs the COCKPIT_MODULES_TOKEN token. Create it in Settings > Keys or unlock the vault - or clear MODULES_CATALOG_REPO_URL to use the local catalog folder.';

/**
 * The network half of GET /api/modules/catalog, with no response and no
 * caching of its own - factored out so `handleCocreateModules` (Gallery tab,
 * "-- Academy --" section) can share the exact same fetch + merge
 * logic and the exact same `_modulesCatalogCache` entry instead of running a
 * second GitLab crawl a few minutes apart.
 * @returns {Promise<object>} the `data` shape handleModulesCatalog used to
 *   build inline, unchanged.
 */
// The crawl in progress, keyed by the token it runs under: after an unlock
// the Catalog section, the update banner and the Academy gallery all miss the
// cache in the same second, and each used to start its own GitLab crawl
// (tree listing plus one module.json read per module). One crawl, three
// readers. A failed crawl is not kept - the next caller starts a new one.
let _modulesCatalogInflight = null; // { token, promise }

function _modulesCatalogRefreshShared(now) {
  if (_modulesCatalogInflight && _modulesCatalogInflight.token === _modulesCatalogCredential()) {
    return _modulesCatalogInflight.promise;
  }
  const entry = { token: _modulesCatalogCredential(), promise: null };
  entry.promise = _modulesCatalogRefresh(now).finally(() => {
    if (_modulesCatalogInflight === entry) _modulesCatalogInflight = null;
  });
  _modulesCatalogInflight = entry;
  return entry.promise;
}

async function _modulesCatalogRefresh(now) {
  if (_modulesCatalogIsLocal()) {
    const dir = modulesCatalogDir();
    let present = false;
    try { present = fs.statSync(dir).isDirectory(); } catch { present = false; }
    if (!present) {
      return {
        ok: false, error: 'catalog-missing', tokenConfigured: true, entries: [], errors: [],
        catalogSource: modulesCatalogSourceInfo(),
        message: 'The local module catalog folder was not found (' + modulesCatalogSourceInfo().location
          + '). Restore it, point MODULES_CATALOG_DIR at it, or set MODULES_CATALOG_REPO_URL to use a GitLab catalog.',
      };
    }
  }
  const projectPath = modulesCatalogProjectPath();
  const unreachable = (message) => ({
    ok: false, error: 'gitlab-unreachable', tokenConfigured: true, entries: [], errors: [], message,
  });
  const GITLAB_UNREACHABLE_MESSAGE = 'Could not read the module catalog from GitLab.';
  const noAccess = () => ({
    ok: false, error: 'gitlab-no-access', tokenConfigured: true, entries: [], errors: [],
    projectPath, message: MODULES_CATALOG_NO_ACCESS_MESSAGE,
  });

  // A 404 from GitLab is ambiguous here (see _modulesCatalogProbeVerdict):
  // both 404 branches below ask the visibility probe, and this run asks it
  // AT MOST ONCE - a 404 on catalog.json followed by a 404 on the tree must
  // not cost two requests. Memoized on `=== null`, never on falsiness: the
  // verdict is a string, but the discipline is written down because the
  // probe's underlying status can legitimately be 0 (no answer).
  let probeVerdict = null;
  const probe = async () => {
    if (probeVerdict === null) probeVerdict = (await _modulesCatalogProbeVerdict()).verdict;
    return probeVerdict;
  };

  // catalog.json: absence (404) is not a failure when the project is visible
  // - an empty curation is valid and the list then comes purely from the tree
  // scan below. But GitLab also answers 404 for a project this caller cannot
  // see (no VPN, a token without access), so the 404 is resolved by the probe
  // first: `no-access` names the cause, `unknown` is today's unreachable.
  let curated = [];
  const catalogRes = await _modulesCatalogGet(_modulesCatalogFileRawUrl('catalog.json'));
  if (catalogRes.ok) {
    const parsed = parseModulesCatalog(catalogRes.text);
    if (!parsed.ok) return unreachable(GITLAB_UNREACHABLE_MESSAGE);
    curated = parsed.modules;
  } else if (catalogRes.status === 404) {
    const verdict = await probe();
    if (verdict === 'no-access') return noAccess();
    if (verdict !== 'empty') return unreachable(GITLAB_UNREACHABLE_MESSAGE);
  } else {
    return unreachable(GITLAB_UNREACHABLE_MESSAGE);
  }

  // modules/ tree: immediate subdirectories only, paginated via x-next-page.
  const treeDirs = [];
  {
    let page = 1;
    for (;;) {
      const r = await _modulesCatalogGet(_modulesCatalogTreeUrl('modules', { page }));
      if (r.status === 404) {
        // Page 1: no modules/ dir yet (an empty catalog repo) OR an invisible
        // project - the same ambiguity as catalog.json above, same probe
        // (memoized, so a run that already asked pays nothing here). Page
        // 2+: the project was visible a moment ago, so this is a listing
        // that broke mid-walk - no probe, today's behaviour.
        if (page === 1) {
          const verdict = await probe();
          if (verdict === 'no-access') return noAccess();
          if (verdict !== 'empty') return unreachable(GITLAB_UNREACHABLE_MESSAGE);
        }
        break;
      }
      if (!r.ok) return unreachable(GITLAB_UNREACHABLE_MESSAGE);
      let pageItems;
      try { pageItems = JSON.parse(r.text); } catch { return unreachable(GITLAB_UNREACHABLE_MESSAGE); }
      if (Array.isArray(pageItems)) {
        for (const it of pageItems) {
          if (it && it.type === 'tree' && typeof it.name === 'string') treeDirs.push(it.name);
        }
      }
      const next = r.headers && r.headers.get ? r.headers.get('x-next-page') : '';
      const nextPage = next ? parseInt(next, 10) : 0;
      if (!nextPage) break;
      page = nextPage;
    }
  }

  // module.json for every discovered directory.
  const manifests = {};
  for (const dirId of treeDirs) {
    const mr = await _modulesCatalogGet(_modulesCatalogFileRawUrl('modules/' + dirId + '/module.json'));
    if (!mr.ok) {
      manifests[dirId] = { ok: false, error: 'cannot read module.json (status ' + mr.status + ')' };
      continue;
    }
    let manifest;
    try {
      manifest = JSON.parse(mr.text);
    } catch (e) {
      manifests[dirId] = { ok: false, error: 'invalid JSON: ' + e.message };
      continue;
    }
    const validated = validateModuleManifest(manifest, dirId);
    manifests[dirId] = validated.valid
      ? { ok: true, manifest: validated.manifest }
      : { ok: false, error: validated.errors.join('; ') };
  }

  const { entries, errors } = mergeModulesCatalog(curated, treeDirs, manifests);
  return {
    ok: true, ref: _modulesCatalogIsLocal() ? null : MODULES_CATALOG_REF,
    projectPath: _modulesCatalogIsLocal() ? null : projectPath, tokenConfigured: true,
    catalogSource: modulesCatalogSourceInfo(),
    entries, errors, fetchedAt: new Date(now).toISOString(),
  };
}

/**
 * GET /api/modules/catalog[?force=1] -> { ok, source, entries, errors, ... }.
 * Always 200: a missing token or an unreachable GitLab are normal states for
 * a fresh install, not errors the Settings > Modules tab should ever 5xx on.
 */
async function handleModulesCatalog(req, res) {
  if (!checkOriginNoBody(req, res)) return;

  if (!_modulesCatalogReady()) {
    jsonResponse(res, 200, {
      ok: false, error: 'no-token', tokenConfigured: false, entries: [], errors: [],
      catalogSource: modulesCatalogSourceInfo(),
      message: MODULES_CATALOG_NO_TOKEN_MESSAGE,
    });
    return;
  }

  const reqUrl = new URL(req.url, 'http://localhost');
  const force = reqUrl.searchParams.get('force') === '1';
  const now = Date.now();

  if (!force && _modulesCatalogCache.token === _modulesCatalogCredential()
      && (now - _modulesCatalogCache.at) < _modulesCatalogTtlMs()) {
    jsonResponse(res, 200, { ..._modulesCatalogCache.data, source: 'cache' });
    return;
  }

  const data = await _modulesCatalogRefreshShared(now);
  _modulesCatalogCache = { token: _modulesCatalogCredential(), at: now, data };
  jsonResponse(res, 200, { ...data, source: _modulesCatalogIsLocal() ? 'local' : 'gitlab' });
}

// ── GET /api/merge-requests/counts ──────────────────────────────────────────
// The "MR:" chips on the top bar (`repos[]` shape). Two rows: the GitLab
// module catalog (chip "MC") - every new or updated module reaches the team as
// a merge request there (POST /api/modules/publish opens it, `main` is
// protected), and a request waiting for review is nobody's view - and the
// app's own feedback merge requests (chip "FB"). A LOCAL catalog has no merge
// requests, so its row is left out. The client renders `label` and `webUrl`
// straight from the payload and keeps no list of its own.
//
// Always 200, on the handleGitlabActivityActiveCount pattern: no token is
// the normal state of a fresh install (`error: 'no_token'`, the chip stays
// off the bar), an unreachable GitLab is `error: 'gitlab_error'` and paints
// "-". The count comes from the `x-total` header of a one-item page, so the
// wire carries no MR body at all. Cache keyed by the TOKEN, like every other
// GitLab cache here, so a Bitwarden unlock mid-run is a cache miss and the
// secrets bus needs no bypass parameter; failures are cached too, so a dead
// GitLab costs one timeout per minute and not one per poll.

const MR_COUNTS_TTL_MS = 60000;
const MR_COUNTS_PER_PAGE = 1;

let _mrCountsCache = { token: null, at: 0, data: null };

function _modulesCatalogMergeRequestsUrl() {
  return `${_gitlabApiBase()}/projects/${encodeURIComponent(modulesCatalogProjectPath())}` +
    `/merge_requests?state=opened&per_page=${MR_COUNTS_PER_PAGE}`;
}

/** The browsable list of open MRs on the catalog project, '' when unknown. */
function _modulesCatalogMergeRequestsWebUrl() {
  const base = _gitlabWebUrl(modulesCatalogRepoUrl(), modulesCatalogProjectPath());
  return base ? base + '/-/merge_requests' : '';
}

/**
 * Turn one GitLab `merge_requests?state=opened` answer into the count a chip
 * shows. Pure: takes the shape _modulesCatalogGet returns, never fetches.
 * `x-total` is the truth when GitLab sends it (it always does for a
 * per_page listing under 10 000); without the header the body length is
 * the floor, which for a one-item page is exactly 0 or 1 - honest for an
 * empty list and a lower bound otherwise. A non-ok status, a body that is
 * not an array and a header that is not a number all collapse to
 * `{ count: null, error: 'gitlab_error' }`, so the client has one shape.
 * @param {{ok: boolean, status: number, text: string, headers?: {get: Function}}} r
 * @returns {{count: number|null, error?: string}}
 */
function parseOpenMergeRequestCount(r) {
  if (!r || !r.ok) return { count: null, error: 'gitlab_error' };
  const headerGet = (name) => (r.headers && typeof r.headers.get === 'function' ? r.headers.get(name) : null);
  const total = headerGet('x-total');
  if (total !== null && total !== undefined && String(total).trim() !== '') {
    const n = parseInt(String(total), 10);
    if (Number.isFinite(n) && n >= 0) return { count: n };
    return { count: null, error: 'gitlab_error' };
  }
  let body;
  try { body = JSON.parse(r.text); } catch { return { count: null, error: 'gitlab_error' }; }
  if (!Array.isArray(body)) return { count: null, error: 'gitlab_error' };
  return { count: body.length };
}

async function handleMergeRequestCounts(req, res) {
  if (!checkOriginNoBody(req, res)) return;
  // Two rows, two DIFFERENT tokens and two different projects: the module
  // catalog under MODULES_CATALOG_TOKEN, and this repository's own feedback
  // merge requests (POST /api/feedback/submit) under APP_UPDATE_TOKEN. The
  // client keeps no list of its own - it paints whatever rows arrive and
  // drops the `no_token` ones - so a row is added here and nowhere else.
  // _appRepoGet and the two URL builders live in the Feedback section far
  // below; function declarations hoist and this only ever runs at request
  // time, the same arrangement _stripTokenNameSuffix already relies on.
  const makeEntry = (key, label, shortLabel, webUrl) => (r) => {
    // `shortLabel` is what the chip shows (the old bar said "App" / "KB"),
    // `label` is what its tooltip spells out.
    const entry = { key, label, shortLabel, count: r.count, webUrl };
    if (r.error) entry.error = r.error;
    return entry;
  };
  const makeModules = makeEntry('modules', 'Module catalog', 'MC', _modulesCatalogMergeRequestsWebUrl());
  const makeFeedback = makeEntry('feedback', 'Feedback from the app', 'FB', _appRepoMergeRequestsWebUrl());
  const modulesToken = _modulesCatalogCredential();
  const appToken = APP_UPDATE_TOKEN;
  // One key over BOTH tokens: a vault unlock that brings either one is a
  // miss, so the secrets bus still needs no bypass parameter.
  const cacheKey = modulesToken + '\u0000' + appToken;
  const now = Date.now();
  if (_mrCountsCache.token === cacheKey && (now - _mrCountsCache.at) < MR_COUNTS_TTL_MS) {
    jsonResponse(res, 200, _mrCountsCache.data);
    return;
  }
  const noToken = { count: null, error: 'no_token' };
  // In parallel: the two reads are independent, and in series a dead GitLab
  // would cost two timeouts on one poll.
  const [modulesCount, feedbackCount] = await Promise.all([
    modulesToken && !_modulesCatalogIsLocal()
      ? _modulesCatalogGet(_modulesCatalogMergeRequestsUrl()).then(parseOpenMergeRequestCount)
      : Promise.resolve(noToken),
    appToken
      ? _appRepoGet(_appRepoMergeRequestsUrl()).then(parseOpenMergeRequestCount)
      : Promise.resolve(noToken),
  ]);
  // A local catalog has no merge requests at all, so it gets no chip: the row
  // is left out rather than painted as a permanent "0".
  const repos = _modulesCatalogIsLocal()
    ? [makeFeedback(feedbackCount)]
    : [makeModules(modulesCount), makeFeedback(feedbackCount)];
  const data = { ok: true, repos };
  _mrCountsCache = { token: cacheKey, at: now, data };
  jsonResponse(res, 200, data);
}

// ── GET /api/modules/pending-publishes ──────────────────────────────────────
// Which installed modules already have a publish waiting for review: an OPEN
// merge request on the catalog project whose source branch is the one
// POST /api/modules/publish creates (`module/<id>-<YYYYMMDD-HHMMSS>`,
// modulesPublishBranchName). Settings > Modules reads it so a module that
// was just published stops saying "Needs publishing" while its MR waits -
// the catalog's `main` only moves when somebody merges. Same contract as the
// MR chips above: always 200, `error: 'no_token'` / `'gitlab_error'` instead
// of a failure, 60 s cache keyed by the token (`force=1` bypasses it),
// failures cached too.

const PENDING_PUBLISHES_PER_PAGE = 100;
const PENDING_PUBLISH_BRANCH_RE = /^module\/([a-z0-9][a-z0-9-]*?)-\d{8}-\d{6}$/;

let _pendingPublishesCache = { token: null, at: 0, data: null };

/**
 * Open catalog MRs -> one row per module id (the newest MR wins when a module
 * has two). Pure: takes the shape _modulesCatalogGet returns, never fetches.
 * A branch that is not a publish branch is skipped, never guessed at.
 * @param {{ok: boolean, text: string}} r
 * @returns {{items: Array<{id: string, branch: string, mrUrl: string, title: string, createdAt: string}>, error?: string}}
 */
function parsePendingModulePublishes(r) {
  if (!r || !r.ok) return { items: [], error: 'gitlab_error' };
  let body;
  try { body = JSON.parse(r.text); } catch { return { items: [], error: 'gitlab_error' }; }
  if (!Array.isArray(body)) return { items: [], error: 'gitlab_error' };
  const byId = new Map();
  for (const mr of body) {
    const branch = mr && typeof mr.source_branch === 'string' ? mr.source_branch : '';
    const m = branch.match(PENDING_PUBLISH_BRANCH_RE);
    if (!m) continue;
    const row = {
      id: m[1],
      branch,
      mrUrl: typeof mr.web_url === 'string' ? mr.web_url : '',
      title: typeof mr.title === 'string' ? mr.title : '',
      createdAt: typeof mr.created_at === 'string' ? mr.created_at : '',
    };
    const prev = byId.get(row.id);
    if (!prev || prev.branch < row.branch) byId.set(row.id, row);
  }
  return { items: [...byId.values()].sort((a, b) => a.id.localeCompare(b.id)) };
}

/**
 * Publish MRs MERGED after a given moment -> `[{ id, mergedAt }]` (ms). Pure,
 * same input shape as parsePendingModulePublishes. A merged publish is the one
 * case where the open-MR list and the catalog snapshot disagree: the MR has
 * left `state=opened` at once, while the catalog cache (MODULES_CATALOG_TTL_MS)
 * still holds the pre-merge `main` - so without this the row went back from
 * "Waiting for merge" to "Newer version locally" for up to five minutes.
 * An unreadable answer is an empty list: no merge seen, nothing invalidated.
 * @param {{ok: boolean, text: string}} r
 * @param {number} sinceMs
 * @returns {Array<{id: string, mergedAt: number}>}
 */
function parseMergedModulePublishes(r, sinceMs) {
  if (!r || !r.ok) return [];
  let body;
  try { body = JSON.parse(r.text); } catch { return []; }
  if (!Array.isArray(body)) return [];
  const out = [];
  for (const mr of body) {
    const branch = mr && typeof mr.source_branch === 'string' ? mr.source_branch : '';
    const m = branch.match(PENDING_PUBLISH_BRANCH_RE);
    const mergedAt = mr && typeof mr.merged_at === 'string' ? Date.parse(mr.merged_at) : NaN;
    if (!m || !Number.isFinite(mergedAt) || mergedAt <= sinceMs) continue;
    out.push({ id: m[1], mergedAt });
  }
  return out;
}

/**
 * Open publish MRs a new publish of `id` makes obsolete. Publishing a module
 * twice before the first MR is merged opened two branches off the same `main`;
 * after the newer one merged, the older one conflicted on the version lines
 * (module.json, catalog.json) and stayed open forever (2026-10-07: !96 vs !98).
 * An older MR is closed only when BOTH hold: the local module history has the
 * commit of ITS publish ("publish <version>", _modulePublishLocalCommit)
 * since the tree was last replaced (publishedVersionsFromLog), so the tree just
 * published carries every change it had; and GitLab shows the same author as
 * the MR just opened, so a same-version MR from somebody else's machine never
 * qualifies. Pure. Version comes from the MR description line "- version: `X`".
 * @param {object[]} openMrs GitLab merge_requests?state=opened body
 * @param {string} id module id
 * @param {number} keepIid the MR this publish just opened
 * @param {number|null} authorId GitLab author id of that MR; null = close nothing
 * @param {Set<string>} publishedVersions versions with a local publish commit
 * @returns {Array<{iid: number, branch: string, version: string}>}
 */
function supersededPublishMrs(openMrs, id, keepIid, authorId, publishedVersions) {
  if (!Array.isArray(openMrs) || !publishedVersions || !Number.isInteger(authorId)) return [];
  const out = [];
  for (const mr of openMrs) {
    const branch = mr && typeof mr.source_branch === 'string' ? mr.source_branch : '';
    const m = branch.match(PENDING_PUBLISH_BRANCH_RE);
    if (!m || m[1] !== id || !Number.isInteger(mr.iid) || mr.iid === keepIid) continue;
    if (!mr.author || mr.author.id !== authorId) continue;
    const v = /^- (?:version|wersja): `([^`]+)`$/m.exec(typeof mr.description === 'string' ? mr.description : '');
    if (!v || !publishedVersions.has(v[1])) continue;
    out.push({ iid: mr.iid, branch, version: v[1] });
  }
  return out;
}

/**
 * Versions with a local publish commit, from moduleGitLog() commits (newest
 * first). Stops at the newest commit that REPLACED the tree - an install from
 * the catalog, a zip import, a reconcile with the catalog: a publish before it
 * is still in the history, but its changes may no longer be in the tree. Pure.
 */
function publishedVersionsFromLog(commits) {
  const out = new Set();
  for (const c of Array.isArray(commits) ? commits : []) {
    const subject = (c && c.subject) || '';
    // The legacy subjects are what modules installed before the English
    // rename carry in their history; both spellings mean the same event.
    if (/^(install from catalog|import from zip file|instalacja z katalogu|import z pliku zip)\b|\((reconciled with catalog|uzgodnione z katalogiem)\)$/.test(subject)) break;
    const m = /^(?:publish|publikacja) (\S+)$/.exec(subject);
    if (m) out.add(m[1]);
  }
  return out;
}

/**
 * True when a publish MR was merged after the catalog snapshot was taken, i.e.
 * the cached catalog cannot show that version yet. Pure.
 * @param {Array<{mergedAt: number}>} merged
 * @param {number} catalogAt `_modulesCatalogCache.at`; 0 = no snapshot
 * @returns {boolean}
 */
function catalogStaleAfterMerges(merged, catalogAt) {
  if (!catalogAt || !Array.isArray(merged)) return false;
  return merged.some(m => m && m.mergedAt > catalogAt);
}

/** The pending-publishes body: `merged` stays server-side, `catalogStale` is computed per answer. */
function _pendingPublishesBody(data) {
  const { merged, ...body } = data;
  const stale = _modulesCatalogCache.token === _modulesCatalogCredential()
    && catalogStaleAfterMerges(merged, _modulesCatalogCache.at);
  // Invalidate the shared snapshot, so every reader (Catalog, update banner,
  // publish version gate) crawls `main` again instead of the pre-merge copy.
  // The drift scan picked its candidates off that same snapshot, so it goes too.
  if (stale) {
    _modulesCatalogCache = { token: null, at: 0, data: null };
    _publishDriftGen += 1;
    _publishDriftCache = { token: null, at: 0, data: null };
  }
  return stale ? { ...body, catalogStale: true } : body;
}

async function handleModulesPendingPublishes(req, res) {
  if (!checkOriginNoBody(req, res)) return;
  const token = _modulesCatalogCredential();
  if (!token) {
    jsonResponse(res, 200, { ok: true, items: [], error: 'no_token' });
    return;
  }
  // A local catalog is written in place by a publish: nothing ever waits for review.
  if (_modulesCatalogIsLocal()) {
    jsonResponse(res, 200, { ok: true, items: [], local: true });
    return;
  }
  // `force=1` right after a publish from the tab: the MR it opened must show
  // up at once, not after the cache runs out.
  const force = new URL(req.url, 'http://localhost').searchParams.get('force') === '1';
  const now = Date.now();
  if (!force && _pendingPublishesCache.token === token && (now - _pendingPublishesCache.at) < MR_COUNTS_TTL_MS) {
    jsonResponse(res, 200, _pendingPublishesBody(_pendingPublishesCache.data));
    return;
  }
  const projectApi = `${_gitlabApiBase()}/projects/${encodeURIComponent(modulesCatalogProjectPath())}`;
  const url = `${projectApi}/merge_requests?state=opened&per_page=${PENDING_PUBLISHES_PER_PAGE}`;
  // Merges since the catalog snapshot - asked only while a snapshot exists;
  // without one the next catalog read crawls `main` anyway.
  const catalogAt = _modulesCatalogCache.token === token ? _modulesCatalogCache.at : 0;
  const mergedUrl = catalogAt
    ? `${projectApi}/merge_requests?state=merged&updated_after=${encodeURIComponent(new Date(catalogAt).toISOString())}`
      + `&per_page=${PENDING_PUBLISHES_PER_PAGE}`
    : null;
  const [openRes, mergedRes] = await Promise.all([
    _modulesCatalogGet(url),
    mergedUrl ? _modulesCatalogGet(mergedUrl) : Promise.resolve(null),
  ]);
  const parsed = parsePendingModulePublishes(openRes);
  const merged = parseMergedModulePublishes(mergedRes, catalogAt);
  // The version each MR carries, read off module.json on its own branch: a
  // module whose local version moved past it needs a NEW publish, and the
  // tab must not hide that behind "Waiting for merge". null when unreadable.
  // At most PUBLISH_DRIFT_CONCURRENCY reads at a time, like the drift scan.
  // An unreadable version stays null, which the client reads as "waiting":
  // right after a publish that is the safer guess than offering a second one.
  const queue = parsed.items.slice();
  const worker = async () => {
    while (queue.length) {
      const item = queue.shift();
      const r = await _modulesCatalogGet(_modulesCatalogFileRawUrl('modules/' + item.id + '/module.json', item.branch));
      let version = null;
      if (r.ok) { try { const v = JSON.parse(r.text).version; if (typeof v === 'string') version = v; } catch { /* unreadable */ } }
      item.version = version;
    }
  };
  await Promise.all(Array.from({ length: PUBLISH_DRIFT_CONCURRENCY }, worker));
  const data = { ok: true, items: parsed.items, merged };
  if (parsed.error) data.error = parsed.error;
  _pendingPublishesCache = { token, at: now, data };
  jsonResponse(res, 200, _pendingPublishesBody(data));
}

/**
 * Same token+cache gate as handleModulesCatalog, without the HTTP envelope -
 * shared by two consumers that both need the warm cache without opening a
 * second GitLab crawl: the "-- Academy --" section's module gallery
 * (handleCocreateModules) and GET /api/modules/updates / the publish version
 * gate below (handleModulesUpdates, handleModulesPublish).
 * @returns {Promise<{ok: boolean, entries?: object[], message?: string}>}
 */
async function _modulesCatalogSnapshot({ force = false } = {}) {
  if (!_modulesCatalogReady()) {
    return { ok: false, entries: [], message: MODULES_CATALOG_NO_TOKEN_MESSAGE };
  }
  const now = Date.now();
  if (!force && _modulesCatalogCache.token === _modulesCatalogCredential()
      && (now - _modulesCatalogCache.at) < _modulesCatalogTtlMs()) {
    return _modulesCatalogCache.data;
  }
  const data = await _modulesCatalogRefreshShared(now);
  _modulesCatalogCache = { token: _modulesCatalogCredential(), at: now, data };
  return data;
}

// -- Module updates (banner) --------------------------------------------------
// GET /api/modules/updates joins the installed modules (module.json on disk)
// with the catalog snapshot above (module.json in the catalog) so
// the top-bar update banner can show "a newer version exists" without a person
// opening Settings > Modules > Catalog. Semver lives in ONE place - the ESM
// js/module-updates.mjs, served to the browser too - so this CJS file loads it
// lazily through a dynamic import() exactly like js/academy-stages.mjs
// (see _cocreateStages() below): a missing or broken file degrades to
// reason: 'internal' with an empty list, never a 500.

const MODULE_UPDATES_LIB_PATH = path.join(ROOT, 'js', 'module-updates.mjs');
let _moduleUpdatesLibCache = null;

/**
 * Loads { classifyModuleUpdate, publishVersionGate, ... } from
 * js/module-updates.mjs, once per process (module-level cache - restart the
 * server to pick up an edit). A missing file or a syntax error returns null
 * rather than throwing, so every caller can degrade readably.
 * @returns {Promise<object|null>}
 */
async function _moduleUpdatesLib() {
  if (_moduleUpdatesLibCache) return _moduleUpdatesLibCache;
  try {
    _moduleUpdatesLibCache = await import(pathToFileURL(MODULE_UPDATES_LIB_PATH).href);
  } catch (e) {
    console.warn('[modules] js/module-updates.mjs unavailable:', e.message);
    return null;
  }
  return _moduleUpdatesLibCache;
}

/**
 * A shape check, not a truthiness check: a lib that imported without throwing
 * but does not export the three functions the callers below invoke would
 * otherwise throw INSIDE the handler on first use - `dispatch` (above) turns
 * that into a 500, breaking the "always 200 / never a raw failure" invariant
 * both handleModulesUpdates and the handleModulesPublish gate promise.
 * `publishBaseWarning` joined the required set alongside `publishVersionGate`
 * the day the base-version warning shipped - a lib missing it degrades the
 * same way a lib missing `classifyModuleUpdate` always has, never a throw.
 * @param {object|null} lib
 * @returns {boolean}
 */
function _moduleUpdatesLibUsable(lib) {
  return Boolean(lib)
    && typeof lib.classifyModuleUpdate === 'function'
    && typeof lib.publishVersionGate === 'function'
    && typeof lib.publishBaseWarning === 'function';
}

/**
 * Joins installed modules (disk) with catalog entries (GitLab) by id. A
 * module absent from the catalog is omitted - there is no update source for
 * it (zip-imported or never published). Pure: no I/O, no lock, so it is
 * testable with a stub `lib`.
 * @param {Array<{id: string, manifest: object}>} installed scanModulesDir().installed
 * @param {Array<{id: string, manifest?: {version?: string}}>} entries catalog snapshot entries
 * @param {{classifyModuleUpdate: Function}} lib js/module-updates.mjs
 * @returns {Array<{id: string, name: string, installedVersion: string, catalogVersion: (string|null), state: string, enabled: boolean}>}
 */
function _moduleUpdateRows(installed, entries, lib) {
  const catalogById = new Map((entries || []).map((e) => [e.id, e]));
  const rows = [];
  for (const m of installed || []) {
    const entry = catalogById.get(m.id);
    if (!entry) continue;
    const installedVersion = m.manifest && m.manifest.version;
    const catalogVersion = (entry.manifest && entry.manifest.version) || null;
    rows.push({
      id: m.id,
      name: (m.manifest && m.manifest.name) || m.id,
      installedVersion: installedVersion || null,
      catalogVersion,
      state: lib.classifyModuleUpdate(installedVersion, catalogVersion),
      enabled: m.enabled !== false,
    });
  }
  rows.sort((a, b) => a.id.localeCompare(b.id));
  return rows;
}

/**
 * GET /api/modules/updates -> { ok, reason, message, modules[], catalogFetchedAt }.
 * Read-only, always 200: every branch below is a normal state (no modules
 * installed, no token, GitLab unreachable, the ESM comparator missing), not an
 * error the banner should surface as a failed request. Reads the SAME catalog
 * cache entry `/api/modules/catalog` fills - no second GitLab crawl.
 */
async function handleModulesUpdates(req, res) {
  if (!checkOriginNoBody(req, res)) return;

  const scan = scanModulesDir();
  if (scan.installed.length === 0) {
    jsonResponse(res, 200, { ok: true, reason: 'no-modules', message: null, modules: [], catalogFetchedAt: null });
    return;
  }

  if (!_modulesCatalogReady()) {
    jsonResponse(res, 200, {
      ok: false, reason: 'no-token', message: MODULES_CATALOG_NO_TOKEN_MESSAGE,
      modules: [], catalogFetchedAt: null,
    });
    return;
  }

  const catalog = await _modulesCatalogSnapshot();
  if (!catalog.ok) {
    jsonResponse(res, 200, {
      ok: false, reason: catalog.error || 'gitlab-unreachable', message: catalog.message || null,
      modules: [], catalogFetchedAt: null,
    });
    return;
  }

  const lib = await _moduleUpdatesLib();
  if (!_moduleUpdatesLibUsable(lib)) {
    jsonResponse(res, 200, {
      ok: false, reason: 'internal', message: 'Could not load the version comparator.',
      modules: [], catalogFetchedAt: catalog.fetchedAt || null,
    });
    return;
  }

  const rows = _moduleUpdateRows(scan.installed, catalog.entries, lib);
  const gitAvailable = await MG.gitAvailable();
  const modules = await Promise.all(rows.map(async (row) => {
    const git = gitAvailable
      ? await MG.moduleGitStatus(path.join(MODULES_DIR, row.id), _moduleGitOpts())
      : { present: false };
    return { ...row, dirty: Boolean(git.present && git.dirty) };
  }));

  jsonResponse(res, 200, { ok: true, reason: null, message: null, modules, catalogFetchedAt: catalog.fetchedAt || null });
}

/**
 * Finds a stray `modules/<id>.bak-<ts>` directory still holding a `.git` -
 * the trace a crashed overwrite/import swap leaves when the process died
 * between "old dir aside" and "backup removed" (docs/architecture/modules.md
 * gap fix). Synchronous and cheap: one readdir plus one existsSync per
 * candidate. Returns the bare directory NAME (not the full path) or null.
 * @param {string} id module id
 * @returns {string|null}
 */
function _findStaleModuleBackup(id) {
  let entries;
  try {
    entries = fs.readdirSync(MODULES_DIR, { withFileTypes: true });
  } catch {
    return null;
  }
  const prefix = id + '.bak-';
  for (const entry of entries) {
    if (!entry.isDirectory() || !entry.name.startsWith(prefix)) continue;
    if (fs.existsSync(path.join(MODULES_DIR, entry.name, '.git'))) return entry.name;
  }
  return null;
}

/**
 * Removes modules/.tmp-install-<id>-<pid>-<ts>/ staging directories whose
 * process is gone. They hold only files downloaded from the catalog (the
 * module's .git never enters staging - it moves from the backup straight
 * onto the new tree), so deleting one loses nothing; they are left behind
 * when the server is restarted in the middle of a long install. A directory
 * of a still-running process (pid alive) is never touched. Never throws.
 * @param {(pid: number) => boolean} [isAlive]
 * @returns {string[]} names removed
 */
function _sweepStaleModuleInstallDirs(isAlive = (pid) => {
  try { process.kill(pid, 0); return true; } catch (e) { return e.code === 'EPERM'; }
}) {
  const removed = [];
  let entries;
  try { entries = fs.readdirSync(MODULES_DIR, { withFileTypes: true }); } catch { return removed; }
  for (const entry of entries) {
    const m = /^\.tmp-install-.+-(\d+)-\d+$/.exec(entry.name);
    if (!entry.isDirectory() || !m) continue;
    const pid = Number(m[1]);
    if (pid === process.pid || isAlive(pid)) continue;
    try {
      fs.rmSync(path.join(MODULES_DIR, entry.name), { recursive: true, force: true, maxRetries: 3, retryDelay: 200 });
      removed.push(entry.name);
    } catch { /* next boot tries again */ }
  }
  return removed;
}
/** Message for the 409 `stale-backup` refusal, naming the exact directory. */
/** user-facing message for the 409 `stale-backup` refusal, naming the exact directory. */
function _staleModuleBackupMessage(backupName) {
  return 'Found an orphaned backup folder modules/' + backupName
    + ' holding this module\'s version history - move it back by hand'
    + ' (modules/' + backupName + '/.git) or delete that folder before you install'
    + ' or import the module again.';
}
/** Message for the 500 `history-stranded` refusal, naming the exact backup directory. */
/** user-facing message for the 500 `history-stranded` refusal, naming the exact backup directory. */
function _strandedModuleHistoryMessage(backupName) {
  return 'Could not restore the module\'s version history after the install - it is safe'
    + ' in modules/' + backupName + ', move it back by hand (modules/' + backupName
    + '/.git) once the other process has released the file.';
}

/**
 * Moves a stray-backup `.git` back onto the fresh module tree, the last step
 * of the overwrite/import swap. Extracted to its own function so the failure
 * mode (a stale `target/.git` blocking the rename, e.g. EPERM while another
 * process still holds a handle, or ENOTDIR when the destination is not a
 * directory) can be exercised by a unit test without monkey-patching `fs` -
 * the api harness cannot inject it because `.git` is stripped from every
 * download/import source before it ever reaches disk
 * (docs/architecture/modules.md gap fix). Never throws.
 * @param {string} bakDir the `<id>.bak-<ts>` directory, still holding `.git`
 * @param {string} targetDir the fresh module directory now live at `<id>`
 * @returns {{ok: true} | {ok: false, error: string}}
 */
function _restoreModuleGitAfterSwap(bakDir, targetDir) {
  try {
    fs.renameSync(path.join(bakDir, '.git'), path.join(targetDir, '.git'));
    return { ok: true };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

/**
 * POST /api/modules/install { id, overwrite? } -> downloads modules/<id>/
 * from the catalog repository into MODULES_DIR/<id>/, through a dotfile temp
 * directory (loadModules() skips dotfiles, serveStatic blocks them too) so a
 * crash mid-download never becomes a half-loaded, half-served module.
 */
async function handleModulesInstall(req, res) {
  if (!checkOrigin(req, res)) return;

  let body;
  try {
    body = await readBody(req, 4096);
  } catch {
    jsonResponse(res, 400, { error: 'bad-request' });
    return;
  }

  const id = body && body.id;
  if (typeof id !== 'string' || !MODULE_ID_RE.test(id) || RESERVED_MODULE_IDS.has(id)) {
    jsonResponse(res, 400, { error: 'invalid-id' });
    return;
  }

  if (!_modulesCatalogReady()) {
    jsonResponse(res, 200, { ok: false, error: 'no-token', message: MODULES_CATALOG_NO_TOKEN_MESSAGE });
    return;
  }

  const overwrite = body.overwrite === true;
  const target = path.join(MODULES_DIR, id);
  if (fs.existsSync(target) && !overwrite) {
    jsonResponse(res, 409, {
      error: 'already-installed', message: 'The module is already installed. Use the update instead.',
    });
    return;
  }

  await withModulesLock(async () => {
    const tmpDir = path.join(MODULES_DIR, '.tmp-install-' + id + '-' + process.pid + '-' + Date.now());
    try {
      // Stale-backup guard BEFORE any network call: a stray modules/<id>.bak-*
      // left by a crashed swap (rename-back-.git failed, see below) may be
      // the ONLY copy of the module's history left. Never auto-delete it -
      // refuse and point at it (docs/architecture/modules.md gap fix).
      const staleBackup = _findStaleModuleBackup(id);
      if (staleBackup) {
        jsonResponse(res, 409, { error: 'stale-backup', message: _staleModuleBackupMessage(staleBackup) });
        return;
      }

      // Dirty guard BEFORE any network call: a re-install must never even
      // start downloading when the local repository has changes it would
      // silently drop (docs/architecture/modules.md).
      // Computed from EXISTENCE alone, not from `overwrite`: two installs of
      // the same not-yet-installed module can both pass the pre-lock check
      // and serialize here, and the second one - still carrying
      // overwrite:false - would otherwise treat the repository the first one
      // just created as absent, back it up and delete the backup.
      let prevGit = { present: false };
      let reconciled = false;
      if (fs.existsSync(target)) {
        prevGit = await MG.moduleGitStatus(target, _moduleGitOpts());
        if (prevGit.present && prevGit.dirty) {
          const dirtyMessage = 'The module has unsaved changes in its local repository - save a version (Settings > Modules) or remove the module by hand before installing it again.';
          let localVersion = null;
          try {
            const lm = JSON.parse(fs.readFileSync(path.join(target, 'module.json'), 'utf8'));
            if (lm && lm.version !== undefined && lm.version !== null && String(lm.version).trim()) localVersion = String(lm.version).trim();
          } catch { /* unparsable: today's 409 below */ }
          if (localVersion === null) {
            jsonResponse(res, 409, { error: 'module-dirty', message: dirtyMessage });
            return;
          }
          const rec = await _moduleReconcileWithCatalog(id, target, localVersion);
          if (!rec.ok) {
            let message = dirtyMessage;
            if (rec.reason === 'differs') {
              const n = rec.added + rec.changed + rec.removed;
              const word = n === 1 ? 'file' : 'files';
              const example = rec.paths.slice(0, 3).join(', ');
              message = 'The module has ' + n + ' ' + word + ' with changes that are not in the published version ' + localVersion
                + (example ? ' (e.g. ' + example + ')' : '')
                + ' - publish them or save a version (Settings > Modules) before updating.';
            } else if (rec.reason === 'gitlab-unreachable') {
              message = 'The module has unsaved changes and they could not be compared with the catalog (no connection to GitLab, most often the VPN is off) - try again.';
            }
            jsonResponse(res, 409, {
              error: 'module-dirty',
              reconcile: { reason: rec.reason, added: rec.added, changed: rec.changed, removed: rec.removed, paths: rec.paths },
              message,
            });
            return;
          }
          // The reconcile compared and committed only what a publish sends
          // (_collectModuleFiles skips dotfiles). Anything git still reports
          // now - a module-local .env, a hand-made config - was never
          // published nor committed, and the swap below would delete it. Only
          // regenerable caches may be dropped, as they always were.
          const left = await MG.moduleGitUnsavedPaths(target, _moduleGitOpts());
          const unsaved = left.ok ? left.paths.filter((p) => !_isRegenerableModulePath(p)) : null;
          if (unsaved === null || unsaved.length > 0) {
            const example = (unsaved || []).slice(0, 3).join(', ');
            jsonResponse(res, 409, {
              error: 'module-dirty',
              reconcile: { reason: 'unpublished-local', added: (unsaved || []).length, changed: 0, removed: 0, paths: (unsaved || []).slice(0, 20) },
              message: 'The module has local files that are not in any published version'
                + (example ? ' (e.g. ' + example + ')' : '')
                + ' - the update would delete them. Save a version (Settings > Modules) or move them before updating the module.',
            });
            return;
          }
          reconciled = true;
          console.log('[modules-install] reconciled ' + id + ' with the catalog (' + localVersion + ')');
        }
      }

      fs.mkdirSync(tmpDir, { recursive: true });

      const catalogSha = await _modulesCatalogHeadSha();
      const treeRes = await _modulesCatalogTreeAll('modules/' + id, _modulesCatalogGet, { ref: catalogSha || undefined });
      // Order matters: an invisible project (no VPN, a token without access)
      // comes back from the tree read as `no-access`, and it MUST be answered
      // before the empty-list check below - otherwise a missing VPN
      // introduces itself as "the module does not exist in the catalog".
      if (!treeRes.ok && treeRes.reason === 'no-access') {
        jsonResponse(res, 400, { error: 'gitlab-no-access', message: MODULES_CATALOG_NO_ACCESS_MESSAGE });
        return;
      }
      if (!treeRes.ok) {
        jsonResponse(res, 400, {
          error: 'gitlab-unreachable',
          message: _modulesCatalogIsLocal() ? 'Could not read the module\'s file list from the local catalog.' : 'Could not read the module\'s file list from GitLab.',
        });
        return;
      }
      const treeEntries = treeRes.items;

      if (treeEntries.length === 0) {
        jsonResponse(res, 400, { error: 'not-found', message: 'The module does not exist in the catalog.' });
        return;
      }

      const files = [];
      for (const entry of treeEntries) {
        if (entry && entry.type === 'tree') continue; // directories create themselves via mkdirSync below
        const sanitized = sanitizeModuleTreePath(entry, id);
        if (!sanitized.ok) { jsonResponse(res, 400, { error: 'unsafe-path' }); return; }
        files.push({ relPath: sanitized.relPath, gitlabPath: entry.path });
      }

      if (files.length > MODULES_INSTALL_MAX_FILES) {
        jsonResponse(res, 400, { error: 'too-many-files' });
        return;
      }

      let totalBytes = 0;
      for (const f of files) {
        const dl = await _modulesCatalogGetBinary(_modulesCatalogFileRawUrl(f.gitlabPath, catalogSha || MODULES_CATALOG_REF));
        if (!dl.ok) { jsonResponse(res, 400, { error: 'gitlab-unreachable' }); return; }
        if (dl.buffer.length > MODULES_INSTALL_MAX_FILE_BYTES) {
          jsonResponse(res, 400, { error: 'too-large' });
          return;
        }
        totalBytes += dl.buffer.length;
        if (totalBytes > MODULES_INSTALL_MAX_TOTAL_BYTES) {
          jsonResponse(res, 400, { error: 'too-large' });
          return;
        }
        // Repeats the guard from serveStatic (path-traversal defense in
        // depth), here against the temp install directory rather than a
        // static-file root.
        const dest = path.resolve(tmpDir, f.relPath);
        if (!dest.startsWith(path.resolve(tmpDir) + path.sep)) {
          jsonResponse(res, 400, { error: 'unsafe-path' });
          return;
        }
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        fs.writeFileSync(dest, dl.buffer);
      }

      let manifest;
      try {
        manifest = JSON.parse(fs.readFileSync(path.join(tmpDir, 'module.json'), 'utf8'));
      } catch (e) {
        jsonResponse(res, 400, { error: 'invalid-manifest', errors: ['cannot read module.json: ' + e.message] });
        return;
      }

      // Structural check FIRST, in soft mode: a manifest that is broken for
      // any other reason (bad id, reserved id, malformed views, ...) answers
      // its usual invalid-manifest error rather than being masked by the area
      // gate below. Soft mode only tolerates a MISSING area at this point -
      // an invalid area VALUE still fails here, same as every other field.
      const preCheck = validateModuleManifest(manifest, id);
      if (!preCheck.valid) {
        jsonResponse(res, 400, { error: 'invalid-manifest', errors: preCheck.errors });
        return;
      }

      // -- Area gate: closes the "new module with no area" back door --------
      // Order (plan step 3a): (a) the artifact's own manifest.area, if valid;
      // (b) body.area sent by the client, if valid; (c) ONLY when overwrite is
      // true, the area already on the module that is being updated - the
      // update path (js/update-banner.js) must never ask, and must never lose
      // the area the installed copy already carries; (d) otherwise 409
      // area-required with ZERO writes - no target directory, nothing
      // mounted, MODULES_ORIGIN_FILE untouched. When the area comes from (b)
      // or (c), it is written into the STAGING module.json (tmpDir) before
      // validateModuleManifest runs in strict mode below, so validation sees
      // the exact file that is about to be moved into modules/<id>/.
      let resolvedArea = null;
      if (manifest.area !== undefined) {
        const check = validateModuleArea(manifest.area);
        if (check.ok) resolvedArea = check.value;
      }
      // An EXPLICIT body.area (the client named the key, even with an empty
      // string or a non-string) must be validated and, if invalid, refused
      // right here with 400 area-invalid - it must never be silently ignored
      // and fall through to the overwrite-existing-area fallback below.
      // body.area simply ABSENT (key never sent) is the normal "let the
      // gate resolve it from elsewhere" case.
      const bodyHasArea = body && Object.prototype.hasOwnProperty.call(body, 'area');
      if (bodyHasArea) {
        const check = validateModuleArea(body.area);
        if (!check.ok) {
          fs.rmSync(tmpDir, { recursive: true, force: true });
          jsonResponse(res, 400, { error: 'area-invalid', message: 'The module\'s business area is not valid.' });
          return;
        }
        if (resolvedArea === null) resolvedArea = check.value;
      }
      if (resolvedArea === null && overwrite && fs.existsSync(target)) {
        let existingText;
        try {
          existingText = fs.readFileSync(path.join(target, 'module.json'), 'utf8');
        } catch (e) {
          // ENOENT (no manifest to read yet, e.g. a half-installed target) is
          // simply "nothing to fall back to" - the area-required prompt below
          // is the correct answer. Any OTHER read failure (permissions, I/O)
          // is a real error and must not be swallowed as if it were ENOENT.
          if (e.code !== 'ENOENT') {
            fs.rmSync(tmpDir, { recursive: true, force: true });
            jsonResponse(res, 500, { error: 'io-error', message: 'cannot read the existing manifest: ' + e.message });
            return;
          }
        }
        if (existingText !== undefined) {
          let existingManifest;
          try {
            existingManifest = JSON.parse(existingText);
          } catch (e) {
            fs.rmSync(tmpDir, { recursive: true, force: true });
            jsonResponse(res, 400, { error: 'invalid-manifest', message: 'the existing module manifest is corrupt: ' + e.message });
            return;
          }
          const check = validateModuleArea(existingManifest.area);
          if (check.ok) resolvedArea = check.value;
        }
      }
      if (resolvedArea === null) {
        fs.rmSync(tmpDir, { recursive: true, force: true });
        jsonResponse(res, 409, { error: 'area-required', needsArea: true, id, suggestions: _moduleAreaSuggestions() });
        return;
      }
      // Always write the resolved area into the STAGING module.json before
      // extraction is finalized - including when it came from the existing
      // install: the staged file replaces the on-disk one, so the retained
      // area must be written into it too, not merely kept true in memory.
      if (resolvedArea !== manifest.area) {
        const manifestPath = path.join(tmpDir, 'module.json');
        const savedArea = setManifestArea(fs.readFileSync(manifestPath, 'utf8'), resolvedArea);
        if (savedArea.ok) {
          if (savedArea.changed) {
            const tmp = manifestPath + '.tmp';
            fs.writeFileSync(tmp, savedArea.text);
            fs.renameSync(tmp, manifestPath);
          }
          manifest.area = resolvedArea;
        }
      }

      // The REQUESTED id, not whatever the manifest claims - this is what
      // catches a catalog entry `a` whose module.json declares `id: "b"`
      // before it is ever renamed into modules/a/.
      const validated = validateModuleManifest(manifest, id, { strict: true });
      if (!validated.valid) {
        jsonResponse(res, 400, { error: 'invalid-manifest', errors: validated.errors });
        return;
      }

      // The pre-lock "already installed" check repeated where it is
      // authoritative: a duplicate install that lost the race must answer
      // the same 409 the first check gives, not swap over the winner's tree.
      if (fs.existsSync(target) && !overwrite) {
        fs.rmSync(tmpDir, { recursive: true, force: true });
        jsonResponse(res, 409, { error: 'already-installed', id, message: 'The module is already installed. Use the update instead.' });
        return;
      }
      let bak = null;
      if (fs.existsSync(target)) {
        bak = target + '.bak-' + Date.now();
        fs.renameSync(target, bak);
      }
      fs.renameSync(tmpDir, target);
      // Move the old .git BACK onto the fresh tree before the backup is
      // deleted - a crash between these two moves must leave the backup on
      // disk (never auto-deleted) rather than lose the only copy of the
      // history. Order is: old dir aside, new tree in, .git back, THEN the
      // backup goes - deleting first is exactly the defect this fixes.
      if (prevGit.present && bak) {
        const restored = _restoreModuleGitAfterSwap(bak, target);
        if (!restored.ok) {
          // The new tree is already live at target WITHOUT its history; bak
          // still holds the only copy - leave it on disk, never rmSync it,
          // and answer with a specific error rather than falling into the
          // generic install-failed catch below (docs/architecture/modules.md
          // gap fix). A retry hits the stale-backup guard above until a
          // human resolves this by hand.
          console.warn('[modules-install] could not restore .git from ' + bak + ':', restored.error);
          jsonResponse(res, 500, {
            error: 'history-stranded',
            message: _strandedModuleHistoryMessage(path.basename(bak)),
          });
          return;
        }
      }
      if (bak) fs.rmSync(bak, { recursive: true, force: true, maxRetries: 3, retryDelay: 200 });

      const asciiVersion = _moduleAsciiVersion(manifest.version);
      let git = { kept: false };
      if (prevGit.present) {
        const commitResult = await MG.moduleGitCommit(target, 'install from catalog ' + asciiVersion, _moduleGitOpts());
        // git-missing cannot happen here (a .git already existed, so git was
        // available when it was created) and nothing-to-commit is fine - an
        // install that changed nothing still leaves the existing history.
        git = { kept: true, committed: commitResult.ok };
        if (reconciled) git.reconciled = true;
      } else {
        const initResult = await MG.moduleGitInit(target, 'install from catalog ' + asciiVersion, _moduleGitOpts());
        // git-missing is silently accepted here: the module IS on disk, which
        // is what this operation promises - the repository is a bonus.
        git = { initialized: initResult.ok, reason: initResult.ok ? null : initResult.reason };
      }

      // Record where this copy came from - the base a later publish compares
      // itself against - inside the same lock as everything else above.
      // catalogSha = the exact catalog tree installed; the dirty-guard
      // reconcile compares against it first (_moduleReconcileWithCatalog).
      _setModuleOrigin(id, { source: 'catalog', version: manifest.version, at: new Date().toISOString(), ...(catalogSha ? { catalogSha } : {}) });

      // The server never restarts itself - loadModules() only runs at boot,
      // so the module is on disk but not yet live until the user restarts
      // through POST /api/settings/restart from the UI.
      jsonResponse(res, 200, { ok: true, id, version: manifest.version, files: files.length, restartRequired: true, git });
    } catch (e) {
      jsonResponse(res, 400, { error: 'install-failed', message: e.message });
    } finally {
      // Every path above - success or failure - must leave no dotfile
      // directory behind. On success this is a harmless no-op: renameSync
      // already moved tmpDir to target.
      fs.rmSync(tmpDir, { recursive: true, force: true, maxRetries: 3, retryDelay: 200 });
    }
  });
}

const MODULE_EXPORT_MAX_BYTES = 32 * 1024 * 1024;
const MODULE_IMPORT_MAX_B64 = 12 * 1024 * 1024; // readBody's default limit (1 MB) is too small for a zip.
const MODULE_IMPORT_MAX_ZIP_BYTES = 8 * 1024 * 1024;

/** Reads MODULES_REGISTRY_FILE, defaulting to { disabled: [] } when it is missing or corrupt. */
function _readModulesRegistry() {
  try {
    const parsed = JSON.parse(fs.readFileSync(MODULES_REGISTRY_FILE, 'utf8'));
    return (parsed && typeof parsed === 'object') ? parsed : { disabled: [] };
  } catch {
    return { disabled: [] };
  }
}

/** tmp+rename write of the modules registry — never a bare fs.writeFileSync. */
function _writeModulesRegistry(registry) {
  fs.mkdirSync(path.dirname(MODULES_REGISTRY_FILE), { recursive: true });
  const tmp = MODULES_REGISTRY_FILE + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(registry, null, 2));
  fs.renameSync(tmp, MODULES_REGISTRY_FILE);
}

/** Reads MODULES_ORIGIN_FILE, defaulting to {} when missing or corrupt. */
function _readModulesOrigin() {
  try {
    const parsed = JSON.parse(fs.readFileSync(MODULES_ORIGIN_FILE, 'utf8'));
    return (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) ? parsed : {};
  } catch {
    return {};
  }
}

/** tmp+rename write of the origin file — never a bare fs.writeFileSync. */
function _writeModulesOrigin(doc) {
  fs.mkdirSync(path.dirname(MODULES_ORIGIN_FILE), { recursive: true });
  const tmp = MODULES_ORIGIN_FILE + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(doc, null, 2));
  fs.renameSync(tmp, MODULES_ORIGIN_FILE);
}

/**
 * Sets or clears one module's origin record. Call only inside withModulesLock -
 * this is a read-modify-write over one shared file, same discipline as the
 * registry helpers above.
 * @param {string} id
 * @param {{source: 'catalog'|'zip'|'publish', version: string, at: string}|null} record null deletes the key
 */
function _setModuleOrigin(id, record) {
  const doc = _readModulesOrigin();
  if (record === null) delete doc[id];
  else doc[id] = record;
  _writeModulesOrigin(doc);
}

// ── Modules: publishing to the catalog (local copy, or branch + merge request) ──
// The catalog repository works through merge requests: `main` is protected, so
// nothing here ever pushes to it. Publishing a module means three GitLab REST
// calls with COCKPIT_MODULES_TOKEN - create a branch off the default ref,
// commit the module's files plus the catalog.json entry onto that branch, then
// open a merge request for a human to review.
//
// No clone, no working copy, no git binary: POST /repository/commits takes the
// whole change as one actions[] array, which is also what makes the write
// atomic. A half-published module is therefore impossible - either the commit
// lands whole or the branch stays empty.
//
//   POST /api/modules/publish { id, summary?, status?, author?, tags?, featured? }

const MODULES_PUBLISH_MAX_FILES = MODULES_INSTALL_MAX_FILES;
const MODULES_PUBLISH_MAX_BYTES = 8 * 1024 * 1024;
const MODULES_PUBLISH_STATUSES = MODULE_STATUSES;

/**
 * module.json text with `status` set. Pure - takes and returns text - so the
 * write the publish handler does is testable without a module on disk. A new
 * key lands right after `version` (where a reader looks for it) instead of at
 * the end; an existing one keeps its place. Two-space indent plus a trailing
 * newline, the shape every scaffold writes.
 * @param {string} text current module.json
 * @param {string} status one of MODULE_STATUSES
 * @returns {{ok: true, text: string, changed: boolean} | {ok: false, error: string}}
 */
function setManifestStatus(text, status) {
  if (!MODULE_STATUSES.includes(status)) return { ok: false, error: 'status-invalid' };
  let doc;
  try { doc = JSON.parse(String(text || '')); } catch (e) { return { ok: false, error: 'manifest-json-invalid: ' + e.message }; }
  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) return { ok: false, error: 'manifest-json-invalid' };
  if (doc.status === status) return { ok: true, text: String(text), changed: false };
  const out = {};
  let placed = false;
  for (const [k, v] of Object.entries(doc)) {
    if (k === 'status') { out.status = status; placed = true; continue; }
    out[k] = v;
    if (k === 'version' && !placed && doc.status === undefined) { out.status = status; placed = true; }
  }
  if (!placed) out.status = status;
  return { ok: true, text: JSON.stringify(out, null, 2) + '\n', changed: true };
}

/**
 * module.json text with `area` set. Pure - same contract as setManifestStatus,
 * used by the install/import area gate (staging module.json, before the
 * strict validateModuleManifest call) and by handleModulesPublish (when the
 * modal supplies an area the manifest does not have yet). A new key lands
 * right after `status` (where setManifestStatus's own key just landed, or
 * where a reader looks for one next); an existing one keeps its place.
 * @param {string} text current module.json
 * @param {string} area a value validateModuleArea has already accepted
 * @returns {{ok: true, text: string, changed: boolean} | {ok: false, error: string}}
 */
function setManifestArea(text, area) {
  const check = validateModuleArea(area);
  if (!check.ok) return { ok: false, error: 'area-invalid' };
  const value = check.value;
  let doc;
  try { doc = JSON.parse(String(text || '')); } catch (e) { return { ok: false, error: 'manifest-json-invalid: ' + e.message }; }
  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) return { ok: false, error: 'manifest-json-invalid' };
  if (doc.area === value) return { ok: true, text: String(text), changed: false };
  const out = {};
  let placed = false;
  for (const [k, v] of Object.entries(doc)) {
    if (k === 'area') { out.area = value; placed = true; continue; }
    out[k] = v;
    if (k === 'status' && !placed && doc.area === undefined) { out.area = value; placed = true; }
  }
  if (!placed) out.area = value;
  return { ok: true, text: JSON.stringify(out, null, 2) + '\n', changed: true };
}

/**
 * Branch name for one publish attempt. Carries a timestamp because a second
 * attempt must not collide with the branch left behind by the first: GitLab
 * answers 400 on an existing branch, and the person would have to delete it by
 * hand before retrying.
 * @param {string} id module id
 * @param {number} nowMs
 * @returns {string}
 */
function modulesPublishBranchName(id, nowMs) {
  return 'module/' + id + '-' + _modulesCatalogBranchStamp(nowMs);
}

/** UTC `YYYYMMDD-HHMMSS` shared by every branch this file opens on the catalog. */
function _modulesCatalogBranchStamp(nowMs) {
  const d = new Date(nowMs);
  const p = (n) => String(n).padStart(2, '0');
  return d.getUTCFullYear() + p(d.getUTCMonth() + 1) + p(d.getUTCDate())
    + '-' + p(d.getUTCHours()) + p(d.getUTCMinutes()) + p(d.getUTCSeconds());
}

/**
 * Where a NEW entry goes in catalog.json: right before its alphabetical
 * successor (the existing entry with the smallest id greater than `id`), at
 * the tail only when there is none. Appending every publish at the tail made
 * every pair of open publish MRs conflict on the same lines (2026-10-10:
 * !142, !145, !146 - each clean against main, all three conflicting with each
 * other). Before the successor the insert is a pure block that changes no
 * existing line, so two MRs collide only when no existing id sorts between
 * them. "First entry with a greater id" in LIST order would not do: the list
 * is not sorted, and one early large id would pull most inserts into one
 * slot. File order carries no meaning - mergeModulesCatalog sorts. Pure.
 * @param {object[]} modules catalog entries
 * @param {string} id the id being added
 * @returns {number} splice index
 */
function catalogInsertIndex(modules, id) {
  let at = -1;
  let best = null;
  modules.forEach((m, i) => {
    const mid = m && typeof m.id === 'string' ? m.id : null;
    if (mid === null || mid <= id) return;
    if (best === null || mid < best) { best = mid; at = i; }
  });
  return at === -1 ? modules.length : at;
}

/**
 * Merge one module entry into a catalog.json body, preserving every other
 * entry and the file's own formatting choice of two-space indent.
 * Pure: takes and returns text, so it is testable without GitLab.
 *
 * The first-publisher `owner` is an invariant, not a field like any other:
 * on `add` it is written only when the caller supplied one with a real
 * `slug`; on `replace` the EXISTING entry's `owner` always wins over whatever
 * the caller passed, so a later publish by someone else can never quietly
 * rewrite who published a module first. `previous` carries the pre-merge
 * entry (or null on `add`) so the caller can detect a takeover from it -
 * parseModulesCatalog() drops `owner`, so this is the only place that sees it.
 *
 * @param {string} catalogText current catalog.json, '' when the file is absent
 * @param {object} entry the curation entry to add or replace (must carry `id`)
 * @returns {{ok: true, text: string, mode: 'add'|'replace', previous: object|null} | {ok: false, error: string}}
 */
function upsertCatalogEntry(catalogText, entry) {
  if (!entry || typeof entry.id !== 'string' || !entry.id) {
    return { ok: false, error: 'entry-id-missing' };
  }
  let doc;
  const raw = String(catalogText || '').trim();
  if (raw === '') {
    doc = { schemaVersion: 1, modules: [] };
  } else {
    try { doc = JSON.parse(raw); } catch (e) { return { ok: false, error: 'catalog-json-invalid: ' + e.message }; }
  }
  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) return { ok: false, error: 'catalog-json-invalid' };
  if (doc.schemaVersion !== 1) return { ok: false, error: 'catalog-schema-unsupported' };
  if (!Array.isArray(doc.modules)) doc.modules = [];

  const at = doc.modules.findIndex((m) => m && m.id === entry.id);
  const mode = at === -1 ? 'add' : 'replace';
  const previous = at === -1 ? null : doc.modules[at];

  if (at === -1) {
    const toAdd = { ...entry };
    const hasOwnerSlug = toAdd.owner && typeof toAdd.owner === 'object' && typeof toAdd.owner.slug === 'string' && toAdd.owner.slug;
    if (!hasOwnerSlug) delete toAdd.owner;
    doc.modules.splice(catalogInsertIndex(doc.modules, entry.id), 0, toAdd);
  } else {
    const merged = { ...previous, ...entry };
    if (previous && previous.owner) merged.owner = previous.owner;
    doc.modules[at] = merged;
  }

  return { ok: true, text: JSON.stringify(doc, null, 2) + '\n', mode, previous };
}

/**
 * GitLab commit actions[] for one publish. A path already present on the
 * default branch has to be sent as `update`; sending `create` for it fails the
 * WHOLE commit with "A file with this name already exists", which is the one
 * error that makes a re-publish look broken. `deletes` (the output of
 * publishDeleteGuard) becomes one `delete` action per path, placed after the
 * create/update actions and before catalog.json - filtered defensively to the
 * module's own prefix so a caller can never delete outside modules/<id>/ or
 * the catalog.json action itself.
 *
 * @param {Array<{path: string, data: Buffer}>} files module files, paths relative to the module dir
 * @param {string} moduleId
 * @param {Set<string>} existingPaths repo paths already on the default branch
 * @param {{text: string, exists: boolean}} catalog the new catalog.json body
 * @param {string[]} [deletes] repo paths (already prefixed 'modules/<id>/') to delete
 * @returns {Array<object>}
 */
function buildPublishActions(files, moduleId, existingPaths, catalog, deletes = []) {
  const actions = files.map((f) => {
    const repoPath = 'modules/' + moduleId + '/' + f.path;
    return {
      action: existingPaths.has(repoPath) ? 'update' : 'create',
      file_path: repoPath,
      encoding: 'base64',
      content: f.data.toString('base64'),
    };
  });
  const prefix = 'modules/' + moduleId + '/';
  for (const p of deletes || []) {
    if (typeof p !== 'string' || p === 'catalog.json' || !p.startsWith(prefix)) continue;
    actions.push({ action: 'delete', file_path: p });
  }
  actions.push({
    action: catalog.exists ? 'update' : 'create',
    file_path: 'catalog.json',
    encoding: 'text',
    content: catalog.text,
  });
  return actions;
}

/**
 * Pure destructive-publish guard: decides whether a publish's implied
 * deletions (paths that exist on the catalog's default branch under
 * modules/<id>/ but are not among the files being sent) may proceed.
 * Modelled after crypto-sync's encryptTree guard, but with thresholds that
 * fit a module (3-10 files) rather than a whole mirror: crypto-sync's 50-file
 * floor would never fire here, and its 30% ratio would refuse a normal
 * rename of one file in three.
 *
 * - no deletions -> ok
 * - `kept === 0` (not one existing path is being re-sent - not even
 *   module.json, which any real re-publish carries) -> `publish-tree-mismatch`,
 *   refused with NO override: the tree read does not look like the module
 *   this caller holds.
 * - more than half the catalog copy would go, and the caller did not pass
 *   `confirm: true` -> `publish-destructive`, refused but overridable.
 * - otherwise -> ok, with every deletion still reported.
 *
 * @param {Array<{path: string}>} files module files about to be sent, paths relative to the module dir
 * @param {string} moduleId
 * @param {Set<string>} existingPaths repo paths already on the default branch (any prefix; scoped here)
 * @param {{confirm?: boolean}} [opts]
 * @returns {{ok: true, deletes: string[], kept: number, existing: number}
 *         | {ok: false, error: 'publish-tree-mismatch'|'publish-destructive', deletes: string[], kept: number, existing: number, message: string}}
 */
function publishDeleteGuard(files, moduleId, existingPaths, opts = {}) {
  const prefix = 'modules/' + moduleId + '/';
  const scoped = [...(existingPaths || [])].filter((p) => typeof p === 'string' && p !== 'catalog.json' && p.startsWith(prefix));
  const sentPaths = new Set((files || []).map((f) => prefix + f.path));

  const kept = scoped.filter((p) => sentPaths.has(p)).length;
  const deletes = scoped.filter((p) => !sentPaths.has(p));
  const existing = scoped.length;

  if (deletes.length === 0) {
    return { ok: true, deletes, kept, existing };
  }
  if (kept === 0) {
    return {
      ok: false, error: 'publish-tree-mismatch', deletes, kept, existing,
      message: 'The catalog tree that was read does not match the module being published - none of its ' + existing + ' existing files is among the files sent. Publish refused.',
    };
  }
  if (deletes.length * 2 > existing && opts.confirm !== true) {
    return {
      ok: false, error: 'publish-destructive', deletes, kept, existing,
      message: 'This publish would delete ' + deletes.length + ' of the module\'s ' + existing + ' files in the catalog. Confirm if that is intended.',
    };
  }
  return { ok: true, deletes, kept, existing };
}

/**
 * Detects a publish by someone other than the module's recorded first
 * publisher. Pure - reads upsertCatalogEntry(...).previous, never the
 * curated snapshot (parseModulesCatalog drops `owner`).
 * @param {object|null} previousEntry the pre-merge catalog entry, or null on a first publish
 * @param {{person_slug: string, display_name: string}|null} me _localIdentity()
 * @returns {{takeover: boolean, previousOwner: {slug: string, name: string}|null}}
 */
function publishTakeover(previousEntry, me) {
  if (!previousEntry || !previousEntry.owner || !me) return { takeover: false, previousOwner: null };
  if (previousEntry.owner.slug === me.person_slug) return { takeover: false, previousOwner: null };
  return {
    takeover: true,
    previousOwner: { slug: previousEntry.owner.slug, name: previousEntry.owner.name || previousEntry.owner.slug },
  };
}

/**
 * One JSON write against the catalog repo. Mirrors _modulesCatalogGet: never
 * throws, and only the fields on this explicit shape leave the function, so a
 * token can never ride out inside an error object.
 * @returns {Promise<{ok: boolean, status: number, text: string, json: object|null}>}
 */
async function _modulesCatalogPostJson(url, body, method = 'POST') {
  // A local catalog is written on disk (_modulesPublishLocal), never through
  // REST - a call that reaches here in local mode is a bug, answered as a
  // refused write rather than a request to whatever host the default URL names.
  if (_modulesCatalogIsLocal()) return { ok: false, status: 0, text: '', json: null };
  try {
    const r = await fetch(url, {
      method,
      headers: { 'PRIVATE-TOKEN': MODULES_CATALOG_TOKEN, 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(MODULES_CATALOG_WRITE_TIMEOUT_MS),
    });
    const text = await r.text().catch(() => '');
    let json = null;
    try { json = JSON.parse(text); } catch { /* non-JSON error page */ }
    return { ok: r.ok, status: r.status, text, json };
  } catch {
    return { ok: false, status: 0, text: '', json: null };
  }
}

/**
 * One entry name the three module tree walkers (publish collector, zip
 * export, zip import) all skip: dotfiles, node_modules, .git - and the
 * Python interpreter's own cache, because a module that ships a Python ETL
 * (sprint-stats, time-off) grows a `__pycache__/` with
 * per-interpreter `.pyc` blobs the moment it runs, the module's own
 * `.gitignore` is not consulted by any of these walkers, and the first
 * publish of sprint-stats would otherwise have sent four of them to the
 * catalog and counted them against MODULES_PUBLISH_MAX_FILES.
 * @param {string} name one path segment (a file or directory name)
 * @returns {boolean}
 */
function _isModuleJunkEntry(name) {
  return name.startsWith('.') || name === 'node_modules' || name === '.git' || name === '__pycache__' || /\.py[co]$/.test(name);
}

/**
 * True for a module-relative path inside a cache the module regenerates on
 * its own (__pycache__, node_modules, .pytest_cache, *.pyc) or OS litter
 * (.DS_Store) - the only unpublished files an install may drop after a
 * reconcile. One list with the module's `.git/info/exclude`
 * (MG.isDropSafeModulePath), so the two can never disagree. Pure.
 * @param {string} relPath forward-slash path relative to modules/<id>/
 */
function _isRegenerableModulePath(relPath) {
  return MG.isDropSafeModulePath(relPath);
}

// Source text a module is written in. CRLF in these is an editor or
// `core.autocrlf` on Windows, never content: published as-is, every line of
// a file changed in the catalog (one merge request: six files rewritten
// line by line for a 27-line change) and flipped back on the next publish
// from a Mac. Data formats (.csv and friends) are deliberately absent - their
// bytes are content.
const MODULE_LF_TEXT_EXTS = new Set([
  '.js', '.mjs', '.cjs', '.ts', '.tsx', '.jsx', '.json', '.md', '.css', '.scss',
  '.html', '.htm', '.txt', '.py', '.yml', '.yaml', '.svg', '.sh', '.toml',
]);
const MODULE_LF_TEXT_NAMES = new Set(['.gitignore', '.gitattributes', '.editorconfig', '.npmrc', '.nvmrc', '.env.example']);

/**
 * The bytes a module file is published as: CRLF -> LF for source text (by
 * extension or exact name, and only when the buffer holds no NUL byte, so a
 * binary that happens to carry a text extension is left alone). Everything
 * else, and a text file with no CRLF, is returned unchanged (same Buffer).
 * Pure.
 * @param {string} relPath forward-slash path relative to modules/<id>/
 * @param {Buffer} buf
 * @returns {Buffer}
 */
function _moduleFileLf(relPath, buf) {
  const name = path.posix.basename(String(relPath));
  if (!MODULE_LF_TEXT_NAMES.has(name) && !MODULE_LF_TEXT_EXTS.has(path.posix.extname(name).toLowerCase())) return buf;
  if (buf.indexOf(0) !== -1 || buf.indexOf('\r\n') === -1) return buf;
  return Buffer.from(buf.toString('latin1').replace(/\r\n/g, '\n'), 'latin1');
}

/**
 * Read modules/<id>/ off disk with the same exclusions the export path uses,
 * as the bytes a publish sends (_moduleFileLf). Publish, the drift scan and
 * the catalog reconcile all read through here, so a Windows checkout with
 * CRLF on disk is neither published as CRLF nor reported as drift.
 */
function _collectModuleFiles(dir) {
  const files = [];
  let totalBytes = 0;
  (function walk(relDir) {
    const abs = path.join(dir, relDir);
    let list;
    try { list = fs.readdirSync(abs, { withFileTypes: true }); } catch { return; }
    for (const e of list) {
      if (_isModuleJunkEntry(e.name)) continue;
      const relPath = relDir ? relDir + '/' + e.name : e.name;
      const absPath = path.join(dir, relPath);
      let st;
      try { st = fs.lstatSync(absPath); } catch { continue; }
      if (st.isSymbolicLink()) continue;
      if (st.isDirectory()) { walk(relPath); continue; }
      if (!st.isFile()) continue;
      totalBytes += st.size;
      if (totalBytes > MODULES_PUBLISH_MAX_BYTES) throw new Error('too-large');
      if (files.length >= MODULES_PUBLISH_MAX_FILES) throw new Error('too-many-files');
      files.push({ path: relPath, data: _moduleFileLf(relPath, fs.readFileSync(absPath)) });
    }
  })('');
  return files;
}

// -- Changes without a new version (publish drift) ---------------------------
// A module whose local version EQUALS the catalog's can still differ from the
// published copy: somebody changed files and did not bump module.json. The
// publish version gate then refuses with `version-not-bumped`, and nothing in
// Settings > Modules said so beforehand. GET /api/modules/publish-drift finds
// those modules by comparing what a publish WOULD send (_collectModuleFiles,
// byte-identical to the base64 actions buildPublishActions builds) against
// the catalog tree's blob ids - a git blob sha1 is computable locally, so no
// file content is downloaded. POST /api/modules/bump-version raises the patch
// number by one, which is what the "Bump version" button there sends.

const PUBLISH_DRIFT_CONCURRENCY = 8;
let _publishDriftCache = { token: null, at: 0, data: null };
// Bumped by every version bump: a scan that started before it must not put
// its (pre-bump) answer back into the cache when it finishes.
let _publishDriftGen = 0;

/** git's blob id for a buffer: sha1("blob <len>\0" + bytes). Pure. */
function gitBlobSha(buf) {
  return crypto.createHash('sha1').update('blob ' + buf.length + '\0').update(buf).digest('hex');
}

/**
 * Compares the files a publish would send with the catalog's tree of that
 * module. Pure.
 * @param {Array<{path: string, data: Buffer}>} files _collectModuleFiles(dir)
 * @param {string} moduleId
 * @param {Array<{type?: string, path?: string, id?: string}>} treeItems _modulesCatalogTreeAll items
 * @returns {{added: number, changed: number, removed: number, paths: string[], changedPaths: string[]}}
 *   `paths` = up to 20 module-relative paths that differ, for a tooltip;
 *   `changedPaths` = every path whose content differs (not capped)
 */
function modulePublishDrift(files, moduleId, treeItems) {
  const prefix = 'modules/' + moduleId + '/';
  const remote = new Map();
  for (const it of treeItems || []) {
    if (it && it.type === 'blob' && typeof it.path === 'string' && it.path.startsWith(prefix)) {
      remote.set(it.path.slice(prefix.length), it.id);
    }
  }
  let added = 0;
  let changed = 0;
  const paths = [];
  const changedPaths = [];
  const local = new Set();
  for (const f of files || []) {
    local.add(f.path);
    if (!remote.has(f.path)) { added += 1; paths.push(f.path); continue; }
    if (remote.get(f.path) !== gitBlobSha(f.data)) { changed += 1; paths.push(f.path); changedPaths.push(f.path); }
  }
  let removed = 0;
  for (const p of remote.keys()) {
    if (!local.has(p)) { removed += 1; paths.push(p); }
  }
  return { added, changed, removed, paths: paths.slice(0, 20), changedPaths };
}

/**
 * Whether two module.json bodies say the same thing once the fields an
 * INSTALL writes locally are set aside. handleModulesInstall stamps `area`
 * into the local manifest (the area prompt, or the previous install's area)
 * when the catalog copy has none, so a byte comparison would flag every such
 * install as "changed without a new version". Key order and formatting are
 * ignored too - only the parsed values count. Pure.
 * @param {string|Buffer} localText
 * @param {string|Buffer} remoteText
 * @returns {boolean} false when either side is not a JSON object
 */
function manifestsEquivalentForPublish(localText, remoteText) {
  const norm = (text) => {
    let doc;
    try { doc = JSON.parse(String(text)); } catch { return null; }
    if (!doc || typeof doc !== 'object' || Array.isArray(doc)) return null;
    const out = { ...doc };
    delete out.area;
    const sortDeep = (v) => (Array.isArray(v) ? v.map(sortDeep)
      : v && typeof v === 'object' ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, sortDeep(v[k])])) : v);
    return JSON.stringify(sortDeep(out));
  };
  const a = norm(localText);
  const b = norm(remoteText);
  return a !== null && a === b;
}

/**
 * Whether the local tree equals a catalog tree once the manifest's locally
 * stamped `area` is set aside. Pure.
 * @returns {{equal: boolean, added: number, changed: number, removed: number, paths: string[]}}
 */
function moduleReconcileVerdict(files, moduleId, treeItems, remoteManifestText) {
  const d = modulePublishDrift(files, moduleId, treeItems);
  let changed = d.changed;
  let paths = d.paths;
  if (d.changedPaths.includes('module.json')) {
    const local = (files || []).find((f) => f.path === 'module.json');
    if (local && manifestsEquivalentForPublish(local.data, remoteManifestText)) {
      changed -= 1;
      paths = paths.filter((p) => p !== 'module.json');
    }
  }
  return { equal: d.added === 0 && changed === 0 && d.removed === 0, added: d.added, changed, removed: d.removed, paths };
}

/**
 * Lazy repair for a dirty module repo: when the local tree is identical to the
 * catalog tree of its own version, commit it ("reconciled with catalog").
 * MUST be called inside withModulesLock. Never throws, never deletes.
 * @returns {Promise<{ok: true, reconciled: true, sha7: string|null, committed: boolean} | {ok: false, reason: string, [k: string]: any}>}
 */
async function _moduleReconcileWithCatalog(id, dir, localVersion, deps = {}) {
  try {
    const getFn = deps.getFn || _modulesCatalogGet;
    const gitOpts = deps.gitOpts || _moduleGitOpts();
    let has;
    if (deps.catalogHasModule) {
      has = await deps.catalogHasModule(id);
    } else {
      const snap = await _modulesCatalogSnapshot();
      if (!snap || !snap.ok) return { ok: false, reason: 'gitlab-unreachable' };
      has = (snap.entries || []).some((e) => e && e.id === id);
    }
    if (!has) return { ok: false, reason: 'not-in-catalog' };
    const found = await _modulesCatalogCommitForVersion(id, localVersion, getFn);
    if (!found.ok) return { ok: false, reason: found.reason };
    let files;
    try { files = _collectModuleFiles(dir); } catch { return { ok: false, reason: 'read-failed' }; }
    // Which catalog tree "version X" means: first the exact commit this copy
    // was installed from (recorded in modules-origin.json since the install
    // pins one sha), then the commit that set the version, then the commits
    // that changed files under the same version. Equal to ANY of them = the
    // copy is published content, not a local change.
    const origin = deps.origin !== undefined ? deps.origin : (_readModulesOrigin()[id] || null);
    const recordedSha = origin && origin.source === 'catalog' && typeof origin.catalogSha === 'string'
      && /^[0-9a-f]{7,64}$/.test(origin.catalogSha)
      && String(origin.version || '').trim() === String(localVersion).trim() ? origin.catalogSha : null;
    const candidates = [];
    if (recordedSha) candidates.push({ sha: recordedSha, manifestText: null });
    if (found.sha !== recordedSha) candidates.push({ sha: found.sha, manifestText: found.manifestText });
    let rangeLoaded = false;
    let best = null;
    for (let i = 0; i < candidates.length && i < MODULES_RECONCILE_MAX_TREES; i += 1) {
      const cand = candidates[i];
      if (cand.manifestText === null) {
        const m = await getFn(_modulesCatalogFileRawUrl('modules/' + id + '/module.json', cand.sha));
        if (!m.ok) { if (m.status === 404) continue; return { ok: false, reason: 'gitlab-unreachable' }; }
        cand.manifestText = m.text;
      }
      const treeRes = await _modulesCatalogTreeAll('modules/' + id, getFn, { ref: cand.sha });
      if (!treeRes.ok) return { ok: false, reason: 'gitlab-unreachable' };
      const v = moduleReconcileVerdict(files, id, treeRes.items, cand.manifestText);
      if (v.equal) { best = v; break; }
      if (!best || (v.added + v.changed + v.removed) < (best.added + best.changed + best.removed)) best = v;
      if (!rangeLoaded && i === candidates.length - 1) {
        rangeLoaded = true;
        for (const sha of await _modulesCatalogVersionRangeShas(id, found, getFn)) {
          if (!candidates.some((c) => c.sha === sha)) candidates.push({ sha, manifestText: found.manifestText });
        }
      }
    }
    const v = best;
    if (!v) return { ok: false, reason: 'version-not-found' };
    if (!v.equal) {
      return { ok: false, reason: 'differs', added: v.added, changed: v.changed, removed: v.removed, paths: v.paths, publishedVersion: localVersion };
    }
    if (files.length === 0) return { ok: false, reason: 'read-failed' };
    const c = await MG.moduleGitCommitPaths(
      dir,
      'publish ' + _moduleAsciiVersion(localVersion) + ' (reconciled with catalog)',
      files.map((f) => f.path),
      gitOpts,
    );
    if (c.ok) return { ok: true, reconciled: true, sha7: c.sha7, committed: true };
    if (c.reason === 'nothing-to-commit') return { ok: true, reconciled: true, sha7: null, committed: false };
    return { ok: false, reason: 'commit-failed', message: c.message || c.reason };
  } catch (e) {
    return { ok: false, reason: 'gitlab-unreachable', message: e && e.message };
  }
}

/**
 * The drift scan's half of the dirty-guard repair: a module whose tree already
 * equals the catalog tree of its version but whose local repo is still dirty
 * (published before the publish handler committed locally, or published from
 * another machine) gets its "reconciled with catalog" commit right away, so the
 * Modules tab stops flagging unsaved changes nobody made and nobody has to
 * commit by hand. A clean repo costs one `git status` and no GitLab call; the
 * reconcile itself re-verifies against the catalog commit of that version and
 * commits only the published paths. Never throws.
 * @returns {Promise<boolean>} true when a commit was made
 */
async function _driftAutoReconcile(id, dir, localVersion, deps = {}) {
  try {
    const gitOpts = deps.gitOpts || _moduleGitOpts();
    const st = await MG.moduleGitStatus(dir, gitOpts);
    if (!st || !st.present || !st.dirty) return false;
    const lock = deps.withLock || withModulesLock;
    const rec = await lock(() => _moduleReconcileWithCatalog(id, dir, localVersion, deps));
    if (rec && rec.ok && rec.committed) {
      console.log('[modules-drift] reconciled ' + id + ' with the catalog (' + localVersion + ')');
      return true;
    }
    return false;
  } catch {
    return false;
  }
}

/**
 * module.json text with the PATCH number raised by one ("0.1.9" -> "0.1.10").
 * Edits only the version literal, so every other byte of the file - key
 * order, indentation, the author's own formatting - is left alone. Pure.
 * @param {string} text
 * @returns {{ok: true, text: string, from: string, to: string}|{ok: false, error: string}}
 */
function bumpManifestPatch(text) {
  let doc;
  try { doc = JSON.parse(String(text || '')); } catch (e) { return { ok: false, error: 'manifest-json-invalid: ' + e.message }; }
  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) return { ok: false, error: 'manifest-json-invalid' };
  const from = doc.version;
  // An optional leading "v" is kept, the same forms compareSemver accepts -
  // otherwise such a module could be flagged "same version" and never bumped.
  const m = typeof from === 'string' ? from.match(/^(v?)(\d+)\.(\d+)\.(\d+)$/) : null;
  if (!m) return { ok: false, error: 'version-unparsable' };
  const to = m[1] + m[2] + '.' + m[3] + '.' + (Number(m[4]) + 1);
  const re = new RegExp('("version"\\s*:\\s*")' + from.replace(/\./g, '\\.') + '(")');
  const next = String(text).replace(re, '$1' + to + '$2');
  let check;
  try { check = JSON.parse(next); } catch { return { ok: false, error: 'version-literal-not-found' }; }
  if (!check || check.version !== to) return { ok: false, error: 'version-literal-not-found' };
  return { ok: true, text: next, from, to };
}

/**
 * GET /api/modules/publish-drift[?force=1] -> { ok, items: [{ id, version, added, changed, removed, paths }], failed: [id], reconciled: [id], error? }
 * `reconciled` names the same-version modules whose dirty local repo matched
 * the catalog and was committed on the spot (_driftAutoReconcile).
 * `failed` names the modules whose catalog tree could not be read, so the
 * client keeps their previous answer and says the check was incomplete.
 * Only modules whose local version equals the catalog's are checked (an
 * older or newer local version already has its own list), and only the ones
 * that differ are returned. Always 200, same no-token / gitlab contract and
 * 60 s token-keyed cache as the other catalog reads; one tree read per
 * checked module, at most PUBLISH_DRIFT_CONCURRENCY at a time.
 */
async function handleModulesPublishDrift(req, res) {
  if (!checkOriginNoBody(req, res)) return;
  const token = _modulesCatalogCredential();
  if (!token) {
    jsonResponse(res, 200, { ok: true, items: [], failed: [], error: 'no_token' });
    return;
  }
  const force = new URL(req.url, 'http://localhost').searchParams.get('force') === '1';
  const now = Date.now();
  if (!force && _publishDriftCache.token === token && (now - _publishDriftCache.at) < MR_COUNTS_TTL_MS) {
    jsonResponse(res, 200, _publishDriftCache.data);
    return;
  }
  const gen = _publishDriftGen;
  // A forced read forces the catalog too: the client's own force=1 catalog
  // read runs next to this one, and candidates picked from an older snapshot
  // would be compared against a tree the client no longer classifies alike.
  const catalog = await _modulesCatalogSnapshot({ force });
  const lib = catalog.ok ? await _moduleUpdatesLib() : null;
  if (!catalog.ok || !_moduleUpdatesLibUsable(lib)) {
    jsonResponse(res, 200, { ok: true, items: [], failed: [], error: 'gitlab_error' });
    return;
  }
  const catalogById = new Map((catalog.entries || []).map((e) => [e.id, e]));
  const candidates = scanModulesDir().installed.filter((m) => {
    const entry = catalogById.get(m.id);
    const local = m.manifest && m.manifest.version;
    return entry && lib.classifyModuleUpdate(local, entry.manifest && entry.manifest.version) === 'current';
  });
  const items = [];
  const failed = [];
  const reconciled = [];
  const queue = candidates.slice();
  async function worker() {
    while (queue.length) {
      const m = queue.shift();
      let files;
      try { files = _collectModuleFiles(path.join(MODULES_DIR, m.id)); } catch { continue; }
      const tree = await _modulesCatalogTreeAll('modules/' + m.id);
      if (!tree.ok) { failed.push(m.id); continue; }
      const drift = modulePublishDrift(files, m.id, tree.items);
      // A differing module.json gets a second look at its CONTENT: the area an
      // install writes locally is not a change the person made.
      if (drift.changedPaths.includes('module.json')) {
        const local = files.find((f) => f.path === 'module.json');
        const remote = await _modulesCatalogGet(_modulesCatalogFileRawUrl('modules/' + m.id + '/module.json'));
        if (!remote.ok) { failed.push(m.id); continue; }
        if (manifestsEquivalentForPublish(local.data, remote.text)) {
          drift.changed -= 1;
          drift.paths = drift.paths.filter((p) => p !== 'module.json');
        }
      }
      delete drift.changedPaths;
      if (drift.added || drift.changed || drift.removed) items.push({ id: m.id, version: m.manifest.version, ...drift });
      else if (await _driftAutoReconcile(m.id, path.join(MODULES_DIR, m.id), m.manifest.version)) reconciled.push(m.id);
    }
  }
  await Promise.all(Array.from({ length: PUBLISH_DRIFT_CONCURRENCY }, worker));
  items.sort((a, b) => a.id.localeCompare(b.id));
  failed.sort();
  reconciled.sort();
  const data = { ok: true, items, failed, reconciled };
  if (failed.length) data.error = 'gitlab_error';
  // `reconciled` is news for THIS answer only: a cached copy repeating it
  // would make the client re-read the installed list on every cache hit.
  if (gen === _publishDriftGen) _publishDriftCache = { token, at: now, data: { ...data, reconciled: [] } };
  jsonResponse(res, 200, data);
}

/**
 * POST /api/modules/bump-version { id } -> { ok, from, to }
 * Raises module.json's patch number by one (bumpManifestPatch), under the
 * modules lock with tmp+rename. Local only - nothing reaches GitLab until the
 * person publishes. The drift cache is dropped so the next read sees the
 * module move from "same version" to "ready to publish".
 */
async function handleModulesBumpVersion(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try { body = await readBody(req); } catch { return jsonResponse(res, 400, { error: 'bad-request' }); }
  const id = body && typeof body.id === 'string' ? body.id : '';
  if (!MODULE_ID_RE.test(id) || RESERVED_MODULE_IDS.has(id)) return jsonResponse(res, 400, { error: 'invalid-id' });
  const dir = path.resolve(path.join(MODULES_DIR, id));
  const manifestPath = path.join(dir, 'module.json');
  if (!dir.startsWith(path.resolve(MODULES_DIR) + path.sep) || !fs.existsSync(manifestPath)) {
    return jsonResponse(res, 404, { error: 'not-found', message: 'There is no such module in the modules/ folder.' });
  }
  const result = await withModulesLock(() => {
    const next = bumpManifestPatch(fs.readFileSync(manifestPath, 'utf8'));
    if (!next.ok) return next;
    const tmp = manifestPath + '.tmp';
    fs.writeFileSync(tmp, next.text);
    fs.renameSync(tmp, manifestPath);
    return next;
  });
  if (!result.ok) {
    return jsonResponse(res, 400, {
      ok: false, error: result.error,
      message: 'Could not bump the version in module.json - the version must look like X.Y.Z.',
    });
  }
  _publishDriftGen += 1;
  _publishDriftCache = { token: null, at: 0, data: null };
  jsonResponse(res, 200, { ok: true, from: result.from, to: result.to });
}

/**
 * Commits exactly the published paths into the module's own repo after a
 * successful publish. Never throws.
 */
async function _modulePublishLocalCommit(dir, version, files, opts) {
  try {
    return await MG.moduleGitCommitPaths(dir, 'publish ' + _moduleAsciiVersion(version), (files || []).map((f) => f.path), opts);
  } catch (e) {
    return { ok: false, reason: 'commit-failed', message: e && e.message };
  }
}

/**
 * POST /api/modules/publish { id, summary?, status?, author?, tags?, featured? }
 * -> { ok, branch, mrUrl, mrIid, files, catalogMode }
 *
 * Always answers JSON. A missing token, an unreachable GitLab and a rejected
 * write are normal states with readable messages, never a 500 and never a raw
 * GitLab error page echoed at the user. Refuses with 409 `version-not-bumped`
 * when the manifest's version is not strictly higher than the catalog's own,
 * unless the catalog cannot be read (`catalogUnavailable: true` then lets the
 * publish through).
 */
async function handleModulesPublish(req, res) {
  if (!checkOrigin(req, res)) return;

  let body;
  try { body = await readBody(req); } catch { return jsonResponse(res, 400, { error: 'bad-request' }); }
  const id = body && typeof body.id === 'string' ? body.id : '';
  if (!MODULE_ID_RE.test(id) || RESERVED_MODULE_IDS.has(id)) {
    return jsonResponse(res, 400, { error: 'invalid-id' });
  }

  const dir = path.resolve(path.join(MODULES_DIR, id));
  if (!dir.startsWith(path.resolve(MODULES_DIR) + path.sep) || !fs.existsSync(dir)) {
    return jsonResponse(res, 404, { error: 'not-found', message: 'There is no such module in the modules/ folder.' });
  }

  let manifest;
  try {
    manifest = JSON.parse(fs.readFileSync(path.join(dir, 'module.json'), 'utf8'));
  } catch (e) {
    return jsonResponse(res, 400, { error: 'invalid-manifest', message: e.message });
  }

  // -- Area gate: validated BEFORE any GitLab access, and BEFORE the
  // no-token check below (plan fix: `no-token` used to return first, which
  // made the area gate untestable without a token even though it never
  // touches the network) -----------------------------------------------
  // An EXPLICIT `body.area` (the publish modal's "Area" field) always wins
  // over whatever is already in the manifest - this is how a person actually
  // changes the area at publish time (e.g. Product -> Engineering). It is
  // validated even when it is empty or not a string: a caller that names the
  // key gets a real answer, never a silent fallback to the old value.
  // `body.area` absent entirely (key not sent at all) falls back to the
  // manifest's own area.
  const bodyHasArea = body && Object.prototype.hasOwnProperty.call(body, 'area');
  let areaValue = null;
  if (bodyHasArea) {
    const areaCheck = validateModuleArea(body.area);
    if (!areaCheck.ok) {
      return jsonResponse(res, 400, { error: 'area-invalid', message: 'The module\'s business area is not valid.' });
    }
    areaValue = areaCheck.value;
  } else if (manifest.area !== undefined) {
    const areaCheck = validateModuleArea(manifest.area);
    if (!areaCheck.ok) {
      return jsonResponse(res, 400, { error: 'area-invalid', message: 'The module\'s business area is not valid.' });
    }
    areaValue = areaCheck.value;
  } else {
    return jsonResponse(res, 400, { error: 'area-missing', message: 'Give the module a business area.' });
  }
  if (areaValue !== manifest.area) {
    const manifestPath = path.join(dir, 'module.json');
    const savedArea = await withModulesLock(() => {
      const next = setManifestArea(fs.readFileSync(manifestPath, 'utf8'), areaValue);
      if (next.ok && next.changed) {
        const tmp = manifestPath + '.tmp';
        fs.writeFileSync(tmp, next.text);
        fs.renameSync(tmp, manifestPath);
      }
      return next;
    });
    if (!savedArea.ok) return jsonResponse(res, 400, { error: 'invalid-manifest', message: savedArea.error });
    manifest.area = areaValue;
  }

  if (!_modulesCatalogReady()) {
    return jsonResponse(res, 200, { ok: false, error: 'no-token', message: MODULES_CATALOG_NO_TOKEN_MESSAGE });
  }

  // The same validation the loader runs, against the DIRECTORY name, so a
  // manifest whose id disagrees with its folder is caught before publishing
  // rather than by the next person who installs it. `strict: true` because
  // the area gate above guarantees `manifest.area` is set by now.
  const validated = validateModuleManifest(manifest, id, { strict: true });
  if (!validated.valid) {
    return jsonResponse(res, 400, { error: 'invalid-manifest', message: validated.errors.join('; ') });
  }


  // Version gate: publishing over an equal or lower version than the catalog
  // already has would let two different bodies of code share one version
  // number. Runs BEFORE the status write-back below, so a refused publish
  // changes nothing on disk. A module absent from the catalog, or a catalog
  // this call cannot read, passes through - `catalogUnavailable` says so in
  // the final payload instead of blocking the publish.
  let catalogUnavailable = false;
  // Reused below to compute the base-version warning without a second GitLab
  // crawl - the snapshot and the lib are both cheap (module-level caches),
  // but the module's OWN catalog version is only known here.
  let moduleUpdatesLib = null;
  let catalogVersionForBase = null;
  {
    const catalogSnap = await _modulesCatalogSnapshot();
    catalogUnavailable = !catalogSnap.ok;
    if (catalogSnap.ok) {
      const lib = await _moduleUpdatesLib();
      if (!_moduleUpdatesLibUsable(lib)) {
        catalogUnavailable = true;
      } else {
        moduleUpdatesLib = lib;
        const entry = (catalogSnap.entries || []).find((e) => e.id === id);
        catalogVersionForBase = entry ? ((entry.manifest && entry.manifest.version) || null) : null;
        const gate = lib.publishVersionGate(manifest.version, entry ? (entry.manifest && entry.manifest.version) : null);
        if (!gate.ok) {
          return jsonResponse(res, 409, {
            ok: false, error: gate.error, localVersion: gate.localVersion,
            catalogVersion: gate.catalogVersion, message: gate.message,
          });
        }
      }
    }
  }

  // The status the modal asked for is SAVED, not merely sent: it goes into
  // module.json before the files are collected, so the published copy carries
  // it, the installed card shows it and the modal reopens on it. Only an
  // explicit, valid value writes - a request without one leaves the manifest
  // alone (and the publish keeps whatever the manifest already says).
  const status = MODULES_PUBLISH_STATUSES.includes(body.status)
    ? body.status
    : (MODULES_PUBLISH_STATUSES.includes(manifest.status) ? manifest.status : 'beta');
  if (MODULES_PUBLISH_STATUSES.includes(body.status) && manifest.status !== body.status) {
    const manifestPath = path.join(dir, 'module.json');
    const saved = await withModulesLock(() => {
      const next = setManifestStatus(fs.readFileSync(manifestPath, 'utf8'), body.status);
      if (!next.ok) return next;
      if (next.changed) {
        const tmp = manifestPath + '.tmp';
        fs.writeFileSync(tmp, next.text);
        fs.renameSync(tmp, manifestPath);
      }
      return next;
    });
    if (!saved.ok) return jsonResponse(res, 400, { error: 'invalid-manifest', message: saved.error });
    manifest.status = body.status;
  }

  let files;
  try {
    files = _collectModuleFiles(dir);
  } catch (e) {
    if (e.message === 'too-large') return jsonResponse(res, 413, { error: 'too-large' });
    if (e.message === 'too-many-files') return jsonResponse(res, 413, { error: 'too-many-files' });
    return jsonResponse(res, 400, { error: 'read-failed', message: e.message });
  }
  if (files.length === 0) return jsonResponse(res, 400, { error: 'empty-module' });

  if (_modulesCatalogIsLocal()) {
    return _modulesPublishLocal(res, { id, dir, body, manifest, files, status, catalogUnavailable, moduleUpdatesLib, catalogVersionForBase });
  }

  const projectPath = modulesCatalogProjectPath();
  if (!projectPath) return jsonResponse(res, 200, { ok: false, error: 'no-repo-url', message: 'The catalog repository address is missing.' });
  const projectApi = `${_gitlabApiBase()}/projects/${encodeURIComponent(projectPath)}`;
  const unreachable = (detail) => jsonResponse(res, 200, {
    ok: false, error: 'gitlab-unreachable',
    message: 'Could not talk to GitLab: ' + detail,
  });

  // Which of this module's paths already exist on the default branch, so each
  // action can be create or update, and so the destructive-publish guard has
  // something to compute deletions from. An incomplete read (a broken page
  // 2+, a non-array body, an x-total mismatch) refuses the WHOLE publish -
  // never "publish without deletions" - because create/update depend on the
  // same list. A 404 on page 1 means the module is new, not an error - once
  // the tree read's own probe has confirmed the project is visible; an
  // invisible project (no VPN, a token without access) is named as such.
  const treeRes = await _modulesCatalogTreeAll('modules/' + id);
  if (!treeRes.ok && treeRes.reason === 'no-access') {
    return jsonResponse(res, 200, { ok: false, error: 'gitlab-no-access', message: MODULES_CATALOG_NO_ACCESS_MESSAGE });
  }
  if (!treeRes.ok) return unreachable('could not read the module\'s complete file tree in the catalog (incomplete list).');
  const existingPaths = new Set();
  for (const it of treeRes.items) {
    if (it && it.type === 'blob' && typeof it.path === 'string') existingPaths.add(it.path);
  }

  // Destructive-publish guard, BEFORE any branch is created: a caller may
  // resubmit with confirmDeletes:true to override the size threshold, but
  // never the tree-mismatch refusal.
  const guard = publishDeleteGuard(files, id, existingPaths, { confirm: body.confirmDeletes === true });
  if (!guard.ok) {
    return jsonResponse(res, 409, {
      ok: false, error: guard.error, deletes: guard.deletes, kept: guard.kept, existing: guard.existing,
      message: guard.message,
    });
  }

  // catalog.json: absent (404) is legitimate - the curation starts empty.
  const catRes = await _modulesCatalogGet(_modulesCatalogFileRawUrl('catalog.json'));
  if (!catRes.ok && catRes.status !== 404) return unreachable('could not read catalog.json.');
  // Warm the GitLab identity FIRST, exactly as handleWhoami and _cocreateIdentity
  // do. _localIdentity() falls back to the git-config/OS name until
  // _gitlabIdentity() has resolved once, and publishing is gated by a DIFFERENT
  // token (COCKPIT_MODULES_TOKEN) than the one that identity reads, so a bare
  // call here can freeze the fallback slug into catalog.json's `owner` on the
  // first publish - which upsertCatalogEntry then refuses to overwrite for good,
  // and every later publish by the SAME person trips publishTakeover against
  // themselves. The 60 s cache keeps this to one call a minute.
  await _gitlabIdentity();
  const me = _localIdentity();
  const entry = { id, status };
  // The area gate above (400 area-missing / area-invalid, run before any
  // GitLab call) guarantees manifest.area is a valid, normalized string here.
  entry.area = manifest.area;
  if (typeof body.summary === 'string' && body.summary.trim()) entry.summary = body.summary.trim().slice(0, 300);
  else if (typeof manifest.description === 'string' && manifest.description.trim()) entry.summary = manifest.description.trim().slice(0, 300);
  if (typeof body.author === 'string' && body.author.trim()) entry.author = body.author.trim().slice(0, 120);
  if (Array.isArray(body.tags)) entry.tags = body.tags.filter((t) => typeof t === 'string' && t.trim()).slice(0, 10).map((t) => t.trim().slice(0, 40));
  if (body.featured === true) entry.featured = true;
  // The owner marker is written ONLY from a GitLab-sourced identity. It is
  // frozen for good on the first publish (upsertCatalogEntry never lets a
  // replace overwrite it), so a slug guessed from git config or the OS user is
  // exactly the value that must never land there: `_gitlabIdentity()` above is a
  // no-op without COCKPIT_APP_TOKEN, which is a DIFFERENT token from the one
  // gating publish, so that fallback is reachable - and it resolves the same
  // person to a different slug ("Morgan Alex" -> morgan-alex vs the
  // GitLab "Alex Morgan" -> alex-morgan), which would then trip
  // publishTakeover against themselves on every later publish. No authoritative
  // identity therefore means no owner and no takeover detection, the same path
  // an anonymous publish already took; the MR description says so instead.
  const owner = me && me.source === 'gitlab' ? me : null;
  if (owner) entry.owner = { slug: owner.person_slug, name: owner.display_name };

  const merged = upsertCatalogEntry(catRes.ok ? catRes.text : '', entry);
  if (!merged.ok) return jsonResponse(res, 200, { ok: false, error: 'catalog-invalid', message: merged.error });

  const takeover = publishTakeover(merged.previous, owner);

  // Warnings are informational only - the publish is never blocked by them.
  const warnings = [];
  const base = _readModulesOrigin()[id];
  if (!catalogUnavailable && moduleUpdatesLib && catalogVersionForBase) {
    const baseWarning = moduleUpdatesLib.publishBaseWarning(base && base.version, catalogVersionForBase);
    if (baseWarning && baseWarning.warn) {
      warnings.push({ code: 'base-outdated', message: baseWarning.message });
    }
  }
  if (takeover.takeover) {
    const prevName = (takeover.previousOwner && takeover.previousOwner.name) || 'someone else';
    // `owner`, not `me`: this branch runs only when publishTakeover said yes,
    // which now requires an authoritative identity, so the two are equal here -
    // reading the authoritative one keeps the warning and the marker in step.
    const meName = (owner && owner.display_name) || 'an anonymous publisher';
    warnings.push({
      code: 'owner-changed',
      message: 'This module was first published by ' + prevName + ' and is now being published by ' + meName + '.',
    });
  }

  const branch = modulesPublishBranchName(id, Date.now());
  const branchRes = await _modulesCatalogPostJson(
    `${projectApi}/repository/branches?branch=${encodeURIComponent(branch)}&ref=${encodeURIComponent(MODULES_CATALOG_REF)}`, {});
  if (!branchRes.ok) {
    // 403 here is the single most likely real-world failure: a token minted
    // before the scopes were widened, or a Reporter role.
    if (branchRes.status === 401 || branchRes.status === 403) {
      return jsonResponse(res, 200, {
        ok: false, error: 'forbidden',
        message: 'The token may not create branches. Create it again in Settings > Keys - it needs the api scope and the Developer role.',
      });
    }
    return unreachable('could not create the branch (HTTP ' + branchRes.status + ').');
  }

  const actions = buildPublishActions(files, id, existingPaths, { text: merged.text, exists: catRes.ok }, guard.deletes);
  const commitRes = await _modulesCatalogPostJson(`${projectApi}/repository/commits`, {
    branch,
    commit_message: 'feat(' + id + '): ' + (merged.mode === 'add' ? 'add module to the catalog' : 'update module in the catalog'),
    actions,
  });
  if (!commitRes.ok) {
    return unreachable('could not write the files to the branch (HTTP ' + commitRes.status + ').');
  }

  const descLines = [
    'Published from Mission Deck.',
    '',
    '- module: `' + id + '`',
    '- version: `' + (manifest.version || '?') + '`',
    '- files: ' + files.length,
  ];
  if (guard.deletes.length > 0) {
    descLines.push('- files deleted: ' + guard.deletes.length);
    const shown = guard.deletes.slice(0, 20);
    for (const p of shown) descLines.push('  - `' + p + '`');
    if (guard.deletes.length > shown.length) descLines.push('  - ... and ' + (guard.deletes.length - shown.length) + ' more');
  }
  // The RAW identity on purpose: the description tells the reviewer who ran
  // the publish, and a git-config name is useful there even though it is not
  // authoritative enough to freeze as the owner marker above.
  descLines.push('- published by: ' + ((me && me.display_name) || 'unknown identity'));
  for (const w of warnings) descLines.push('- ' + w.message);
  descLines.push('', 'The `main` branch is protected, so the change lands after review.');

  const mrRes = await _modulesCatalogPostJson(`${projectApi}/merge_requests`, {
    source_branch: branch,
    target_branch: MODULES_CATALOG_REF,
    title: (takeover.takeover ? '[Takeover] ' : '')
      + (merged.mode === 'add' ? 'New module: ' : 'Module update: ') + (manifest.name || id),
    description: descLines.join('\n'),
    remove_source_branch: true,
  });
  if (!mrRes.ok) {
    // The commit already landed on the branch, so this is recoverable by hand -
    // say so instead of implying the whole publish failed.
    return jsonResponse(res, 200, {
      ok: false, error: 'mr-failed', branch,
      message: 'The files reached branch ' + branch + ', but the merge request could not be opened (HTTP ' + mrRes.status + '). Open it by hand in GitLab.',
    });
  }

  // Only a SUCCESSFUL publish updates the base a later publish compares
  // itself against - handleModulesPublish is the one caller of
  // _setModuleOrigin that does not already hold withModulesLock.
  let localCommit = { ok: false, reason: 'not-run' };
  await withModulesLock(async () => {
    _setModuleOrigin(id, { source: 'publish', version: manifest.version, at: new Date().toISOString() });
    localCommit = await _modulePublishLocalCommit(dir, manifest.version, files, _moduleGitOpts({ author: _moduleGitCommitAuthor() }));
    if (!localCommit.ok && localCommit.reason !== 'no-repo' && localCommit.reason !== 'nothing-to-commit') {
      console.warn('[modules-publish] local commit failed for ' + id + ': ' + localCommit.reason);
    }
  });

  const newIid = (mrRes.json && mrRes.json.iid) || null;
  const authorId = (mrRes.json && mrRes.json.author && mrRes.json.author.id) || null;
  // AFTER the local commit: that commit is what proves the older MRs' versions
  // are in this tree, and an older MR of THIS publish's own version cannot exist.
  const superseded = Number.isInteger(newIid)
    ? await _closeSupersededPublishMrs(projectApi, id, newIid, authorId, dir)
    : [];

  return jsonResponse(res, 200, {
    ok: true,
    branch,
    mrUrl: (mrRes.json && mrRes.json.web_url) || null,
    mrIid: (mrRes.json && mrRes.json.iid) || null,
    files: files.length,
    catalogMode: merged.mode,
    catalogUnavailable,
    deleted: guard.deletes.length,
    // The list, not only the count: the person who triggered the deletion sees
    // the MR description only if they open GitLab, so the names belong in the
    // answer they get here. Capped like the MR description is.
    deletes: guard.deletes.slice(0, 20),
    warnings,
    takeover: takeover.takeover ? takeover.previousOwner : null,
    superseded,
    localCommit: { ok: Boolean(localCommit.ok), sha7: localCommit.sha7 || null, reason: localCommit.ok ? null : (localCommit.reason || null) },
  });
}

/**
 * Writes one module file set into a local catalog folder: every file through
 * tmp+rename, then every path in `deletes` removed and the directories they
 * leave empty pruned. Paths are re-checked against `moduleDir` - a file can
 * never land outside catalog/modules/<id>/. Dotfiles already in the folder
 * (a .gitignore the publish never sends) are left alone. Throws on I/O errors;
 * the caller answers them.
 * @param {string} moduleDir absolute catalog/modules/<id>
 * @param {Array<{path: string, data: Buffer}>} files
 * @param {string[]} deletes repo paths ('modules/<id>/...') to remove
 * @param {string} moduleId
 */
function _localCatalogWriteModule(moduleDir, files, deletes, moduleId) {
  const inside = (abs) => abs.startsWith(moduleDir + path.sep);
  for (const f of files) {
    const dest = path.resolve(moduleDir, f.path);
    if (!inside(dest)) throw new Error('unsafe-path: ' + f.path);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    const tmp = dest + '.tmp-' + process.pid;
    fs.writeFileSync(tmp, f.data);
    fs.renameSync(tmp, dest);
  }
  const prefix = 'modules/' + moduleId + '/';
  for (const p of deletes || []) {
    if (typeof p !== 'string' || !p.startsWith(prefix)) continue;
    const abs = path.resolve(moduleDir, p.slice(prefix.length));
    if (!inside(abs)) continue;
    fs.rmSync(abs, { force: true });
    // Prune the directories this delete emptied, never the module folder itself.
    let parent = path.dirname(abs);
    while (inside(parent)) {
      try {
        if (fs.readdirSync(parent).length > 0) break;
        fs.rmdirSync(parent);
      } catch { break; }
      parent = path.dirname(parent);
    }
  }
}

/**
 * The local half of POST /api/modules/publish: no branch, no merge request,
 * no token. The module's files are copied into <catalog>/modules/<id>/ and its
 * entry is upserted into <catalog>/catalog.json, both on this disk; the person
 * then commits or opens a pull request with their own git tooling. Every gate
 * before this point (area, manifest, version, status write-back) is shared
 * with the GitLab path, and so is the destructive-delete guard below.
 */
async function _modulesPublishLocal(res, ctx) {
  const { id, dir, body, manifest, files, status, catalogUnavailable, moduleUpdatesLib, catalogVersionForBase } = ctx;
  const catalogDir = modulesCatalogDir();
  const location = modulesCatalogSourceInfo().location;
  try {
    if (!fs.statSync(catalogDir).isDirectory()) throw new Error('not a directory');
  } catch {
    return jsonResponse(res, 200, {
      ok: false, error: 'catalog-missing',
      message: 'The local module catalog folder was not found (' + location + ').',
    });
  }

  const treeRes = await _modulesCatalogTreeAll('modules/' + id);
  if (!treeRes.ok) {
    return jsonResponse(res, 200, { ok: false, error: 'catalog-unreadable', message: 'Could not read the module folder in the local catalog.' });
  }
  const existingPaths = new Set();
  for (const it of treeRes.items) {
    if (it && it.type === 'blob' && typeof it.path === 'string') existingPaths.add(it.path);
  }
  const guard = publishDeleteGuard(files, id, existingPaths, { confirm: body.confirmDeletes === true });
  if (!guard.ok) {
    return jsonResponse(res, 409, {
      ok: false, error: guard.error, deletes: guard.deletes, kept: guard.kept, existing: guard.existing,
      message: guard.message,
    });
  }

  const catalogFile = path.join(catalogDir, 'catalog.json');
  let catalogText = '';
  try { catalogText = fs.readFileSync(catalogFile, 'utf8'); } catch (e) {
    if (e.code !== 'ENOENT') return jsonResponse(res, 200, { ok: false, error: 'catalog-unreadable', message: 'Could not read catalog.json: ' + e.message });
  }

  await _gitlabIdentity();
  const me = _localIdentity();
  const owner = me && me.source === 'gitlab' ? me : null;
  const entry = { id, status, area: manifest.area };
  if (typeof body.summary === 'string' && body.summary.trim()) entry.summary = body.summary.trim().slice(0, 300);
  else if (typeof manifest.description === 'string' && manifest.description.trim()) entry.summary = manifest.description.trim().slice(0, 300);
  if (typeof body.author === 'string' && body.author.trim()) entry.author = body.author.trim().slice(0, 120);
  if (Array.isArray(body.tags)) entry.tags = body.tags.filter((t) => typeof t === 'string' && t.trim()).slice(0, 10).map((t) => t.trim().slice(0, 40));
  if (body.featured === true) entry.featured = true;
  if (owner) entry.owner = { slug: owner.person_slug, name: owner.display_name };

  const merged = upsertCatalogEntry(catalogText, entry);
  if (!merged.ok) return jsonResponse(res, 200, { ok: false, error: 'catalog-invalid', message: merged.error });
  const takeover = publishTakeover(merged.previous, owner);

  const warnings = [];
  const base = _readModulesOrigin()[id];
  if (!catalogUnavailable && moduleUpdatesLib && catalogVersionForBase) {
    const baseWarning = moduleUpdatesLib.publishBaseWarning(base && base.version, catalogVersionForBase);
    if (baseWarning && baseWarning.warn) warnings.push({ code: 'base-outdated', message: baseWarning.message });
  }
  if (takeover.takeover) {
    const prevName = (takeover.previousOwner && takeover.previousOwner.name) || 'someone else';
    const meName = (owner && owner.display_name) || 'an anonymous publisher';
    warnings.push({ code: 'owner-changed', message: 'This module was first published by ' + prevName + ' and is now being published by ' + meName + '.' });
  }

  let localCommit = { ok: false, reason: 'not-run' };
  try {
    await withModulesLock(async () => {
      const moduleDir = path.join(catalogDir, 'modules', id);
      fs.mkdirSync(moduleDir, { recursive: true });
      _localCatalogWriteModule(path.resolve(moduleDir), files, guard.deletes, id);
      const tmp = catalogFile + '.tmp-' + process.pid;
      fs.writeFileSync(tmp, merged.text);
      fs.renameSync(tmp, catalogFile);
      _setModuleOrigin(id, { source: 'publish', version: manifest.version, at: new Date().toISOString() });
      localCommit = await _modulePublishLocalCommit(dir, manifest.version, files, _moduleGitOpts({ author: _moduleGitCommitAuthor() }));
      if (!localCommit.ok && localCommit.reason !== 'no-repo' && localCommit.reason !== 'nothing-to-commit') {
        console.warn('[modules-publish] local commit failed for ' + id + ': ' + localCommit.reason);
      }
    });
  } catch (e) {
    return jsonResponse(res, 200, { ok: false, error: 'write-failed', message: 'Could not write the module into the local catalog: ' + e.message });
  }

  // The catalog changed on disk: every snapshot reader must see it now.
  _modulesCatalogCache = { token: null, at: 0, data: null };
  _publishDriftGen += 1;
  _publishDriftCache = { token: null, at: 0, data: null };

  return jsonResponse(res, 200, {
    ok: true,
    local: true,
    catalogDir: location,
    modulePath: location + 'modules/' + id + '/',
    branch: null,
    mrUrl: null,
    mrIid: null,
    files: files.length,
    catalogMode: merged.mode,
    catalogUnavailable,
    deleted: guard.deletes.length,
    deletes: guard.deletes.slice(0, 20),
    warnings,
    takeover: takeover.takeover ? takeover.previousOwner : null,
    superseded: [],
    localCommit: { ok: Boolean(localCommit.ok), sha7: localCommit.sha7 || null, reason: localCommit.ok ? null : (localCommit.reason || null) },
  });
}

/**
 * Closes the open publish MRs of `id` that the MR `keepIid` supersedes (see
 * supersededPublishMrs), each with a note pointing at the new one. Best
 * effort: a GitLab failure leaves that MR open and is only logged - the
 * publish itself already succeeded. Never throws.
 * @returns {Promise<number[]>} iids actually closed
 */
async function _closeSupersededPublishMrs(projectApi, id, keepIid, authorId, dir) {
  const closed = [];
  try {
    const log = await MG.moduleGitLog(dir, _moduleGitOpts({ limit: 200 }));
    const versions = publishedVersionsFromLog(log && log.commits);
    if (!versions.size) return closed;
    const r = await _modulesCatalogGet(`${projectApi}/merge_requests?state=opened&per_page=${PENDING_PUBLISHES_PER_PAGE}`);
    let open = [];
    try { open = r.ok ? JSON.parse(r.text) : []; } catch { open = []; }
    for (const mr of supersededPublishMrs(open, id, keepIid, authorId, versions)) {
      await _modulesCatalogPostJson(`${projectApi}/merge_requests/${mr.iid}/notes`, {
        body: 'Superseded by !' + keepIid + ' - a newer publish of this module contains the changes of this version (' + mr.version + ').',
      });
      const c = await _modulesCatalogPostJson(`${projectApi}/merge_requests/${mr.iid}`, { state_event: 'close' }, 'PUT');
      if (c.ok) closed.push(mr.iid);
      else console.warn('[modules-publish] did not close MR !' + mr.iid + ' (HTTP ' + c.status + ')');
    }
  } catch (e) {
    console.warn('[modules-publish] closing superseded MRs: ' + ((e && e.message) || e));
  }
  if (closed.length) _pendingPublishesCache = { token: null, at: 0, data: null };
  return closed;
}

// ── Modules: filling in areas in the catalog (one MR on GitLab) ─────────────
// The catalog entries published before `area` existed (plan
// 2026-09-12-module-areas.md) show "Area not set" on every machine
// until the remote gets the field. POST /api/modules/publish cannot carry that
// fix: its version gate refuses an equal version (409 version-not-bumped), and
// bumping five versions to add one field would rewrite five whole file trees.
// So this is the publish flow minus the module files - one branch, one commit
// whose actions are catalog.json plus each modules/<id>/module.json with
// `area` set, one merge request. `main` stays protected; a human merges.
//
//   POST /api/modules/catalog/migrate-areas { areas?: {id: area}, dryRun?: true }
//
// Reached with curl only, like /api/cocreate/admin/reset: it is a one-off
// backfill, not a button. The area of each entry comes from the request body
// first and from the installed module of the same id second - never from a
// default, and an entry with no source is reported as skipped, not guessed.

/**
 * Which catalog entries get which area. Pure - no I/O.
 * @param {Array<{id: string, area?: string, curated?: boolean}>} entries
 *   mergeModulesCatalog output (`area` is already curation || manifest)
 * @param {Object<string, string>} installedAreas id -> area of the modules
 *   installed on this machine
 * @param {Object<string, string>} requested id -> area from the request body,
 *   already validated by the handler
 * @returns {{set: Array<{id: string, area: string, source: 'request'|'installed', curated: boolean}>,
 *   skipped: Array<{id: string, reason: 'has-area'|'area-invalid'|'no-source'}>}}
 */
function planCatalogAreaBackfill(entries, installedAreas, requested) {
  const set = [];
  const skipped = [];
  for (const e of Array.isArray(entries) ? entries : []) {
    if (!e || typeof e.id !== 'string') continue;
    if (typeof e.area === 'string' && e.area.trim()) { skipped.push({ id: e.id, reason: 'has-area' }); continue; }
    const curated = e.curated === true;
    const hasRequest = requested && Object.prototype.hasOwnProperty.call(requested, e.id);
    if (hasRequest) {
      const check = validateModuleArea(requested[e.id]);
      if (!check.ok) { skipped.push({ id: e.id, reason: 'area-invalid' }); continue; }
      set.push({ id: e.id, area: check.value, source: 'request', curated });
      continue;
    }
    const check = validateModuleArea(installedAreas ? installedAreas[e.id] : undefined);
    if (check.ok) { set.push({ id: e.id, area: check.value, source: 'installed', curated }); continue; }
    skipped.push({ id: e.id, reason: 'no-source' });
  }
  return { set, skipped };
}

/**
 * catalog.json text with `area` set on the named EXISTING entries. Pure.
 * Deliberately never adds an entry: an uncurated module takes its status from
 * its manifest (mergeModulesCatalog), and a curation entry created here would
 * silently change that to `stable`. A new key lands right after `status`,
 * the way setManifestArea places it; an existing one keeps its place and
 * every other field of the entry - `owner` included - is untouched.
 * @param {string} catalogText current catalog.json
 * @param {Object<string, string>} areasById id -> area
 * @returns {{ok: true, text: string, changed: string[], missing: string[]} | {ok: false, error: string}}
 */
function setCatalogEntryAreas(catalogText, areasById) {
  let doc;
  try { doc = JSON.parse(String(catalogText || '')); } catch (e) { return { ok: false, error: 'catalog-json-invalid: ' + e.message }; }
  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) return { ok: false, error: 'catalog-json-invalid' };
  if (doc.schemaVersion !== 1) return { ok: false, error: 'catalog-schema-unsupported' };
  if (!Array.isArray(doc.modules)) return { ok: false, error: 'catalog-json-invalid' };
  const changed = [];
  const missing = [];
  for (const [id, area] of Object.entries(areasById || {})) {
    const check = validateModuleArea(area);
    if (!check.ok) return { ok: false, error: 'area-invalid: ' + id };
    const at = doc.modules.findIndex((m) => m && m.id === id);
    if (at === -1) { missing.push(id); continue; }
    const entry = doc.modules[at];
    if (entry.area === check.value) continue;
    const out = {};
    let placed = false;
    for (const [k, v] of Object.entries(entry)) {
      if (k === 'area') { out.area = check.value; placed = true; continue; }
      out[k] = v;
      if (k === 'status' && !placed && entry.area === undefined) { out.area = check.value; placed = true; }
    }
    if (!placed) out.area = check.value;
    doc.modules[at] = out;
    changed.push(id);
  }
  return { ok: true, text: JSON.stringify(doc, null, 2) + '\n', changed, missing };
}

/**
 * POST /api/modules/catalog/migrate-areas { areas?, dryRun? }
 * -> { ok, dryRun, set, skipped, branch, mrUrl, mrIid, files }
 *
 * Always answers JSON the way handleModulesPublish does: a missing token and
 * an unreachable GitLab are readable states, never a 500. `dryRun: true`
 * answers the plan and touches nothing. The catalog is re-read fresh (no
 * cache) because the plan must be made against today's remote, not a
 * snapshot from a few minutes ago.
 */
async function handleModulesCatalogMigrateAreas(req, res) {
  if (!checkOrigin(req, res)) return;

  let body;
  try { body = await readBody(req); } catch { return jsonResponse(res, 400, { error: 'bad-request' }); }
  if (!body || typeof body !== 'object' || Array.isArray(body)) body = {};
  const dryRun = body.dryRun === true;
  const requested = {};
  if (body.areas !== undefined) {
    if (!body.areas || typeof body.areas !== 'object' || Array.isArray(body.areas)) {
      return jsonResponse(res, 400, { error: 'bad-request' });
    }
    for (const [id, area] of Object.entries(body.areas)) {
      if (!MODULE_ID_RE.test(id)) return jsonResponse(res, 400, { error: 'invalid-id', id });
      const check = validateModuleArea(area);
      if (!check.ok) {
        return jsonResponse(res, 400, { error: 'area-invalid', id, message: 'The module\'s business area is not valid.' });
      }
      requested[id] = check.value;
    }
  }

  if (!_modulesCatalogReady()) {
    return jsonResponse(res, 200, { ok: false, error: 'no-token', message: MODULES_CATALOG_NO_TOKEN_MESSAGE });
  }
  const unreachable = (message) => jsonResponse(res, 200, {
    ok: false, error: 'gitlab-unreachable', message: 'Could not fill in the areas in the catalog: ' + message,
  });

  const snap = await _modulesCatalogRefresh(Date.now());
  if (!snap.ok) return jsonResponse(res, 200, { ok: false, error: snap.error, message: snap.message });

  const installedAreas = {};
  for (const m of scanModulesDir().installed) {
    if (m.manifest && typeof m.manifest.area === 'string') installedAreas[m.id] = m.manifest.area;
  }
  const plan = planCatalogAreaBackfill(snap.entries, installedAreas, requested);
  const answer = (extra) => jsonResponse(res, 200, {
    ok: true, dryRun, set: plan.set, skipped: plan.skipped, branch: null, mrUrl: null, mrIid: null, files: 0, ...extra,
  });
  if (plan.set.length === 0) return answer({ message: 'Every catalog entry already has an area - nothing to fill in.' });
  if (dryRun) return answer({});

  // The files to patch, read RAW (the snapshot above carries parsed
  // manifests, and a write must start from the exact text on the branch).
  const actions = [];
  const curatedAreas = {};
  for (const s of plan.set) if (s.curated) curatedAreas[s.id] = s.area;
  if (Object.keys(curatedAreas).length > 0) {
    const catRes = await _modulesCatalogGet(_modulesCatalogFileRawUrl('catalog.json'));
    if (!catRes.ok) return unreachable('could not read catalog.json.');
    const next = setCatalogEntryAreas(catRes.text, curatedAreas);
    if (!next.ok) return jsonResponse(res, 200, { ok: false, error: 'catalog-invalid', message: next.error });
    if (next.changed.length > 0) actions.push({ action: 'update', file_path: 'catalog.json', content: next.text });
  }
  for (const s of plan.set) {
    const filePath = 'modules/' + s.id + '/module.json';
    const mRes = await _modulesCatalogGet(_modulesCatalogFileRawUrl(filePath));
    if (!mRes.ok) return unreachable('could not read ' + filePath + '.');
    const next = setManifestArea(mRes.text, s.area);
    if (!next.ok) return jsonResponse(res, 200, { ok: false, error: 'manifest-invalid', id: s.id, message: next.error });
    if (next.changed) actions.push({ action: 'update', file_path: filePath, content: next.text });
  }
  if (actions.length === 0) return answer({ message: 'Every catalog entry already has an area - nothing to fill in.' });

  if (_modulesCatalogIsLocal()) {
    // A local catalog takes the same patch straight onto the disk: no branch,
    // no merge request - the person commits the change with their own tools.
    try {
      await withModulesLock(() => {
        for (const a of actions) {
          const abs = _localCatalogResolve(a.file_path);
          if (!abs) throw new Error('unsafe-path: ' + a.file_path);
          const tmp = abs + '.tmp-' + process.pid;
          fs.writeFileSync(tmp, a.content);
          fs.renameSync(tmp, abs);
        }
      });
    } catch (e) {
      return jsonResponse(res, 200, { ok: false, error: 'write-failed', message: 'Could not update the local catalog: ' + e.message });
    }
    _modulesCatalogCache = { token: null, at: 0, data: null };
    return answer({ local: true, files: actions.length });
  }

  const projectApi = `${_gitlabApiBase()}/projects/${encodeURIComponent(modulesCatalogProjectPath())}`;
  const branch = 'catalog/areas-' + _modulesCatalogBranchStamp(Date.now());
  const branchRes = await _modulesCatalogPostJson(
    `${projectApi}/repository/branches?branch=${encodeURIComponent(branch)}&ref=${encodeURIComponent(MODULES_CATALOG_REF)}`, {});
  if (!branchRes.ok) {
    if (branchRes.status === 401 || branchRes.status === 403) {
      return jsonResponse(res, 200, {
        ok: false, error: 'forbidden',
        message: 'The token may not create branches. Create it again in Settings > Keys - it needs the api scope and the Developer role.',
      });
    }
    return unreachable('could not create the branch (HTTP ' + branchRes.status + ').');
  }

  const commitRes = await _modulesCatalogPostJson(`${projectApi}/repository/commits`, {
    branch,
    commit_message: 'chore(catalog): fill in module areas',
    actions,
  });
  if (!commitRes.ok) return unreachable('could not write the files to the branch (HTTP ' + commitRes.status + ').');

  await _gitlabIdentity();
  const me = _localIdentity();
  const descLines = ['Business areas of modules, filled in from Mission Deck.', ''];
  for (const s of plan.set) {
    descLines.push('- `' + s.id + '` → `' + s.area + '` (' + (s.source === 'request' ? 'given by hand' : 'from the installed module') + ')');
  }
  for (const s of plan.skipped) {
    if (s.reason === 'no-source') descLines.push('- `' + s.id + '` - skipped, no source for the area');
  }
  descLines.push('', '- files: ' + actions.length);
  descLines.push('- published by: ' + ((me && me.display_name) || 'unknown identity'));
  descLines.push('', 'The `main` branch is protected, so the change lands after review.');

  const mrRes = await _modulesCatalogPostJson(`${projectApi}/merge_requests`, {
    source_branch: branch,
    target_branch: MODULES_CATALOG_REF,
    title: 'Module areas in the catalog',
    description: descLines.join('\n'),
    remove_source_branch: true,
  });
  if (!mrRes.ok) {
    return jsonResponse(res, 200, {
      ok: false, error: 'mr-failed', branch,
      message: 'The files reached branch ' + branch + ', but the merge request could not be opened (HTTP ' + mrRes.status + '). Open it by hand in GitLab.',
    });
  }

  return answer({
    branch,
    mrUrl: (mrRes.json && mrRes.json.web_url) || null,
    mrIid: (mrRes.json && mrRes.json.iid) || null,
    files: actions.length,
  });
}

/**
 * GET /api/modules/installed -> { installed, invalid, activeIds, modulesDir }.
 * Fresh disk scan (unlike /api/modules/manifest, which reads the boot-time
 * _loadedModules snapshot) — see the plan's "two contract gaps" note: a
 * disabled module must still be visible so it can be re-enabled, and a module
 * dropped in after boot must show up before "requires restart" makes sense.
 */
/**
 * GET /api/modules/installed also carries the local git repository state per
 * module (docs/architecture/modules.md): a `git` field per installed
 * entry, plus a top-level `gitAvailable`. scanModulesDir() itself stays
 * synchronous (it runs inside loadModules() at boot) - the git probes run
 * only here, in parallel, one process each.
 */
async function handleModulesInstalled(_req, res) {
  const scan = scanModulesDir();
  const gitAvailable = await MG.gitAvailable();
  const originDoc = _readModulesOrigin();
  const installed = await Promise.all(scan.installed.map(async (m) => ({
    ...m,
    origin: originDoc[m.id] || null,
    git: gitAvailable
      ? await MG.moduleGitStatus(path.join(MODULES_DIR, m.id), _moduleGitOpts())
      : { present: fs.existsSync(path.join(MODULES_DIR, m.id, '.git')) },
  })));
  jsonResponse(res, 200, {
    installed,
    invalid: scan.invalid,
    activeIds: _loadedModules.modules.map(m => m.id),
    modulesDir: MODULES_DIR,
    gitAvailable,
  });
}

/**
 * POST /api/modules/toggle { id, enabled } -> flips membership of `id` in the
 * registry's `disabled` array. Read-only route surface stays the same; only
 * the JSON file on disk changes, so every change needs a restart to load or
 * unload the module's routes.
 */
async function handleModuleToggle(req, res) {
  if (!checkOrigin(req, res)) return;

  let body;
  try {
    body = await readBody(req);
  } catch {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }
  const { id, enabled } = body || {};
  if (typeof id !== 'string' || !MODULE_ID_RE.test(id) || typeof enabled !== 'boolean') {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }

  const disabledList = await withModulesLock(() => {
    const registry = _readModulesRegistry();
    const disabled = new Set(Array.isArray(registry.disabled) ? registry.disabled : []);
    if (enabled) disabled.delete(id); else disabled.add(id);
    const next = { ...registry, disabled: Array.from(disabled) };
    _writeModulesRegistry(next);
    return next.disabled;
  });

  jsonResponse(res, 200, { status: 'ok', disabled: disabledList, restartRequired: true });
}

/**
 * POST /api/modules/remove { id, removeData, force } -> deletes modules/<id>/
 * and, when removeData is true, data/modules/<id>/ too. Data is kept by
 * default — removing a module should not silently discard what it produced.
 * A module with an uncommitted local git repository refuses with 409
 * `module-dirty` unless `force:true` — that history is otherwise gone the
 * moment the directory is (docs/architecture/modules.md).
 */
async function handleModuleRemove(req, res) {
  if (!checkOrigin(req, res)) return;

  let body;
  try {
    body = await readBody(req);
  } catch {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }
  const { id, removeData, force } = body || {};
  if (typeof id !== 'string' || !MODULE_ID_RE.test(id)) {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }
  // Double guard: MODULE_ID_RE already excludes ".." and slashes, but a future
  // relaxation of that regex must not turn into a path-traversal delete.
  const dir = path.resolve(path.join(MODULES_DIR, id));
  if (!dir.startsWith(path.resolve(MODULES_DIR) + path.sep)) {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }
  if (!fs.existsSync(dir)) {
    return jsonResponse(res, 404, { error: 'not-found' });
  }

  // The dirty probe and the rmSync are ONE critical section: a git-commit or an
  // import for the same id that won the lock between the two would make the
  // probe's answer stale - a "clean" remove deleting a repository somebody just
  // committed to, or a module-dirty refusal for a tree that is clean by now.
  // Install and import already probe inside the lock for the same reason.
  const outcome = await withModulesLock(async () => {
    const st = await MG.moduleGitStatus(dir, _moduleGitOpts());
    if (st.present && st.dirty && force !== true) {
      return { dirty: true, changedFiles: st.changedFiles };
    }
    fs.rmSync(dir, { recursive: true, force: true, maxRetries: 3, retryDelay: 200 });
    if (removeData === true) {
      const dataDir = path.resolve(path.join(MODULES_DATA_DIR, id));
      if (dataDir.startsWith(path.resolve(MODULES_DATA_DIR) + path.sep)) {
        fs.rmSync(dataDir, { recursive: true, force: true, maxRetries: 3, retryDelay: 200 });
      }
    }
    // Drop `id` from `disabled` too, so a later re-install of the same id
    // does not silently come back turned off.
    const registry = _readModulesRegistry();
    const disabled = (Array.isArray(registry.disabled) ? registry.disabled : []).filter((x) => x !== id);
    _writeModulesRegistry({ ...registry, disabled });
    // The origin record describes a copy that no longer exists.
    _setModuleOrigin(id, null);
    return { dirty: false, removedRepo: st.present };
  });

  if (outcome.dirty) {
    return jsonResponse(res, 409, {
      error: 'module-dirty',
      changedFiles: outcome.changedFiles,
      message: 'The module has unsaved changes in its local repository - save a version or confirm the removal anyway.',
    });
  }

  jsonResponse(res, 200, { status: 'ok', removedData: Boolean(removeData), removedRepo: outcome.removedRepo, restartRequired: true });
}

// ── Modules: local git ──────────────────────────────────────────────────────
// The two routes behind the git row on a module card (scripts/_module-git.js).
// Both are human actions from Settings > Modules, never called by an agent.

/**
 * Turns a resolved local identity's display name into a git-safe author
 * name: strip `<`/`>` (they would break the "Name <email>" grammar a commit
 * author line depends on) and every control character, then cap the length.
 * Falls back to MG.DEFAULT_AUTHOR.name when nothing usable is left.
 * @param {unknown} rawName
 * @returns {string}
 */
function _moduleGitAuthorName(rawName) {
  if (typeof rawName !== 'string') return MG.DEFAULT_AUTHOR.name;
  const cleaned = rawName.replace(/[<>\x00-\x1f\x7f]/g, '').trim().slice(0, 80);
  return cleaned.length > 0 ? cleaned : MG.DEFAULT_AUTHOR.name;
}

/**
 * Resolves the module's own git author for a person-initiated "Save
 * version" commit: the display name GET /api/whoami already resolves, paired
 * with the fixed cockpit@local address (this repo has no per-person email
 * to draw from, and the address is never displayed).
 * @returns {{name: string, email: string}}
 */
function _moduleGitCommitAuthor() {
  const me = _localIdentity();
  return { name: _moduleGitAuthorName(me && me.display_name), email: 'cockpit@local' };
}

/**
 * POST /api/modules/git-init { id } -> "Initialize repository": git init +
 * a first commit for a module scaffolded before this feature shipped. The id
 * must match an entry scanModulesDir() actually found on disk, and it reaches
 * the path join only after MODULE_ID_RE, the reserved list and the
 * resolve-prefix guard have all passed - so the string joined below is the
 * matched record's id, character for character.
 */
async function handleModulesGitInit(req, res) {
  if (!checkOrigin(req, res)) return;

  let body;
  try {
    body = await readBody(req, 4096);
  } catch {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }
  const id = body && body.id;
  if (typeof id !== 'string' || !MODULE_ID_RE.test(id) || RESERVED_MODULE_IDS.has(id)) {
    return jsonResponse(res, 400, { error: 'invalid-id' });
  }
  const dir = path.resolve(path.join(MODULES_DIR, id));
  if (!dir.startsWith(path.resolve(MODULES_DIR) + path.sep)) {
    return jsonResponse(res, 400, { error: 'invalid-id' });
  }
  const match = scanModulesDir().installed.find((m) => m.id === id);
  if (!match) return jsonResponse(res, 404, { error: 'not-found' });

  const result = await withModulesLock(() => MG.moduleGitInit(dir, 'initial state', _moduleGitOpts()));

  if (!result.ok && result.reason === 'already-present') {
    return jsonResponse(res, 409, { error: 'already-present', message: 'This module already has a local repository.' });
  }
  if (!result.ok && result.reason === 'git-missing') {
    return jsonResponse(res, 200, { ok: false, reason: 'git-missing', message: 'Git is not installed on this computer.' });
  }
  if (!result.ok) {
    return jsonResponse(res, 200, { ok: false, reason: result.reason, message: result.message || 'Could not initialize the repository.' });
  }

  const git = await MG.moduleGitStatus(dir, _moduleGitOpts());
  jsonResponse(res, 200, { ok: true, git });
}

/**
 * POST /api/modules/git-commit { id, message } -> "Save version": git add
 * -A + a commit inside modules/<id>/ alone (pinned by scripts/_module-git.js,
 * never the mission-deck tree). A human action from the module card - never
 * called by an agent.
 */
async function handleModulesGitCommit(req, res) {
  if (!checkOrigin(req, res)) return;

  let body;
  try {
    body = await readBody(req, 4096);
  } catch {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }
  const id = body && body.id;
  if (typeof id !== 'string' || !MODULE_ID_RE.test(id) || RESERVED_MODULE_IDS.has(id)) {
    return jsonResponse(res, 400, { error: 'invalid-id' });
  }
  const dir = path.resolve(path.join(MODULES_DIR, id));
  if (!dir.startsWith(path.resolve(MODULES_DIR) + path.sep)) {
    return jsonResponse(res, 400, { error: 'invalid-id' });
  }
  const match = scanModulesDir().installed.find((m) => m.id === id);
  if (!match) return jsonResponse(res, 404, { error: 'not-found' });

  const message = typeof body.message === 'string' ? body.message.trim() : '';
  if (!message || message.length > 200) {
    return jsonResponse(res, 400, { error: 'bad-message' });
  }

  const author = _moduleGitCommitAuthor();
  const result = await withModulesLock(() => MG.moduleGitCommit(dir, message, _moduleGitOpts({ author })));

  if (!result.ok && result.reason === 'no-repo') {
    return jsonResponse(res, 409, { error: 'no-repo', message: 'This module does not have a local repository yet.' });
  }
  if (!result.ok && result.reason === 'nothing-to-commit') {
    return jsonResponse(res, 409, { error: 'nothing-to-commit' });
  }
  if (!result.ok) {
    return jsonResponse(res, 400, { error: result.reason || 'commit-failed', message: result.message });
  }

  const git = await MG.moduleGitStatus(dir, _moduleGitOpts());
  jsonResponse(res, 200, { ok: true, sha7: result.sha7, git });
}

/**
 * GET /api/modules/git-log?id=<id>&limit=<n> -> the recent commits of ONE
 * module's own repository, newest first, for the "History" list a card
 * expands under its "last saved" line. Read-only and fetched per click,
 * never as part of GET /api/modules/installed (which already spawns one git
 * per module per render). Shapes: `{ ok, present:false, commits:[] }` for a
 * module with no .git yet, `{ ok, present:true, commits }` otherwise; a git
 * failure is a 200 with `ok:false` and a readable message, because "cannot
 * read the history" is an answer the card renders, not a server fault.
 */
async function handleModulesGitLog(req, res) {
  const params = new URL(req.url, 'http://localhost').searchParams;
  const id = params.get('id') || '';
  if (!MODULE_ID_RE.test(id) || RESERVED_MODULE_IDS.has(id)) {
    return jsonResponse(res, 400, { error: 'invalid-id' });
  }
  const dir = path.resolve(path.join(MODULES_DIR, id));
  if (!dir.startsWith(path.resolve(MODULES_DIR) + path.sep)) {
    return jsonResponse(res, 400, { error: 'invalid-id' });
  }
  const match = scanModulesDir().installed.find((m) => m.id === id);
  if (!match) return jsonResponse(res, 404, { error: 'not-found' });

  const rawLimit = parseInt(params.get('limit') || '', 10);
  const limit = Number.isInteger(rawLimit) && rawLimit > 0 ? rawLimit : undefined;

  const log = await MG.moduleGitLog(path.join(MODULES_DIR, match.id), _moduleGitOpts({ limit }));
  if (!log.present) {
    return jsonResponse(res, 200, { ok: true, present: false, commits: [] });
  }
  if (log.error) {
    return jsonResponse(res, 200, { ok: false, present: true, reason: 'git-error', message: 'Could not read the module history: ' + log.error });
  }
  jsonResponse(res, 200, { ok: true, present: true, commits: log.commits });
}

/**
 * Reduce an arbitrary manifest string to characters that are safe inside a
 * Content-Disposition filename: ASCII letters, digits, dot, dash, underscore.
 * Anything else (a control character, a quote, an accented letter) is dropped.
 * Empty or unusable input falls back to `fallback`.
 * @param {unknown} value
 * @param {string} fallback
 * @returns {string}
 */
function _safeFilenamePart(value, fallback) {
  const safe = (value === null || value === undefined) ? '' : value;
  const cleaned = String(safe).replace(/[^A-Za-z0-9._-]/g, '');
  return cleaned.length > 0 ? cleaned.slice(0, 64) : fallback;
}

/**
 * GET /api/modules/export?id=<id> -> a .zip download of modules/<id>/,
 * entries prefixed with "<id>/" so the archive is self-describing once
 * unzipped by hand. Every ERROR path still leaves through jsonResponse; only
 * the success path answers a binary body directly (see plan Risks).
 */
function handleModuleExport(req, res) {
  const id = new URL(req.url, 'http://localhost').searchParams.get('id') || '';
  if (!MODULE_ID_RE.test(id)) {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }
  const dir = path.resolve(path.join(MODULES_DIR, id));
  if (!dir.startsWith(path.resolve(MODULES_DIR) + path.sep)) {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }
  if (!fs.existsSync(dir)) {
    return jsonResponse(res, 404, { error: 'not-found' });
  }

  let manifest;
  try {
    manifest = JSON.parse(fs.readFileSync(path.join(dir, 'module.json'), 'utf8'));
  } catch (e) {
    return jsonResponse(res, 400, { error: 'invalid-manifest', message: e.message });
  }

  const entries = [];
  let totalBytes = 0;
  function walk(relDir) {
    const abs = path.join(dir, relDir);
    let list;
    try { list = fs.readdirSync(abs, { withFileTypes: true }); } catch { return; }
    for (const e of list) {
      if (_isModuleJunkEntry(e.name)) continue;
      const relPath = relDir ? relDir + '/' + e.name : e.name;
      const absPath = path.join(dir, relPath);
      let st;
      try { st = fs.lstatSync(absPath); } catch { continue; }
      if (st.isSymbolicLink()) continue;
      if (st.isDirectory()) { walk(relPath); continue; }
      if (!st.isFile()) continue;
      totalBytes += st.size;
      if (totalBytes > MODULE_EXPORT_MAX_BYTES) throw new Error('too-large');
      entries.push({ name: id + '/' + relPath, data: fs.readFileSync(absPath), mtime: st.mtime });
    }
  }

  try {
    walk('');
  } catch (e) {
    if (e.message === 'too-large') return jsonResponse(res, 413, { error: 'too-large' });
    return jsonResponse(res, 400, { error: 'export-failed', message: e.message });
  }

  const buf = writeZip(entries);
  // The manifest only guarantees `version` is a non-empty string, and this value
  // goes straight into a response header. A CR/LF or any non-Latin1 character
  // makes res.writeHead throw ERR_INVALID_CHAR synchronously, which would break
  // export for an honest author using a non-ASCII version just as surely as for
  // an imported manifest that set one deliberately. Reduce to a safe class here
  // rather than tightening validateModuleManifest, which would retroactively
  // invalidate modules that are otherwise fine.
  const version = _safeFilenamePart(manifest.version, '0.0.0');
  res.writeHead(200, {
    'Content-Type': 'application/zip',
    'Content-Disposition': 'attachment; filename="' + id + '-' + version + '.zip"',
    'Content-Length': buf.length,
    'Cache-Control': 'no-store',
  });
  res.end(buf);
}

/**
 * True for a zip entry name this import must silently drop before any check:
 * macOS resource forks, genuine dotfiles/dotdirs and vendored trees. Must NOT
 * match ".." — a traversal segment has to reach isSafeEntryName below and
 * fail the WHOLE import loudly, never be swallowed here as if it were benign.
 */
function _isIncidentalImportEntry(name) {
  if (name.startsWith('__MACOSX/')) return true;
  return name.split('/').some((seg) => (seg.startsWith('.') && seg !== '.' && seg !== '..') || seg === 'node_modules' || seg === '__pycache__' || /\.py[co]$/.test(seg));
}

/**
 * POST /api/modules/import { filename, dataBase64, overwrite } -> installs a
 * module from a base64-encoded zip. `filename` is never used as a path, only
 * in messages. Order of checks is part of the security contract (plan step
 * 11) and must not be reordered: origin -> size -> archive parse -> filter ->
 * per-entry safety -> common-prefix strip -> manifest -> atomic install.
 */
async function handleModuleImport(req, res) {
  if (!checkOrigin(req, res)) return;

  let body;
  try {
    body = await readBody(req, MODULE_IMPORT_MAX_B64);
  } catch {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }
  const { dataBase64 } = body || {};
  const overwrite = body && body.overwrite === true;
  if (typeof dataBase64 !== 'string' || !dataBase64) {
    return jsonResponse(res, 400, { error: 'bad-request' });
  }

  const zipBuf = Buffer.from(dataBase64, 'base64');
  if (zipBuf.length > MODULE_IMPORT_MAX_ZIP_BYTES) {
    return jsonResponse(res, 413, { error: 'too-large' });
  }

  let rawEntries;
  try {
    rawEntries = readZip(zipBuf, { maxEntries: 2000, maxFileBytes: 4 * 1024 * 1024, maxTotalBytes: 32 * 1024 * 1024 });
  } catch (e) {
    return jsonResponse(res, 400, { error: 'bad-archive', message: e.message });
  }

  let entries = rawEntries.filter((e) => !e.isDir && !_isIncidentalImportEntry(e.name));

  // Barrier #1 (isSafeEntryName) + symlink attribute check, before any prefix
  // stripping and before any write. A single unsafe entry fails the WHOLE
  // import — no silent per-entry skip.
  for (const e of entries) {
    if (!isSafeEntryName(e.name)) return jsonResponse(res, 400, { error: 'unsafe-entry' });
    const unixMode = e.externalAttributes >>> 16;
    if ((unixMode & 0xF000) === 0xA000) return jsonResponse(res, 400, { error: 'unsafe-entry' });
  }

  // macOS zips (and our own export) wrap everything in one top-level
  // directory — strip it so module.json lands at the top. Every entry must
  // actually contain a "/" for this to apply; a flat "module.json" with no
  // separator is not itself a directory wrapping the rest.
  const allNamesNested = entries.length > 0 && entries.every((e) => e.name.includes('/'));
  const topDirs = new Set(entries.map((e) => e.name.split('/')[0]));
  if (allNamesNested && topDirs.size === 1) {
    const prefix = [...topDirs][0] + '/';
    entries = entries
      .map((e) => ({ ...e, name: e.name.slice(prefix.length) }))
      .filter((e) => e.name.length > 0);
  }

  // Extraction must not overwrite the manifest that was validated. Reject
  // case-only collisions too: macOS and Windows commonly fold file names.
  const entryNames = new Set();
  for (const entry of entries) {
    const key = entry.name.toLowerCase();
    if (entryNames.has(key)) {
      return jsonResponse(res, 400, { error: 'duplicate-entry', message: 'The archive contains duplicate file paths.' });
    }
    entryNames.add(key);
  }

  const manifestEntry = entries.find((e) => e.name === 'module.json');
  if (!manifestEntry) return jsonResponse(res, 400, { error: 'no-manifest' });

  let manifest;
  try {
    manifest = JSON.parse(manifestEntry.data.toString('utf8'));
  } catch (e) {
    return jsonResponse(res, 400, { error: 'invalid-manifest', errors: ['cannot parse module.json: ' + e.message] });
  }
  // manifest.id decides the target directory name — there is no directory yet
  // to compare it against, so passing it as its own dirId is intentional, not
  // a tautology bug (see plan Risks): every OTHER check still applies.
  const id = manifest && manifest.id;

  // Structural check FIRST, in soft mode: any other defect (bad id, reserved
  // id, malformed views, ...) answers its usual invalid-manifest error rather
  // than being masked by the area gate below. Soft mode only tolerates a
  // MISSING area here - an invalid area VALUE still fails now, same as every
  // other field.
  const preCheck = validateModuleManifest(manifest, id);
  if (!preCheck.valid) return jsonResponse(res, 400, { error: 'invalid-manifest', errors: preCheck.errors });

  // -- Area gate: same rules and order as handleModulesInstall ---------------
  // (a) manifest.area if valid; (b) body.area if valid; (c) ONLY when
  // overwrite is true, the area already on the module being updated (the
  // update path must never ask and must never lose the existing area);
  // (d) otherwise 409 area-required with ZERO writes so far - nothing has
  // been extracted to disk yet at this point in the handler.
  let resolvedArea = null;
  if (manifest.area !== undefined) {
    const check = validateModuleArea(manifest.area);
    if (check.ok) resolvedArea = check.value;
  }
  // An EXPLICIT body.area (the client named the key, even with an empty
  // string or a non-string) must be validated and, if invalid, refused right
  // here with 400 area-invalid - it must never be silently ignored and fall
  // through to the overwrite-existing-area fallback below. body.area simply
  // ABSENT (key never sent) is the normal "let the gate resolve it from
  // elsewhere" case.
  const bodyHasArea = body && Object.prototype.hasOwnProperty.call(body, 'area');
  if (bodyHasArea) {
    const check = validateModuleArea(body.area);
    if (!check.ok) {
      return jsonResponse(res, 400, { error: 'area-invalid', message: 'The module\'s business area is not valid.' });
    }
    if (resolvedArea === null) resolvedArea = check.value;
  }
  // An overwrite's fallback is resolved under the swap lock below, not from
  // a snapshot that could become stale while another operation holds it.
  if (resolvedArea === null && !overwrite) {
    return jsonResponse(res, 409, { error: 'area-required', needsArea: true, id, suggestions: _moduleAreaSuggestions() });
  }
  // Always write the resolved area into the archive's own module.json before
  // extraction - including the areaFromExisting case: the import replaces the
  // whole on-disk tree, so the retained area must be written into the NEW
  // module.json too, not merely kept true in memory for validation.
  if (resolvedArea !== null && resolvedArea !== manifest.area) {
    const next = setManifestArea(manifestEntry.data.toString('utf8'), resolvedArea);
    if (next.ok) {
      manifestEntry.data = Buffer.from(next.text, 'utf8');
      manifest.area = resolvedArea;
    }
  }

  const validation = validateModuleManifest(manifest, id, { strict: resolvedArea !== null });
  if (!validation.valid) return jsonResponse(res, 400, { error: 'invalid-manifest', errors: validation.errors });

  // Stale-backup guard BEFORE any write: a stray modules/<id>.bak-* left by a
  // crashed swap (rename-back-.git failed, see below) may be the ONLY copy of
  // the module's history left. Never auto-delete it - refuse and point at it
  // (docs/architecture/modules.md gap fix).
  const staleBackup = _findStaleModuleBackup(id);
  if (staleBackup) {
    return jsonResponse(res, 409, { error: 'stale-backup', id, message: _staleModuleBackupMessage(staleBackup) });
  }

  const tmpDir = path.join(MODULES_DIR, '.import-' + process.pid + '-' + Date.now());
  const tmpRoot = path.resolve(tmpDir) + path.sep;

  try {
    fs.mkdirSync(tmpDir, { recursive: true });
    for (const e of entries) {
      const dest = path.resolve(tmpDir, e.name);
      // Barrier #3: final safety net right before the write, in case the
      // first two ever had a gap.
      if (!dest.startsWith(tmpRoot)) {
        throw Object.assign(new Error('unsafe entry after prefix strip: ' + e.name), { code: 'unsafe-entry' });
      }
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.writeFileSync(dest, e.data);
    }

    const outcome = await withModulesLock(async () => {
      const target = path.join(MODULES_DIR, id);
      const existed = fs.existsSync(target);
      if (existed && !overwrite) return { conflict: true };

      if (resolvedArea === null) {
        let existingText;
        try {
          existingText = fs.readFileSync(path.join(target, 'module.json'), 'utf8');
        } catch (e) {
          if (e.code !== 'ENOENT') {
            return { errorStatus: 500, errorBody: { error: 'io-error', message: 'Cannot read the existing manifest: ' + e.message } };
          }
        }
        if (existingText !== undefined) {
          let existingManifest;
          try {
            existingManifest = JSON.parse(existingText);
          } catch (e) {
            return { errorStatus: 400, errorBody: { error: 'invalid-manifest', message: 'The existing module manifest is corrupted: ' + e.message } };
          }
          const check = validateModuleArea(existingManifest && existingManifest.area);
          if (check.ok) resolvedArea = check.value;
        }
        if (resolvedArea === null) {
          return { errorStatus: 409, errorBody: { error: 'area-required', needsArea: true, id, suggestions: _moduleAreaSuggestions() } };
        }
        const manifestPath = path.join(tmpDir, 'module.json');
        const next = setManifestArea(fs.readFileSync(manifestPath, 'utf8'), resolvedArea);
        if (!next.ok) {
          return { errorStatus: 400, errorBody: { error: 'invalid-manifest', message: next.error } };
        }
        if (next.changed) {
          fs.writeFileSync(manifestPath + '.tmp', next.text);
          fs.renameSync(manifestPath + '.tmp', manifestPath);
        }
        manifest.area = resolvedArea;
      }
      const finalValidation = validateModuleManifest(manifest, id, { strict: true });
      if (!finalValidation.valid) {
        return { errorStatus: 400, errorBody: { error: 'invalid-manifest', errors: finalValidation.errors } };
      }

      let prevGit = { present: false };
      if (existed) {
        prevGit = await MG.moduleGitStatus(target, _moduleGitOpts());
        if (prevGit.present && prevGit.dirty) return { dirty: true };
      }

      let bak = null;
      if (existed) {
        bak = target + '.bak-' + Date.now();
        fs.renameSync(target, bak);
      }
      fs.renameSync(tmpDir, target);
      // Same swap order as the catalog install: old dir aside, new tree in,
      // .git back, THEN the backup goes - never delete the old .git first.
      if (prevGit.present && bak) {
        const restored = _restoreModuleGitAfterSwap(bak, target);
        if (!restored.ok) {
          // The new tree is already live at target WITHOUT its history; bak
          // still holds the only copy - leave it on disk, never rmSync it,
          // and report the specific failure rather than a generic
          // import-failed (docs/architecture/modules.md gap fix). A
          // retry hits the stale-backup guard above until a human resolves
          // this by hand.
          console.warn('[modules-import] could not restore .git from ' + bak + ':', restored.error);
          return { stranded: true, backupName: path.basename(bak) };
        }
      }
      if (bak) fs.rmSync(bak, { recursive: true, force: true, maxRetries: 3, retryDelay: 200 });

      let git;
      if (prevGit.present) {
        const commitResult = await MG.moduleGitCommit(target, 'import from zip file', _moduleGitOpts());
        git = { kept: true, committed: commitResult.ok };
      } else {
        const initResult = await MG.moduleGitInit(target, 'import from zip file', _moduleGitOpts());
        git = { initialized: initResult.ok, reason: initResult.ok ? null : initResult.reason };
      }

      _setModuleOrigin(id, { source: 'zip', version: manifest.version, at: new Date().toISOString() });

      return { conflict: false, dirty: false, overwritten: existed, git };
    });

    if (outcome.errorStatus) return jsonResponse(res, outcome.errorStatus, outcome.errorBody);
    if (outcome.conflict) return jsonResponse(res, 409, { error: 'exists', id });
    if (outcome.dirty) {
      return jsonResponse(res, 409, {
        error: 'module-dirty',
        id,
        message: 'The module has unsaved changes in its local repository - save a version (Settings > Modules) or remove the module by hand before importing it again.',
      });
    }
    if (outcome.stranded) {
      return jsonResponse(res, 500, {
        error: 'history-stranded',
        id,
        message: _strandedModuleHistoryMessage(outcome.backupName),
      });
    }

    jsonResponse(res, 200, {
      status: 'ok', id, name: manifest.name, version: manifest.version,
      overwritten: outcome.overwritten, restartRequired: true, git: outcome.git,
    });
  } catch (e) {
    if (e && e.code === 'unsafe-entry') return jsonResponse(res, 400, { error: 'unsafe-entry' });
    jsonResponse(res, 400, { error: 'import-failed', message: e.message });
  } finally {
    // The temp dir must never survive any error path — including the happy
    // path, where renameSync already moved it and this is a harmless no-op.
    fs.rmSync(tmpDir, { recursive: true, force: true, maxRetries: 3, retryDelay: 200 });
  }
}

// ── Onboarding (wave 2) ──────────────────────────────────────────────────────
// Placeholder section. The onboarding wizard ships in wave 2. The endpoints
// below are specified in user-data/BUILD-CONTRACT.md and are intentionally
// NOT implemented yet:
//
//   GET  /api/onboarding-wizard/status
//   GET  /api/onboarding-wizard/clone-progress
//
// "Academy" (/api/cocreate/*) shipped ahead of the wizard - see the
// "-- Academy --" section below - so its prefix is no longer here.
//
// Until the wizard lands the router answers its routes with a 501 carrying
// `wave: 2`, so the frontend can render "coming soon" instead of guessing from a
// bare 404.
const WAVE2_ROUTE_PREFIXES = ['/api/onboarding-wizard/'];
const WAVE2_ROUTES = new Set();

function _isWave2Route(urlPath) {
  return WAVE2_ROUTES.has(urlPath) || WAVE2_ROUTE_PREFIXES.some(p => urlPath.startsWith(p));
}

function handleWave2NotImplemented(_req, res) {
  jsonResponse(res, 501, {
    error: 'not-implemented',
    wave: 2,
    message: 'This feature will be available in the second wave (rollout wizard).',
  });
}

// -- Academy --
// The "Training" view's backend: progressive, server-checked training stages.
// Full contract: docs/architecture/academy.md. Frontend config
// (curriculum text, tab list, gating list) lives in ONE place this file also
// reads - js/academy-stages.mjs - never a second copy of that content
// in here. What IS here, on purpose, is a small fallback shape (etap ids and
// the gated-stage order) used only when that file cannot be loaded, so the
// six routes below stay correct even before it exists.
//
// Two rules a reviewer should check first:
//   - a module id from a request body never reaches a filesystem path or a
//     process argument - the three module checks below match against
//     scanModulesDir().installed (derived from disk) and use ONLY that
//     record's own id.
//   - this whole section spawns NO child process of its own - every check
//     reads a file or reuses an existing probe/fetch helper. The Claude Code
//     login step was the one exception (`claude auth status`) until it turned
//     out that command answers "are there credentials on this machine", not
//     "is this CLI logged in": it passed for a person the CLI still asked to
//     log in. There is no cheap call that answers the second question - a
//     real API call costs money and seconds - so the step is self-attest now
//     and the spawn is gone.

// Stages: lazy load of js/academy-stages.mjs -------------------------

const COCREATE_STAGES_MODULE_PATH = path.join(ROOT, 'js', 'academy-stages.mjs');
const COCREATE_ETAP_IDS_FALLBACK = ['etap-1', 'etap-2', 'etap-3', 'etap-4'];
const COCREATE_GATED_STAGES_FALLBACK = ['etap-1', 'etap-2', 'etap-3'];

let _cocreateStagesCache = null;

/**
 * Loads { STAGES, TC_TABS, GATED_STAGES } from js/academy-stages.mjs,
 * once per process (module-level cache - restart the server to pick up an
 * edit). A missing file or a syntax error degrades to the fallback shape
 * above rather than throwing: a fresh checkout without that file yet must
 * still answer every route below with a normal response.
 * @returns {Promise<{STAGES: object[], TC_TABS: object[], GATED_STAGES: string[]}>}
 */
async function _cocreateStages() {
  if (_cocreateStagesCache) return _cocreateStagesCache;
  try {
    const mod = await import(pathToFileURL(COCREATE_STAGES_MODULE_PATH).href);
    const STAGES = Array.isArray(mod.STAGES) ? mod.STAGES : [];
    const TC_TABS = Array.isArray(mod.TC_TABS) ? mod.TC_TABS : [];
    const GATED_STAGES = Array.isArray(mod.GATED_STAGES) && mod.GATED_STAGES.length > 0
      ? mod.GATED_STAGES
      : COCREATE_GATED_STAGES_FALLBACK;
    _cocreateStagesCache = { STAGES, TC_TABS, GATED_STAGES };
  } catch (e) {
    console.warn('[cocreate] js/academy-stages.mjs unavailable, using the default shape:', e.message);
    _cocreateStagesCache = { STAGES: [], TC_TABS: [], GATED_STAGES: COCREATE_GATED_STAGES_FALLBACK };
  }
  return _cocreateStagesCache;
}

function _cocreateEtapIds(cfg) {
  return cfg.STAGES.length > 0 ? cfg.STAGES.map((s) => s.id) : COCREATE_ETAP_IDS_FALLBACK;
}

function _cocreateFindEtap(cfg, etap) {
  return cfg.STAGES.find((s) => s.id === etap) || null;
}

function _cocreateFindStep(etapCfg, step) {
  if (!etapCfg || !Array.isArray(etapCfg.steps)) return null;
  return etapCfg.steps.find((s) => s.id === step) || null;
}

function _cocreateIsGated(gatedStages, etap) {
  return gatedStages.includes(etap);
}

/** Pure gating decision: does `personSlug` currently qualify to unlock `etap`? */
function _cocreateCanUnlock(progress, gatedStages, etap, personSlug) {
  if (!_cocreateIsGated(gatedStages, etap)) return true; // etap-1 and any ungated etap
  const idx = gatedStages.indexOf(etap);
  if (idx <= 0) return true; // the first gated stage is always open
  const previous = gatedStages[idx - 1];
  return _cocreateHasPerson((progress.completed || {})[previous], personSlug);
}

// Identity ---------------------------------------------------------------------
// Mirrors handleWhoami's own order: the GitLab-derived record is authoritative
// once it exists, so this must await it before falling back to the git/OS
// name - otherwise a vault unlock mid-session would split one person's
// progress across two different person_slug values.
async function _cocreateIdentity() {
  await _gitlabIdentity();
  return _localIdentity();
}

function _cocreateSlugFromName(name) {
  return _normalizeName(name || '').replace(/\s+/g, '-');
}

/**
 * Photo URL for a person_slug, resolved against the team directory the same
 * way js/team-directory.js does client-side (first_name + last_name,
 * normalized the same way _resolveIdentity() built the slug). Returns null on
 * a fresh clone with no team/ folder - the caller falls back to initials.
 */
function _cocreateAvatarForSlug(slug) {
  if (!slug) return null;
  let data;
  try {
    data = JSON.parse(fs.readFileSync(path.join(DATA_TIER_0_DIR, 'team', 'team-members.json'), 'utf8'));
  } catch {
    return null;
  }
  const list = Array.isArray(data.team_members) ? data.team_members : [];
  const match = list.find((m) => _cocreateSlugFromName([m.first_name, m.last_name].filter(Boolean).join(' ')) === slug);
  if (!match || !match.avatar) return null;
  return DATA_TIER_0_URL_PATH + 'team/avatars/' + encodeURIComponent(match.avatar);
}

// Progress: storage in ds-data ------------------------------------------------
// ONE FILE PER PERSON: data-sub-repositories/ds-data/academy/progress/<slug>.json.
//
// A single shared progress.json would put every participant on the same line of
// the same file, so two people finishing a step at the same time would collide
// on every autopush. Per-person files make that impossible by construction -
// nobody ever writes anybody else's file, which is also what lets the autopush
// below stage exactly one path instead of `git add -A`.
//
// The directory is PLAINTEXT and never a git repo (the encrypted mirror is what
// sync pushes), so the self-heal here is "skip the unreadable file", not the
// git-checkout-HEAD recovery _healSubRepoJson() runs for the tracked mirror.

const COCREATE_PROGRESS_SUBDIR = 'academy/progress';

/**
 * A person slug is server-derived (never request input), but it becomes a FILE
 * NAME here, so it is validated as one before it is ever joined into a path.
 * @param {string} slug @returns {string|null}
 */
/**
 * Where Academy progress and the mural may be read and written. Normally the
 * cloned team data; in sample mode the local sample copy, which has no clone
 * (and needs none: _cocreatePushDataFile skips publishing there).
 */
function _cocreateStorageReady() {
  return SAMPLE_MODE_ACTIVE ? fs.existsSync(DATA_TIER_0_DIR) : dataTier0Exists();
}

function _cocreateSlugSafe(slug) {
  return typeof slug === 'string' && /^[a-z0-9][a-z0-9-]{0,63}$/.test(slug) ? slug : null;
}

// POST /api/cocreate/admin/reset is the ONE route in this section that writes
// somebody else's progress file - and then autopublishes it through the same
// _cocreateWritePerson path the person's own unlock and verify-step use. It is
// a trainer's tool reached with curl, never from the UI, so it stays off
// unless .env says otherwise. Read per call: the flag is `config` in
// ENV_SCHEMA, edited in .env alone, and a restart child re-reads it.
function _cocreateAdminResetEnabled() {
  return process.env.COCREATE_ADMIN_RESET === '1';
}

function _cocreateProgressDir() {
  return path.join(DATA_TIER_0_DIR, ...COCREATE_PROGRESS_SUBDIR.split('/'));
}

function _cocreatePersonFile(slug) {
  return path.join(_cocreateProgressDir(), slug + '.json');
}

function _cocreateProgressRelPath(slug) {
  return COCREATE_PROGRESS_SUBDIR + '/' + slug + '.json';
}

function _cocreateEmptyProgress() {
  return { version: 1, unlocks: {}, steps: {}, completed: {} };
}

/** One person's own document - the only thing this cockpit ever writes. */
function _cocreateEmptyPerson(slug, displayName) {
  return {
    version: 1,
    person_slug: slug,
    display_name: displayName || slug,
    unlocks: {},
    steps: {},
    completed: {},
  };
}

/** Never throws. Returns the empty person doc when the file is absent or corrupt. */
function _cocreateReadPerson(slug, displayName) {
  const safe = _cocreateSlugSafe(slug);
  if (!safe) return _cocreateEmptyPerson(String(slug || ''), displayName);
  let parsed;
  try {
    parsed = JSON.parse(fs.readFileSync(_cocreatePersonFile(safe), 'utf8'));
  } catch (e) {
    if (e.code !== 'ENOENT') console.warn('[cocreate] skipping an unreadable progress file', safe, e.message);
    return _cocreateEmptyPerson(safe, displayName);
  }
  return {
    version: 1,
    person_slug: safe,
    display_name: (parsed && parsed.display_name) || displayName || safe,
    unlocks: (parsed && typeof parsed.unlocks === 'object' && parsed.unlocks) || {},
    steps: (parsed && typeof parsed.steps === 'object' && parsed.steps) || {},
    completed: (parsed && typeof parsed.completed === 'object' && parsed.completed) || {},
  };
}

/**
 * Aggregate every person file into the team-wide shape the read handlers use:
 * unlocks[etap] / steps[etap][step] / completed[etap] are arrays of person rows.
 * `storage` is a read-time annotation, not part of any file on disk.
 */
function _cocreateReadProgress() {
  if (!_cocreateStorageReady()) {
    return { ..._cocreateEmptyProgress(), storage: 'unavailable' };
  }
  let names = [];
  try {
    names = fs.readdirSync(_cocreateProgressDir()).filter((f) => f.endsWith('.json'));
  } catch { return { ..._cocreateEmptyProgress(), storage: 'ok' }; } // no dir yet - a normal fresh state

  const out = { ..._cocreateEmptyProgress(), storage: 'ok' };
  for (const name of names) {
    const slug = _cocreateSlugSafe(name.slice(0, -'.json'.length));
    if (!slug) continue;
    const doc = _cocreateReadPerson(slug);
    for (const [etap, at] of Object.entries(doc.unlocks)) {
      if (!Array.isArray(out.unlocks[etap])) out.unlocks[etap] = [];
      out.unlocks[etap].push({ person_slug: slug, display_name: doc.display_name, unlocked_at: at });
    }
    for (const [etap, stepMap] of Object.entries(doc.steps)) {
      if (!out.steps[etap]) out.steps[etap] = {};
      for (const [stepId, rec] of Object.entries(stepMap || {})) {
        if (!Array.isArray(out.steps[etap][stepId])) out.steps[etap][stepId] = [];
        out.steps[etap][stepId].push({
          person_slug: slug,
          checked_at: rec && rec.checked_at,
          method: rec && rec.method,
        });
      }
    }
    for (const [etap, at] of Object.entries(doc.completed)) {
      if (!Array.isArray(out.completed[etap])) out.completed[etap] = [];
      out.completed[etap].push({ person_slug: slug, display_name: doc.display_name, completed_at: at });
    }
  }
  return out;
}

const withCocreateProgressLock = _makeChainLock();

/**
 * Runs `mutate(ownDocument)` and persists ONLY that person's file through
 * tmp+rename, then publishes it (see _cocreatePushPersonFile). A mutate that
 * empties the document deletes the file instead of leaving an empty husk.
 *
 * Resolves { ok:false, reason:'repo-missing' } instead of writing when ds-data
 * is not cloned - the route handler turns that into a 409 pointing at the sync
 * panel, never a 503 (a fresh install is normal).
 *
 * @param {{person_slug: string, display_name: string}} me
 * @param {(doc: object) => object|void} mutate
 * @returns {Promise<{ok: boolean, reason?: string, data?: object, sync?: object}>}
 */
async function _cocreateWritePerson(me, mutate) {
  const slug = _cocreateSlugSafe(me && me.person_slug);
  if (!slug) return { ok: false, reason: 'no-identity' };
  const written = await withCocreateProgressLock(() => {
    if (!_cocreateStorageReady()) return { ok: false, reason: 'repo-missing' };
    const doc = _cocreateReadPerson(slug, me.display_name);
    const next = mutate(doc) || doc;
    next.display_name = me.display_name || next.display_name;
    next.updated_at = new Date().toISOString();
    const target = _cocreatePersonFile(slug);
    const empty = !Object.keys(next.unlocks).length
      && !Object.keys(next.steps).length
      && !Object.keys(next.completed).length;
    if (empty) {
      try { fs.unlinkSync(target); } catch { /* already gone - nothing to publish differently */ }
      return { ok: true, data: next, removed: true };
    }
    fs.mkdirSync(path.dirname(target), { recursive: true });
    const tmp = target + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(next, null, 2), 'utf8');
    fs.renameSync(tmp, target);
    return { ok: true, data: next, removed: false };
  });
  if (!written.ok) return written;
  const sync = await _cocreatePushPersonFile(slug, written.removed);
  _cocreateRecordSync(sync);
  return { ...written, sync };
}

// Progress: autopublishing a single file --------------------------------------
// Every verified step publishes immediately, so nobody has to remember to press
// "Send". What travels is ONE path - this person's own progress file - which
// is why the staging below names it explicitly instead of `git add -A`.

/** Where the LAST push outcome is remembered. Local cache, never team data:
 * writing the result back into the pushed file would re-dirty the very file it
 * describes and leave the mirror permanently one commit behind the plaintext. */
function _cocreateSyncStatePath() {
  return path.join(ROOT, 'data', 'academy-sync.json');
}

let _cocreateLastSync = null;

function _cocreateRecordSync(sync) {
  _cocreateLastSync = { ...sync, at: new Date().toISOString() };
  // The api suite points DATA_TIER_0_DIR at a temp directory but shares this
  // ROOT, so a test server writing here would leave `skipped / test-mode` in
  // the developer's own cache - and the view's callout would then claim a
  // publish was skipped that had in fact been pushed. The in-memory value
  // stays, so the response still carries the outcome the tests assert on.
  if (IS_TEST_MODE) return;
  try {
    fs.mkdirSync(path.join(ROOT, 'data'), { recursive: true });
    fs.writeFileSync(_cocreateSyncStatePath(), JSON.stringify(_cocreateLastSync, null, 2), 'utf8');
  } catch { /* a status cache that cannot be written is not worth failing a step over */ }
}

function _cocreateReadSync() {
  if (_cocreateLastSync) return _cocreateLastSync;
  try { _cocreateLastSync = JSON.parse(fs.readFileSync(_cocreateSyncStatePath(), 'utf8')); }
  catch { _cocreateLastSync = null; }
  return _cocreateLastSync;
}

/**
 * Encrypt and push EXACTLY this person's progress file.
 *
 * Two invariants make this safe next to the full sync in the Settings panel:
 *
 *  1. The pull is UNCONDITIONAL, not "only when rev-list says we are behind".
 *     A targeted push that merges remote commits into the mirror without
 *     decrypting them would leave the mirror holding .enc files that are absent
 *     from the plaintext tree - and the next FULL push runs encryptTree, which
 *     builds keepEnc from plaintext and unlinks every .enc it does not find
 *     there. That would delete every teammate's progress. Pulling first (which
 *     decrypts) keeps the plaintext tree a superset of the mirror, exactly the
 *     pairing _repoPush relies on.
 *  2. Both locks are held across the encrypt AND the git calls, so this can
 *     never interleave with dataTier0Encrypt()'s whole-tree walk.
 *
 * Never throws and never fails a step: a missing key, a missing token or an
 * unreachable remote are reported as a state, and the progress stays on disk.
 *
 * Takes the file to publish as a plaintext-relative path so BOTH per-person
 * documents this section writes travel the same way: the progress JSON and the
 * mural entry. Nothing else about it is generic - the caller has already
 * derived the path from the server-side identity, never from a request.
 *
 * @param {string} relPath path inside the plaintext tree, e.g. "a/b/<slug>.json"
 * @param {string} absPath the same file on disk
 * @param {boolean} removed the file was deleted (admin reset, mural removal)
 * @param {string} message commit subject
 * @returns {Promise<{state: string, reason?: string, message?: string}>}
 */
async function _cocreatePushDataFile(relPath, absPath, removed, message) {
  // A publish that cannot happen is a sync state, never a failed step.
  if (SAMPLE_MODE_ACTIVE) return { state: 'skipped', reason: 'sample-mode' };
  if (IS_TEST_MODE) return { state: 'skipped', reason: 'test-mode' };
  if (!dataTier0Exists()) return { state: 'skipped', reason: 'repo-missing' };
  if (!DATA_TIER_0_TOKEN) return { state: 'skipped', reason: 'no-token' };

  let key;
  clearDataTierKeyCache();
  try { key = dataTierMasterKey(); } catch {
    // No key means no ciphertext - and pushing the plaintext instead is the one
    // thing this whole layer exists to prevent.
    return { state: 'skipped', reason: 'no-key' };
  }

  return withDataTierLock(async () => {
    const fileLock = await _acquireRepoFileLock(DATA_TIER_0_GIT_DIR);
    if (!fileLock.ok) return { state: 'deferred', reason: 'locked' };
    try {
      const pull = await _repoPull(DATA_REPOS[0]);
      if (!pull.ok) return { state: 'error', reason: pull.error || 'pull-failed', message: pull.message };

      const encName = crypto_sync.encryptRelPath(relPath, key);
      const encRel = encName + '.enc';
      const encAbs = path.join(DATA_TIER_0_GIT_DIR, encRel);

      if (removed) {
        try { fs.unlinkSync(encAbs); } catch { /* nothing to remove */ }
        // An entry that was never pushed leaves git nothing to stage, and `add`
        // on an untracked, now-absent path exits non-zero - which would report a
        // removal that fully succeeded as a failed publish.
        const tracked = await gitExecDataTier0(['ls-files', '--', encRel]);
        if (!tracked.stdout.trim()) return { state: 'ok', reason: 'removed' };
      } else {
        let buf;
        try { buf = fs.readFileSync(absPath); } catch {
          return { state: 'skipped', reason: 'no-file' };
        }
        fs.mkdirSync(path.dirname(encAbs), { recursive: true });
        // tmp + rename, same as _repoPushScoped: a process dying mid-write must
        // never leave a half-encrypted .enc for the next pull to choke on.
        const tmp = encAbs + '.tmp-' + process.pid;
        fs.writeFileSync(tmp, crypto_sync.encryptBuffer(buf, relPath, encName, key), 'utf8');
        fs.renameSync(tmp, encAbs);
      }

      // Explicit pathspec: `-A` would sweep in whatever else the pull or another
      // session left dirty in the mirror, which is the opposite of "one file".
      const add = await gitExecDataTier0(['add', '--', encRel]);
      if (add.code !== 0) return { state: 'error', reason: 'add-failed', message: _redactGitStderr(add.stderr) };

      const staged = await gitExecDataTier0(['diff', '--cached', '--name-only', '--', encRel]);
      if (!staged.stdout.trim()) return { state: 'ok', reason: 'no-change' };

      const commit = await gitExecDataTier0(['commit', '-m', message, '--', encRel]);
      const nothing = /nothing to commit|no changes added to commit/i.test(commit.stdout + commit.stderr);
      if (commit.code !== 0 && !nothing) {
        return { state: 'error', reason: 'commit-failed', message: _redactGitStderr(commit.stderr) };
      }

      let push = await gitExecDataTier0(['push']);
      if (push.code !== 0) {
        // One retry: somebody else pushed between our pull and our push.
        const again = await _repoPull(DATA_REPOS[0]);
        if (!again.ok) return { state: 'error', reason: again.error || 'pull-failed' };
        push = await gitExecDataTier0(['push']);
      }
      if (push.code !== 0) {
        return {
          state: 'error',
          reason: classifyGitError(push.stderr, push.code, { killed: push.killed }),
          message: _redactGitStderr(push.stderr),
        };
      }
      writeRefreshTimestamp('_data-tier-0-push');
      return { state: 'ok', reason: removed ? 'removed' : 'pushed' };
    } catch (e) {
      return { state: 'error', reason: 'exception', message: e && e.message };
    } finally {
      _releaseRepoFileLock(DATA_TIER_0_GIT_DIR);
    }
  });
}

/** Publish ONE person's progress file. Thin wrapper over the push above. */
function _cocreatePushPersonFile(slug, removed) {
  return _cocreatePushDataFile(
    _cocreateProgressRelPath(slug),
    _cocreatePersonFile(slug),
    removed,
    'academy: progress ' + slug,
  );
}

function _cocreateHasPerson(list, personSlug) {
  return Array.isArray(list) && list.some((e) => e && e.person_slug === personSlug);
}

// Mural: storage in ds-data ---------------------------------------------------
// data-sub-repositories/ds-data/academy/mural/<slug>.md - the SAME
// plaintext working tree as the progress files above, for the same reason: the
// original app kept its mural in the APP repository, so leaving a trace meant
// a branch, a commit and a merge request, and the entry was invisible to the
// team until somebody merged it. Here it is team data: one file per person,
// written only by that person, encrypted and pushed the moment it is saved.
//
// The file is markdown with a YAML frontmatter header the server owns
// (author / person_slug / date - the field names are part of the file format) - the same shape templates/ uses - so a rewrite
// regenerates the header instead of stacking a second one on top of the first.

const COCREATE_MURAL_SUBDIR = 'academy/mural';
const COCREATE_MURAL_MAX_CHARS = 8000;

function _cocreateMuralDir() {
  return path.join(DATA_TIER_0_DIR, ...COCREATE_MURAL_SUBDIR.split('/'));
}

function _cocreateMuralFile(slug) {
  return path.join(_cocreateMuralDir(), slug + '.md');
}

function _cocreateMuralRelPath(slug) {
  return COCREATE_MURAL_SUBDIR + '/' + slug + '.md';
}

/**
 * Split "---\nkey: value\n---\n\nbody" into { meta, body }. Never throws: a file
 * a person edited by hand without a header is still a valid entry, it just has
 * no metadata and falls back to the slug.
 * @param {string} text
 * @returns {{meta: Record<string,string>, body: string}}
 */
function _cocreateMuralParse(text) {
  const raw = String(text || '').replace(/^\uFEFF/, '');
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(raw);
  if (!m) return { meta: {}, body: raw.trim() };
  const meta = {};
  for (const line of m[1].split(/\r?\n/)) {
    const kv = /^([a-z_]+):\s*(.*)$/.exec(line.trim());
    if (kv) meta[kv[1]] = kv[2].trim();
  }
  return { meta, body: raw.slice(m[0].length).trim() };
}

/** Serialize one entry back to disk form. The header is server-owned. */
function _cocreateMuralSerialize(slug, displayName, date, body) {
  return [
    '---',
    'author: ' + (displayName || slug),
    'person_slug: ' + slug,
    'date: ' + date,
    '---',
    '',
    body.trim(),
    '',
  ].join('\n');
}

/** One entry, enriched the way the progress rows are (team photo by slug). */
function _cocreateMuralEntry(slug) {
  let text;
  try { text = fs.readFileSync(_cocreateMuralFile(slug), 'utf8'); } catch { return null; }
  const { meta, body } = _cocreateMuralParse(text);
  return {
    person_slug: slug,
    display_name: meta.author || meta.autor || slug,
    date: meta.date || meta.data || '',
    content: body,
    avatar_url: _cocreateAvatarForSlug(slug),
  };
}

/**
 * Every mural entry on disk, newest first. `storage` mirrors the progress
 * reader: a data repo that is not cloned is a normal fresh state, not an error.
 * @returns {{entries: object[], storage: string}}
 */
function _cocreateReadMural() {
  if (!_cocreateStorageReady()) return { entries: [], storage: 'unavailable' };
  let names = [];
  try {
    names = fs.readdirSync(_cocreateMuralDir()).filter((f) => f.endsWith('.md'));
  } catch { return { entries: [], storage: 'ok' }; } // no dir yet - nobody wrote one

  const entries = [];
  for (const name of names) {
    const slug = _cocreateSlugSafe(name.slice(0, -'.md'.length));
    if (!slug) continue;
    const entry = _cocreateMuralEntry(slug);
    if (entry) entries.push(entry);
  }
  entries.sort((a, b) => String(b.date).localeCompare(String(a.date)) || a.person_slug.localeCompare(b.person_slug));
  return { entries, storage: 'ok' };
}

const withCocreateMuralLock = _makeChainLock();

/**
 * Write (or delete, on empty content) THIS person's mural entry and publish it.
 * Same contract as _cocreateWritePerson: { ok:false, reason:'repo-missing' }
 * instead of a write when ds-data is not cloned.
 *
 * @param {{person_slug: string, display_name: string}} me
 * @param {string} content markdown body, already length-checked by the handler
 * @returns {Promise<{ok: boolean, reason?: string, entry?: object|null, sync?: object}>}
 */
async function _cocreateWriteMural(me, content) {
  const slug = _cocreateSlugSafe(me && me.person_slug);
  if (!slug) return { ok: false, reason: 'no-identity' };
  const body = String(content || '').trim();

  const written = await withCocreateMuralLock(() => {
    if (!_cocreateStorageReady()) return { ok: false, reason: 'repo-missing' };
    const target = _cocreateMuralFile(slug);
    if (!body) {
      try { fs.unlinkSync(target); } catch { /* already gone */ }
      return { ok: true, removed: true };
    }
    const previous = _cocreateMuralEntry(slug);
    const date = (previous && previous.date) || new Date().toISOString().slice(0, 10);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    const tmp = target + '.tmp';
    fs.writeFileSync(tmp, _cocreateMuralSerialize(slug, me.display_name, date, body), 'utf8');
    fs.renameSync(tmp, target);
    return { ok: true, removed: false };
  });
  if (!written.ok) return written;

  const sync = await _cocreatePushDataFile(
    _cocreateMuralRelPath(slug),
    _cocreateMuralFile(slug),
    written.removed,
    'academy: mural ' + slug,
  );
  _cocreateRecordSync(sync);
  return { ok: true, entry: written.removed ? null : _cocreateMuralEntry(slug), sync };
}


// Server-side step checks -----------------------------------------------------

/** Port of the old cockpit's VS Code terminal-location check, WSL branch kept. */
function _cocreateCheckVscodeTerminal() {
  const home = os.homedir();
  const candidates = [];

  if (process.platform === 'win32') {
    candidates.push(path.join(process.env.APPDATA || home, 'Code', 'User', 'settings.json'));
  } else if (process.platform === 'darwin') {
    candidates.push(path.join(home, 'Library', 'Application Support', 'Code', 'User', 'settings.json'));
  } else {
    candidates.push(path.join(home, '.config', 'Code', 'User', 'settings.json'));
    // WSL: VS Code runs on Windows; settings.json lives in Windows AppData,
    // reachable from WSL at /mnt/c/Users/<user>/AppData/Roaming/Code/User/.
    try {
      const procVer = fs.readFileSync('/proc/version', 'utf8');
      if (/microsoft|wsl/i.test(procVer)) {
        const skipDirs = new Set(['Public', 'Default', 'Default User', 'All Users']);
        let winUsers = [];
        try { winUsers = fs.readdirSync('/mnt/c/Users'); } catch { /* /mnt/c not mounted */ }
        for (const u of winUsers) {
          if (skipDirs.has(u) || u.endsWith('.ini')) continue;
          candidates.push(`/mnt/c/Users/${u}/AppData/Roaming/Code/User/settings.json`);
        }
      }
    } catch { /* /proc/version unavailable - not WSL */ }
  }

  const TERMINAL_KEYS = [
    'terminal.integrated.defaultProfile.osx',
    'terminal.integrated.defaultProfile.linux',
    'terminal.integrated.defaultProfile.windows',
    'terminal.integrated.defaultLocation',
    'terminal.integrated.shell.osx',
    'terminal.integrated.shell.linux',
  ];

  for (const settingsPath of candidates) {
    let raw;
    try {
      raw = fs.readFileSync(settingsPath, 'utf8');
    } catch (e) {
      if (e.code === 'ENOENT') continue;
      console.warn('[cocreate] settings.json read error:', settingsPath, e.message);
      continue;
    }
    let settings;
    try {
      settings = JSON.parse(raw);
    } catch {
      return { pass: false, detail: 'Could not read the VS Code settings.json file (invalid JSON).' };
    }
    const hasTerminalSetting = TERMINAL_KEYS.some((k) => k in settings);
    if (hasTerminalSetting) {
      return { pass: true, detail: 'Found a terminal setting in the VS Code settings.json file.' };
    }
    return {
      pass: false,
      detail: 'No terminal setting found in settings.json - add e.g. "terminal.integrated.defaultLocation": "editor".',
    };
  }
  return { pass: false, detail: 'The VS Code settings.json file was not found - is VS Code installed?' };
}

async function _cocreateCheckClaudeCli() {
  const probe = await _probeClaudeCli();
  return {
    pass: !!probe.installed,
    detail: probe.installed
      ? 'Claude Code CLI is installed (version ' + (probe.version || '?') + ').'
      : 'Claude Code CLI was not found on PATH - install it before continuing the course.',
  };
}

// The "Log in to Claude Code" step (etap-1/step-2b) no longer has a server
// probe. `claude auth status` says whether credentials are STORED on the
// machine - not whether the CLI is logged in - and it passed the step for a
// person who never went through the CLI login (the credentials may come from
// the app or the browser, or be expired already). The only reliable test is a
// real API call: slow, paid and breaking this section's "zero child processes"
// rule. So the step is self-attest, and its instructions tell the person what
// to look for and how to log in (`/login`, `claude auth login`).

function _cocreateCheckTerminalReady() {
  const probe = _probeClaudeTerminal();
  return {
    pass: probe.installed,
    detail: probe.installed
      ? 'The terminal built into the cockpit works (pty and the WebSocket connection are ready).'
      : 'The terminal built into the cockpit does not work yet - check the "Tools" tab in Settings.',
  };
}

/**
 * The module the participant is building in Etap 3, found on disk - NEVER
 * from request input. `demo-hub` is the shipped template, so it is excluded.
 */
function _cocreateFindOwnModule() {
  return _cocreateOwnModules()[0] || null;
}

/**
 * Every own module on disk, not just the first: a machine that installed a
 * few modules from the catalog holds them next to the one the person built,
 * and scanModulesDir orders by name, so "the first non-demo-hub directory"
 * pointed at whichever id sorted lowest.
 */
function _cocreateOwnModules() {
  const scan = scanModulesDir();
  return scan.installed.filter((m) => m.id !== 'demo-hub');
}

function _cocreateCheckModuleScaffold() {
  const found = _cocreateFindOwnModule();
  return found
    ? { pass: true, detail: 'Found the scaffold of module "' + found.id + '" with a valid module.json.' }
    : {
      pass: false,
      detail: 'No module of your own found yet - run node scripts/new-module.js <id> "<Label>" --area "<Area>".',
    };
}

function _cocreateCheckModuleEnabled() {
  const own = _cocreateOwnModules();
  if (own.length === 0) {
    return { pass: false, detail: 'Build the module scaffold first (previous step) before enabling it.' };
  }
  const enabled = own.find((m) => {
    const loaded = _loadedModules.modules.find((l) => l.id === m.id);
    return !!(loaded && Array.isArray(loaded.manifest.views) && loaded.manifest.views.length > 0);
  });
  return enabled
    ? { pass: true, detail: 'Module "' + enabled.id + '" is enabled and visible in the manifest with at least one view.' }
    : {
      pass: false,
      detail: 'Module "' + own[0].id + '" is not enabled yet - enable it in Settings > Modules and restart the server.',
    };
}

/**
 * The pure half of the publish check: which of the person's modules has
 * reached the catalog repository, decided from data already fetched.
 *
 * A publish creates the branch `module/<id>-<stamp>` and opens a merge
 * request with `remove_source_branch: true` (handleModulesPublish), so the
 * branch is the evidence only UNTIL a human merges the MR - after that GitLab
 * deletes the branch and the evidence is the entry in `catalog.json` on
 * `main`. The first version looked at the branch alone, which failed the
 * step for good for exactly the people whose module had been merged. Either
 * state passes; a `catalogIds` of null means the catalog could not be read
 * and only the branch half is decided.
 * @param {{moduleIds: string[], branches: string[], catalogIds: string[]|null}} p
 * @returns {{pass: boolean, detail: string, moduleId?: string, state?: 'merged'|'branch'}}
 */
function cocreatePublishedState({ moduleIds, branches, catalogIds }) {
  const ids = Array.isArray(moduleIds) ? moduleIds : [];
  const br = Array.isArray(branches) ? branches : [];
  const cat = Array.isArray(catalogIds) ? new Set(catalogIds) : null;
  for (const id of ids) {
    if (cat && cat.has(id)) {
      return {
        pass: true, moduleId: id, state: 'merged',
        detail: 'Module "' + id + '" is already in the cockpit-modules catalog - the merge request was merged.',
      };
    }
  }
  for (const id of ids) {
    const prefix = 'module/' + id + '-';
    if (br.some((b) => typeof b === 'string' && b.startsWith(prefix))) {
      return {
        pass: true, moduleId: id, state: 'branch',
        detail: 'Found the publish branch "' + prefix + '*" - once the MR is merged, module "' + id + '" will appear in the catalog.',
      };
    }
  }
  const first = ids[0] || '';
  return {
    pass: false,
    detail: cat
      ? 'Module "' + first + '" is not in the catalog or on a branch "module/' + first + '-*" yet - click "Publish" on the module card.'
      : 'No branch "module/' + first + '-*" found on the remote repository yet (the catalog could not be read) - click "Publish" on the module card.',
  };
}

async function _cocreateCheckModulePublished() {
  const own = _cocreateOwnModules();
  if (own.length === 0) {
    return { pass: false, detail: 'Build and enable the module first, before publishing it.' };
  }
  if (!_modulesCatalogReady()) {
    return { pass: false, detail: MODULES_CATALOG_NO_TOKEN_MESSAGE };
  }
  const projectApi = `${_gitlabApiBase()}/projects/${encodeURIComponent(modulesCatalogProjectPath())}`;
  // Catalog on main (merged) and the module/ branches (published, not merged
  // yet) in parallel - the catalog answers for every module in one request,
  // the branch list is one request per own module.
  const [catRes, ...branchRes] = await Promise.all([
    _modulesCatalogGet(_modulesCatalogFileRawUrl('catalog.json')),
    ...own.map((m) => _modulesCatalogGet(
      `${projectApi}/repository/branches?search=${encodeURIComponent('module/' + m.id + '-')}`)),
  ]);
  let catalogIds = null;
  if (catRes.ok) {
    const parsed = parseModulesCatalog(catRes.text);
    if (parsed.ok) catalogIds = parsed.modules.map((e) => e.id);
  } else if (catRes.status === 404) {
    // A catalog with no catalog.json yet is an empty catalog, not a failure.
    catalogIds = [];
  }
  const branches = [];
  let branchesFailed = false;
  for (const r of branchRes) {
    if (!r.ok) { branchesFailed = true; continue; }
    try {
      const parsed = JSON.parse(r.text);
      if (Array.isArray(parsed)) for (const b of parsed) if (b && typeof b.name === 'string') branches.push(b.name);
    } catch { branchesFailed = true; }
  }
  if (catalogIds === null && branchesFailed) {
    return { pass: false, detail: 'Could not check the publication on GitLab - try again in a moment.' };
  }
  return cocreatePublishedState({ moduleIds: own.map((m) => m.id), branches, catalogIds });
}

/**
 * Mural: PASS once THIS person has an entry in ds-data. Resolves the identity
 * itself because a check takes no arguments - and it must be this person's own
 * file, never "somebody wrote something on the mural".
 */
async function _cocreateCheckMuralEntry() {
  if (!_cocreateStorageReady()) {
    return {
      pass: false,
      detail: 'The ds-data repository is not cloned - clone it in the sync panel to save the entry.',
    };
  }
  const me = await _cocreateIdentity();
  const slug = _cocreateSlugSafe(me && me.person_slug);
  if (!slug) {
    return { pass: false, detail: 'Could not determine your identity - configure the GitLab token.' };
  }
  const entry = _cocreateMuralEntry(slug);
  return entry && entry.content
    ? { pass: true, detail: 'Your entry is already on the Mural - you will see it in the "Mural" tab.' }
    : { pass: false, detail: 'Your entry was not found - write it in the "Mural" tab and click "Save entry".' };
}

const COCREATE_SERVER_CHECKS = {
  'etap-1': {
    'step-1': _cocreateCheckVscodeTerminal,
    'step-2': _cocreateCheckClaudeCli,
    'step-5': _cocreateCheckTerminalReady,
    'step-6': _cocreateCheckMuralEntry,
  },
  'etap-3': {
    'step-2': _cocreateCheckModuleScaffold,
    'step-3': _cocreateCheckModuleEnabled,
    // step-5 (module contract test) removed - /new-idea writes the tests itself.
    // The ids of later steps are NOT renumbered: progress is keyed on the
    // step id in the person's file, so renumbering would rewrite others' passes.
    'step-7': _cocreateCheckModulePublished,
  },
};

// Default self-attest path ----------------------------------------------------
const COCREATE_SELF_ATTEST_RESULT = { pass: true, detail: 'Confirmed on your word - moving on!' };

// Six handlers ------------------------------------------------------------------

/**
 * GET /api/cocreate/progress -> unlocks/steps projected onto the current
 * person, completed[] aggregated across the whole team and enriched with
 * avatar_url, unlockable (etap ids this person may unlock right now) and
 * storage ('ok' | 'unavailable').
 */
async function handleCocreateProgress(req, res) {
  if (!checkOriginNoBody(req, res)) return;

  const me = await _cocreateIdentity();
  const cfg = await _cocreateStages();
  const etapIds = _cocreateEtapIds(cfg);
  const progress = _cocreateReadProgress();
  const meOut = me ? { person_slug: me.person_slug, display_name: me.display_name } : null;

  if (progress.storage === 'unavailable') {
    jsonResponse(res, 200, {
      version: 1,
      unlocks: {},
      steps: {},
      completed: {},
      unlockable: etapIds.filter((etap) => !_cocreateIsGated(cfg.GATED_STAGES, etap)),
      me: meOut,
      storage: 'unavailable',
      sync: _cocreateReadSync(),
    });
    return;
  }

  const personSlug = me ? me.person_slug : null;
  const unlocks = {};
  const steps = {};
  for (const etap of etapIds) {
    unlocks[etap] = personSlug ? _cocreateHasPerson(progress.unlocks[etap], personSlug) : false;
    const etapCfg = _cocreateFindEtap(cfg, etap);
    const stepIds = etapCfg ? etapCfg.steps.map((s) => s.id) : Object.keys(progress.steps[etap] || {});
    const stepMap = {};
    for (const stepId of stepIds) {
      stepMap[stepId] = personSlug
        ? _cocreateHasPerson((progress.steps[etap] || {})[stepId], personSlug)
        : false;
    }
    steps[etap] = stepMap;
  }

  const completed = {};
  for (const etap of Object.keys(progress.completed || {})) {
    completed[etap] = (progress.completed[etap] || []).map((entry) => ({
      person_slug: entry.person_slug,
      display_name: entry.display_name,
      completed_at: entry.completed_at,
      avatar_url: _cocreateAvatarForSlug(entry.person_slug),
    }));
  }

  const unlockable = etapIds.filter((etap) => (
    personSlug
      ? _cocreateCanUnlock(progress, cfg.GATED_STAGES, etap, personSlug)
      : !_cocreateIsGated(cfg.GATED_STAGES, etap)
  ));

  jsonResponse(res, 200, {
    version: 1, unlocks, steps, completed, unlockable, me: meOut,
    storage: 'ok', sync: _cocreateReadSync(),
  });
}

/**
 * POST /api/cocreate/unlock { etap } -> { ok:true, etap } | 400 | 403 | 409.
 * etap-1 (and any etap outside GATED_STAGES) is always unlockable; a gated
 * etap requires the caller to already be in completed[<previous etap>].
 */
async function handleCocreateUnlock(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try {
    body = await readBody(req, 1024);
  } catch {
    jsonResponse(res, 400, { error: 'bad-request', message: 'Invalid JSON request.' });
    return;
  }

  const etap = body && body.etap;
  const cfg = await _cocreateStages();
  const etapIds = _cocreateEtapIds(cfg);
  if (typeof etap !== 'string' || !etapIds.includes(etap)) {
    jsonResponse(res, 400, { error: 'bad-request', message: 'Unknown stage: ' + _cocreateLabel(etap) });
    return;
  }

  const me = await _cocreateIdentity();
  if (!me) {
    jsonResponse(res, 400, {
      error: 'no-identity',
      message: 'Could not determine your identity - configure the GitLab token.',
    });
    return;
  }

  const progress = _cocreateReadProgress();
  if (!_cocreateCanUnlock(progress, cfg.GATED_STAGES, etap, me.person_slug)) {
    const idx = cfg.GATED_STAGES.indexOf(etap);
    const previous = idx > 0 ? cfg.GATED_STAGES[idx - 1] : null;
    jsonResponse(res, 403, {
      error: 'locked',
      message: previous
        ? 'Finish stage "' + previous + '" first to unlock "' + etap + '".'
        : 'This stage is still locked.',
    });
    return;
  }

  const result = await _cocreateWritePerson(me, (doc) => {
    doc.unlocks[etap] = new Date().toISOString();
    return doc;
  });

  if (!result.ok) {
    jsonResponse(res, 409, {
      error: 'repo-missing',
      message: 'The ds-data repository is not cloned - clone it in the sync panel to save your progress (cloning needs the VPN on).',
    });
    return;
  }

  jsonResponse(res, 200, { ok: true, etap, sync: result.sync || null });
}

/**
 * POST /api/cocreate/verify-step { etap, step, method? } -> { pass, detail }.
 * Runs the matching COCREATE_SERVER_CHECKS entry, or the self-attest default
 * when the step carries no server check. Persists a pass under the caller's
 * person_slug and closes the etap into `completed` once every one of its
 * steps has a passing record for that person.
 */
async function handleCocreateVerifyStep(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try {
    body = await readBody(req, 1024);
  } catch {
    jsonResponse(res, 400, { error: 'bad-request', message: 'Invalid JSON request.' });
    return;
  }

  const etap = body && body.etap;
  const step = body && body.step;
  const method = typeof (body && body.method) === 'string' ? body.method.slice(0, 40) : null;

  const cfg = await _cocreateStages();
  const etapCfg = typeof etap === 'string' ? _cocreateFindEtap(cfg, etap) : null;
  if (!etapCfg) {
    jsonResponse(res, 400, { error: 'bad-request', message: 'Unknown stage: ' + _cocreateLabel(etap) });
    return;
  }
  const stepCfg = typeof step === 'string' ? _cocreateFindStep(etapCfg, step) : null;
  if (!stepCfg) {
    jsonResponse(res, 400, { error: 'bad-request', message: 'Unknown step: ' + _cocreateLabel(step) });
    return;
  }

  const checkFn = (COCREATE_SERVER_CHECKS[etap] || {})[step];
  let result;
  if (checkFn) {
    try {
      result = await checkFn();
    } catch (e) {
      result = { pass: false, detail: 'The check ended with an error: ' + e.message };
    }
  } else {
    result = COCREATE_SELF_ATTEST_RESULT;
  }

  if (!result.pass) {
    jsonResponse(res, 200, { pass: false, detail: result.detail });
    return;
  }

  const me = await _cocreateIdentity();
  if (!me) {
    jsonResponse(res, 200, {
      pass: true,
      detail: result.detail + ' (Could not save progress - no identity: configure the GitLab token.)',
    });
    return;
  }

  const writeResult = await _cocreateWritePerson(me, (doc) => {
    const now = new Date().toISOString();
    if (!doc.steps[etap]) doc.steps[etap] = {};
    doc.steps[etap][step] = {
      checked_at: now,
      method: method || (stepCfg.check && stepCfg.check.type) || 'self-attest',
    };
    // Completion is derived from this person's own document, so it can never
    // disagree with the steps sitting right above it in the same file.
    const allStepIds = etapCfg.steps.map((s) => s.id);
    if (allStepIds.every((id) => doc.steps[etap][id]) && !doc.completed[etap]) {
      doc.completed[etap] = now;
    }
    return doc;
  });

  if (!writeResult.ok) {
    jsonResponse(res, 409, {
      error: 'repo-missing',
      message: 'The ds-data repository is not cloned - progress was not saved. Clone it in the sync panel (cloning needs the VPN on).',
    });
    return;
  }

  jsonResponse(res, 200, { pass: true, detail: result.detail, sync: writeResult.sync || null });
}

/**
 * GET /api/cocreate/modules -> the "Gallery" tab: installed modules merged
 * with the shared catalog by id, author resolved through the team directory.
 * Always 200 - no token or an unreachable catalog degrades to
 * `catalogAvailable:false` plus the installed-only list, never a 5xx.
 */
async function handleCocreateModules(req, res) {
  if (!checkOriginNoBody(req, res)) return;
  const scan = scanModulesDir();

  const fromDisk = new Map(scan.installed.map((m) => [m.id, {
    id: m.id,
    name: m.manifest.name,
    description: m.manifest.description || '',
    version: m.manifest.version,
    author: m.manifest.author || '',
    tags: m.manifest.tags || [],
    installed: true,
    inCatalog: false,
  }]));

  const catalog = await _modulesCatalogSnapshot();
  if (catalog.ok) {
    for (const e of catalog.entries || []) {
      const existing = fromDisk.get(e.id);
      const manifest = (e.manifest) || {};
      fromDisk.set(e.id, {
        id: e.id,
        name: manifest.name || (existing && existing.name) || e.id,
        description: manifest.description || (existing && existing.description) || '',
        version: manifest.version || (existing && existing.version) || '',
        author: e.author || (existing && existing.author) || '',
        tags: (e.tags && e.tags.length ? e.tags : manifest.tags) || (existing && existing.tags) || [],
        installed: !!existing,
        inCatalog: true,
      });
    }
  }

  const entries = Array.from(fromDisk.values()).map((entry) => ({
    ...entry,
    avatar_url: entry.author ? _cocreateAvatarForSlug(_cocreateSlugFromName(entry.author)) : null,
  }));

  jsonResponse(res, 200, {
    entries,
    catalogAvailable: !!catalog.ok,
    reason: catalog.ok ? null : (catalog.message || null),
  });
}

// Opening files in the editor (no child process) -----------------------------
// The old cockpit shelled out to `code <path>`; this section budgets exactly
// one child-process call (the login check above), so this handler resolves a
// CLOSED key -> path map and hands back a vscode:// URI instead of launching
// anything itself. The request body carries a key, never a path.
// Echoing an unknown id back to the caller is good UX and a crash risk: a body
// like {"key":{"toString":"x"}} makes String(value) throw
// "Cannot convert object to primitive value", turning a clean 400 into a 500.
// Every message in this section that quotes request input goes through here.
function _cocreateLabel(value) {
  if (typeof value === 'string') return value.length > 60 ? value.slice(0, 60) + '...' : value;
  if (value === null) return 'null';
  if (value === undefined) return 'none';
  try { return String(value).slice(0, 60); } catch { return '[non-text value]'; }
}

const COCREATE_OPEN_FILE_MAP = {
  // The human-facing guide etap-1/step-3 opens, plus the two files
  // etap-3/step-3b opens once a person already has a working module of their
  // own: CLAUDE.md and README.md are deliberately the "read the whole thing
  // before bigger changes" step, never first-day reading. The module contract
  // stays reachable by key for agents and tests, with no step pointing a
  // person at it.
  'przewodnik-po-repo': 'docs/guides/repo-guide.md',
  'claude-md': 'CLAUDE.md',
  'readme': 'README.md',
  'module-readme': 'modules-template/README.md',
  'demo-hub-module-json': 'modules/demo-hub/module.json',
};

async function handleCocreateOpenFile(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try {
    body = await readBody(req, 512);
  } catch {
    jsonResponse(res, 400, { error: 'bad-request', message: 'Invalid JSON request.' });
    return;
  }

  const key = body && body.key;
  const relPath = typeof key === 'string' ? COCREATE_OPEN_FILE_MAP[key] : null;
  if (!relPath) {
    jsonResponse(res, 400, { error: 'bad-request', message: 'Unknown file key: ' + _cocreateLabel(key) });
    return;
  }
  const absPath = path.join(ROOT, relPath);
  if (!fs.existsSync(absPath)) {
    jsonResponse(res, 404, { error: 'not-found', message: 'The file does not exist: ' + relPath });
    return;
  }

  jsonResponse(res, 200, {
    ok: true,
    key,
    path: relPath,
    absPath: absPath.split(path.sep).join('/'),
    uri: pathToFileURL(absPath).href.replace(/^file:\/\//, 'vscode://file'),
    detail: 'Open the file ' + relPath + ' in your editor.',
  });
}

/**
 * GET /api/cocreate/mural -> { entries[], storage, me }.
 * `entries` is the whole team's mural, newest first; the client resolves each
 * author's photo through js/team-directory.js and falls back to `avatar_url`,
 * which this handler fills from the slug for the rows the directory misses.
 */
async function handleCocreateMuralRead(req, res) {
  if (!checkOriginNoBody(req, res)) return;
  const me = await _cocreateIdentity();
  const mural = _cocreateReadMural();
  jsonResponse(res, 200, {
    version: 1,
    entries: mural.entries,
    storage: mural.storage,
    me: me ? { person_slug: me.person_slug, display_name: me.display_name } : null,
  });
}

/**
 * POST /api/cocreate/mural { content } -> { ok, entry, sync } | 400 | 409.
 * Writes ONLY the caller's own entry: the file name comes from the
 * server-derived person_slug, never from the body. An empty body removes it.
 */
async function handleCocreateMuralWrite(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try {
    body = await readBody(req, 64 * 1024);
  } catch {
    jsonResponse(res, 400, { error: 'bad-request', message: 'Invalid JSON request.' });
    return;
  }

  const content = body && body.content;
  if (typeof content !== 'string') {
    jsonResponse(res, 400, { error: 'bad-request', message: 'The entry has no content.' });
    return;
  }
  if (content.length > COCREATE_MURAL_MAX_CHARS) {
    jsonResponse(res, 400, {
      error: 'too-long',
      message: 'An entry may have at most ' + COCREATE_MURAL_MAX_CHARS + ' characters.',
    });
    return;
  }

  const me = await _cocreateIdentity();
  if (!me) {
    jsonResponse(res, 400, {
      error: 'no-identity',
      message: 'Could not determine your identity - configure the GitLab token.',
    });
    return;
  }

  const result = await _cocreateWriteMural(me, content);
  if (!result.ok) {
    jsonResponse(res, 409, {
      error: 'repo-missing',
      message: 'The ds-data repository is not cloned - clone it in the sync panel to save the entry (cloning needs the VPN on).',
    });
    return;
  }

  jsonResponse(res, 200, { ok: true, entry: result.entry || null, sync: result.sync || null });
}

/**
 * POST /api/cocreate/admin/reset { user, etap?, cascade? } -> removes one
 * person's rows from unlocks/steps/completed. No screen calls this - it is a
 * manual escape hatch for a stuck or re-run training session.
 */
async function handleCocreateAdminReset(req, res) {
  if (!checkOrigin(req, res)) return;
  if (!_cocreateAdminResetEnabled()) {
    jsonResponse(res, 403, {
      error: 'admin-disabled',
      message: 'Resetting another person\'s progress is disabled. Set COCREATE_ADMIN_RESET=1 in .env and restart the server.',
    });
    return;
  }
  let body;
  try {
    body = await readBody(req, 1024);
  } catch {
    jsonResponse(res, 400, { error: 'bad-request', message: 'Invalid JSON request.' });
    return;
  }

  const personSlug = typeof (body && body.user) === 'string' ? body.user.trim() : '';
  if (!personSlug) {
    jsonResponse(res, 400, { error: 'bad-request', message: 'The "user" field (person_slug) is required.' });
    return;
  }
  // The same gate _cocreateWritePerson applies, but answered as 400 here so a
  // typo in the slug is not reported as "repo missing".
  if (!_cocreateSlugSafe(personSlug)) {
    jsonResponse(res, 400, { error: 'bad-request', message: 'The "user" field must be a person_slug: lowercase letters, digits and hyphens.' });
    return;
  }
  const cascade = !(body && body.cascade === false);
  const cfg = await _cocreateStages();
  const etapIds = _cocreateEtapIds(cfg);
  const requestedEtap = (body && typeof body.etap === 'string') ? body.etap : 'all';

  let targetEtaps;
  if (requestedEtap === 'all') {
    targetEtaps = etapIds;
  } else if (etapIds.includes(requestedEtap)) {
    const idx = etapIds.indexOf(requestedEtap);
    targetEtaps = cascade ? etapIds.slice(idx) : [requestedEtap];
  } else {
    jsonResponse(res, 400, { error: 'bad-request', message: 'Unknown stage: ' + requestedEtap });
    return;
  }

  const result = await _cocreateWritePerson({ person_slug: personSlug, display_name: null }, (doc) => {
    for (const etap of targetEtaps) {
      delete doc.unlocks[etap];
      delete doc.steps[etap];
      delete doc.completed[etap];
    }
    return doc;
  });

  if (!result.ok) {
    jsonResponse(res, 409, {
      error: 'repo-missing',
      message: 'The ds-data repository is not cloned - there is nothing to clear.',
    });
    return;
  }

  jsonResponse(res, 200, { ok: true, user: personSlug, etaps: targetEtaps });
}

// -- End: Academy -------------------------------------------------------
// Load-bearing marker, not decoration: AC7 (plan step 21) bounds its spawn/exec
// scan with `indexOf('\n// -- ', ...)` starting right after the section header
// above. Without this exact "// -- " line the scan falls through to end of
// file and starts counting the child-process calls in Tools/tools-run and
// the restart flow much further down. Do not delete it as a stray comment.

// ── Claude Terminal — status endpoint ───────────────────────────────────────
/**
 * GET /api/claude-terminal/status?sessionId=<id> -> { alive, bufferedBytes }.
 * Degrades gracefully when pty/wss are null (alive:false, never a 503) — the
 * client uses this on init to decide whether to auto-reconnect.
 */
function handleClaudeTerminalStatus(req, res) {
  const sessionId = new URL(req.url, 'http://localhost').searchParams.get('sessionId');
  const session = sessionId ? _claudeTerminalSessions.get(sessionId) : null;
  jsonResponse(res, 200, {
    // pty.pid is the liveness proxy — node-pty sets it on spawn, nulls on exit.
    alive: !!(session && session.pty && session.pty.pid),
    bufferedBytes: session ? session.buffer.length : 0,
    available: !!(pty && wss),
  });
}

// ── Tools (environment diagnostics) ─────────────────────────────────────────
// Backs Settings > Tools: is every tool this cockpit leans on actually
// installed and working. Eleven probes, four groups.
//
// FACTS ONLY. A record carries an id, a version, a state and a small `detail`
// bag - never a sentence. Every label, every "why it matters" line and
// every fix command lives in js/settings-narzedzia.js, exactly the way
// js/settings-skille.js owns the copy for the Skills tab. Copy can then change
// without anyone touching a probe.
//
// ALWAYS 200. "Not installed" is an answer, not an error - the same rule
// handleGitlabSshAccess states for a machine with no `ssh` binary at all. A
// probe that throws or times out degrades to state 'unknown' on its own row and
// never takes the other ten down with it.
//
// ONLY LITERALS FROM THIS FILE REACH execFile. The single request input is
// `refresh`, which is compared, never interpolated. The one argument built at
// runtime (the @playwright/mcp pin) comes from .mcp.json, a repo file, and is
// still validated against a strict pattern before it is passed on.

const TOOLS_TTL_MS = 60 * 1000;
const TOOL_PROBE_TIMEOUT_MS = 5000;
// npx has to look through its own cache, which is slower than any other probe,
// and slower still while an npm install or a test run holds the cache lock.
const TOOL_NPX_TIMEOUT_MS = 10000;

let _toolsCache = { at: 0, data: null };

// Windows ships a .cmd shim for every npm-installed CLI, and execFile will not
// run one without a shell. CLAUDE_CMD above solves the same problem for the
// terminal; this is its general form.
const _toolIsWin = process.platform === 'win32';
function _toolCmd(name) { return _toolIsWin ? name + '.cmd' : name; }
// A shell ONLY for the .cmd shims. Node refuses to spawn them without one
// (CVE-2024-27980), but with `shell: true` it joins command and args UNQUOTED
// into `cmd /d /s /c`, so a real binary at "C:\Program Files\nodejs\node.exe"
// - process.execPath on every default Windows install - splits at the space
// and cmd.exe runs "C:\Program". A real binary therefore never gets a shell.
function _toolShell(cmd, isWin = _toolIsWin) { return !!isWin && /\.(cmd|bat)$/i.test(String(cmd || '')); }
// Kill a child AND its descendants. On Windows a shell child is cmd.exe, and
// killing that alone leaves the installer it started running; taskkill /T
// walks the tree. Everywhere else SIGKILL on the direct child is what it was.
function _toolKill(child) {
  if (!child || !child.pid) return;
  if (_toolIsWin) {
    try { spawn('taskkill', ['/PID', String(child.pid), '/T', '/F'], { stdio: 'ignore' }); } catch (_e) { /* already gone */ }
    return;
  }
  try { child.kill('SIGKILL'); } catch (_e) { /* already gone */ }
}

/**
 * Run one probe command. Never rejects: a missing binary, a non-zero exit and a
 * timeout are all answers this endpoint reports rather than errors it raises.
 * @returns {Promise<{ok: boolean, out: string}>}
 */
function _toolExec(cmd, args, timeout, env) {
  const limit = timeout || TOOL_PROBE_TIMEOUT_MS;
  return new Promise(resolve => {
    let settled = false;
    let deadline = null;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      if (deadline) clearTimeout(deadline);
      resolve(result);
    };
    const child = execFile(cmd, args, {
      timeout: limit,
      encoding: 'utf8',
      shell: _toolShell(cmd),
      cwd: ROOT,
      // `env` replaces the environment wholesale, so a caller that needs one
      // extra variable passes the whole spread - omitting it inherits ours.
      ...(env ? { env } : {}),
    }, (err, stdout, stderr) => {
      const out = String(stdout || '').trim() || String(stderr || '').trim();
      finish({ ok: !err, out });
    });
    // execFile's own `timeout` is NOT a deadline on the answer. It signals the
    // direct child, but the callback fires on 'close', which waits for the
    // stdio streams - and a wrapper like npx leaves a grandchild holding them
    // open, so the promise can outlive the timeout by minutes. With every probe
    // inside one Promise.all, that is the whole endpoint hanging on one slow
    // tool. The deadline is therefore enforced here too.
    deadline = setTimeout(() => {
      _toolKill(child);
      finish({ ok: false, out: '' });
    }, limit + 500);
    if (deadline.unref) deadline.unref();
  });
}

/**
 * The first dotted version in a CLI banner. `bw` prints a bare "2026.6.0",
 * `claude` prints "2.1.261 (Claude Code)", `git` prints "git version 2.53.0".
 * @param {string} text @returns {string|null}
 */
function _toolVersionFrom(text) {
  const m = /(\d+\.\d+(?:\.\d+)*)/.exec(String(text || ''));
  return m ? m[1] : null;
}

/**
 * A comparable version string, or null when there is nothing to compare.
 * Everything from the first `-` or `+` is dropped, so a prerelease install
 * (24.19.0-nightly) is read as the release it is based on instead of collapsing
 * into NaN halfway through a segment-wise compare.
 * @param {string} raw @returns {string|null}
 */
function _normalizeVersion(raw) {
  if (raw === null || raw === undefined) return null;
  const cut = String(raw).trim().replace(/^v/i, '').split('-')[0].split('+')[0];
  return /^\d+(\.\d+)*$/.test(cut) ? cut : null;
}

/** Segment-wise numeric compare of two normalized versions. */
function _cmpVersion(a, b) {
  const pa = String(a).split('.').map(Number);
  const pb = String(b).split('.').map(Number);
  const len = Math.max(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const x = pa[i] || 0;
    const y = pb[i] || 0;
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}

/**
 * Does `version` satisfy an `engines`-style range like ">=24 <25"?
 *
 * Returns null - NOT false - when either side cannot be parsed. A Node install
 * whose version string this cannot read is an unknown, not a wrong version, and
 * those two states send a person to two different places.
 *
 * @param {string} version @param {string} range @returns {boolean|null}
 */
function _satisfiesEngineRange(version, range) {
  const v = _normalizeVersion(version);
  if (!v) return null;
  const clauses = String(range || '').trim().split(/\s+/).filter(Boolean);
  if (!clauses.length) return true;
  for (const clause of clauses) {
    const m = /^(>=|<=|>|<|=)?v?(\d+(?:\.\d+)*)$/.exec(clause);
    if (!m) return null;
    const cmp = _cmpVersion(v, m[2]);
    switch (m[1] || '=') {
      case '>=': if (cmp < 0) return false; break;
      case '>': if (cmp <= 0) return false; break;
      case '<=': if (cmp > 0) return false; break;
      case '<': if (cmp >= 0) return false; break;
      default: if (cmp !== 0) return false;
    }
  }
  return true;
}

/**
 * The one place a probe result turns into a colour.
 *
 * `installed` is deliberately three-valued: false is "the binary is not there",
 * null is "the probe could not tell". `degraded` is the tool being present but
 * needing a person - a locked vault, a stale index - which is a warning, never
 * a failure.
 *
 * @param {{installed: boolean|null, version?: string|null, expected?: string|null, degraded?: boolean}} f
 * @returns {'ok'|'warn'|'missing'|'unknown'}
 */
function _classifyTool(f) {
  if (f.installed === false) return 'missing';
  if (f.installed === null || f.installed === undefined) return 'unknown';
  if (f.degraded) return 'warn';
  if (f.expected) {
    const satisfied = _satisfiesEngineRange(f.version, f.expected);
    if (satisfied === null) return 'unknown';
    if (satisfied === false) return 'warn';
  }
  return 'ok';
}

/** `engines` from package.json, or an empty object when it cannot be read. */
function _toolEngines() {
  try {
    return JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).engines || {};
  } catch (_e) { return {}; }
}

/** Parsed .mcp.json, or null. */
function _toolMcpConfig() {
  try {
    return JSON.parse(fs.readFileSync(path.join(ROOT, '.mcp.json'), 'utf8'));
  } catch (_e) { return null; }
}

/**
 * The @playwright/mcp spec pinned in .mcp.json, e.g. '@playwright/mcp@0.0.80'.
 * Read from the file and never from a literal here: a hardcoded version makes
 * the card lie on the day somebody bumps the pin. Validated before use, because
 * it becomes an execFile argument.
 * @returns {string|null}
 */
function _toolPlaywrightMcpSpec(mcp) {
  const args = (((mcp || {}).mcpServers || {}).playwright || {}).args;
  if (!Array.isArray(args)) return null;
  const spec = args.find(a => typeof a === 'string' && a.startsWith('@playwright/mcp@'));
  return spec && /^@playwright\/mcp@[\w.-]+$/.test(spec) ? spec : null;
}

// ── The eleven probes ────────────────────────────────────────────────────────
// Each returns one complete record. Each is independent: nothing here reads
// another probe's result.

function _probeNode() {
  const expected = _toolEngines().node || null;
  const version = process.versions.node;
  return {
    id: 'node', group: 'runtime', installed: true, version, expected,
    state: _classifyTool({ installed: true, version, expected }), detail: null,
  };
}

async function _probeNpm() {
  const expected = _toolEngines().npm || null;
  const r = await _toolExec(_toolCmd('npm'), ['-v']);
  const version = r.ok ? _toolVersionFrom(r.out) : null;
  return {
    id: 'npm', group: 'runtime', installed: r.ok, version, expected,
    state: _classifyTool({ installed: r.ok, version, expected }), detail: null,
  };
}

async function _probeGit() {
  const r = await _toolExec('git', ['--version']);
  const version = r.ok ? _toolVersionFrom(r.out) : null;
  return {
    id: 'git', group: 'runtime', installed: r.ok, version, expected: null,
    state: _classifyTool({ installed: r.ok, version }), detail: null,
  };
}

// Python is not something this server runs on, but the mini apps, the
// Playwright recipes and a number of Claude Code skills reach for it, and the
// command that answers differs per system: macOS ships `python3` and usually
// no `python` at all, while Windows has `python` (python.org, Microsoft
// Store) and the `py` launcher - and its Store STUB named python.exe exits
// non-zero with an install hint when nothing is installed, which is exactly
// the "missing" answer. Candidates are tried in order and the first that
// prints a version wins. All of them are real binaries, so no shell anywhere.
const PYTHON_EXPECTED = '>=3.10 <4';
function _pythonCandidates(platform) {
  return platform === 'win32'
    ? [['py', ['-3', '--version']], ['python', ['--version']]]
    : [['python3', ['--version']], ['python', ['--version']]];
}

async function _probePython() {
  let found = null;
  for (const [cmd, args] of _pythonCandidates(process.platform)) {
    const r = await _toolExec(cmd, args);
    const version = r.ok ? _toolVersionFrom(r.out) : null;
    if (r.ok && version) { found = { cmd, version }; break; }
  }
  const installed = !!found;
  const version = found ? found.version : null;
  return {
    id: 'python', group: 'runtime', installed, version, expected: PYTHON_EXPECTED,
    state: _classifyTool({ installed, version, expected: PYTHON_EXPECTED }),
    detail: found ? { command: found.cmd } : null,
  };
}

/**
 * Bitwarden CLI: is it there, which version, and is the vault open.
 *
 * `bw status` also returns userEmail and userId. NEITHER leaves this function.
 * Same rule the _bwLastLoad record carries: item and key names only, never a
 * value, and never the person behind them.
 */
async function _probeBitwarden() {
  const ver = await _toolExec('bw', ['--version']);
  if (!ver.ok) {
    return {
      id: 'bitwarden', group: 'sejf', installed: false, version: null, expected: null,
      state: 'missing', detail: null,
    };
  }
  const version = _toolVersionFrom(ver.out);
  // The session lives in THIS process, not in the child's environment: a bare
  // `bw status` answers "locked" while the top bar shows an open vault. Handing
  // the probe the same BW_SESSION handleBitwardenStatus uses is what makes the
  // two endpoints agree - without it the tab reports a lock nobody can undo.
  const st = await _toolExec('bw', ['status'], null,
    _bwSession ? { ...process.env, BW_SESSION: _bwSession } : null);
  let lockState = 'unknown';
  let serverUrl = null;
  if (st.ok) {
    try {
      const raw = st.out;
      const start = raw.indexOf('{');
      const parsed = JSON.parse(start >= 0 ? raw.slice(start) : '{}');
      lockState = parsed.status || 'unknown';
      serverUrl = parsed.serverUrl || null;
    } catch (_e) { /* CLI present, output unparseable - stays 'unknown' */ }
  }
  return {
    id: 'bitwarden', group: 'sejf', installed: true, version, expected: null,
    state: _classifyTool({ installed: true, degraded: lockState !== 'unlocked' }),
    detail: { lockState, serverUrl },
  };
}

async function _probeClaudeCli() {
  const r = await _toolExec(_claudeCli().cmd, ['--version']);
  const version = r.ok ? _toolVersionFrom(r.out) : null;
  return {
    id: 'claude-cli', group: 'claude', installed: r.ok, version, expected: null,
    state: _classifyTool({ installed: r.ok, version }), detail: null,
  };
}

/**
 * The terminal inside the app. Free: `pty` and `wss` are module-level, and the
 * WebSocket upgrade handler already refuses with 503 when either is null.
 *
 * This is the pairing worth showing. A machine can have the Claude CLI on PATH
 * and still have a dead terminal, because node-pty failed to build - and today
 * the only symptom is a connection that will not open.
 */
function _probeClaudeTerminal() {
  const installed = !!(pty && wss);
  return {
    id: 'claude-terminal', group: 'claude', installed, version: null, expected: null,
    state: _classifyTool({ installed }),
    detail: { pty: !!pty, ws: !!wss },
  };
}

function _probeMcpConfig() {
  const mcp = _toolMcpConfig();
  if (!mcp) {
    return {
      id: 'mcp-config', group: 'claude', installed: false, version: null, expected: null,
      state: 'missing', detail: null,
    };
  }
  const servers = Object.keys(mcp.mcpServers || {});
  const missing = ['gitnexus', 'playwright'].filter(n => !servers.includes(n));
  return {
    id: 'mcp-config', group: 'claude', installed: true, version: null, expected: null,
    state: _classifyTool({ installed: true, degraded: missing.length > 0 }),
    detail: { servers, missing },
  };
}

/**
 * The Playwright MCP package, warmed in the npx cache by `npm run setup`.
 * `--no-install` is what makes this a PROBE and not a download: npx exits
 * non-zero instead of fetching, and that exit is the "run setup" warning.
 */
async function _probePlaywrightMcp() {
  const spec = _toolPlaywrightMcpSpec(_toolMcpConfig());
  if (!spec) {
    return {
      id: 'playwright-mcp', group: 'weryfikacja', installed: null, version: null, expected: null,
      state: 'unknown', detail: null,
    };
  }
  const pinned = spec.slice(spec.lastIndexOf('@') + 1);
  const r = await _toolExec(_toolCmd('npx'), ['--no-install', spec, '--version'], TOOL_NPX_TIMEOUT_MS);
  const version = r.ok ? _toolVersionFrom(r.out) : null;
  return {
    id: 'playwright-mcp', group: 'weryfikacja', installed: r.ok, version, expected: null,
    state: _classifyTool({ installed: r.ok }),
    detail: { pinned },
  };
}

function _probeChromium() {
  const builds = installedChromium();
  const installed = builds.length > 0;
  // The headed build is what the card should name. Sorting puts
  // chromium_headless_shell-* last, so taking the plain tail would report the
  // shell on a machine that has both.
  const headed = builds.filter(b => /^chromium-\d+$/.test(b));
  return {
    id: 'chromium', group: 'weryfikacja', installed,
    version: headed[headed.length - 1] || builds[builds.length - 1] || null, expected: null,
    state: _classifyTool({ installed }),
    detail: { builds, root: browsersRoot() },
  };
}

async function _probeGitnexusCli() {
  const r = await _toolExec(_toolCmd('gitnexus'), ['--version']);
  const version = r.ok ? _toolVersionFrom(r.out) : null;
  return {
    id: 'gitnexus-cli', group: 'weryfikacja', installed: r.ok, version, expected: null,
    state: _classifyTool({ installed: r.ok, version }), detail: null,
  };
}

/**
 * Is the code graph still describing this working tree?
 *
 * A stale index is a WARNING and never a failure: it goes stale on every single
 * commit, and a red pill for a normal state teaches people to ignore the
 * colours. It still has to be visible - CLAUDE.md requires an `impact` run
 * before editing any symbol, and against a stale index that rule quietly
 * becomes a no-op with nothing but a log line to say so.
 */
async function _probeGitnexusIndex() {
  let meta = null;
  try {
    meta = JSON.parse(fs.readFileSync(path.join(ROOT, '.gitnexus', 'meta.json'), 'utf8'));
  } catch (_e) { /* no index yet */ }
  if (!meta) {
    return {
      id: 'gitnexus-index', group: 'weryfikacja', installed: false, version: null, expected: null,
      state: 'missing', detail: null,
    };
  }
  const head = await _toolExec('git', ['-C', ROOT, 'rev-parse', 'HEAD']);
  const headCommit = head.ok ? head.out.split('\n')[0].trim() : null;
  const indexedCommit = meta.lastCommit || null;
  const stale = !!(headCommit && indexedCommit && headCommit !== indexedCommit);
  return {
    id: 'gitnexus-index', group: 'weryfikacja', installed: true,
    version: (meta.stats && meta.stats.nodes) ? String(meta.stats.nodes) : null,
    expected: null,
    state: _classifyTool({ installed: true, degraded: stale }),
    detail: {
      stale,
      indexedAt: meta.indexedAt || null,
      indexedCommit: indexedCommit ? indexedCommit.slice(0, 7) : null,
      headCommit: headCommit ? headCommit.slice(0, 7) : null,
    },
  };
}

// id and group are repeated here so a probe that throws can still be reported
// on its own row instead of vanishing from the response.
const TOOL_PROBES = [
  ['node', 'runtime', _probeNode],
  ['npm', 'runtime', _probeNpm],
  ['git', 'runtime', _probeGit],
  ['python', 'runtime', _probePython],
  ['bitwarden', 'sejf', _probeBitwarden],
  ['claude-cli', 'claude', _probeClaudeCli],
  ['claude-terminal', 'claude', _probeClaudeTerminal],
  ['mcp-config', 'claude', _probeMcpConfig],
  ['playwright-mcp', 'weryfikacja', _probePlaywrightMcp],
  ['chromium', 'weryfikacja', _probeChromium],
  ['gitnexus-cli', 'weryfikacja', _probeGitnexusCli],
  ['gitnexus-index', 'weryfikacja', _probeGitnexusIndex],
];

/**
 * GET /api/tools/status[?refresh=1] -> { checked_at, platform, cached, tools[] }.
 * `platform` is process.platform, so the tab can show the remedy for THIS
 * system (winget on Windows, Homebrew on macOS) without guessing from the
 * browser's user agent.
 *
 * Probes run in parallel; serial they would add up to something nobody waits
 * for, and renderSettingsView fans out every panel at once anyway. The 60 s
 * cache keeps a tab switch free, and `refresh=1` is what the "Check again"
 * button sends.
 */
let _toolsInflight = null; // the probe run in progress, shared by concurrent callers

async function handleToolsStatus(req, res) {
  const refresh = new URL(req.url, 'http://localhost').searchParams.get('refresh') === '1';
  const now = Date.now();
  // `job` is recomputed even on a cache hit: it is module state, it costs
  // nothing, and it is what the tab polls while a job runs. Without that the
  // client would have to spend a full re-probe - eleven child processes, npx
  // among them - every few seconds just to learn whether a job finished.
  if (!refresh && _toolsCache.data && (now - _toolsCache.at) < TOOLS_TTL_MS) {
    return jsonResponse(res, 200, { ..._toolsCache.data, cached: true, job: _toolJobPublic() });
  }

  // One probe run at a time. A run is twelve child processes (`bw status`
  // among them, and `npx` with a 10 s budget), and the wizard and Settings >
  // Tools both ask on `cockpit:secrets-changed` in the same tick - so a
  // miss used to mean two runs, and two tabs on the cache's expiry meant two
  // more. A caller that arrives while a run is on gets that run's answer;
  // `refresh=1` skips the cache, never the run in progress.
  if (!_toolsInflight) {
    _toolsInflight = (async () => {
      const tools = await Promise.all(TOOL_PROBES.map(([id, group, fn]) =>
        Promise.resolve().then(fn).catch(() => ({
          id, group, installed: null, version: null, expected: null, state: 'unknown', detail: null,
        }))));
      const data = { checked_at: new Date().toISOString(), platform: process.platform, tools };
      _toolsCache = { at: Date.now(), data };
      return data;
    })().finally(() => { _toolsInflight = null; });
  }
  const data = await _toolsInflight;
  return jsonResponse(res, 200, { ...data, cached: false, job: _toolJobPublic() });
}

// ── Tool jobs (buttons in the tab) ──────────────────────────────────────────
// The half of this tab that ACTS instead of describing: install what is
// missing, rebuild the code map when it drifts.
//
// This is NOT a "run a command" endpoint and must never become one. The request
// carries a job ID, that ID is looked up in the closed table below, and the
// command line comes from this file alone - nothing from the request is ever
// interpolated into an argument. Adding a job means editing this table, in a
// review, which is exactly the gate such a feature needs.
//
// What is deliberately NOT here: node, npm and git. They are the runtime this
// server is running ON - replacing node underneath a live process is how you
// get a half-written index and a dead port - so those cards keep a copyable
// command and no button.

const _npmBin = () => (_toolIsWin ? 'npm.cmd' : 'npm');

// Long by design: a Chromium download is ~150 MB and a cold global npm install
// is minutes, not seconds. Past this, something is hung rather than slow.
const TOOL_JOB_TIMEOUT_MS = 20 * 60 * 1000;

/**
 * Every job this cockpit will run on request. `resolve()` is called at start
 * time, never at module load, so a job can look at the disk first.
 * `restart` marks the jobs whose effect only lands in a fresh server process.
 */
const TOOL_JOBS = {
  'gitnexus-reindex': {
    resolve: () => {
      const inv = analyzeInvocation(ROOT);
      return { cmd: inv.cmd, args: inv.args, env: GITNEXUS_ANALYZE_ENV };
    },
    // The analyzer refuses to run over an index a previous run left dirty (an
    // interrupted analyze, or a concurrent reader holding the database) and
    // fails with "FTS index is inconsistent". Its OWN recovery runs on the next
    // invocation: it sees the flag and forces a full rebuild. Observed on this
    // repo - first click fails in 7 s, second succeeds. One retry turns a button
    // that needs clicking twice into one that works, and it is not blind
    // retrying: it is handing the tool its documented self-heal path.
    retryOnce: true,
  },
  'gitnexus-install': {
    resolve: () => ({ cmd: _npmBin(), args: ['install', '-g', 'gitnexus@' + GITNEXUS_CLI_VERSION] }),
  },
  'bitwarden-install': {
    // The npm distribution, not Homebrew: it is the same command on macOS,
    // Windows and Linux, and it needs no second package manager present.
    resolve: () => ({ cmd: _npmBin(), args: ['install', '-g', '@bitwarden/cli'] }),
  },
  'claude-install': {
    // Same package the terminal's own "not found" message names, so the button
    // and that message can never send a person to two different installers.
    resolve: () => ({ cmd: _npmBin(), args: ['install', '-g', '@anthropic-ai/claude-code'] }),
  },
  'playwright-setup': {
    resolve: () => ({
      cmd: process.execPath,
      args: [path.join(ROOT, 'scripts', 'bootstrap-playwright.js')],
    }),
  },
  'deps-install': {
    // Rebuilds node-pty, which is what a dead in-app terminal usually needs.
    resolve: () => ({ cmd: _npmBin(), args: ['install'] }),
    restart: true,
  },
};

// Serializes the start decision. The chain lock is what makes "is one already
// running?" and "start one" a single step - two clicks a millisecond apart must
// not both pass the check and spawn two installers over one npm prefix.
const withToolJobLock = _makeChainLock();

let _toolJob = {
  id: null, running: false, startedAt: null, finishedAt: null,
  ok: null, error: null, restartRequired: false,
};

/** The state as the UI sees it. No paths, no command line, no raw log. */
function _toolJobPublic() {
  return { ..._toolJob };
}

/**
 * One line a person can act on, pulled from the job output.
 *
 * NOT simply the last line: a crashing CLI ends on a stack frame, and
 * "at async Command.<anonymous> (file:///.../lazy-action.js:33:9)" on a card is
 * worse than nothing - it looks like a bug in this cockpit and says nothing
 * about what failed. Stack frames are dropped, the last line that actually
 * reads like a failure wins, and the whole log still goes to the server console.
 */
function _reindexFailureLine(tail) {
  const lines = String(tail || '')
    .split('\n')
    .map(l => l.replace(/\x1b\[[0-9;]*m/g, '').trim())
    .filter(Boolean)
    .filter(l => !/^at\s/.test(l));
  const spoken = [...lines].reverse().find(
    l => /error|failed|cannot|denied|refus|EACCES|ENOENT|EBUSY|locked/i.test(l));
  return (spoken || lines[lines.length - 1] || '').slice(0, 300) || null;
}

/**
 * Spawn one job and record how it ends. Fire-and-forget by design: the HTTP
 * request returns immediately and the tab polls GET /api/tools/status.
 *
 * The child is NOT detached, so a server restart takes it down with it. That is
 * the right trade: every job here is idempotent and re-runnable, while an
 * orphaned installer still writing after the server that started it is gone
 * would be a background job nobody can see or stop from this UI.
 *
 * @param {string} id a key of TOOL_JOBS, already validated by the caller
 */
function _startToolJob(id) {
  const job = TOOL_JOBS[id];
  _toolJob = {
    id, running: true, startedAt: new Date().toISOString(), finishedAt: null,
    ok: null, error: null, restartRequired: false,
  };

  let tail = '';
  const keepTail = (chunk) => { tail = (tail + String(chunk)).slice(-4000); };

  const finish = (ok, error) => {
    if (!_toolJob.running || _toolJob.id !== id) return;
    _toolJob = {
      id,
      running: false,
      startedAt: _toolJob.startedAt,
      finishedAt: new Date().toISOString(),
      ok,
      error: ok ? null : error,
      restartRequired: !!(ok && job.restart),
    };
    // Whatever the job changed, the cached probe answer predates it.
    _toolsCache = { at: 0, data: null };
    // The same reasoning one memo over, and it is load-bearing for exactly
    // one job: `bitwarden-install` puts the CLI on this machine, and the bw
    // memo is holding an ENOENT that _bwProbeCacheable deliberately treats as
    // a FACT worth caching. Without this the top bar's pill - which paints
    // nothing for "no CLI" and has no poll of its own - would stay absent
    // until a page reload or a vault event, right after the button that was
    // supposed to fix it reported success.
    if (ok && id === 'bitwarden-install') _bwStatusInvalidate();
  };

  const attempt = (n) => {
    tail = '';
    const spec = job.resolve();
    let child;
    try {
      child = spawn(spec.cmd, spec.args, {
        cwd: ROOT,
        // The installer runs for minutes - an allowlist, not a copy of
        // process.env with the vault tokens (see _childEnvAllowlist).
        env: _childEnvAllowlist(process.env, { extra: spec.env || {} }),
        stdio: ['ignore', 'pipe', 'pipe'],
        shell: _toolShell(spec.cmd),
      });
    } catch (e) {
      finish(false, e.message);
      return;
    }

    const killer = setTimeout(() => {
      _toolKill(child);
    }, TOOL_JOB_TIMEOUT_MS);
    if (killer.unref) killer.unref();

    child.stdout.on('data', keepTail);
    child.stderr.on('data', keepTail);
    child.on('error', (e) => { clearTimeout(killer); finish(false, e.message); });
    child.on('close', (code) => {
      clearTimeout(killer);
      if (code === 0) return finish(true, null);
      console.error('[tools:' + id + '] attempt ' + n + ' exit ' + code + '\n' + tail);
      if (job.retryOnce && n === 1) {
        console.warn('[tools:' + id + '] retrying once - the tool repairs its own state on the next run');
        return attempt(2);
      }
      finish(false, _reindexFailureLine(tail) || ('the job ended with code ' + code));
    });
  };

  attempt(1);
}

/**
 * POST /api/tools/run { job } -> 202 { started, reason, job }.
 *
 * Never 200: the work has been ACCEPTED, not done. A second call while a job
 * runs is also a 202 with started:false - asking twice is not an error, and the
 * caller gets the same state either way. An unknown job id is a 400: it can
 * only come from a stale client or a hand-written request.
 */
async function handleToolsRun(req, res) {
  if (!checkOrigin(req, res)) return;

  // readBody already parses - it resolves the object, not the text.
  let body;
  try {
    body = await readBody(req, 1024);
  } catch (_e) {
    return jsonResponse(res, 400, { error: 'invalid-json' });
  }
  const id = body && body.job;
  if (typeof id !== 'string' || !Object.prototype.hasOwnProperty.call(TOOL_JOBS, id)) {
    return jsonResponse(res, 400, { error: 'unknown-job' });
  }

  const result = await withToolJobLock(async () => {
    if (_toolJob.running) return { started: false, reason: 'running' };
    // The api suite spawns a real server; without this guard it would also
    // install packages globally and rewrite the developer's index. Same shape
    // as the restart endpoint's TEST_DISABLE_RESTART / IS_TEST_MODE guard.
    if (IS_TEST_MODE) return { started: false, reason: 'test-mode' };
    _startToolJob(id);
    return { started: true, reason: null };
  });

  return jsonResponse(res, 202, { ...result, job: _toolJobPublic() });
}


// ── Assets endpoints ───────────────────────────────────────────────────────
// The Assets hub reads committed files, not application state: the token
// layer (css/ds-tokens.css), the icon set (assets/icons/ds/) and the mascot
// artwork (assets/mascot/) are plain CSS, JSON and SVG which serveStatic
// already answers, so only the mascot gallery needs a route - a directory
// listing is the one thing the browser cannot do for itself.

const MASCOT_DIR = path.join(ROOT, 'assets', 'mascot');

/**
 * Lists the .svg base names in the mascot directory.
 * A missing directory is a normal state (a partial checkout), not a failure:
 * it yields an empty list so the view paints its own empty state. Any other
 * read error is thrown, so the caller can answer 500.
 *
 * @param {string} dir
 * @returns {Promise<string[]>} base names, extension stripped
 */
async function _mascotAssetNames(dir) {
  let files;
  try {
    files = await fs.promises.readdir(dir);
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  return files.filter(f => /\.svg$/i.test(f)).map(f => f.replace(/\.svg$/i, ''));
}

/**
 * Reads the pose labels from assets/mascot/manifest.json. A missing or broken
 * manifest only costs the labels - the SVG listing stays the source of truth.
 *
 * @returns {Promise<Map<string, {pose: string, label: string}>>} keyed by base name
 */
async function _mascotManifest() {
  const out = new Map();
  try {
    const data = JSON.parse(await fs.promises.readFile(path.join(MASCOT_DIR, 'manifest.json'), 'utf8'));
    for (const p of Array.isArray(data.poses) ? data.poses : []) {
      if (p && typeof p.file === 'string') out.set(p.file.replace(/\.svg$/i, ''), { pose: String(p.pose || ''), label: String(p.label || '') });
    }
  } catch { /* labels are optional */ }
  return out;
}

/**
 * GET /api/assets/mascot
 * The mascot gallery: one item per SVG pose of Pip. Read-only, no token, no
 * cache - the files are committed and change only with a pull.
 */
async function handleAssetsMascot(req, res) {
  if (!checkOriginNoBody(req, res)) return;

  let names;
  try {
    names = await _mascotAssetNames(MASCOT_DIR);
  } catch {
    return jsonResponse(res, 500, { status: 'error', message: 'Cannot read mascot assets' });
  }
  const meta = await _mascotManifest();

  const items = names
    .sort((a, b) => a.localeCompare(b))
    .map(name => ({
      name,
      pose: meta.get(name)?.pose || null,
      label: meta.get(name)?.label || name,
      svg: `/assets/mascot/${name}.svg`,
    }));

  return jsonResponse(res, 200, { items, count: items.length });
}

// ── Prototypes (registry and details, read-only) ────────────────────────────
// Stage 1 of the prototype migration plan: ready screen prototypes carried
// over from the original cockpit. The data source is the data
// repository (DATA_REPO_DEFS), the prototypes/ directory in its plaintext
// tree. The routes are read-only - adding, editing and deleting arrive in
// Stage 2. The API paths stay 1:1 with the original cockpit: they are baked into
// the source code of every existing prototype and into the build shell that
// builds them.

// A prototype id ("proto-xxxx") and an icon/illustration slug share the same
// shape, as in the source - hence one pattern for both. Validated BEFORE any
// path is built.
const PROTO_ID_RE = /^[a-z0-9-]+$/;
const PROTO_FILE_RE = /^[a-z0-9._-]+$/;

// MUST come from _dataRepoDef - never glued together by hand, otherwise a test
// substituting DATA_SUB_REPOS_DIR reads the developer's directory instead of its own
// test tree.
const PRODUCT_DATA_DIR = DATA_TIER_0_DIR;
const PROTOTYPES_DIR = path.join(PRODUCT_DATA_DIR, 'prototypes');

// Public address of published prototypes. Env-only: empty means "not
// configured" and the UI hides the link to the published version.
function protoPagesBaseUrl() {
  return String(process.env.PROTO_PAGES_BASE_URL || '').trim().replace(/\/+$/, '');
}

function _prototypesJsonPath() {
  return path.join(PROTOTYPES_DIR, 'prototypes.json');
}

// Serializes every write of prototypes.json (create/update/delete) so two
// clients never interleave read-modify-write on the same file.
const withProtoLock = _makeChainLock();

// Atomic write of prototypes.json (temp file + rename - never a direct
// fs.writeFileSync on a shared file).
function _writePrototypes(data) {
  fs.mkdirSync(PROTOTYPES_DIR, { recursive: true });
  const p = _prototypesJsonPath();
  const tmp = p + '.tmp-' + process.pid;
  fs.writeFileSync(tmp, JSON.stringify(data, null, 2) + '\n', 'utf8');
  fs.renameSync(tmp, p);
}

// Directories already on disk under PROTOTYPES_DIR that the registry does not
// know (e.g. a leftover of an interrupted write by an older handler). An
// orphaned directory counts towards the pool of taken ids on a par with the
// registry - otherwise a new entry could get an id colliding with files it cannot see.
function _protoOrphanDirIds() {
  let entries;
  try {
    entries = fs.readdirSync(PROTOTYPES_DIR, { withFileTypes: true });
  } catch {
    return [];
  }
  return entries.filter((e) => e.isDirectory() && PROTO_ID_RE.test(e.name)).map((e) => e.name);
}

// Generates a unique proto-<hex> id (the pattern from the original cockpit).
// The id NEVER comes from the request.
// `existingIds` MUST already cover both the registry and the orphaned directories
// (see _protoOrphanDirIds) - this function does not add them itself.
function _protoMakeId(existingIds) {
  for (let i = 0; i < 10000; i++) {
    const candidate = 'proto-' + crypto.randomBytes(6).toString('hex');
    if (!existingIds.has(candidate)) return candidate;
  }
  throw new Error('could not generate a unique prototype id');
}

// Reads prototypes.json. A missing file or corrupted JSON is a NORMAL state
// (source not downloaded yet) - never an error: answers an empty collection.
function _readPrototypes() {
  let raw;
  try {
    raw = fs.readFileSync(_prototypesJsonPath(), 'utf8');
  } catch {
    return { items: [] };
  }
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { items: [] };
  }
  if (!parsed || !Array.isArray(parsed.items)) return { items: [] };
  return parsed;
}

// Read for a WRITE route (create/update/delete): a missing file is still a
// normal state (the first write creates the registry), but a file that is
// PRESENT and unreadable/corrupted/badly shaped THROWS instead of quietly
// returning `{ items: [] }`. Without that distinction a write on a corrupted
// registry would replace other people's work with an empty collection - GET can
// afford it (it changes nothing on disk), a write cannot.
function _readPrototypesForWrite() {
  let raw;
  try {
    raw = fs.readFileSync(_prototypesJsonPath(), 'utf8');
  } catch (e) {
    if (e && e.code === 'ENOENT') return { items: [] };
    const err = new Error(`The prototype registry is unreadable: ${e.message}`);
    err.protoRegistryUnreadable = true;
    throw err;
  }
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    const err = new Error(`The prototype registry has corrupted JSON: ${e.message}`);
    err.protoRegistryUnreadable = true;
    throw err;
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) || !Array.isArray(parsed.items)) {
    const err = new Error('The prototype registry has an unexpected shape (expected { items: [...] })');
    err.protoRegistryUnreadable = true;
    throw err;
  }
  return parsed;
}

// POST/PUT of this registry have one field allowlist and must NEVER accept a
// body of any shape other than an object - `null`, an array or a primitive (valid
// JSON, but not an object) must not throw on the first `body.field`.
function _asPlainObject(value) {
  return (value && typeof value === 'object' && !Array.isArray(value)) ? value : {};
}

// Computed ON READ from the presence of a source file in the prototype directory -
// never written to prototypes.json. Three values: 'react' (index.tsx),
// 'vanilla' (render.js, the contract of the old built-in preview) and 'missing',
// when the directory exists (or does not exist at all) and NEITHER of the two
// source files is there - e.g. a registry entry added before the starter managed
// to copy, or exactly this state after a failed starter write.
// 'missing' is NOT guessed as 'vanilla' by default - that was a regression
// against the original cockpit, which also assumed a react source.
function _protoFormat(id) {
  // The same condition as _protoDir: the id is checked BEFORE the path is
  // built, even when it comes from a local data file - the section has one
  // rule and no exception to it.
  if (!id || !PROTO_ID_RE.test(id)) return 'missing';
  const dir = path.join(PROTOTYPES_DIR, id);
  if (fs.existsSync(path.join(dir, 'index.tsx'))) return 'react';
  if (fs.existsSync(path.join(dir, 'render.js'))) return 'vanilla';
  return 'missing';
}

// Validates a prototype id BEFORE building the path and returns its
// directory. An extra barrier: the joined path must still lie under
// PROTOTYPES_DIR (defence in depth, should PROTO_ID_RE ever be relaxed).
// Returns null and sends a 400/403 answer when validation fails.
function _protoDir(id, res) {
  if (!id || !PROTO_ID_RE.test(id)) {
    jsonResponse(res, 400, { error: 'invalid-proto-id' });
    return null;
  }
  const dir = path.join(PROTOTYPES_DIR, id);
  if (!dir.startsWith(PROTOTYPES_DIR + path.sep)) {
    jsonResponse(res, 403, { error: 'forbidden' });
    return null;
  }
  return dir;
}

// Serves a file from a fixed (already validated) path. A missing file answers
// notFoundBody as a JSON 404; an existing file goes through _serveResolvedFile
// (ETag, gzip, streaming) - prototype asset directories weigh 0.25-6.2 MB and
// must not be read into memory whole on every request.
function _protoServeFile(req, res, filePath, urlPath, notFoundBody) {
  fs.stat(filePath, (err, stats) => {
    if (err || !stats.isFile()) {
      jsonResponse(res, 404, notFoundBody);
      return;
    }
    _serveResolvedFile(req, res, filePath, urlPath);
  });
}

// GET /api/prototypes
// Registry: every item from prototypes.json, with the format computed on
// read. A missing data directory is a normal state - an empty list, code 200.
function handlePrototypesGet(_req, res) {
  const data = _readPrototypes();
  const items = data.items.map((it) => ({ ...it, format: _protoFormat(it.id) }));
  return jsonResponse(res, 200, { items });
}

// GET /api/prototypes/initiatives
// Map "dt-xxxx" -> discovery initiative title, only for the ids that
// prototypes.json points at. The cards are read one by one and only
// those somebody refers to - the discovery-tasks/ directory has dozens of
// files, and the registry needs one field from them. A missing directory, a missing
// file and bad JSON are normal states: such an id simply does not reach the map,
// and the client then shows the prototype alone, without an initiative name.
function handlePrototypeInitiatives(_req, res) {
  const wanted = new Set();
  for (const it of _readPrototypes().items) {
    const dt = String(it && it.discoveryTaskId || '').trim();
    if (dt && PROTO_ID_RE.test(dt)) wanted.add(dt);
  }
  const map = {};
  for (const dt of wanted) {
    const filePath = path.join(PRODUCT_DATA_DIR, 'discovery-tasks', dt + '.json');
    let parsed;
    try {
      parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    } catch {
      continue;
    }
    const title = String(parsed && (parsed.title || parsed.tytul) || '').trim();
    if (title) map[dt] = title;
  }
  return jsonResponse(res, 200, { map });
}

// GET /api/prototypes/spec/<id>
// Returns the prototype's spec.json (the scope of work).
function handlePrototypeSpec(req, res) {
  const urlPath = req.url.split('?')[0];
  const id = urlPath.slice('/api/prototypes/spec/'.length);
  const dir = _protoDir(id, res);
  if (!dir) return;
  const filePath = path.join(dir, 'spec.json');
  _protoServeFile(req, res, filePath, urlPath, { _missing: true });
}

// The compliance review (compliance.json) is NOT carried over from the original
// cockpit - a product decision, the Compliance tab fell out of scope. There is
// deliberately no read route for this file; it may exist in team data and is ignored.

// GET /api/prototypes/asset/<id>/<file>
// Returns a binary asset from <dir>/assets/<file> (screenshots etc.).
function handlePrototypeAsset(req, res) {
  const urlPath = req.url.split('?')[0];
  const rest = urlPath.slice('/api/prototypes/asset/'.length); // "<id>/<file>"
  const slash = rest.indexOf('/');
  if (slash === -1) {
    jsonResponse(res, 404, { error: 'invalid-asset-path' });
    return;
  }
  const id = rest.slice(0, slash);
  const dir = _protoDir(id, res);
  if (!dir) return;
  let file;
  try {
    file = decodeURIComponent(rest.slice(slash + 1));
  } catch {
    jsonResponse(res, 400, { error: 'invalid-filename' });
    return;
  }
  if (!file || !PROTO_FILE_RE.test(file)) {
    jsonResponse(res, 400, { error: 'invalid-filename' });
    return;
  }
  const assetsDir = path.join(dir, 'assets');
  const filePath = path.join(assetsDir, file);
  if (!filePath.startsWith(assetsDir + path.sep)) {
    jsonResponse(res, 403, { error: 'forbidden' });
    return;
  }
  _protoServeFile(req, res, filePath, urlPath, { error: 'asset-not-found' });
}

// GET /api/prototypes/code/<id>
// Returns render.js (the 'vanilla' contract; 'react' prototypes do not have this file).
function handlePrototypeCode(req, res) {
  const urlPath = req.url.split('?')[0]; // strip the cache-bust ?v=
  const id = urlPath.slice('/api/prototypes/code/'.length);
  const dir = _protoDir(id, res);
  if (!dir) return;
  const filePath = path.join(dir, 'render.js');
  _protoServeFile(req, res, filePath, urlPath, { _missing: true });
}

// GET /api/prototypes/style/<id>
// Returns the prototype's own stylesheet.
function handlePrototypeStyle(req, res) {
  const urlPath = req.url.split('?')[0]; // strip the cache-bust ?v=
  const id = urlPath.slice('/api/prototypes/style/'.length);
  const dir = _protoDir(id, res);
  if (!dir) return;
  const filePath = path.join(dir, 'styles.css');
  _protoServeFile(req, res, filePath, urlPath, { _missing: true });
}

// Slug -> file name maps, built from the committed manifests of the icon set
// (assets/icons/ds/manifest.json) and the illustration set (the mascot poses,
// assets/mascot/manifest.json). A slug NEVER reaches a path unless it is a
// key of one of these maps.
const PROTO_DS_ICONS_DIR = path.join(ROOT, 'assets', 'icons', 'ds');
const PROTO_DS_ILLUSTRATIONS_DIR = path.join(ROOT, 'assets', 'mascot');
let _protoDsIconSlugMap = null;
let _protoDsIllustrationSlugMap = null;

/**
 * Reads one manifest into {slug: file}. Understands both shapes: the icon set
 * (`{icons: [{slug, file}]}`) and the mascot set (`{poses: [{file}]}`, slug =
 * file name without .svg). A missing or broken manifest yields an empty map.
 * @param {string} manifestPath
 * @returns {Object<string,string>}
 */
function _protoLoadSlugMap(manifestPath) {
  let data;
  try {
    data = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  } catch {
    return {};
  }
  const map = {};
  const plain = (f) => typeof f === 'string' && /^[A-Za-z0-9._-]+\.svg$/.test(f);
  for (const entry of Array.isArray(data && data.icons) ? data.icons : []) {
    if (entry && typeof entry.slug === 'string' && plain(entry.file)) map[entry.slug] = entry.file;
  }
  for (const entry of Array.isArray(data && data.poses) ? data.poses : []) {
    if (entry && plain(entry.file)) map[entry.file.replace(/\.svg$/, '')] = entry.file;
  }
  return map;
}

function _protoDsIconMap() {
  if (!_protoDsIconSlugMap) {
    _protoDsIconSlugMap = _protoLoadSlugMap(path.join(PROTO_DS_ICONS_DIR, 'manifest.json'));
  }
  return _protoDsIconSlugMap;
}

function _protoDsIllustrationMap() {
  if (!_protoDsIllustrationSlugMap) {
    _protoDsIllustrationSlugMap = _protoLoadSlugMap(path.join(PROTO_DS_ILLUSTRATIONS_DIR, 'manifest.json'));
  }
  return _protoDsIllustrationSlugMap;
}

// GET /api/prototypes/ds-icon/<slug>
// Serves one icon of the set from assets/icons/ds/<file>.
function handlePrototypeDsIcon(req, res) {
  const urlPath = req.url.split('?')[0];
  const slug = urlPath.slice('/api/prototypes/ds-icon/'.length);
  if (!slug || !PROTO_ID_RE.test(slug)) {
    jsonResponse(res, 400, { error: 'invalid-slug' });
    return;
  }
  const fileName = _protoDsIconMap()[slug];
  if (!fileName) {
    jsonResponse(res, 404, { error: 'icon-not-found' });
    return;
  }
  const filePath = path.join(PROTO_DS_ICONS_DIR, fileName);
  if (!filePath.startsWith(PROTO_DS_ICONS_DIR + path.sep)) {
    jsonResponse(res, 403, { error: 'forbidden' });
    return;
  }
  _protoServeFile(req, res, filePath, urlPath, { error: 'icon-file-missing' });
}

// GET /api/prototypes/ds-illustration/<slug>
// Serves one illustration (a mascot pose) from assets/mascot/<file>.
function handlePrototypeDsIllustration(req, res) {
  const urlPath = req.url.split('?')[0];
  const slug = urlPath.slice('/api/prototypes/ds-illustration/'.length);
  if (!slug || !PROTO_ID_RE.test(slug)) {
    jsonResponse(res, 400, { error: 'invalid-slug' });
    return;
  }
  const fileName = _protoDsIllustrationMap()[slug];
  if (!fileName) {
    jsonResponse(res, 404, { error: 'illustration-not-found' });
    return;
  }
  const filePath = path.join(PROTO_DS_ILLUSTRATIONS_DIR, fileName);
  if (!filePath.startsWith(PROTO_DS_ILLUSTRATIONS_DIR + path.sep)) {
    jsonResponse(res, 403, { error: 'forbidden' });
    return;
  }
  _protoServeFile(req, res, filePath, urlPath, { error: 'illustration-file-missing' });
}

// GET /api/prototypes/deploy-status lives in the "Prototypes: local build
// and publish" section below - it answers about the build shell, not the registry.

// -- Python script runner ---------------------------------------------------
// One runner for the Python helper scripts (today: Figma reference). Output
// lines `@@PROGRESS:{json}` are progress, every other line is a log line.

const PYTHON_STEP_TIMEOUT_MS = 90 * 60 * 1000;

// The Python interpreter as the Tools tab sees it (_pythonCandidates):
// the first candidate that prints a version. Windows gets `py -3 <script>`,
// the rest `python3 <script>`. The result is { cmd, argsPrefix } or null.
async function _pythonFind() {
  for (const [cmd, args] of _pythonCandidates(process.platform)) {
    const r = await _toolExec(cmd, args);
    if (r.ok && _toolVersionFrom(r.out)) return { cmd, argsPrefix: args.slice(0, -1) };
  }
  return null;
}

// Parses one line of script output. `@@PROGRESS:{json}` is progress, every
// other non-empty line is a log. Pure - tests/test_server_helpers.mjs.
function _pythonParseLine(line) {
  const text = String(line || '').replace(/\r$/, '');
  if (!text.trim()) return null;
  if (text.startsWith('@@PROGRESS:')) {
    try {
      const d = JSON.parse(text.slice('@@PROGRESS:'.length));
      const pct = Math.max(0, Math.min(100, Number(d && d.pct) || 0));
      return { kind: 'progress', pct, msg: String((d && d.msg) || '') };
    } catch {
      return { kind: 'log', text };
    }
  }
  return { kind: 'log', text };
}

// The script's percentage (0-100) scaled into the step's range [from, to] of the
// whole run's progress bar. Pure.
function _pythonScalePct(pct, from, to) {
  const p = Math.max(0, Math.min(100, Number(pct) || 0));
  return Math.round(from + (to - from) * (p / 100));
}

// Runs one script and streams its output. `stdinLine` (when
// given) is written to the child's stdin and stdin is closed; without it
// stdin is empty right away, so the script never waits for a terminal.
// `opts` (optional): { env: extra NON-secret variables, timeoutMs }. Used by
// the Figma reference below.
function _pythonRunScript(python, scriptPath, extraArgs, stdinLine, range, onProgress, onLog, opts) {
  const stepTimeoutMs = (opts && opts.timeoutMs) || PYTHON_STEP_TIMEOUT_MS;
  return new Promise((resolve) => {
    const child = spawn(python.cmd, [...python.argsPrefix, scriptPath, ...extraArgs], {
      cwd: ROOT,
      // The child environment without any secret: only what Python needs
      // to start, plus the input/output directories.
      env: {
        PATH: process.env.PATH || '',
        HOME: process.env.HOME || '',
        USERPROFILE: process.env.USERPROFILE || '',
        SYSTEMROOT: process.env.SYSTEMROOT || process.env.SystemRoot || '',
        TEMP: process.env.TEMP || '',
        TMP: process.env.TMP || '',
        LANG: process.env.LANG || 'C.UTF-8',
        PYTHONIOENCODING: 'utf-8',
        PYTHONUNBUFFERED: '1',
        ...((opts && opts.env) || {}),
      },
      stdio: ['pipe', 'pipe', 'pipe'],
    });
    let settled = false;
    let timedOut = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      clearTimeout(deadline);
      resolve(result);
    };
    const deadline = setTimeout(() => {
      timedOut = true;
      _toolKill(child);
    }, stepTimeoutMs);

    const feed = (stream, isStdout) => {
      let buf = '';
      stream.setEncoding('utf8');
      stream.on('data', (chunk) => {
        buf += chunk;
        let nl;
        while ((nl = buf.indexOf('\n')) >= 0) {
          const parsed = _pythonParseLine(buf.slice(0, nl));
          buf = buf.slice(nl + 1);
          if (!parsed) continue;
          if (parsed.kind === 'progress' && isStdout) onProgress(_pythonScalePct(parsed.pct, range[0], range[1]), parsed.msg);
          else onLog(parsed.text || parsed.msg);
        }
      });
      stream.on('end', () => {
        const parsed = _pythonParseLine(buf);
        if (parsed && parsed.kind === 'log') onLog(parsed.text);
      });
    };
    feed(child.stdout, true);
    feed(child.stderr, false);

    child.on('error', (err) => finish({ ok: false, error: 'spawn-failed', message: err.message }));
    child.on('close', (code) => {
      if (timedOut) finish({ ok: false, error: 'timeout', message: `The script did not finish within ${Math.round(stepTimeoutMs / 60000)} minutes` });
      else if (code === 0) finish({ ok: true });
      else finish({ ok: false, error: 'script-failed', code, message: `The script ended with code ${code}` });
    });

    if (stdinLine !== null && stdinLine !== undefined) {
      child.stdin.on('error', () => { /* the child closed stdin before reading - the error surfaces through the exit code */ });
      child.stdin.end(stdinLine + '\n');
    } else {
      child.stdin.end();
    }
  });
}

// -- Figma reference ----------------------------------------------------------
// A structural reference of a Figma design (frames, layout trees, typography,
// colours, components, token map, file hygiene, PNG snapshots) into
// user-data/figma-reference/<id>/. The same run as in the original tool
// (scripts/figma_reference.py, moved onto the Python standard library
// alone), called through the Figma REST API - no MCP loop.
//
// The server is the orchestrator: it validates the parameters BEFORE opening the
// stream, runs the child with the same runner as the analytics refresh
// (_pythonRunScript) and turns its output into SSE events
// (start / progress / log / done / error). The Figma token (FIGMA_TOKEN, the
// Bitwarden vault) lives in process memory and reaches the child as one JSON line on
// STDIN ({"figmaToken": ...}), never in its environment or argv - `ps`
// shows both to everyone on the same account. The child's output is
// additionally scrubbed of the token value before it reaches a `log` event.
//
// One run at a time (`busy`, no queue) - the same Figma request budget.
// GET /api/figma-reference/status?id= answers whether the reference already exists
// and since when (read-only, no token) - for a freshness check.
const FIGMA_REFERENCE_DIR = path.join(USER_DATA_DIR, 'figma-reference');
const FIGMA_REFERENCE_SCRIPT = path.join(ROOT, 'scripts', 'figma_reference.py');
const FIGMA_REFERENCE_TIMEOUT_MS = 45 * 60 * 1000;
const FIGMA_FILE_KEY_RE = /^[0-9a-zA-Z]{22,128}$/;
const FIGMA_NODE_ID_RE = /^\d+[:-]\d+$/;
const FIGMA_OUT_ID_RE = /^[a-z0-9][a-z0-9-]{0,63}$/;

let _figmaReferenceRunning = false;

// Pure: validation and normalization of the stream parameters. Returns
// { ok: true, file, nodeId (API form "96560:26612"), outId, scale, overwrite }
// or { ok: false, field, message }. Nothing from the request reaches a path
// other than through FIGMA_OUT_ID_RE.
function _figmaReferenceParseParams(searchParams) {
  const get = (k) => String(searchParams.get(k) || '').trim();
  const file = get('file');
  if (!FIGMA_FILE_KEY_RE.test(file)) {
    return { ok: false, field: 'file', message: 'Invalid Figma file key (expected 22-128 alphanumeric characters)' };
  }
  const node = get('node');
  if (!FIGMA_NODE_ID_RE.test(node)) {
    return { ok: false, field: 'node', message: 'Invalid Figma node id (expected the form 96560:26612 or 96560-26612) - point at a page or a section' };
  }
  const outId = get('id');
  if (!FIGMA_OUT_ID_RE.test(outId)) {
    return { ok: false, field: 'id', message: 'Invalid reference id (lowercase letters, digits and hyphens, up to 64 characters)' };
  }
  const scale = get('scale') || '2';
  if (scale !== '1' && scale !== '2') {
    return { ok: false, field: 'scale', message: 'Invalid scale (expected 1 or 2)' };
  }
  const overwrite = ['1', 'true'].includes(get('overwrite').toLowerCase());
  return { ok: true, file, nodeId: node.replace('-', ':'), outId, scale, overwrite };
}

// Pure: the child's argv. The token NEVER goes here - only the `--token-stdin` flag.
function _figmaReferenceBuildArgs(p) {
  const args = ['--token-stdin', '--file', p.file, '--node-id', p.nodeId, '--out-id', p.outId, '--scale', p.scale];
  if (p.overwrite) args.push('--overwrite');
  if (p.ifChanged) args.push('--if-changed');
  return args;
}

// Pure: one JSON line on the child's stdin.
function _figmaReferenceStdinLine(token) {
  return JSON.stringify({ figmaToken: token });
}

// Pure: removes the token value from log text.
function _figmaReferenceRedact(text, token) {
  const t = String(text === undefined || text === null ? '' : text);
  return token ? t.split(token).join('***') : t;
}

// Pure: the reference state from frames.json (or null when the manifest is unreadable).
function _figmaReferenceSummarize(manifest, mtimeIso) {
  if (!manifest || typeof manifest !== 'object') return null;
  const sections = Array.isArray(manifest.sections) ? manifest.sections : [];
  const frames = sections.reduce((n, s) => n + (Array.isArray(s && s.frames) ? s.frames.length : 0), 0);
  return {
    fileKey: String(manifest.fileKey || ''),
    fileName: String(manifest.fileName || ''),
    nodeId: String(manifest.nodeId || ''),
    scale: Number(manifest.scale) || null,
    sections: sections.length,
    frames,
    figmaLastModified: String(manifest.lastModified || '') || null,
    fetchedAt: String(manifest._fetched_at || '') || mtimeIso || null,
  };
}

/**
 * GET /api/figma-reference/status?id=<outId>
 * Whether user-data/figma-reference/<id>/frames.json exists and how old it is.
 * Read-only; a missing reference is a 200 with `exists: false`, not an error.
 */
function handleFigmaReferenceStatus(req, res) {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const id = String(url.searchParams.get('id') || '').trim();
  if (!FIGMA_OUT_ID_RE.test(id)) {
    return jsonResponse(res, 400, { error: 'bad-params', field: 'id', message: 'Invalid reference id (lowercase letters, digits and hyphens, up to 64 characters)' });
  }
  const manifestPath = path.join(FIGMA_REFERENCE_DIR, id, 'frames.json');
  let stat;
  try { stat = fs.statSync(manifestPath); } catch { stat = null; }
  if (!stat || !stat.isFile()) {
    return jsonResponse(res, 200, { id, exists: false, running: _figmaReferenceRunning });
  }
  let manifest = null;
  try { manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8')); } catch { manifest = null; }
  const summary = _figmaReferenceSummarize(manifest, stat.mtime.toISOString());
  return jsonResponse(res, 200, {
    id,
    exists: true,
    running: _figmaReferenceRunning,
    manifestModifiedAt: stat.mtime.toISOString(),
    ...(summary || { fetchedAt: stat.mtime.toISOString() }),
  });
}

/**
 * Core of the Figma reference fetch, used by the SSE stream below. Never throws:
 * returns { ok: true, summary } or { ok: false, error, message }.
 * @param {{file: string, nodeId: string, outId: string, scale: string, overwrite: boolean}} parsed
 * @param {{log?: function(string): void, progress?: function(number, string): void}} [hooks]
 */
async function _figmaReferenceRun(parsed, hooks) {
  const token = String(process.env.FIGMA_TOKEN || '').trim();
  const log = (text) => { const t = _figmaReferenceRedact(text, token); if (t && hooks && hooks.log) hooks.log(t); };
  const progress = (pct, msg) => { if (hooks && hooks.progress) hooks.progress(pct, msg); };
  try {
    if (IS_TEST_MODE) return { ok: false, error: 'test-mode', message: 'Fetching a Figma reference is disabled in test mode' };
    if (_figmaReferenceRunning) return { ok: false, error: 'busy', message: 'A Figma reference fetch is already running - wait for it to finish' };
    if (!token) {
      return { ok: false, error: 'no-token', message: 'The Figma token (FIGMA_TOKEN) is missing - unlock the Bitwarden vault (Settings > Keys) and try again' };
    }
    const python = await _pythonFind();
    if (!python) {
      return { ok: false, error: 'no-python', message: 'Python 3 is missing - install it (Settings > Tools shows the command) and try again' };
    }
    _figmaReferenceRunning = true;
    try {
      progress(0, 'Fetching the reference from Figma...');
      const run = await _pythonRunScript(
        python, FIGMA_REFERENCE_SCRIPT, _figmaReferenceBuildArgs(parsed),
        _figmaReferenceStdinLine(token), [0, 100], progress, log,
        { env: { USER_DATA_DIR }, timeoutMs: FIGMA_REFERENCE_TIMEOUT_MS },
      );
      if (!run.ok) {
        if (run.error === 'script-failed' && run.code === 2) {
          return { ok: false, error: 'scope-mismatch', message: 'This reference id already holds a reference of another Figma file or node - use a different id or repeat with overwrite=1' };
        }
        return { ok: false, error: run.error || 'error', message: `The Figma reference fetch failed: ${run.message}` };
      }
      let manifest = null;
      try { manifest = JSON.parse(fs.readFileSync(path.join(FIGMA_REFERENCE_DIR, parsed.outId, 'frames.json'), 'utf8')); } catch { manifest = null; }
      progress(100, 'Done');
      return { ok: true, summary: _figmaReferenceSummarize(manifest, null) };
    } finally {
      _figmaReferenceRunning = false;
    }
  } catch (e) {
    return { ok: false, error: 'error', message: `The Figma reference fetch failed: ${_figmaReferenceRedact((e && e.message) || e, token)}` };
  }
}

/**
 * GET /api/figma-reference/stream?file=<key>&node=<id>&id=<outId>[&scale=1|2][&overwrite=1]
 * Fetches a reference from Figma as an SSE stream (start / log / progress /
 * done / error). Bad parameters are a 400 JSON BEFORE the stream opens;
 * state refusals (test-mode, busy, no-token, no-python, scope-mismatch) are an
 * `error` event with an `error` field.
 */
async function handleFigmaReferenceStream(req, res) {
  if (!checkOriginNoBody(req, res)) return;
  const url = new URL(req.url, `http://${req.headers.host}`);
  const parsed = _figmaReferenceParseParams(url.searchParams);
  if (!parsed.ok) {
    return jsonResponse(res, 400, { error: 'bad-params', field: parsed.field, message: parsed.message });
  }

  sseOpen(req, res);
  const keepAlive = setInterval(() => { if (!res.writableEnded) res.write(': ping\n\n'); }, 25000);
  req.on('close', () => clearInterval(keepAlive));
  sseEvent(res, 'start', { op: 'figma-reference', id: parsed.outId, file: parsed.file, node: parsed.nodeId, scale: Number(parsed.scale) });
  try {
    const r = await _figmaReferenceRun(parsed, {
      log: (t) => { if (!res.writableEnded) sseEvent(res, 'log', { text: t }); },
      progress: (pct, msg) => { if (!res.writableEnded) sseEvent(res, 'progress', { pct, msg }); },
    });
    if (res.writableEnded) return;
    if (!r.ok) {
      sseEvent(res, 'error', { error: r.error || 'error', message: r.message });
      return;
    }
    sseEvent(res, 'done', {
      id: parsed.outId,
      message: r.summary
        ? `Figma reference fetched: ${r.summary.frames} frames in ${r.summary.sections} sections`
        : 'Figma reference fetched',
      summary: r.summary,
    });
  } finally {
    clearInterval(keepAlive);
    if (!res.writableEnded) res.end();
  }
}

// -- Prototypes: writing (Stage 2) --------------------------------------------
// Three write routes. Each: checkOrigin, withProtoLock, write to a temp
// file + rename. `format` is computed on read and NEVER enters the changes
// written to disk. `area` and `discoveryTaskId` survive every write
// intact - neither is validated here against an external source
// (mission-deck has no source of discovery tasks, see the plan note at
// DISCOVERY_TASKS_DIR).

const PROTO_NAME_MAX_LEN = 200;

// The template directory of a new screen (not to be confused with PROTO_SHELL_SEED_DIR
// below - that one builds and displays, this one is the SOURCE copied into a new entry).
// The only starter: a generic screen with demo states. Overridable
// in tests (PROTOTYPE_STARTER_DIR) - the only way for the API suite to exercise a missing
// template and a broken template without touching the real templates/prototype/starter/.
const PROTO_STARTER_DIR = process.env.PROTOTYPE_STARTER_DIR
  ? path.resolve(process.env.PROTOTYPE_STARTER_DIR)
  : path.join(ROOT, 'templates', 'prototype', 'starter');

// Tokens substituted in the starter source. The name MUST go through
// JSON.stringify - the only safe way to embed arbitrary text
// (apostrophe, quote, newline, non-ASCII characters) as a literal in TSX
// code without breaking the syntax or putting non-ASCII bytes outside the string literal.
const PROTO_STARTER_NAME_TOKEN = '{{PROTO_NAME_JSON}}';
const PROTO_STARTER_ID_TOKEN = '{{PROTO_ID}}';

/**
 * Replaces both starter template tokens and checks that no unknown token
 * `{{...}}` survived the substitution - otherwise a misnamed token in the template
 * would land in the prototype as dead text instead of reporting itself as an error.
 * @param {string} tsx
 * @param {string} name
 * @param {string} id
 * @returns {string}
 */
function _protoSubstituteStarterTokens(tsx, name, id) {
  const nameJson = JSON.stringify(name);
  let out = tsx.split(PROTO_STARTER_NAME_TOKEN).join(nameJson);
  out = out.split(PROTO_STARTER_ID_TOKEN).join(id);
  const leftover = out.match(/\{\{[A-Z0-9_]+\}\}/);
  if (leftover) throw new Error(`An unknown starter template token was left unsubstituted: ${leftover[0]}`);
  return out;
}

/**
 * Extracts { id, label, group } from the starter source's `demoStates` array - ONLY
 * to generate a true scope description in spec.json, never for runtime
 * behaviour (the build shell does that). No match or a parse error
 * gives an empty list - the spec then has a more general but still true
 * description, instead of throwing on an unexpected template shape.
 * @param {string} tsx
 * @returns {Array<{id: string, label: string, group: string}>}
 */
function _protoParseStarterDemoStates(tsx) {
  const block = /demoStates\s*:\s*DemoStateDef\[\]\s*=\s*\[([\s\S]*?)\];/.exec(tsx) || /demoStates\s*=\s*\[([\s\S]*?)\];/.exec(tsx);
  if (!block) return [];
  const out = [];
  const entryRe = /\{\s*id\s*:\s*'([^']*)'\s*,\s*label\s*:\s*'([^']*)'\s*,\s*group\s*:\s*'([^']*)'\s*\}/g;
  let m;
  while ((m = entryRe.exec(block[1])) !== null) {
    out.push({ id: m[1], label: m[2], group: m[3] });
  }
  return out;
}

/**
 * Builds a MINIMAL but true spec.json: it describes only what the starter
 * really contains (demo states read from the source, custom elements read
 * from the markers in styles.css) - it never pretends to a business readiness
 * that does not exist yet. The plan that creates the prototype is to replace it
 * once the real scope is settled.
 *
 * `customElements` MUST be an array (even empty) - scripts/check-proto-ds.js
 * blocks every React prototype whose spec.json does not have this field as an
 * array. Today's starter has no CUSTOM marker (a CSS comment) in
 * styles.css, so an empty array comes out - the true state, not a
 * guess. Should a future starter add a marker, the entry comes out without
 * `reason`/`lead_confirmed`: proto-ds-guardian confirms a custom element,
 * the backend does not invent it for anyone - the gate then correctly blocks until
 * that review.
 * @param {string} name
 * @param {string} tsx
 * @param {string} [stylesCss]
 * @returns {object}
 */
function _protoGenerateStarterSpec(name, tsx, stylesCss) {
  const templateName = 'templates/prototype/starter';
  const today = todayStr();
  const demoStates = _protoParseStarterDemoStates(tsx);
  const groups = new Map();
  for (const s of demoStates) {
    const g = s.group || 'States';
    if (!groups.has(g)) groups.set(g, []);
    groups.get(g).push(s.label || s.id);
  }
  const scope = Array.from(groups.entries()).map(([group, items]) => ({ group, items }));
  const stateList = demoStates.map((s) => s.label || s.id).join(', ');
  const css = typeof stylesCss === 'string' ? stylesCss : '';
  const customElements = [...css.matchAll(/\/\*\s*CUSTOM\s*:\s*([a-zA-Z0-9_-]+)/g)].map((m) => ({ name: m[1] }));
  return {
    updated: today,
    summary: `Starter of prototype "${name}" created automatically by POST /api/prototypes from template `
      + `${templateName}. Contains one empty screen for the prototype's content with demo states`
      + (stateList ? ` (${stateList})` : '') + ' - no business scope. Replace once the '
      + 'real scope is settled in an accepted plan.',
    scope: scope.length ? scope : [
      { group: 'Starter', items: ['Start screen without business scope - to be filled in by the plan'] },
    ],
    releases: [
      { date: today, items: [`Created from the starter template (${templateName})`] },
    ],
    customElements,
  };
}

/**
 * Copies the React starter into the new prototype's directory, ATOMICALLY: a
 * temporary directory is assembled first next to the target (same volume - `rename` is
 * atomic only within one file system), and only once ALL files are complete
 * does one rename onto the target directory happen. No
 * partial write (e.g. index.tsx without styles.css) is ever visible under the
 * final path.
 *
 * Two outcomes (NO tolerance for a missing template - templates/prototype/starter/
 * is now a fixed contract, not parallel work in progress):
 *   - { ok: true }            - starter copied, the format will be 'react'.
 *   - { ok: false, error: string } - reading index.tsx OR styles.css
 *     failed (missing file, unreadable disk), or the copy/validation
 *     failed - the caller MUST turn this into an error response (500
 *     starter-copy-failed) and NEVER create a registry entry without a working
 *     source.
 * The source goes through _protoValidateTsx (isAllowedProtoImport), so a starter with
 * the frame cannot bypass the allowlist.
 * @param {{id: string, name: string}} args
 */
function _protoStageStarter({ id, name }) {
  const starterDir = PROTO_STARTER_DIR;
  let indexTsxRaw;
  try {
    indexTsxRaw = fs.readFileSync(path.join(starterDir, 'index.tsx'), 'utf8');
  } catch (e) {
    return { ok: false, error: `Reading the starter template (index.tsx) failed: ${e.message}` };
  }
  let stylesCssRaw;
  try {
    stylesCssRaw = fs.readFileSync(path.join(starterDir, 'styles.css'), 'utf8');
  } catch (e) {
    return { ok: false, error: `Reading the starter template (styles.css) failed: ${e.message}` };
  }

  let indexTsx;
  try {
    indexTsx = _protoSubstituteStarterTokens(indexTsxRaw, name, id);
    _protoValidateTsx(indexTsx);
  } catch (e) {
    return { ok: false, error: e.message };
  }
  const spec = _protoGenerateStarterSpec(name, indexTsx, stylesCssRaw);

  const finalDir = path.join(PROTOTYPES_DIR, id);
  if (fs.existsSync(finalDir)) {
    // The id is freshly generated and checked against the registry AND the
    // directories on disk (see _protoOrphanDirIds) - this branch should
    // never fire. Should it fire anyway, we NEVER overwrite somebody else's
    // directory.
    return { ok: false, error: `The prototype directory already exists: ${id}` };
  }
  const tmpDir = path.join(PROTOTYPES_DIR, `.tmp-starter-${id}-${process.pid}-${Date.now()}`);
  try {
    fs.mkdirSync(tmpDir, { recursive: true });
    fs.writeFileSync(path.join(tmpDir, 'index.tsx'), indexTsx, 'utf8');
    fs.writeFileSync(path.join(tmpDir, 'styles.css'), stylesCssRaw, 'utf8');
    fs.writeFileSync(path.join(tmpDir, 'spec.json'), JSON.stringify(spec, null, 2) + '\n', 'utf8');
    fs.renameSync(tmpDir, finalDir);
  } catch (e) {
    try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch { /* best-effort cleanup */ }
    return { ok: false, error: `Writing the starter files failed: ${e.message}` };
  }
  return { ok: true };
}

/**
 * POST /api/prototypes { name, area?, owners?, discoveryTaskId?, description?,
 *   figmaUrls?, sourceDocs?, editors?, requester? }
 * Creates a new registry entry. The id is generated server-side
 * (proto-<hex>), never accepted from the request.
 */
async function handlePrototypeCreate(req, res) {
  if (!checkOrigin(req, res)) return;
  let bodyRaw;
  try { bodyRaw = await readBody(req, 1024 * 256); } catch { return jsonResponse(res, 400, { error: 'invalid-json' }); }
  // The body is validated as an object BEFORE any field is read - valid
  // JSON that is not an object (null, an array, a number, a string) has no
  // right to throw on `body.name` or to widen the validation to fields
  // the form does not send.
  const body = _asPlainObject(bodyRaw);
  const r = await _protoCreateEntry(body);
  return jsonResponse(res, r.code, r.body);
}

/**
 * Core of POST /api/prototypes. Returns { code, body } - never writes the
 * response itself.
 * @param {object} body
 * @returns {Promise<{code: number, body: object}>}
 */
async function _protoCreateEntry(body) {
  const name = typeof body.name === 'string' ? body.name.trim() : '';
  if (!name) return { code: 400, body: { error: 'name-required', message: 'The prototype name is required.' } };
  if (name.length > PROTO_NAME_MAX_LEN) {
    return { code: 400, body: { error: 'name-too-long', message: `The name is too long (limit ${PROTO_NAME_MAX_LEN} characters).` } };
  }
  if (body.area !== undefined && typeof body.area !== 'string') {
    return { code: 400, body: { error: 'invalid-area', message: 'The area field must be a string.' } };
  }
  if (body.owners !== undefined && (!Array.isArray(body.owners) || body.owners.some((o) => typeof o !== 'string'))) {
    return { code: 400, body: { error: 'invalid-owners', message: 'The owners field must be an array of strings.' } };
  }
  if (body.discoveryTaskId !== undefined && typeof body.discoveryTaskId !== 'string') {
    return { code: 400, body: { error: 'invalid-discovery-task-id', message: 'The discoveryTaskId field must be a string.' } };
  }
  return withProtoLock(() => {
    let data;
    try {
      data = _readPrototypesForWrite();
    } catch (e) {
      // The registry exists but is unreadable/corrupted - we refuse the write
      // instead of replacing other people's work with an empty collection. Whoever
      // looks after the data must repair the file or restore it from history.
      return { code: 409, body: { error: 'registry-unreadable', message: e.message } };
    }
    const existingIds = new Set(data.items.map((it) => it.id));
    for (const dirId of _protoOrphanDirIds()) existingIds.add(dirId);
    const id = _protoMakeId(existingIds);
    const now = new Date().toISOString();
    const item = {
      id,
      name,
      area: typeof body.area === 'string' ? body.area : '',
      owners: Array.isArray(body.owners) ? body.owners.filter((o) => typeof o === 'string') : [],
      created_at: now,
      updated_at: now,
    };
    if (typeof body.discoveryTaskId === 'string') item.discoveryTaskId = body.discoveryTaskId;

    // Starter BEFORE the registry: NO tolerance for a missing template - the
    // templates/prototype/starter/ contract is a fixed resource, not parallel
    // work in progress. Every failure (missing/unreadable index.tsx OR styles.css,
    // a disallowed import, a write error) ends the request with an error BEFORE the
    // registry is touched - there is never an entry without a working source. Entries with format:
    // 'missing' on GET concern only existing, older metadata records
    // without source files - not a new POST.
    const staged = _protoStageStarter({ id, name });
    if (!staged.ok) {
      return { code: 500, body: { error: 'starter-copy-failed', message: staged.error } };
    }

    data.items.push(item);
    try {
      _writePrototypes(data);
    } catch (e) {
      // The registry was not written, but the starter already sits on disk under the new id -
      // we clean it up so no orphaned directory without a matching
      // entry is left behind.
      try { fs.rmSync(path.join(PROTOTYPES_DIR, id), { recursive: true, force: true }); } catch { /* best-effort */ }
      return { code: 500, body: { error: 'write-failed', message: e.message } };
    }
    return {
      code: 200,
      body: {
        status: 'added',
        item: { ...item, format: _protoFormat(item.id) },
        starter: 'copied',
      },
    };
  });
}

/**
 * PUT /api/prototypes/<id> { name?, area?, owners?, discoveryTaskId?,
 *   description?, figmaUrls?, sourceDocs?, editors? }
 * Merges the changes OVER the existing entry ({ ...existing, ...changes }) - a field
 * absent from the body survives the write unchanged. No other key from the body
 * reaches the entry (allowlist), so an echo of `format` from a read never gets
 * written.
 */
async function handlePrototypeUpdate(req, res) {
  if (!checkOrigin(req, res)) return;
  const urlPath = req.url.split('?')[0];
  const id = urlPath.slice('/api/prototypes/'.length);
  if (!id || !PROTO_ID_RE.test(id)) {
    return jsonResponse(res, 400, { error: 'invalid-proto-id' });
  }
  let bodyRaw;
  try { bodyRaw = await readBody(req, 1024 * 256); } catch { return jsonResponse(res, 400, { error: 'invalid-json' }); }
  const body = _asPlainObject(bodyRaw);

  const changes = {};
  if ('name' in body) {
    const name = typeof body.name === 'string' ? body.name.trim() : '';
    if (!name) return jsonResponse(res, 400, { error: 'name-required', message: 'The prototype name is required.' });
    if (name.length > PROTO_NAME_MAX_LEN) {
      return jsonResponse(res, 400, { error: 'name-too-long', message: `The name is too long (limit ${PROTO_NAME_MAX_LEN} characters).` });
    }
    changes.name = name;
  }
  if ('area' in body) {
    if (typeof body.area !== 'string') return jsonResponse(res, 400, { error: 'invalid-area', message: 'The area field must be a string.' });
    changes.area = body.area;
  }
  if ('owners' in body) {
    if (!Array.isArray(body.owners) || body.owners.some((o) => typeof o !== 'string')) {
      return jsonResponse(res, 400, { error: 'invalid-owners', message: 'The owners field must be an array of strings.' });
    }
    changes.owners = body.owners.filter((o) => typeof o === 'string');
  }
  if ('discoveryTaskId' in body) {
    if (typeof body.discoveryTaskId !== 'string') {
      return jsonResponse(res, 400, { error: 'invalid-discovery-task-id', message: 'The discoveryTaskId field must be a string.' });
    }
    changes.discoveryTaskId = body.discoveryTaskId;
  }

  return withProtoLock(() => {
    let data;
    try {
      data = _readPrototypesForWrite();
    } catch (e) {
      return jsonResponse(res, 409, { error: 'registry-unreadable', message: e.message });
    }
    const idx = data.items.findIndex((it) => it.id === id);
    if (idx === -1) return jsonResponse(res, 404, { error: 'not-found' });
    // Merging OVER the existing entry - fields outside `changes` (e.g. area,
    // discoveryTaskId, when the form does not touch them) survive unchanged.
    const merged = { ...data.items[idx], ...changes, id, updated_at: new Date().toISOString() };
    data.items[idx] = merged;
    try {
      _writePrototypes(data);
    } catch (e) {
      return jsonResponse(res, 500, { error: 'write-failed', message: e.message });
    }
    return jsonResponse(res, 200, { status: 'updated', item: { ...merged, format: _protoFormat(merged.id) } });
  });
}

/**
 * DELETE /api/prototypes/<id>
 * Removes the entry from the registry AND the prototype directory on disk - otherwise a
 * 0.25-6.2 MB directory is orphaned (invisible in the registry, but still
 * published). The id is validated BEFORE the path is built; the directory is
 * removed only when it really exists and lies under PROTOTYPES_DIR.
 */
async function handlePrototypeDelete(req, res) {
  if (!checkOrigin(req, res)) return;
  const urlPath = req.url.split('?')[0];
  const id = urlPath.slice('/api/prototypes/'.length);
  const dir = _protoDir(id, res); // validates the id, builds the path, checks PROTOTYPES_DIR
  if (!dir) return;

  return withProtoLock(() => {
    let data;
    try {
      data = _readPrototypesForWrite();
    } catch (e) {
      return jsonResponse(res, 409, { error: 'registry-unreadable', message: e.message });
    }
    const idx = data.items.findIndex((it) => it.id === id);
    if (idx === -1) return jsonResponse(res, 404, { error: 'not-found' });
    data.items.splice(idx, 1);
    try {
      _writePrototypes(data);
    } catch (e) {
      return jsonResponse(res, 500, { error: 'write-failed', message: e.message });
    }
    // The directory is removed only AFTER the registry write is confirmed, and only when
    // it really exists as a directory (a one-off removal).
    try {
      const stat = fs.statSync(dir);
      if (stat.isDirectory()) fs.rmSync(dir, { recursive: true, force: true });
    } catch {
      // The directory no longer exists - nothing to remove.
    }
    return jsonResponse(res, 200, { status: 'deleted', id });
  });
}

// -- Prototypes: local build and publishing ------------------------------------
//
// A React prototype (index.tsx contract) does not render in the browser on its
// own: it needs a BUILD SHELL - a separate Vite + React project in which the
// prototype source loads as one lazy route. That shell is the directory
// data-sub-repositories/data-prototypes/. It has two possible origins, and that
// is the only difference between "local preview" and "publish":
//
//   * a CLONE of the git repository named by PROTO_BUILD_REPO_URL. Only a clone
//     can publish: publishing is a commit and a push to that repository, and
//     whatever hosting watches it (GitHub/GitLab Pages, Cloudflare Pages,
//     Netlify, ...) serves the result under PROTO_PAGES_BASE_URL.
//   * the SEED in templates/prototype-build-shell/ - copied when there is no
//     clone. Enough to build and run a prototype LOCALLY; it is never a git
//     repository, so nothing can be pushed from it.
//
// The shell is created LAZILY, on first use, never at server start: an
// `npm install` on every boot costs minutes on a machine that never opens a
// prototype. Publishing streams over its own SSE route
// (/api/prototypes/deploy-stream: start/log/progress/done/error).

// The build shell directory. POC_PAGES_DATA_DIR relocates it the way
// DATA_SUB_REPOS_DIR relocates the data source directories - without it a test reads
// the developer's directory instead of its own tree.
const PROTO_BUILD_DIR = process.env.POC_PAGES_DATA_DIR
  ? path.resolve(process.env.POC_PAGES_DATA_DIR)
  : path.join(SUB_REPOS_ROOT, 'data-prototypes');

// Git remote of the publishing shell. Env-only, no default: without it the
// cockpit builds prototypes locally and publishing answers `no-remote`.
function protoBuildRepoUrl() {
  return String(process.env.PROTO_BUILD_REPO_URL || '').trim();
}

// Port of the local Vite dev server. A constant, because the preview address
// (http://localhost:<port>/<slug>) goes to the browser.
const PROTO_VITE_PORT = Number(process.env.PROTO_VITE_PORT || 5173);
// Interval and number of attempts of the Vite start probe - overridable ONLY for
// tests (see tests/test_proto_build.mjs): in production always 1000ms/30
// attempts (30 seconds), because `npm install` on the first start can take that
// long. A test simulating a busy port despite --strictPort cannot wait 30
// seconds on every start.
const PROTO_VITE_PROBE_MS = Number(process.env.PROTO_VITE_PROBE_MS || 1000);
const PROTO_VITE_PROBE_ATTEMPTS = Number(process.env.PROTO_VITE_PROBE_ATTEMPTS || 30);

// Optional HTTPS token for the publishing remote, read on EVERY call and never
// memoised at start: it may come from the vault and appear mid-session, after
// an unlock (see the cockpit:secrets-changed bus). Without it git uses
// whatever credentials the machine already has (SSH key, credential helper).
function _protoDeployToken() {
  return String(process.env.PROTO_DEPLOY_TOKEN || '').trim();
}

// Username paired with the token in the one-command insteadOf rewrite. Most
// hosts accept any non-empty name with a personal access token.
function _protoDeployTokenUser() {
  const raw = String(process.env.PROTO_DEPLOY_TOKEN_USER || '').trim();
  return /^[A-Za-z0-9._-]{1,64}$/.test(raw) ? raw : 'oauth2';
}

// The shell as a git clone (the only state publishing is allowed from).
function _protoBuildCloned() {
  return fs.existsSync(path.join(PROTO_BUILD_DIR, '.git'));
}

// The shell is ready for a local build (a clone or the seed).
function _protoBuildShellReady() {
  return fs.existsSync(path.join(PROTO_BUILD_DIR, 'package.json'));
}

// Serializes EVERY write to the build shell (local preview and publish
// write the same files: src/prototype-codes.ts and src/prototypes/registry.ts).
// A separate chain from withProtoLock - that one guards prototypes.json and cannot
// wait several minutes for `npm run build`.
const withProtoBuildLock = _makeChainLock();

// ── Build shell: seed and token alignment ────────────────────────────────────

const PROTO_SHELL_SEED_DIR = path.join(ROOT, 'templates', 'prototype-build-shell');

function _protoPkgRange(pkg, name) {
  for (const field of ['dependencies', 'optionalDependencies', 'devDependencies']) {
    if (pkg[field] && pkg[field][name]) return pkg[field][name];
  }
  return null;
}

function _protoPkgDeclares(pkg, name) {
  return Boolean(_protoPkgRange(pkg, name));
}

// The app's own design tokens, copied into the shell as src/ds-tokens.css so a
// prototype renders with the same semantic token names the cockpit uses.
const PROTO_APP_TOKENS_FILE = path.join(ROOT, 'css', 'ds-tokens.css');

function _protoCopyAppTokens(buildDir = PROTO_BUILD_DIR) {
  try {
    fs.mkdirSync(path.join(buildDir, 'src'), { recursive: true });
    fs.copyFileSync(PROTO_APP_TOKENS_FILE, path.join(buildDir, 'src', 'ds-tokens.css'));
  } catch (e) {
    console.warn('[proto-shell] cannot copy design tokens into the shell:', e.message);
  }
}

/**
 * Creates the build shell when it is missing: copies the seed and the DS icons.
 * Does nothing for a clone or for a shell that already exists.
 * @returns {boolean} whether the shell is ready to use
 */
function _protoEnsureBuildShell() {
  if (_protoBuildCloned()) return true;
  if (!_protoBuildShellReady()) {
    if (!fs.existsSync(path.join(PROTO_SHELL_SEED_DIR, 'package.json'))) {
      console.warn('[proto-shell] no seed in', PROTO_SHELL_SEED_DIR);
      return false;
    }
    fs.mkdirSync(PROTO_BUILD_DIR, { recursive: true });
    console.log('[proto-shell] copying the build shell seed into', PROTO_BUILD_DIR);
    fs.cpSync(PROTO_SHELL_SEED_DIR, PROTO_BUILD_DIR, { recursive: true, force: true });
    // Icons: the shell reads them from public/ds-icons/; the source is the same
    // assets/icons/ds/ directory that /api/prototypes/ds-icon serves.
    if (fs.existsSync(PROTO_DS_ICONS_DIR)) {
      const dest = path.join(PROTO_BUILD_DIR, 'public', 'ds-icons');
      fs.mkdirSync(dest, { recursive: true });
      fs.cpSync(PROTO_DS_ICONS_DIR, dest, { recursive: true, force: true });
    }
    _protoCopyAppTokens();
  }
  return _protoBuildShellReady();
}

// ── Build shell: node_modules health ────────────────────────────────────────

// Presence probes. A bare fs.existsSync(node_modules) passes for a directory
// holding half a tree, so specific files are checked.
const PROTO_NODE_MODULES_PROBES = [
  { rel: path.join('vite', 'bin', 'vite.js') },
];

/**
 * Probe paths MISSING from <buildDir>/node_modules (empty list = healthy).
 * @param {string} buildDir
 * @returns {string[]}
 */
function _protoShellMissingDeps(buildDir) {
  const missing = [];
  for (const probe of PROTO_NODE_MODULES_PROBES) {
    if (!fs.existsSync(path.join(buildDir, 'node_modules', probe.rel))) missing.push(probe.rel);
  }
  return missing;
}

// Installs the shell dependencies only when the probe reported something. Deleting
// node_modules is NARROW: only a missing vite itself justifies it (a broken
// tree), because one package missing since the last install is fixed by
// a plain `npm install` in seconds.
// Keys npm / vite / eslint in the shell MAY inherit - an allowlist, never a
// copy of process.env. After a vault unlock process.env carries every cockpit
// token, and `ps eww <pid>` shows a child's envp to anyone on the same account.
// No npm_config_* / npm_package_* / npm_lifecycle_* key either: a server started
// by `npm start` carries `npm_config_omit=dev` (this repo's .npmrc), and every
// child npm would then silently skip devDependencies - vite included.
const PROTO_NPM_ENV_ALLOW = CHILD_ENV_BASE_KEYS;

// `source` is injected by tests; process.env by default.
function _protoNpmEnv(source) {
  return _childEnvAllowlist(source || process.env);
}

// The shell install in progress (one per process). Without it every further
// click on "Local preview" during a cold install saw a missing
// vite/bin/vite.js, deleted node_modules from under the install already running,
// and started its own `npm install` in the same directory - four installs
// at once, none of which could finish. Now every further caller
// (a preview from a second tab, a publish) waits for THE SAME result.
let _protoNodeModulesInFlight = null;
// Install state for GET /api/prototypes/local-preview-status: when it started
// and whether it began from an empty tree (then it takes minutes, not seconds).
let _protoInstallState = null;

/**
 * Guards the shell dependencies. Parallel calls share one install.
 * @returns {Promise<{ok: boolean, message?: string}>}
 */
function _protoEnsureNodeModules() {
  if (_protoNodeModulesInFlight) return _protoNodeModulesInFlight;
  const run = _protoEnsureNodeModulesOnce().finally(() => {
    if (_protoNodeModulesInFlight === run) _protoNodeModulesInFlight = null;
    _protoInstallState = null;
  });
  _protoNodeModulesInFlight = run;
  return run;
}

async function _protoEnsureNodeModulesOnce() {
  const missing = _protoShellMissingDeps(PROTO_BUILD_DIR);
  if (missing.length === 0) return { ok: true };
  console.log('[proto-shell] node_modules incomplete (missing:', missing.join(', '), ') - installing...');
  const cold = missing.some((rel) => rel.includes('vite'));
  _protoInstallState = { startedAt: Date.now(), cold, attempt: 1 };
  if (cold) {
    try { fs.rmSync(path.join(PROTO_BUILD_DIR, 'node_modules'), { recursive: true, force: true }); } catch { /* nothing to remove */ }
  }

  // One install run. Returns an error message or null.
  const runInstall = () => new Promise((resolve) => {
    // --prefer-online, not --prefer-offline: cached tarballs are still
    // useful, but the registry metadata is refreshed, which spares the
    // "notarget" error on a machine with an old cache. --include=dev says outright that
    // vite and typescript are part of the shell - together with clearing npm_config_*
    // in _protoNpmEnv().
    execFile(process.platform === 'win32' ? 'npm.cmd' : 'npm', ['install', '--prefer-online', '--include=dev'], {
      cwd: PROTO_BUILD_DIR,
      shell: process.platform === 'win32',
      env: _protoNpmEnv(),
      timeout: 600000,
      maxBuffer: 16 * 1024 * 1024,
    }, (err, _stdout, stderr) => {
      if (!err) { resolve(null); return; }
      // The execFile message alone is "Command failed" - the reason is in npm's stderr,
      // and without it the person reading the toast has nothing to look for.
      resolve(_protoTail(_redactGitStderr(String(stderr || err.message)), 6) || err.message);
    });
  });

  let failure = await runInstall();
  if (failure === null && _protoShellMissingDeps(PROTO_BUILD_DIR).length > 0) {
    // Exit code 0 is not proof enough: npm can finish with zero and
    // the private package will not be there.
    failure = `still missing after the install: ${_protoShellMissingDeps(PROTO_BUILD_DIR).join(', ')}`;
  }
  if (failure === null) return { ok: true };
  console.warn('[proto-shell] npm install failed:', failure);
  return { ok: false, message: failure };
}

// ── Build shell: libraries imported by a prototype ──────────────────────────
//
// The import allowlist (scripts/_proto-imports.js) admits a few libraries
// outside the DS. The validator lets them through, but that does not mean the shell
// has them: a shell clone from 2026-09-13 did not declare the export libraries and
// one prototype's preview failed in Vite on "Failed to resolve import
// write-excel-file/browser" (audit R-05). The export libraries are public,
// so the cockpit installs them into the shell at the versions the remote
// repository declares - the package.json entry then travels
// in the publish commit (PROTO_PUBLISH_SHELL_FILES). Bryntum is
// licensed and is NEVER installed from here: without the package in the shell
// the answer is a 503 with an explanation, not an empty grid or a 500 from the pipeline.
const PROTO_LIBRARY_PINS = Object.freeze({
  'write-excel-file': '4.1.1',
  jspdf: '4.2.1',
  html2canvas: '1.4.1',
});
const PROTO_LICENSED_LIBRARIES = Object.freeze([
  '@bryntum/scheduler', '@bryntum/scheduler-react', '@bryntum/scheduler-trial',
]);

// The package root of a specifier: 'write-excel-file/browser' ->
// 'write-excel-file', '@bryntum/scheduler/x' -> '@bryntum/scheduler'.
function _protoPackageRoot(spec) {
  const segs = String(spec || '').split('/');
  return spec.startsWith('@') ? segs.slice(0, 2).join('/') : segs[0];
}

/**
 * Non-React libraries the prototype source imports (sorted,
 * unique). A pure function.
 * @param {string} tsx
 * @returns {string[]}
 */
function _protoImportedLibraries(tsx) {
  const { protoImportSpecifiers } = require('./scripts/_proto-imports');
  const known = new Set([...Object.keys(PROTO_LIBRARY_PINS), ...PROTO_LICENSED_LIBRARIES]);
  const out = new Set();
  for (const { spec } of protoImportSpecifiers(tsx)) {
    if (spec.startsWith('.')) continue;
    const root = _protoPackageRoot(spec);
    if (known.has(root)) out.add(root);
  }
  return [...out].sort();
}

// The `resolve.alias` target from the shell's vite.config.* for `name` (or null).
// The shell clone aliases '@bryntum/scheduler' to '@bryntum/scheduler-trial'.
function _protoViteAliasTarget(buildDir, name) {
  const esc = name.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
  const re = new RegExp(`['"]${esc}['"]\\s*:\\s*['"]([^'"]+)['"]`);
  for (const file of ['vite.config.ts', 'vite.config.js']) {
    let text = '';
    try { text = fs.readFileSync(path.join(buildDir, file), 'utf8'); } catch { continue; }
    const m = re.exec(text);
    if (m) return m[1];
  }
  return null;
}

/**
 * Which of `names` the shell does NOT have: a package is available when package.json
 * declares it AND node_modules/<name>/package.json exists - only one or the
 * other means a remote build or a Vite run without the package. A package aliased in
 * vite.config.* counts when the alias target is available.
 * @param {string[]} names
 * @param {string} [buildDir]
 * @returns {string[]}
 */
function _protoMissingLibraries(names, buildDir = PROTO_BUILD_DIR) {
  let pkg = {};
  try { pkg = JSON.parse(fs.readFileSync(path.join(buildDir, 'package.json'), 'utf8')); } catch { /* no package.json - nothing is available */ }
  const present = (name) => _protoPkgDeclares(pkg, name)
    && fs.existsSync(path.join(buildDir, 'node_modules', ...name.split('/'), 'package.json'));
  return names.filter((name) => {
    if (present(name)) return false;
    const target = _protoViteAliasTarget(buildDir, name);
    return !(target && target !== name && present(target));
  });
}

// The refusal text for missing libraries - a pure function.
function _protoMissingLibrariesMessage({ licensed = [], failed = [], failure = '' }) {
  const parts = [];
  if (licensed.length) {
    parts.push(`The prototype imports ${licensed.join(', ')}, and the build shell does not have that package (missing from package.json or node_modules). `
      + 'Bryntum is a licensed library and the cockpit does not install it itself: pull a current clone of the shell '
      + '(data-sub-repositories/data-prototypes/, the publish does this in its first phase) or wait for a decision on the Bryntum license.');
  }
  if (failed.length) {
    parts.push(`The prototype needs the libraries ${failed.join(', ')}, and installing them into the build shell failed`
      + `${failure ? `: ${failure}` : ''}. Check the network connection and try again.`);
  }
  return parts.join(' ');
}

/**
 * Makes sure the shell has every library the prototype imports.
 * Missing export libraries are installed (`npm install --save-exact` at
 * pinned versions), a missing Bryntum is not. Does not take
 * withProtoBuildLock - the publish calls this from under it, the preview wraps it itself.
 * @param {string} tsx
 * @param {(line: string) => void} [log]
 * @returns {Promise<{ok: true, installed: string[]}|{ok: false, missing: string[], message: string}>}
 */
async function _protoEnsureLibraryDeps(tsx, log) {
  const say = typeof log === 'function' ? log : (line) => console.log('[proto-shell]', line);
  const missing = _protoMissingLibraries(_protoImportedLibraries(tsx));
  if (missing.length === 0) return { ok: true, installed: [] };
  const licensed = missing.filter((name) => PROTO_LICENSED_LIBRARIES.includes(name));
  const installable = missing.filter((name) => PROTO_LIBRARY_PINS[name]);
  let failure = '';
  if (installable.length) {
    // A pin ONLY for libraries package.json does not declare. A declaration
    // from the clone (e.g. after a pull) wins: `--save-exact name@pin` would overwrite
    // a newer version with an old one and the publish would ship that downgrade in its commit. When
    // everything missing is declared, a plain `npm install` is enough.
    let pkg = {};
    try { pkg = JSON.parse(fs.readFileSync(path.join(PROTO_BUILD_DIR, 'package.json'), 'utf8')); } catch { /* no package.json */ }
    const specs = installable.filter((name) => !_protoPkgDeclares(pkg, name)).map((name) => `${name}@${PROTO_LIBRARY_PINS[name]}`);
    const args = specs.length
      ? ['install', '--save-exact', '--prefer-online', '--include=dev', ...specs]
      : ['install', '--prefer-online', '--include=dev'];
    say(`Installing the prototype libraries into the shell: ${specs.length ? specs.join(', ') : installable.join(', ') + ' (versions from package.json)'}`);
    failure = await new Promise((resolve) => {
      execFile(process.platform === 'win32' ? 'npm.cmd' : 'npm', args, {
          cwd: PROTO_BUILD_DIR,
          shell: process.platform === 'win32',
          env: _protoNpmEnv(),
          timeout: 600000,
          maxBuffer: 16 * 1024 * 1024,
        }, (err, _stdout, stderr) => {
          if (!err) { resolve(''); return; }
          resolve(_protoTail(_redactGitStderr(String(stderr || err.message)), 6) || err.message);
        });
    });
  }
  const stillMissing = _protoMissingLibraries(missing);
  const failed = stillMissing.filter((name) => PROTO_LIBRARY_PINS[name]);
  if (failed.length && !failure) failure = `still missing after the install: ${failed.join(', ')}`;
  const stillLicensed = stillMissing.filter((name) => licensed.includes(name));
  if (stillMissing.length === 0) return { ok: true, installed: installable };
  console.warn('[proto-shell] missing prototype libraries:', stillMissing.join(', '), failure ? `(${failure})` : '');
  return {
    ok: false,
    missing: stillMissing,
    message: _protoMissingLibrariesMessage({ licensed: stillLicensed, failed, failure }),
  };
}

// ── Prototype sources -> shell ──────────────────────────────────────────────

// Six default widths - the same set as the built-in preview uses for a
// module that declares neither `breakpoints` nor `viewports`.
const PROTO_DEFAULT_BREAKPOINTS = [375, 768, 960, 1280, 1536, 1920];

/**
 * Reads the width declaration from the prototype source (`breakpoints` in the new
 * format, `viewports` in the old one). A pure function, no file system. Always
 * returns a sorted, non-empty list.
 * @param {string} src
 * @returns {number[]}
 */
function _protoParseBreakpoints(src) {
  const text = typeof src === 'string' ? src : '';
  const bp = text.match(/export\s+const\s+breakpoints(?:\s*:\s*[^=]+)?\s*=\s*\[([^\]]*)\]/);
  if (bp) {
    const nums = bp[1].split(',').map((s) => parseInt(s.trim(), 10)).filter((n) => Number.isFinite(n) && n > 0);
    if (nums.length) return Array.from(new Set(nums)).sort((a, b) => a - b);
  }
  const vp = text.match(/export\s+const\s+viewports\s*=\s*\[([^\]]*)\]/);
  if (vp) {
    const nums = [];
    for (const tok of vp[1].split(',')) {
      const v = tok.trim().replace(/^['"]|['"]$/g, '');
      if (v === 'mobile') nums.push(375);
      else if (v === 'desktop') nums.push(1920);
    }
    if (nums.length) return Array.from(new Set(nums)).sort((a, b) => a - b);
  }
  return PROTO_DEFAULT_BREAKPOINTS.slice();
}

/**
 * Validates a prototype's index.tsx BEFORE copying it into the shell: it must have
 * a default export, and every import must be on the allowlist. Throws on a
 * violation - the caller turns it into a phase error.
 *
 * The upstream UI package is NOT and must not be on this list. The DS layer in the team
 * data is an adapter over that package and imports it freely, but this
 * validator looks only at the PROTOTYPE source: the single allowed DS
 * surface ('../../ds') is what lets the compliance tools reason about one
 * import path instead of dozens of package exports.
 *
 * The list of allowed specifiers and their extraction from the source live in ONE
 * module, scripts/_proto-imports.js, which the DS gate requires too
 * (scripts/check-proto-ds.js, rule react-import). Two separate lists
 * drifted apart (audit R-01/R-02, 2026-09-29): the server let Bryntum through,
 * the linter blocked it, and one prototype failed here on write-excel-file.
 * A local import ('./...') is allowed ONLY for what
 * _protoStageSources really copies into the shell: styles.css, the prototype's *.json
 * files and the assets in assets/. Dynamic imports,
 * `export ... from` and imports without `from` are checked too, and comments are skipped.
 * @param {string} tsx
 */
function _protoValidateTsx(tsx) {
  if (!tsx || !tsx.includes('export default')) {
    throw new Error('index.tsx has no default export (export default)');
  }
  const bad = require('./scripts/_proto-imports').disallowedProtoImports(tsx);
  if (bad.length) throw new Error(`disallowed import in index.tsx: ${bad[0].spec}`);
}

// Atomic write (temp file + rename), creating the directory.
async function _protoWriteFile(absPath, content) {
  await fs.promises.mkdir(path.dirname(absPath), { recursive: true });
  const tmp = `${absPath}.tmp_${process.pid}_${Date.now()}`;
  await fs.promises.writeFile(tmp, content, 'utf8');
  await fs.promises.rename(tmp, absPath);
}

/**
 * Copies the shared prototype dependencies (the DS library, shared components,
 * shared CSS) from the team data into the shell's src/, so the imports '../../ds',
 * '../../components' and '../_shared/*' resolve at all. The source of truth is
 * the team data - these shell directories are overwritten on every run.
 */
async function _protoSyncSharedDeps() {
  // One list shared with the orphan quarantine - otherwise the two sides could drift apart.
  const pairs = _protoSharedSyncRoots().map((r) => ({ src: r.srcDir, dest: path.join(PROTO_BUILD_DIR, ...r.shellRel.split('/')) }));
  for (const { src, dest } of pairs) {
    if (!fs.existsSync(src)) continue;
    await fs.promises.mkdir(dest, { recursive: true });
    fs.cpSync(src, dest, { recursive: true, force: true });
  }
}

/**
 * Copies the prototype's assets/ to public/proto-assets/<slug>/ plus every DS icon
 * the source refers to through 'ds-icon/<slug>'.
 * @param {{id: string, slug: string, codeText: string}} args
 */
async function _protoCopyAssets({ id, slug, codeText }) {
  const srcAssetsDir = path.join(PROTOTYPES_DIR, id, 'assets');
  const destAssetsDir = path.join(PROTO_BUILD_DIR, 'public', 'proto-assets', slug);
  await fs.promises.mkdir(destAssetsDir, { recursive: true });
  try {
    for (const f of await fs.promises.readdir(srcAssetsDir)) {
      const from = path.join(srcAssetsDir, f);
      if (!(await fs.promises.stat(from)).isFile()) continue;
      await fs.promises.copyFile(from, path.join(destAssetsDir, f));
    }
  } catch { /* a prototype without assets/ - a normal state */ }

  const iconSlugs = new Set();
  const iconRe = /ds-icon\/([a-z0-9-]+)/g;
  let m;
  while ((m = iconRe.exec(codeText)) !== null) iconSlugs.add(m[1]);
  if (iconSlugs.size === 0) return;
  const slugMap = _protoDsIconMap();
  const destIconsDir = path.join(destAssetsDir, 'icons');
  await fs.promises.mkdir(destIconsDir, { recursive: true });
  for (const iconSlug of iconSlugs) {
    const fileName = slugMap[iconSlug];
    if (!fileName) continue;
    try {
      await fs.promises.copyFile(path.join(PROTO_DS_ICONS_DIR, fileName), path.join(destIconsDir, `${iconSlug}.svg`));
    } catch { /* missing icon file - skipped, not a critical error */ }
  }
}

/**
 * Builds the content of src/prototype-codes.ts from a code -> slug map. A pure function,
 * exported for tests: the only place that knows the format of this file.
 * @param {Object<string,string>} entries
 * @returns {string}
 */
function _protoCodesFileContent(entries) {
  const body = Object.keys(entries).sort().map((k) => `  '${k}': '${entries[k]}',`).join('\n');
  return [
    '// Map of test code -> prototype slug for the form on the start page.',
    '//',
    '// This map ships in the client bundle and is readable by anyone. It is NOT',
    '// an access control mechanism - the real gate is on the hosting side.',
    '//',
    '// GENERATED FILE by the cockpit (publish and local prototype preview).',
    'export const PROTOTYPE_CODES: Record<string, string> = {',
    body,
    '}',
    '',
  ].join('\n');
}

// Parses an existing prototype-codes.ts into a code -> slug map. A pure function.
function _protoParseCodes(text) {
  const entries = {};
  const lineRe = /^\s*'(\d+)':\s*'([a-z0-9-]+)',?\s*$/gm;
  let m;
  while ((m = lineRe.exec(String(text || ''))) !== null) entries[m[1]] = m[2];
  return entries;
}

/**
 * Inserts (or updates) a code -> slug entry in src/prototype-codes.ts. The file
 * is generated WHOLE EVERY TIME from the parsed map, never
 * appended as text - so it stays valid TypeScript even after a
 * manual edit.
 */
async function _protoUpsertCode({ code, slug }) {
  const codesPath = path.join(PROTO_BUILD_DIR, 'src', 'prototype-codes.ts');
  let existing = '';
  try { existing = await fs.promises.readFile(codesPath, 'utf8'); } catch { /* first write */ }
  const entries = _protoParseCodes(existing);
  for (const [k, v] of Object.entries(entries)) {
    if (v === slug || k === code) delete entries[k];
  }
  entries[code] = slug;
  await _protoWriteFile(codesPath, _protoCodesFileContent(entries));
}

// The code assigned to a slug in the shell (or null).
async function _protoCodeForSlug(slug) {
  const codesPath = path.join(PROTO_BUILD_DIR, 'src', 'prototype-codes.ts');
  try {
    const entries = _protoParseCodes(await fs.promises.readFile(codesPath, 'utf8'));
    for (const [code, s] of Object.entries(entries)) if (s === slug) return code;
  } catch { /* no file */ }
  return null;
}

// The canonical code from the registry (prototypes.json) - wins over whatever the
// local shell happens to have, so the invitation code is the same on every machine.
function _protoCanonicalCode(data, id) {
  const item = data.items.find((it) => it.id === id);
  return (item && item.invitationCode) || null;
}

// A deterministic fallback code from the slug - when nobody has assigned one yet.
function _protoPlaceholderCode(slug) {
  let hash = 0;
  for (let i = 0; i < slug.length; i++) hash = ((hash << 5) - hash + slug.charCodeAt(i)) | 0;
  return String(Math.abs(hash) % 1000000).padStart(6, '0');
}

async function _protoPersistCanonicalCode(id, code) {
  return withProtoLock(() => {
    let data;
    try {
      data = _readPrototypesForWrite();
    } catch (e) {
      // Registry unreadable: this write is opportunistic (the code works even
      // without being persisted), so it logs and gives up instead of replacing it with an empty
      // collection - the same standard as the POST/PUT/DELETE routes.
      console.warn('[prototypes] invitation code write skipped - registry unreadable:', e.message);
      return;
    }
    const item = data.items.find((it) => it.id === id);
    if (!item || item.invitationCode === code) return;
    item.invitationCode = code;
    try { _writePrototypes(data); } catch (e) { console.warn('[prototypes] writing the invitation code failed:', e.message); }
  });
}

/**
 * Builds the content of src/prototypes/registry.ts from a list of {slug, breakpoints}. A pure
 * function, exported for tests.
 * @param {Array<{slug: string, breakpoints: number[]}>} entries
 * @returns {string}
 */
function _protoRegistryFileContent(entries) {
  const lines = entries.map((e) => `  ${JSON.stringify(e.slug)}: { load: () => import('./${e.slug}/index'), breakpoints: [${e.breakpoints.join(', ')}] },`);
  return [
    '// GENERATED FILE by the cockpit (publish and local prototype preview).',
    '// Do not edit by hand - it is produced deterministically from src/prototypes/*/index.tsx.',
    // A named type import: the shell's tsconfig has no esModuleInterop, so
    // the default "import type React from 'react'" would not pass tsc -b.
    "import type { ComponentType } from 'react'",
    '',
    'export interface PrototypeEntry {',
    '  load: () => Promise<{ default: ComponentType }>',
    '  breakpoints: number[]',
    '}',
    '',
    'export const PROTOTYPE_COMPONENTS: Record<string, PrototypeEntry> = {',
    ...lines,
    '}',
    '',
  ].join('\n');
}

// Regenerates registry.ts from the state of the src/prototypes/ directory (every subdirectory with
// index.tsx, except _shared).
async function _protoRegenerateRegistry() {
  const prototypesDir = path.join(PROTO_BUILD_DIR, 'src', 'prototypes');
  let dirents = [];
  try { dirents = await fs.promises.readdir(prototypesDir, { withFileTypes: true }); } catch { /* no directory */ }
  const slugs = [];
  for (const e of dirents) {
    if (!e.isDirectory() || e.name === '_shared') continue;
    try {
      await fs.promises.access(path.join(prototypesDir, e.name, 'index.tsx'), fs.constants.F_OK);
      slugs.push(e.name);
    } catch { /* a directory without index.tsx */ }
  }
  slugs.sort();
  const entries = [];
  for (const slug of slugs) {
    let breakpoints = PROTO_DEFAULT_BREAKPOINTS.slice();
    try {
      const meta = JSON.parse(await fs.promises.readFile(path.join(prototypesDir, slug, 'meta.json'), 'utf8'));
      if (Array.isArray(meta.breakpoints) && meta.breakpoints.length) breakpoints = meta.breakpoints;
    } catch { /* no meta.json - the default set */ }
    entries.push({ slug, breakpoints });
  }
  await _protoWriteFile(path.join(prototypesDir, 'registry.ts'), _protoRegistryFileContent(entries));
}

/**
 * Writes one prototype's sources into the shell: index.tsx, styles.css,
 * meta.json, .json data files, assets, the code entry and the route registry. Called by
 * the local preview and by the publish - ONE place, so the two paths cannot
 * drift apart. Assumes the source is already loaded and validated.
 * @param {{id: string, slug: string, indexTsx: string, stylesCss: string, code: string}} args
 * @returns {Promise<{breakpoints: number[]}>}
 */
async function _protoStageSources({ id, slug, indexTsx, stylesCss, code }) {
  const protoDir = path.join(PROTOTYPES_DIR, id);
  const targetDir = path.join(PROTO_BUILD_DIR, 'src', 'prototypes', slug);
  await _protoWriteFile(path.join(targetDir, 'index.tsx'), indexTsx);
  await _protoWriteFile(path.join(targetDir, 'styles.css'), stylesCss);
  const breakpoints = _protoParseBreakpoints(indexTsx);
  await _protoWriteFile(path.join(targetDir, 'meta.json'), JSON.stringify({ breakpoints }, null, 2) + '\n');

  // The prototype's data files (stores.json, indicators.json, ...) - without spec.json
  // and compliance.json, which describe the prototype rather than being its data.
  try {
    const files = await fs.promises.readdir(protoDir);
    for (const f of files) {
      if (!f.endsWith('.json') || f === 'spec.json' || f === 'compliance.json') continue;
      await _protoWriteFile(path.join(targetDir, f), await fs.promises.readFile(path.join(protoDir, f), 'utf8'));
    }
  } catch { /* data files are optional */ }

  await _protoCopyAssets({ id, slug, codeText: indexTsx });
  await _protoUpsertCode({ code, slug });
  await _protoRegenerateRegistry();
  return { breakpoints };
}

// ── Local Vite dev server ───────────────────────────────────────────────────

// An address probe with a short time limit: true on any HTTP answer.
function _protoProbeUrl(urlStr, timeoutMs) {
  return new Promise((resolve) => {
    const u = new URL(urlStr);
    const req = http.request({ hostname: u.hostname, port: u.port, path: u.pathname, method: 'GET', timeout: timeoutMs }, (res) => {
      res.resume();
      resolve(true);
    });
    req.on('timeout', () => { req.destroy(); resolve(false); });
    req.on('error', () => resolve(false));
    req.end();
  });
}

// The Vite server child process. Kept so a second one is not started on the same
// port. Detached and unref()'d, so it survives a cockpit restart.
let _protoViteChild = null;
// The stderr tail of the current Vite child - the only trace when an attempt ends
// in a timeout (e.g. a busy port despite --strictPort, or a config error), so
// the answer has something to show besides "did not answer". stderr goes
// to a FILE (PROTO_VITE_STDERR_LOG), not a pipe: the pipe ends together with
// the cockpit process, and a Vite that survived a restart got EPIPE on its first write to
// stderr (a warning, a transform error) and exited - an open
// prototype preview lost its server mid-work (2026-10-07).
const PROTO_VITE_STDERR_MAX = 4000;

/**
 * Makes sure a Vite dev server started in the shell directory stands on
 * PROTO_VITE_PORT. A server already standing (our own or started by hand) is
 * reused.
 * @returns {Promise<boolean>}
 */
/**
 * Path of the current dev server's marker. Vite keeps the configuration
 * and project directory from the moment of START, so a process that came up for the seed
 * keeps serving it after a publish swapped the shell for the remote clone - and
 * does so with code 200, so an HTTP probe alone will never detect it.
 */
const PROTO_VITE_MARKER = process.env.PROTOTYPE_VITE_MARKER_PATH
  ? path.resolve(process.env.PROTOTYPE_VITE_MARKER_PATH)
  : path.join(ROOT, 'data', 'proto-vite.json');

const PROTO_VITE_STDERR_LOG = path.join(path.dirname(PROTO_VITE_MARKER), 'proto-vite-stderr.log');

function _protoViteStderrTail() {
  try {
    const buf = fs.readFileSync(PROTO_VITE_STDERR_LOG);
    return buf.subarray(Math.max(0, buf.length - PROTO_VITE_STDERR_MAX)).toString('utf8');
  } catch { return ''; }
}

function _protoViteMarker() {
  try { return JSON.parse(fs.readFileSync(PROTO_VITE_MARKER, 'utf8')); } catch { return null; }
}

// `startedAt` (ms since the epoch) says since when the server reads the shell configuration -
// see _protoViteIsStale. Tmp+rename: half a marker read in the middle of a
// write would look like a "foreign process" and block the preview.
function _protoWriteViteMarker(pid, startedAt = Date.now()) {
  try {
    fs.mkdirSync(path.dirname(PROTO_VITE_MARKER), { recursive: true });
    const tmp = `${PROTO_VITE_MARKER}.tmp_${process.pid}`;
    fs.writeFileSync(tmp, JSON.stringify({ dir: PROTO_BUILD_DIR, port: PROTO_VITE_PORT, pid, startedAt }, null, 2));
    fs.renameSync(tmp, PROTO_VITE_MARKER);
  } catch { /* the marker is a hint, not a precondition */ }
}

// Shell files a running Vite reads ONCE, at start.
// node_modules/.package-lock.json stands in for "the dependency tree changed"
// (npm rewrites it on every install). This bites harder here than in the
// original tool: _protoAlignShellToToken after a vault unlock mid-session rewrites
// package.json and deletes the lockfile, and installing the prototype libraries
// (_protoEnsureLibraryDeps) changes the tree - a Vite started earlier
// served the old configuration with code 200 (audit R-07).
const PROTO_VITE_CONFIG_FILES = Object.freeze([
  'postcss.config.js',
  'package.json',
  'vite.config.ts',
  'vite.config.js',
  'node_modules/.package-lock.json',
]);

/**
 * The newest mtime (ms) among PROTO_VITE_CONFIG_FILES in `buildDir`; 0 when
 * none exists. A missing file is not a staleness signal.
 * @param {string} [buildDir]
 * @returns {number}
 */
function _protoViteConfigNewestMtime(buildDir = PROTO_BUILD_DIR) {
  let newest = 0;
  for (const rel of PROTO_VITE_CONFIG_FILES) {
    try {
      const st = fs.statSync(path.join(buildDir, ...rel.split('/')));
      if (st.mtimeMs > newest) newest = st.mtimeMs;
    } catch { /* no file */ }
  }
  return newest;
}

/**
 * Whether the server described by the marker reads a configuration older than the one on disk.
 * Pure with respect to the marker and the newest mtime. A marker without
 * `startedAt` (written before this change) is NOT stale - the caller
 * adopts it, because restarting a process on the basis of nothing would be worse.
 * @param {{startedAt?: number}|null} marker
 * @param {number} newestMtime
 * @returns {boolean}
 */
function _protoViteIsStale(marker, newestMtime) {
  const startedAt = Number(marker && marker.startedAt);
  if (!Number.isFinite(startedAt) || startedAt <= 0) return false;
  return newestMtime > 0 && newestMtime > startedAt;
}

/**
 * Stops the dev server described by the marker. Always by a specific PID
 * (a process group, because npm run dev is a shell over vite) - never by name.
 * @param {number} pid
 * @returns {Promise<void>}
 */
async function _protoStopVite(pid) {
  if (!pid) return;
  if (process.platform === 'win32') {
    _toolKill({ pid });
  } else {
    for (const target of [-pid, pid]) {
      try { process.kill(target, 'SIGTERM'); break; } catch { /* the group may not exist */ }
    }
  }
  for (let i = 0; i < 10; i++) {
    await new Promise((r) => setTimeout(r, 300));
    if (!(await _protoProbeUrl(`http://localhost:${PROTO_VITE_PORT}/`, 500))) return;
  }
}

async function _protoEnsureViteRunning() {
  const viteUrl = `http://localhost:${PROTO_VITE_PORT}/`;
  if (await _protoProbeUrl(viteUrl, 1000)) {
    const marker = _protoViteMarker();
    const sameDir = Boolean(marker && marker.dir === PROTO_BUILD_DIR);
    const stale = sameDir && _protoViteIsStale(marker, _protoViteConfigNewestMtime());
    if (sameDir && !stale) {
      // A marker from before the startedAt field: we adopt the server from now on and detect
      // only changes made from this moment.
      if (marker.pid && !(Number(marker.startedAt) > 0)) _protoWriteViteMarker(marker.pid);
      return { ok: true };
    }
    // The port is taken by a process serving ANOTHER directory (or by something
    // we did not start). We stop our own, we leave somebody else's alone.
    if (!marker || !marker.pid) {
      console.warn('[proto-vite] port', PROTO_VITE_PORT, 'taken by a foreign process - not touching it');
      return { ok: false, message: `Port ${PROTO_VITE_PORT} is held by a process the cockpit did not start `
        + '- stop it and try again.' };
    }
    if (stale) {
      console.warn('[proto-vite] the shell configuration changed after the dev server started (pid', marker.pid, ') - restarting our own process');
    } else {
      console.log('[proto-vite] the dev server stands for', marker.dir, '- restarting for', PROTO_BUILD_DIR);
    }
    await _protoStopVite(marker.pid);
    if (_protoViteChild) _protoViteChild = null;
    if (await _protoProbeUrl(viteUrl, 1000)) {
      return { ok: false, message: `Could not stop the Vite server on port ${PROTO_VITE_PORT}` };
    }
  }

  // A child that already died (e.g. broken node_modules) must not block
  // the next attempt for the rest of the server process's life.
  if (_protoViteChild && _protoViteChild.exitCode !== null) _protoViteChild = null;

  if (!_protoViteChild) {
    let stderrFd = 'ignore';
    try {
      fs.mkdirSync(path.dirname(PROTO_VITE_STDERR_LOG), { recursive: true });
      stderrFd = fs.openSync(PROTO_VITE_STDERR_LOG, 'w');
    } catch (err) {
      console.warn('[proto-vite] no stderr file, starting without it:', err.message);
    }
    const child = spawn(process.platform === 'win32' ? 'npm.cmd' : 'npm',
      // `--` separates npm arguments from the arguments passed to vite: WITHOUT
      // them `npm run dev` starts Vite on its default port (5173,
      // or the first free one above, e.g. 5174), completely ignoring
      // PROTO_VITE_PORT - the probe below would then keep polling the right,
      // configured port on which nothing will ever stand. `--strictPort`
      // turns that into a fast, readable error (Vite exits at once) when
      // the port is taken, instead of silently picking another. `--host localhost`
      // keeps the binding consistent with the address _protoProbeUrl probes.
      ['run', 'dev', '--', '--port', String(PROTO_VITE_PORT), '--strictPort', '--host', 'localhost'],
      {
        cwd: PROTO_BUILD_DIR,
        stdio: ['ignore', 'ignore', stderrFd],
        // A process group only on posix (there _protoStopVite kills `-pid`);
        // on Windows `taskkill /T` stops the tree, and `detached` would take
        // the hidden console from windowsHide away from the shell and every `npm run dev` child
        // would open its own window.
        detached: process.platform !== 'win32',
        shell: process.platform === 'win32',
        env: _protoNpmEnv(),
      });
    // The child has its own copy of the descriptor; we close ours so it does not leak.
    if (typeof stderrFd === 'number') { try { fs.closeSync(stderrFd); } catch { /* already closed */ } }
    child.on('error', (err) => {
      console.warn('[proto-vite] could not start:', err.message);
      if (_protoViteChild === child) _protoViteChild = null;
    });
    child.on('exit', (code) => {
      if (code !== 0) console.warn('[proto-vite] the dev server exited with code', code);
      if (_protoViteChild === child) _protoViteChild = null;
    });
    child.unref();
    _protoViteChild = child;
    _protoWriteViteMarker(child.pid);
  }

  // A LOCAL reference, not `_protoViteChild`: the 'exit' handler clears
  // `_protoViteChild` immediately, so detecting "the child already died while
  // waiting" needs a variable of its own that survives that
  // clearing.
  const activeChild = _protoViteChild;

  for (let i = 0; i < PROTO_VITE_PROBE_ATTEMPTS; i++) {
    await new Promise((r) => setTimeout(r, PROTO_VITE_PROBE_MS));
    if (await _protoProbeUrl(viteUrl, 1000)) return { ok: true };
    // The child already died while waiting (e.g. --strictPort refused,
    // the port really is taken) - further probing would only waste time until
    // the end of 30 seconds on a process that no longer exists.
    if (activeChild && activeChild.exitCode !== null) break;
  }

  // Timeout OR an earlier child exit: a process that did not become
  // healthy must not be detached and abandoned - it would hold the port/resources
  // forever, and the next attempt would again wait 30 seconds on the same child.
  const stderrTail = _protoTail(_protoViteStderrTail(), 10).trim();
  if (_protoViteChild === activeChild) _protoViteChild = null;
  if (activeChild && activeChild.exitCode === null) await _protoStopVite(activeChild.pid);
  try { fs.rmSync(PROTO_VITE_MARKER, { force: true }); } catch { /* the marker is a hint */ }
  return {
    ok: false,
    message: stderrTail
      ? `The Vite server did not answer in time on port ${PROTO_VITE_PORT}. Last lines: ${stderrTail}`
      : `The Vite server did not answer in time on port ${PROTO_VITE_PORT}.`,
  };
}

// A ready bundle dropped into public/<slug>/ (a build output from another repository)
// wins over the src/prototypes/<slug> source: it is what the published version
// serves. Vite serves only FILES from public/, never a directory
// index, so the preview address is then index.html itself.
function _protoPrebuiltBundleIndex(slug) {
  try {
    return fs.statSync(path.join(PROTO_BUILD_DIR, 'public', slug, 'index.html')).isFile();
  } catch { return false; }
}

// ── Routes: status, local preview, publish ──────────────────────────────────

// GET /api/prototypes/deploy-status
// One answer for three buttons in the prototype details view:
//   * baseUrl  - address of the published version ("Run prototype"),
//   * canBuild - whether a local build is possible (always, as long as the seed exists),
//   * enabled  - whether publishing is configured (PROTO_BUILD_REPO_URL set;
//                the clone is made in the first publishing phase).
function handlePrototypeDeployStatus(_req, res) {
  const hasToken = Boolean(_protoDeployToken());
  return jsonResponse(res, 200, {
    enabled: Boolean(protoBuildRepoUrl()),
    hasToken,
    cloned: _protoBuildCloned(),
    canBuild: _protoBuildShellReady() || fs.existsSync(path.join(PROTO_SHELL_SEED_DIR, 'package.json')),
    baseUrl: protoPagesBaseUrl(),
  });
}

// The common preamble of preview and publish: id, registry, sources,
// validation. Returns { error: {code, message} } or { item, slug, indexTsx,
// stylesCss }. Does not touch the shell disk - only the callers do.
async function _protoLoadSourcesFor(id) {
  if (!id || !/^proto-[a-z0-9-]{1,64}$/.test(id)) {
    return { error: { code: 400, message: 'Invalid prototype id' } };
  }
  const item = _readPrototypes().items.find((it) => it.id === id);
  if (!item) return { error: { code: 404, message: `Unknown prototype: ${id}` } };

  const protoDir = path.join(PROTOTYPES_DIR, id);
  let indexTsx;
  try {
    indexTsx = await fs.promises.readFile(path.join(protoDir, 'index.tsx'), 'utf8');
  } catch {
    return { error: { code: 400, message: `Prototype ${id} has no index.tsx file - building supports React prototypes only` } };
  }
  let stylesCss = '';
  try { stylesCss = await fs.promises.readFile(path.join(protoDir, 'styles.css'), 'utf8'); } catch { /* opcjonalny */ }
  try {
    _protoValidateTsx(indexTsx);
  } catch (e) {
    return { error: { code: 400, message: `Validating index.tsx failed: ${e.message}` } };
  }
  return { item, slug: id.replace(/^proto-/, ''), indexTsx, stylesCss };
}

// POST /api/prototypes/local-preview/<id>
// Copies the prototype sources into the build shell and makes sure a local
// Vite server stands. Answers with the address the browser opens in a new tab.
async function handlePrototypeLocalPreview(req, res) {
  if (!checkOriginNoBody(req, res)) return;
  const id = decodeURIComponent(req.url.split('?')[0].slice('/api/prototypes/local-preview/'.length));
  if (IS_TEST_MODE) {
    return jsonResponse(res, 503, { status: 'error', message: 'Local preview is disabled in test mode' });
  }
  if (!id || !/^proto-[a-z0-9-]{1,64}$/.test(id)) {
    return jsonResponse(res, 400, { status: 'error', message: 'Invalid prototype id' });
  }
  // A second tab with the same id joins the running pass in the status;
  // the `runs` counter keeps the entry until the last of them finishes.
  const prev = _protoPreviewRuns.get(id);
  if (prev) prev.runs += 1;
  else _protoPreviewRuns.set(id, { startedAt: Date.now(), phase: 'prepare', phaseStartedAt: Date.now(), runs: 1 });
  try {
    return await _protoLocalPreviewRun(res, id);
  } finally {
    const run = _protoPreviewRuns.get(id);
    if (run && --run.runs <= 0) _protoPreviewRuns.delete(id);
  }
}

// Local preview passes in progress, by prototype id: the phase and since when.
// Read by GET /api/prototypes/local-preview-status, from which the progress modal
// says what is happening and why it takes time.
const _protoPreviewRuns = new Map();

/** @param {string} id @param {'prepare'|'install'|'libs'|'vite'} phase */
function _protoPreviewPhase(id, phase) {
  const run = _protoPreviewRuns.get(id);
  if (run && run.phase !== phase) { run.phase = phase; run.phaseStartedAt = Date.now(); }
}

async function _protoLocalPreviewRun(res, id) {
  if (!_protoEnsureBuildShell()) {
    return jsonResponse(res, 503, { status: 'error', message: 'The prototype build environment is not ready - the seed is missing in templates/prototype-build-shell/' });
  }
  const slug = id.replace(/^proto-/, '');

  // A ready bundle wins: it is self-contained (its own build output, without
  // DS adapters), so neither the index.tsx requirement nor the token gate applies to it.
  if (_protoPrebuiltBundleIndex(slug)) {
    _protoPreviewPhase(id, 'install');
    const heal = await _protoEnsureNodeModules();
    if (!heal.ok) return jsonResponse(res, 500, { status: 'error', message: `npm install failed: ${heal.message}` });
    _protoPreviewPhase(id, 'vite');
    const vitePrebuilt = await _protoEnsureViteRunning();
    if (!vitePrebuilt.ok) return jsonResponse(res, 503, { status: 'error', message: vitePrebuilt.message });
    return jsonResponse(res, 200, { url: `http://localhost:${PROTO_VITE_PORT}/${slug}/index.html`, prebuilt: true });
  }

  const src = await _protoLoadSourcesFor(id);
  if (src.error) return jsonResponse(res, src.error.code, { status: 'error', message: src.error.message });

  const writeErr = await withProtoBuildLock(async () => {
    try {
      await _protoSyncSharedDeps();
    } catch (e) {
      return { code: 500, message: `Syncing the shared dependencies failed: ${e.message}` };
    }
    try {
      const code = _protoCanonicalCode(_readPrototypes(), id)
        || await _protoCodeForSlug(slug)
        || _protoPlaceholderCode(slug);
      await _protoStageSources({ id, slug, indexTsx: src.indexTsx, stylesCss: src.stylesCss, code });
    } catch (e) {
      return { code: 500, message: `Writing the shell files failed: ${e.message}` };
    }
    return null;
  });
  if (writeErr) return jsonResponse(res, writeErr.code, { status: 'error', message: writeErr.message });

  _protoPreviewPhase(id, 'install');
  const heal = await _protoEnsureNodeModules();
  if (!heal.ok) return jsonResponse(res, 500, { status: 'error', message: `npm install failed: ${heal.message}` });

  _protoPreviewPhase(id, 'libs');
  // Non-DS libraries the prototype imports (audit R-05): missing
  // export libraries are installed, a missing Bryntum is a 503 with an
  // explanation - never "Failed to resolve import" in the browser.
  const libs = await withProtoBuildLock(() => _protoEnsureLibraryDeps(src.indexTsx));
  if (!libs.ok) return jsonResponse(res, 503, { status: 'error', error: 'deps-missing', missing: libs.missing, message: libs.message });

  _protoPreviewPhase(id, 'vite');
  const vite = await _protoEnsureViteRunning();
  if (!vite.ok) return jsonResponse(res, 503, { status: 'error', message: vite.message });
  return jsonResponse(res, 200, { url: `http://localhost:${PROTO_VITE_PORT}/${slug}` });
}

// GET /api/prototypes/local-preview-status[?id=proto-...]
// A read for the local preview progress modal: the phase of this id's pass and
// the state of the shared shell dependency install (cold or top-up, since
// when, how many packages already sit in node_modules). Starts nothing, always 200
// for a valid request - no pass is `active: false`.
function handlePrototypeLocalPreviewStatus(req, res) {
  const id = new URL(req.url, 'http://localhost').searchParams.get('id') || '';
  if (id && !/^proto-[a-z0-9-]{1,64}$/.test(id)) {
    return jsonResponse(res, 400, { status: 'error', message: 'Invalid prototype id' });
  }
  const run = id ? _protoPreviewRuns.get(id) : null;
  let install = null;
  if (_protoInstallState) {
    let packages = 0;
    try {
      for (const name of fs.readdirSync(path.join(PROTO_BUILD_DIR, 'node_modules'))) {
        if (name.startsWith('.')) continue;
        if (name.startsWith('@')) {
          try { packages += fs.readdirSync(path.join(PROTO_BUILD_DIR, 'node_modules', name)).length; } catch { /* znika w trakcie */ }
        } else packages += 1;
      }
    } catch { /* node_modules does not exist yet */ }
    install = { ..._protoInstallState, packages };
  }
  return jsonResponse(res, 200, {
    active: Boolean(run),
    phase: run ? run.phase : null,
    startedAt: run ? run.startedAt : null,
    phaseStartedAt: run ? run.phaseStartedAt : null,
    install,
    now: Date.now(),
  });
}

// Runs a command in the shell directory. Always with an explicit cwd, never the
// default. Resolves with the exit code instead of throwing - a non-zero build code
// is a PHASE error, not an exception.
function _protoSpawn(cmd, args, opts) {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, args, { ...opts, shell: process.platform === 'win32' });
    let stdout = ''; let stderr = '';
    child.stdout.on('data', (d) => { stdout += d.toString('utf8'); });
    child.stderr.on('data', (d) => { stderr += d.toString('utf8'); });
    child.on('close', (code) => resolve({ code, stdout, stderr }));
    child.on('error', reject);
  });
}

function _protoTail(text, n = 20) {
  return _redactGitStderr(String(text || '').split('\n').slice(-n).join('\n'));
}

// The environment for `npm run lint|build` in the shell: the path to its own binaries
// and the encoded token for the private feed.
function _protoBuildEnv() {
  return {
    ..._protoNpmEnv(),
    PATH: path.join(PROTO_BUILD_DIR, 'node_modules', '.bin') + path.delimiter + process.env.PATH,
    NODE_ENV: 'development',
  };
}

// An address without the userinfo part (`https://pat:TOKEN@host/...` -> `https://host/...`).
// A pure function: what may be stored in the shell's `remote.origin.url`, and the
// `insteadOf` key under which the token is attached. An address without userinfo comes back
// unchanged; an address that is not https does too.
function _protoStripUrlCredentials(url) {
  const s = String(url || '').trim();
  return s.replace(/^(https?:\/\/)[^/@]+@/i, '$1');
}

// Git in the shell directory.
//
// The token is NEVER part of a stored address. Every remote operation, clone
// included, gets it through `-c url.<with token>.insteadOf=<without token>` for
// one command. A clone whose `remote.origin.url` still carries credentials is
// repaired on the first remote operation (`remote set-url` to the bare address).
//
// `opts` (optional): { cwd, remoteUrl } points the same command at ANOTHER
// working directory and remote address, with the same token injection.
function _protoGitExec(args, timeoutMs, opts) {
  const token = _protoDeployToken();
  const isRemote = ['fetch', 'push', 'pull', 'ls-remote', 'clone'].includes(args[0]);
  const cwd = (opts && opts.cwd) || PROTO_BUILD_DIR;
  const extUrl = (opts && opts.remoteUrl) || null;
  const gitArgs = args[0] === 'clone' ? [] : ['-C', cwd];
  // Always strips first: an address like `https://org@host/...` carries its
  // own userinfo, and `user:TOKEN@org@...` would be a malformed address git
  // refuses - the stored remote is stripped the same way below.
  const withAuth = (url) => {
    const cleanUrl = _protoStripUrlCredentials(url);
    if (!token || !/^https:\/\//.test(cleanUrl)) return;
    const authUrl = cleanUrl.replace(/^https:\/\//, `https://${_protoDeployTokenUser()}:${encodeURIComponent(token)}@`);
    gitArgs.push('-c', `url.${authUrl}.insteadOf=${cleanUrl}`);
  };
  if (extUrl) {
    withAuth(extUrl);
  } else if (args[0] === 'clone') {
    withAuth(protoBuildRepoUrl());
  } else if (isRemote) {
    const remote = spawnSync('git', ['-C', PROTO_BUILD_DIR, 'remote', 'get-url', 'origin'], { encoding: 'utf8', timeout: 5000 });
    const storedUrl = String(remote.stdout || '').trim();
    const remoteUrl = _protoStripUrlCredentials(storedUrl);
    if (remote.status === 0 && storedUrl !== remoteUrl) {
      spawnSync('git', ['-C', PROTO_BUILD_DIR, 'remote', 'set-url', 'origin', remoteUrl], { encoding: 'utf8', timeout: 5000 });
      console.warn('[proto-deploy] the shell remote.origin.url contained credentials - stored the address without them');
    }
    if (remote.status === 0) withAuth(remoteUrl);
  }
  gitArgs.push(...args);
  return new Promise((resolve) => {
    execFile('git', gitArgs, {
      timeout: timeoutMs || (isRemote ? 300000 : 30000),
      maxBuffer: 16 * 1024 * 1024,
      env: _gitNoPromptEnv(),
    }, (err, stdout, stderr) => {
      resolve({ stdout: stdout || '', stderr: stderr || '', code: err ? (err.code || 1) : 0, killed: !!(err && err.killed) });
    });
  });
}

// Clones the publishing shell repository. Called only from publishing - the
// local preview works from the seed and never needs the network.
async function _protoCloneBuildRepo(log) {
  const url = protoBuildRepoUrl();
  if (!url) return { ok: false, error: 'no-remote', message: 'Publishing is not configured - set PROTO_BUILD_REPO_URL in .env' };
  // The token goes through -c insteadOf in _protoGitExec, never through the address - otherwise
  // git stores it in the clone's remote.origin.url (as it did until 2026-09-13).
  // The directory may already exist as the SEED (a copy of the seed, without .git). The seed is
  // nobody's work - it comes from templates/ - so it is moved aside, not
  // silently deleted: its node_modules can weigh hundreds of megabytes and
  // reinstalling them takes minutes.
  if (fs.existsSync(PROTO_BUILD_DIR) && !_protoBuildCloned()) {
    const parked = PROTO_BUILD_DIR + '.seed-' + Date.now();
    try {
      fs.renameSync(PROTO_BUILD_DIR, parked);
      log(`Shell seed moved aside to ${path.basename(parked)} - the clone takes its place`);
    } catch (e) {
      return { ok: false, message: `Could not move the shell seed aside: ${e.message}` };
    }
  }
  fs.mkdirSync(PROTO_BUILD_DIR, { recursive: true });
  log('Cloning the shell repository...');
  const r = await _protoGitExec(['clone', '--depth', '1', url, PROTO_BUILD_DIR], 600000);
  if (r.code !== 0) {
    return { ok: false, message: `git clone failed: ${_protoTail(r.stderr)}` };
  }
  log('Shell repository cloned');
  return { ok: true };
}

// ── Publish gate: a published version from outside the shared repository ────
//
// 2026-09-12: a publish from this machine rolled the published version back
// by 1244 lines (and components/DesktopShell.tsx by eight). The old cockpit
// had published its copy straight from the plaintext tree and never synced
// it with the shared data repo; this cockpit pulled the shared repository, got the state
// from two days earlier and "published" it. No step asked whether what it
// was sending was older than what already hung on the hosting.
//
// The question this gate answers is NOT "is the local copy
// newer" - two files without a shared history cannot be ordered in
// time. It is: "did the published copy EVER pass through the shared
// data repository". If so, somebody synced it and the local copy
// is from the same line (newer after a pull or older, because somebody sent but did not
// publish) - the publish goes ahead normally. If not, somebody published from a
// machine that did not sync its data, and sending the local copy
// would ERASE that work on the hosting: refusal `stale-source`, overridable
// only by an explicit `force=1` after reading the file list.
//
// The check decrypts nothing. Encryption is deterministic (the
// same file, the same path, the same key -> the same bytes; precisely so
// that an unchanged file makes no diff), so the published content is encrypted
// again, its git blob hash is computed and `git log --find-object=<sha>` is asked
// about the mirror's history. Measured: 8-25 ms per file, without touching the network.
// A `null` answer (no mirror, no key) counts as "did not pass" -
// the safe direction, because in this direction the override is one click, and in the
// other the loss is public.

// The git blob id for content `buf` - without calling git.
function _gitBlobSha(buf) {
  return crypto.createHash('sha1').update(`blob ${buf.length}\0`).update(buf).digest('hex');
}

/**
 * Whether content `plain` under path `relPath` was EVER in the mirror history
 * of source `d`. `true`/`false`, or `null` when it cannot be determined
 * (no mirror, no key, a git error).
 * @param {object} d a DATA_REPOS row
 * @param {string} relPath path in the plaintext tree (posix)
 * @param {Buffer} plain
 * @returns {Promise<boolean|null>}
 */
async function _protoContentInMirrorHistory(d, relPath, plain) {
  if (!fs.existsSync(path.join(d.dir, '.git'))) return null;
  let key;
  try { key = _repoMasterKey(d); } catch { return null; }
  let encRelPath;
  let armored;
  try {
    if (d.mirrorFormat === 'v1') {
      encRelPath = relPath + '.enc';
      armored = crypto_sync.encryptBufferV1(plain, relPath, key, d.hkdfInfo);
    } else {
      const encName = crypto_sync.encryptRelPath(relPath, key, d.hkdfInfo);
      encRelPath = encName + '.enc';
      armored = crypto_sync.encryptBuffer(plain, relPath, encName, key, d.hkdfInfo);
    }
  } catch { return null; }
  const sha = _gitBlobSha(Buffer.from(armored, 'utf8'));
  const r = await d.gitExecFn(['log', '--format=%H', '-n', '1', `--find-object=${sha}`, '--', encRelPath]);
  if (r.code !== 0) return null;
  if (String(r.stdout || '').trim()) return true;
  // A shallow clone (measured: the data mirror on this machine has its boundary at
  // 2026-09-07) has no versions from before the boundary, so "not found" does not mean
  // "never passed" there - it means "cannot be determined", i.e. null.
  const shallow = await d.gitExecFn(['rev-parse', '--is-shallow-repository']);
  if (shallow.code === 0 && String(shallow.stdout || '').trim() === 'true') return null;
  return false;
}

/**
 * The gate's decision - a pure function, exported for tests.
 * @param {{relPath: string, published: 'same'|'missing'|'differs', inHistory: boolean|null}[]} findings
 * @returns {{ok: boolean, stale: string[], unknown: string[], compared: number}}
 */
function protoDeployStaleVerdict(findings) {
  const stale = [];
  const unknown = [];
  for (const f of findings || []) {
    if (f.published !== 'differs') continue;
    if (f.inHistory === true) continue;
    if (f.inHistory === false) stale.push(f.relPath);
    else unknown.push(f.relPath);
  }
  return { ok: stale.length === 0 && unknown.length === 0, stale, unknown, compared: (findings || []).length };
}

// The `stale-source` refusal text - a pure function, exported for tests.
function protoStaleSourceMessage(verdict) {
  const stale = (verdict && verdict.stale) || [];
  const unknown = (verdict && verdict.unknown) || [];
  const list = (arr) => arr.slice(0, 6).join(', ') + (arr.length > 6 ? ` and ${arr.length - 6} more` : '');
  const parts = [];
  if (stale.length) {
    parts.push(`The published version contains files that never passed through the shared data repository (${stale.length}): ${list(stale)}. `
      + 'Most likely somebody published it from a computer where the team data was not synced - sending the local copy would roll that work back on the hosting. '
      + 'Sync the data on that computer (Sync > Send), pull it here and publish again.');
  }
  if (unknown.length) {
    parts.push(`For ${unknown.length} file(s) the published version could not be checked (no mirror, no team data key or a shallow clone without older history): ${list(unknown)}.`);
    if (verdict && verdict.shallow) {
      // The one cause with a one-line fix: name it and the command, so the
      // remedy is deepening the mirror rather than clicking "Publish anyway"
      // by habit - which would make the gate a formality on this machine.
      const dir = verdict.mirrorDir || 'data-sub-repositories/ds-data-encrypted';
      parts.push(`The team data mirror on this computer is a shallow clone - deepen its history with \`git -C ${dir} fetch --unshallow\` and publish again; the gate will then answer for sure.`);
    }
  }
  parts.push('If you know the local version is meant to replace the published one, use "Publish anyway".');
  return parts.join(' ');
}

// Pairs (a file in the plaintext team data tree, its place in the shell) for
// everything a prototype publish rewrites: the prototype's sources and data,
// its assets and the shared dependencies (ds/, components/, prototypes/_shared/).
// The same list _protoStageSources and _protoSyncSharedDeps write - it is
// the subject of the gate, not just index.tsx.
function _protoPublishPairs(id, slug) {
  const pairs = [];
  const protoDir = path.join(PROTOTYPES_DIR, id);
  const push = (plainRel, shellRel) => pairs.push({ relPath: plainRel, shellPath: shellRel });
  push(`prototypes/${id}/index.tsx`, `src/prototypes/${slug}/index.tsx`);
  push(`prototypes/${id}/styles.css`, `src/prototypes/${slug}/styles.css`);
  let files = [];
  try { files = fs.readdirSync(protoDir); } catch { /* no directory */ }
  for (const f of files) {
    if (!f.endsWith('.json') || f === 'spec.json' || f === 'compliance.json') continue;
    push(`prototypes/${id}/${f}`, `src/prototypes/${slug}/${f}`);
  }
  let assets = [];
  try { assets = fs.readdirSync(path.join(protoDir, 'assets')); } catch { /* no assets */ }
  for (const f of assets) push(`prototypes/${id}/assets/${f}`, `public/proto-assets/${slug}/${f}`);
  const walk = (plainRoot, shellRoot) => {
    const abs = path.join(PRODUCT_DATA_DIR, ...plainRoot.split('/'));
    let entries = [];
    try { entries = fs.readdirSync(abs, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      if (e.isDirectory()) walk(`${plainRoot}/${e.name}`, `${shellRoot}/${e.name}`);
      else if (e.isFile()) push(`${plainRoot}/${e.name}`, `${shellRoot}/${e.name}`);
    }
  };
  walk('ds', 'src/ds');
  walk('components', 'src/components');
  walk('prototypes/_shared', 'src/prototypes/_shared');
  return pairs;
}

// A file's content from the shell HEAD as a buffer (assets are binary - execFile with
// the default utf8 would break every PNG). null when the file is not in HEAD.
function _protoGitShowBuffer(shellPath) {
  return new Promise((resolve) => {
    execFile('git', ['-C', PROTO_BUILD_DIR, 'show', `HEAD:${shellPath}`], {
      encoding: 'buffer', maxBuffer: 64 * 1024 * 1024, env: _gitNoPromptEnv(),
    }, (err, stdout) => resolve(err ? null : stdout));
  });
}

/**
 * The publish gate for one prototype. Assumes the shell is after a pull
 * (HEAD == origin/main), and compares EVERY file the publish is about to
 * rewrite with its published copy: different -> was the published content
 * in the team data mirror history. Writes nothing.
 * @param {{id: string, slug: string}} args
 * @returns {Promise<{ok: boolean, stale: string[], unknown: string[], compared: number}>}
 */
async function _protoPublishedGuard({ id, slug }) {
  const d = _findDataRepo('data-tier-0');
  const pairs = _protoPublishPairs(id, slug);
  const roots = [...new Set(pairs.map((p) => p.shellPath.split('/').slice(0, -1).join('/')))];
  const tree = await _protoGitExec(['ls-tree', '-r', 'HEAD', '--', ...roots]);
  const published = new Map();
  if (tree.code === 0) {
    for (const line of String(tree.stdout || '').split('\n')) {
      const m = /^\d+ blob ([0-9a-f]{40})\t(.+)$/.exec(line);
      if (m) published.set(m[2], m[1]);
    }
  }
  const findings = [];
  for (const { relPath, shellPath } of pairs) {
    const publishedSha = published.get(shellPath);
    if (!publishedSha) { findings.push({ relPath, published: 'missing', inHistory: null }); continue; }
    let local;
    try { local = fs.readFileSync(path.join(PRODUCT_DATA_DIR, ...relPath.split('/'))); } catch { continue; }
    if (_gitBlobSha(local) === publishedSha) { findings.push({ relPath, published: 'same', inHistory: null }); continue; }
    const publishedBuf = await _protoGitShowBuffer(shellPath);
    const inHistory = publishedBuf && d ? await _protoContentInMirrorHistory(d, relPath, publishedBuf) : null;
    findings.push({ relPath, published: 'differs', inHistory });
  }
  const verdict = protoDeployStaleVerdict(findings);
  // `unknown` has three causes and only one of them has a fix a person can
  // run (a shallow mirror); tell the message which one it is.
  if (verdict.unknown.length && d && fs.existsSync(path.join(d.dir, '.git'))) {
    const shallow = await d.gitExecFn(['rev-parse', '--is-shallow-repository']);
    verdict.shallow = shallow.code === 0 && String(shallow.stdout || '').trim() === 'true';
    verdict.mirrorDir = path.relative(ROOT, d.dir).split(path.sep).join('/');
  }
  return verdict;
}

/**
 * The files of this publish (the same pairs as the gate above) that are waiting
 * to be sent in the team data. A publish from such a machine puts on the
 * hosting a version the shared repository does not know: another computer will not
 * pull it, will see an older copy, and the next publish from there will roll that
 * work back (2026-10-07, proto-96d41b3d8a79: dark mode and a compact view
 * published from computer A without sending the data, overwritten from computer B).
 * Read-only. `files: null` when it cannot be determined (no clone, no
 * key); `unresolved` - pending mirror files whose paths could not
 * be read (the _repoPendingSet decrypt limit), so it is unknown whose they are.
 * @param {{id: string, slug: string}} args
 * @returns {Promise<{files: string[]|null, unresolved: number}>}
 */
async function _protoUnsentPublishFiles({ id, slug }) {
  const d = _findDataRepo('data-tier-0');
  if (!d || !d.existsFn()) return { files: null, unresolved: 0 };
  let pending;
  try { pending = await _repoPendingSet(d, { resolveNames: true }); } catch { return { files: null, unresolved: 0 }; }
  const ours = new Set(_protoPublishPairs(id, slug).map((p) => p.relPath));
  const out = [];
  let unresolved = 0;
  for (const entry of pending.values()) {
    if (!entry.relPath) unresolved += 1;
    else if (ours.has(entry.relPath)) out.push(entry.relPath);
  }
  return { files: [...new Set(out)].sort(), unresolved };
}

// The `unsent-source` refusal text - a pure function, exported for tests.
function protoUnsentSourceMessage(files) {
  const list = (files || []).slice(0, 6).join(', ') + ((files || []).length > 6 ? ` and ${files.length - 6} more` : '');
  return `The files of this prototype have not been sent to the shared team data repository (${(files || []).length}): ${list}. `
    + 'Publishing without them would put on the hosting a version other computers will not pull - the next publish from another computer would roll that work back. '
    + 'Send the team data and publish again.';
}

/**
 * Narrows the GENERATED files to what really travels in the publish commit.
 * The local preview writes into the same shell: after it, src/prototypes/ holds
 * working copies of other prototypes (unpublished ones too), and
 * _protoRegenerateRegistry reads the directory - so registry.ts would list entries
 * the commit does not carry, and the build on the remote pipeline would fail on a missing
 * import. The registry is built here from (files tracked in HEAD) + (the published
 * slug), the widths of tracked slugs from their meta.json IN HEAD (the working copy
 * may be another preview), and the code map from HEAD + the published slug's entry.
 * @param {{slug: string, code: string, breakpoints: number[]}} args
 */
async function _protoNarrowGeneratedForPublish({ slug, code, breakpoints }) {
  const tracked = await _protoGitExec(['ls-files', '--', 'src/prototypes/*/index.tsx']);
  const slugs = new Set([slug]);
  for (const line of String(tracked.stdout || '').split('\n')) {
    const m = /^src\/prototypes\/([^/]+)\/index\.tsx$/.exec(line.trim());
    if (m && m[1] !== '_shared') slugs.add(m[1]);
  }
  const entries = [];
  for (const s of [...slugs].sort()) {
    let bps = PROTO_DEFAULT_BREAKPOINTS.slice();
    if (s === slug) {
      bps = breakpoints;
    } else {
      const meta = await _protoGitExec(['show', `HEAD:src/prototypes/${s}/meta.json`]);
      try {
        const parsed = JSON.parse(meta.stdout);
        if (meta.code === 0 && Array.isArray(parsed.breakpoints) && parsed.breakpoints.length) bps = parsed.breakpoints;
      } catch { /* no meta.json in HEAD - the default set */ }
    }
    entries.push({ slug: s, breakpoints: bps });
  }
  await _protoWriteFile(path.join(PROTO_BUILD_DIR, 'src', 'prototypes', 'registry.ts'), _protoRegistryFileContent(entries));

  const head = await _protoGitExec(['show', 'HEAD:src/prototype-codes.ts']);
  const codes = _protoParseCodes(head.code === 0 ? head.stdout : '');
  for (const [k, v] of Object.entries(codes)) {
    if (v === slug || k === code) delete codes[k];
  }
  codes[code] = slug;
  await _protoWriteFile(path.join(PROTO_BUILD_DIR, 'src', 'prototype-codes.ts'), _protoCodesFileContent(codes));
  return { slugs: [...slugs].sort() };
}

// The paths the publish commit CARRIES - and nothing else. It used to be `git add
// src/ public/`, and that took every working copy of another prototype the
// local preview had left in the shell (including prototypes never published)
// and sent it to the hosting under somebody else's commit.
//
// The shell manifests and configuration the publish commit carries. Every
// configuration file Vite reads at start (PROTO_VITE_CONFIG_FILES) must
// be here: the clone's vite.config.ts carries the alias `@bryntum/scheduler ->
// @bryntum/scheduler-trial`, and a change made locally and not sent meant
// a remote build with a different resolution than the local one (audit R-04). package.json and
// package-lock.json are rewritten by installing the prototype libraries
// (_protoEnsureLibraryDeps). tests/test_proto_build.mjs guards this consistency.
const PROTO_PUBLISH_SHELL_FILES = Object.freeze([
  'package.json', 'package-lock.json', 'postcss.config.js', 'vite.config.ts', 'vite.config.js',
]);

function _protoPublishAddPaths(slug) {
  const shellFiles = PROTO_PUBLISH_SHELL_FILES;
  const wanted = [
    `src/prototypes/${slug}/`,
    `public/proto-assets/${slug}/`,
    'src/prototype-codes.ts',
    'src/prototypes/registry.ts',
    'src/ds/',
    'src/components/',
    'src/prototypes/_shared/',
    ...shellFiles,
  ];
  return wanted.filter((p) => fs.existsSync(path.join(PROTO_BUILD_DIR, p)));
}

// Quarantine of untracked previews for the duration of the publish gates. `tsc -b`
// (tsconfig.app.json: include ["src"]), `eslint .` and `vite build` read the WHOLE
// tree, so an orphaned preview copy (an untracked src/prototypes/<slug>/)
// broke the publish of EVERY prototype on somebody else's error. Moving was chosen
// over a separate tsconfig, because one move works for all three
// tools at once, and nothing is deleted (it may be somebody's work in progress) -
// they go back in `finally`, and on a collision they stay in quarantine.
const PROTO_QUARANTINE_DIR = process.env.PROTO_QUARANTINE_DIR
  ? path.resolve(process.env.PROTO_QUARANTINE_DIR)
  : path.join(ROOT, 'data', 'proto-preview-quarantine');

/**
 * Pure: which src/prototypes/ directories go to quarantine. Not included:
 * the published slug, `_shared` and any directory with files tracked in HEAD.
 * @param {{onDisk: string[], trackedPaths: string[], slug: string}} args
 *   trackedPaths - output of `git ls-files -- src/prototypes` (relative paths)
 * @returns {string[]}
 */
function _protoQuarantineSelect({ onDisk, trackedPaths, slug }) {
  const tracked = new Set();
  for (const p of trackedPaths || []) {
    const m = /^src\/prototypes\/([^/]+)\//.exec(String(p).replace(/\\/g, '/'));
    if (m) tracked.add(m[1]);
  }
  return (onDisk || []).filter((n) => n !== slug && n !== '_shared' && !tracked.has(n)).sort();
}

// Shared shell directories that _protoSyncSharedDeps fills from the team
// data (cpSync without deleting). A file that vanished from the data or was left by a
// preview stays there forever and - because tsc/eslint/vite read the whole src/ -
// breaks the publish of EVERY prototype. `shellRel` written with '/'.
function _protoSharedSyncRoots() {
  return [
    { shellRel: 'src/ds', srcDir: path.join(PRODUCT_DATA_DIR, 'ds') },
    { shellRel: 'src/components', srcDir: path.join(PRODUCT_DATA_DIR, 'components') },
    { shellRel: 'src/prototypes/_shared', srcDir: path.join(PROTOTYPES_DIR, '_shared') },
  ];
}

// Files (relative paths with '/') under a directory, recursively. No directory -> [].
function _protoListFilesRel(absDir, relPrefix) {
  const out = [];
  const walk = (abs, rel) => {
    let entries = [];
    try { entries = fs.readdirSync(abs, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      if (e.isDirectory()) walk(path.join(abs, e.name), `${rel}/${e.name}`);
      else if (e.isFile()) out.push(`${rel}/${e.name}`);
    }
  };
  walk(absDir, relPrefix);
  return out;
}

/**
 * Pure: which FILES of the shared directories (src/ds, src/components,
 * src/prototypes/_shared) go to quarantine. An orphan = a file untracked
 * in the shell index AND without a counterpart in the team data. A new shared
 * component just copied from the data is untracked by definition and is meant to
 * travel in the commit - which is why being untracked alone is not enough. A
 * tracked file that is no longer in the data is NOT touched: taking it away
 * would mean a deletion in the publish commit.
 * @param {{onDisk: string[], trackedPaths: string[], sourcePaths: string[]}} args
 * @returns {string[]}
 */
function _protoQuarantineSelectFiles({ onDisk, trackedPaths, sourcePaths }) {
  const norm = (p) => String(p).replace(/\\/g, '/');
  const tracked = new Set((trackedPaths || []).map(norm));
  const source = new Set((sourcePaths || []).map(norm));
  return (onDisk || []).map(norm).filter((p) => !tracked.has(p) && !source.has(p)).sort();
}

/**
 * Pure: the pathspec for the publish `git add`/`git status`. Files kept in
 * quarantine for the duration of the gates go back in place BEFORE the commit, and
 * 'src/components/' in the publish paths would add them to the commit - which is why
 * each gets `:(exclude)`. Without positive paths nothing is
 * appended (an exclude alone in git means "everything except"). The `literal` magic:
 * a name with `*`, `?` or `[` cannot act as a glob and exclude somebody else's file.
 */
function _protoPublishPathspec(paths, excludedFiles) {
  const pos = [...(paths || [])];
  if (!pos.length) return pos;
  return pos.concat((excludedFiles || []).map((p) => `:(exclude,literal)${p}`));
}

// Moves a directory: rename, and on EXDEV (another volume) copy + delete.
// `force: false` is required: without it cpSync ignores errorOnExist and
// silently overwrites an existing target. `rename` is injectable only for the EXDEV test.
function _protoMoveDir(from, to, { rename = fs.renameSync } = {}) {
  fs.mkdirSync(path.dirname(to), { recursive: true });
  try {
    rename(from, to);
  } catch (e) {
    if (e.code !== 'EXDEV') throw e;
    fs.cpSync(from, to, { recursive: true, force: false, errorOnExist: true });
    fs.rmSync(from, { recursive: true, force: true });
  }
}

/**
 * Restores previews left in quarantine by an interrupted publish
 * (a process crash between the move and `restore()`). Called at the start of
 * every quarantine, under the same withProtoBuildLock. Never overwrites:
 * a taken place = the directory stays in quarantine and goes to `left`.
 * @returns {{restored: string[], left: string[]}} paths relative to buildDir / the quarantine
 */
function _protoQuarantineRecover({ buildDir = PROTO_BUILD_DIR, quarantineRoot = PROTO_QUARANTINE_DIR, log = () => {} } = {}) {
  const restored = [];
  const left = [];
  let stamps = [];
  try {
    stamps = fs.readdirSync(quarantineRoot, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort();
  } catch { return { restored, left }; }
  for (const stamp of stamps) {
    const stampDir = path.join(quarantineRoot, stamp);
    for (const rel of [path.join('src', 'prototypes'), path.join('public', 'proto-assets')]) {
      let names = [];
      try {
        names = fs.readdirSync(path.join(stampDir, rel), { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name);
      } catch { continue; }
      for (const n of names) {
        const held = path.join(stampDir, rel, n);
        const orig = path.join(buildDir, rel, n);
        if (fs.existsSync(orig)) { left.push(path.join(stamp, rel, n)); continue; }
        try {
          _protoMoveDir(held, orig);
          restored.push(path.join(rel, n));
        } catch (e) {
          left.push(path.join(stamp, rel, n));
          console.warn(`[proto-quarantine] did not restore ${orig}: ${e.message}`);
        }
      }
    }
    // Files of the shared directories (src/components etc.) sit under files/<path>.
    const filesRoot = path.join(stampDir, 'files');
    for (const rel of _protoListFilesRel(filesRoot, '')) {
      const r = rel.replace(/^\//, '');
      const held = path.join(filesRoot, ...r.split('/'));
      const orig = path.join(buildDir, ...r.split('/'));
      if (fs.existsSync(orig)) { left.push(path.join(stamp, 'files', ...r.split('/'))); continue; }
      try {
        _protoMoveDir(held, orig);
        restored.push(r);
      } catch (e) {
        left.push(path.join(stamp, 'files', ...r.split('/')));
        console.warn(`[proto-quarantine] did not restore ${orig}: ${e.message}`);
      }
    }
    // Cleaning up only an EMPTY marker: a file recovery does not know
    // (e.g. put here by hand) must not vanish silently during somebody else's publish.
    if (!left.some((p) => p.startsWith(stamp + path.sep)) && _protoListFilesRel(stampDir, '').length === 0) {
      try { fs.rmSync(stampDir, { recursive: true, force: true }); } catch { /* najlepszy wysilek */ }
    }
  }
  if (restored.length) log(`Restored ${restored.length} previews left in quarantine by an interrupted publish: ${restored.join(', ')}`);
  if (left.length) log(`Note: ${left.length} previews or files are still waiting in ${quarantineRoot}, because their place in the shell is taken: ${left.join(', ')}. Compare the quarantined copy with the file in the shell and delete the redundant one; as long as it is there, this message will repeat.`);
  return { restored, left };
}

/**
 * Moves untracked previews (src/prototypes/<slug>/ and
 * public/proto-assets/<slug>/ of the same slugs) to
 * <quarantineRoot>/<timestamp>/. Returns `restore()` - safe to
 * call many times; never overwrites and never deletes: a directory whose
 * place is taken stays in quarantine (an entry in `left` and in the log).
 * A move error rolls back what was already moved, and throws.
 * @returns {Promise<{moved: string[], dir: string, left: string[], restore: () => string[]}>}
 */
async function _protoQuarantineUntracked({ buildDir = PROTO_BUILD_DIR, slug, quarantineRoot = PROTO_QUARANTINE_DIR, sharedRoots = _protoSharedSyncRoots(), log = () => {} }) {
  const protosDir = path.join(buildDir, 'src', 'prototypes');
  // First, whatever an interrupted publish left behind - otherwise other people's previews
  // would silently vanish from the shell until a manual cleanup.
  _protoQuarantineRecover({ buildDir, quarantineRoot, log });
  let onDisk = [];
  try {
    onDisk = fs.readdirSync(protosDir, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name);
  } catch { /* no directory - nothing to move */ }
  // -z and quotePath=false: a non-ASCII path comes back exactly as it sits on
  // disk - a quoted one would miss the set and a tracked file would look like an orphan.
  const ls = await _protoGitExec(['-c', 'core.quotePath=false', 'ls-files', '-z', '--', 'src/prototypes', ...sharedRoots.map((r) => r.shellRel)], undefined, { cwd: buildDir });
  if (ls.code !== 0) throw new Error(`git ls-files failed: ${_protoTail(ls.stderr)}`);
  const trackedPaths = String(ls.stdout || '').split('\0').filter(Boolean);
  const names = _protoQuarantineSelect({ onDisk, trackedPaths, slug });
  const files = [];
  for (const root of sharedRoots) {
    files.push(..._protoQuarantineSelectFiles({
      onDisk: _protoListFilesRel(path.join(buildDir, ...root.shellRel.split('/')), root.shellRel),
      trackedPaths,
      sourcePaths: _protoListFilesRel(root.srcDir, root.shellRel),
    }));
  }
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  const dir = path.join(quarantineRoot, stamp);
  const pairs = [];
  for (const n of names) {
    pairs.push([path.join(protosDir, n), path.join(dir, 'src', 'prototypes', n)]);
    const assets = path.join(buildDir, 'public', 'proto-assets', n);
    if (fs.existsSync(assets)) pairs.push([assets, path.join(dir, 'public', 'proto-assets', n)]);
  }
  for (const rel of files) pairs.push([path.join(buildDir, ...rel.split('/')), path.join(dir, 'files', ...rel.split('/'))]);
  const done = [];
  const restoreOne = ([orig, held]) => {
    if (fs.existsSync(orig)) return false;
    _protoMoveDir(held, orig);
    return true;
  };
  try {
    for (const pair of pairs) { _protoMoveDir(pair[0], pair[1]); done.push(pair); }
  } catch (e) {
    for (const pair of done.reverse()) { try { restoreOne(pair); } catch { /* najlepszy wysilek */ } }
    throw e;
  }
  if (names.length) log(`Quarantine: ${names.length} untracked previews moved out of the tree for the duration of the gates (${names.join(', ')})`);
  if (files.length) log(`Quarantine: ${files.length} orphaned shared files (untracked and absent from the team data) moved out of the tree for the duration of the gates and out of the commit (${files.join(', ')})`);
  const left = [];
  let restored = false;
  const restore = () => {
    if (restored) return left;
    restored = true;
    for (const pair of done) {
      try {
        if (!restoreOne(pair)) { left.push(pair[1]); console.warn(`[proto-quarantine] place taken, left in quarantine: ${pair[1]}`); }
      } catch (e) {
        left.push(pair[1]);
        console.warn(`[proto-quarantine] did not restore ${pair[0]}: ${e.message} - copy in ${pair[1]}`);
      }
    }
    if (left.length) log(`Note: ${left.length} previews or files stayed in quarantine (place taken): ${left.join(', ')}`);
    else if (done.length) { try { fs.rmSync(dir, { recursive: true, force: true }); } catch { /* empty quarantine directory */ } }
    return left;
  };
  return { moved: names, files, dir, get left() { return left; }, restore };
}

function _protoFirstSrcPath(text) {
  const m = /(src[\\/][^\s:()'"]+)/.exec(String(text || ''));
  return m ? m[1].replace(/\\/g, '/') : null;
}

/**
 * Pure: extracts from tsc/ESLint/Vite output the file with the first ERROR and, when it
 * lies in another prototype than the published one, says so. ESLint
 * (stylish format) is blocks: a line with the path, below it indented
 * `L:K  error|warning  ...` - a file with warnings only is not named
 * as the error (that is how a publish once blamed DesktopShell.tsx for somebody else's error).
 * tsc: `src/x.tsx(1,2): error TS...` on one line. Without a recognized error:
 * the first path in the output (Vite/Rollup), and when there are only ESLint warnings -
 * a message that they are not what stopped the gate.
 * @returns {{file: string|null, proto: string|null, kind: 'error'|'warning'|null, text: string}}
 */
function protoGateErrorHint(output, slug) {
  const raw = String(output || '');
  let errFile = null;
  let warnFile = null;
  let cur = null;
  for (const line of raw.split(/\r?\n/)) {
    if (/^\S/.test(line)) {
      cur = _protoFirstSrcPath(line);
      if (cur && (/\berror\s+TS\d+/i.test(line) || /[):]\s*error\b/i.test(line))) { errFile = cur; break; }
      continue;
    }
    if (!cur) continue;
    if (/^\s+\d+:\d+\s+error\s/.test(line)) { errFile = cur; break; }
    if (!warnFile && /^\s+\d+:\d+\s+warning\s/.test(line)) warnFile = cur;
  }
  if (!errFile && warnFile) {
    return {
      file: warnFile, proto: null, kind: 'warning',
      text: ` The output has no error attributed to a file - there are only warnings (the first in ${warnFile}). The reason the gate stopped is in the log.`,
    };
  }
  const file = errFile || _protoFirstSrcPath(raw);
  if (!file) return { file: null, proto: null, kind: null, text: '' };
  const pm = /^src\/prototypes\/([^/]+)\//.exec(file);
  const proto = pm && pm[1] !== '_shared' ? pm[1] : null;
  let text = ` First error in file ${file}.`;
  if (proto && proto !== slug) text += ` This is an error in prototype ${proto}, which is not being published - fix it or remove it from the shell.`;
  return { file, proto, kind: 'error', text };
}

// Syncing the build shell with origin before a publish.
//
// Until 2026-10-08 this was a single `git pull --rebase --autostash`. When a local
// change in the shell (a local preview, or a publish that wrote files and
// failed on ESLint/build) touched a file somebody had published in the meantime,
// the autostash came back with a conflict - and git then exits with code 0.
// The publish went on, UU files stayed in the shell, and EVERY next
// publish from this machine failed on `Pulling is not possible because you
// have unmerged files`.
//
// The shell is nobody's source of truth (the sources live in the data repo, and
// the publish rewrites src/prototypes/<slug>/ anyway), so a local change does not
// need to be carried through the pull. But it is not deleted either: files that
// come from origin and are changed locally or in conflict go to a
// named stash entry (recoverable), and the rest goes through a plain
// rebase. No file may stay in conflict after the pull - that is a hard
// gate, not git's exit code.
//
// `git(args)` -> Promise<{ code, stdout, stderr }>; _protoGitExec by default,
// in tests git on a local repository.
async function _protoShellSyncWithOrigin({ git = _protoGitExec, log = () => {}, now = () => new Date() } = {}) {
  const zList = (out) => String(out || '').split('\0').filter(Boolean);
  const listUnmerged = async () => {
    const r = await git(['diff', '--name-only', '-z', '--diff-filter=U']);
    return r.code === 0 ? zList(r.stdout) : null;
  };
  // An aborted rebase from a previous pass blocks everything after it.
  const abortRebaseIfAny = async () => {
    const gd = await git(['rev-parse', '--absolute-git-dir']);
    const gitDir = gd.code === 0 ? gd.stdout.trim() : '';
    const inProgress = Boolean(gitDir) && ['rebase-merge', 'rebase-apply'].some((n) => fs.existsSync(path.join(gitDir, n)));
    if (inProgress) await git(['rebase', '--abort']);
    return inProgress;
  };

  if (await abortRebaseIfAny()) log('Aborted an unfinished shell rebase from a previous publish');

  const fetch = await git(['fetch', '--prune', 'origin']);
  if (fetch.code !== 0) return { ok: false, error: 'pull-failed', message: `git fetch failed: ${_protoTail(fetch.stderr)}` };

  const unmerged = await listUnmerged();
  if (unmerged === null) return { ok: false, error: 'pull-failed', message: 'Could not read the shell state (git diff)' };
  // --no-renames: on a rename in origin `--name-only` gives only the new
  // name, and a local change of the old one would not reach the stash.
  const dirtyR = await git(['diff', '--name-only', '-z', '--no-renames', 'HEAD']);
  const incomingR = await git(['diff', '--name-only', '-z', '--no-renames', 'HEAD', '@{upstream}']);
  // An untracked file on a path origin adds overturns the pull ("untracked
  // working tree files would be overwritten") - it goes to the stash too.
  const untrackedR = await git(['ls-files', '-z', '--others', '--exclude-standard']);
  if (dirtyR.code !== 0 || incomingR.code !== 0 || untrackedR.code !== 0) {
    return { ok: false, error: 'pull-failed', message: `Could not compare the shell with origin: ${_protoTail(dirtyR.stderr || incomingR.stderr || untrackedR.stderr)}` };
  }
  const incoming = new Set(zList(incomingR.stdout));
  const untrackedHit = zList(untrackedR.stdout).filter((p) => incoming.has(p));
  const park = [...new Set([...unmerged, ...untrackedHit, ...zList(dirtyR.stdout).filter((p) => incoming.has(p))])].sort();

  let stashMessage = null;
  if (park.length) {
    // A file in conflict will not enter the stash until it is marked as
    // resolved - `add` records it together with the markers, nothing is lost.
    if (unmerged.length) {
      const add = await git(['--literal-pathspecs', 'add', '--', ...unmerged]);
      if (add.code !== 0) return { ok: false, error: 'shell-conflict', paths: unmerged, message: `Could not set aside the conflicting files: ${_protoTail(add.stderr)}` };
    }
    stashMessage = `cockpit-deploy pre-pull ${now().toISOString()}`;
    // --literal-pathspecs: a name like `[id].tsx` is a file, not a pattern.
    const stash = await git(['--literal-pathspecs', 'stash', 'push', ...(untrackedHit.length ? ['--include-untracked'] : []), '-m', stashMessage, '--', ...park]);
    if (stash.code !== 0) return { ok: false, error: 'shell-conflict', paths: park, message: `Could not set aside the local shell changes: ${_protoTail(stash.stderr)}` };
    log(`Stashed in the shell (${stashMessage}) ${park.length} file(s) changed both locally and in origin: ${park.slice(0, 5).join(', ')}${park.length > 5 ? ', …' : ''}`);
  }

  // The remaining local changes touch nothing that comes from origin, so
  // the autostash has nothing to fight over.
  const pull = await git(['pull', '--rebase', '--autostash']);
  if (pull.code !== 0) {
    await abortRebaseIfAny();
    return { ok: false, error: 'pull-failed', message: `git pull failed: ${_protoTail(pull.stderr)}`, stashMessage };
  }
  const after = await listUnmerged();
  if (after === null || after.length) {
    return {
      ok: false,
      error: 'shell-conflict',
      paths: after || [],
      stashMessage,
      message: `After the shell sync, files in conflict remain: ${(after || []).slice(0, 5).join(', ')} - the local changes are in the shell stash (data-sub-repositories/data-prototypes/)`,
    };
  }
  return { ok: true, parked: park, stashMessage };
}

/**
 * GET /api/prototypes/deploy-stream?id=proto-xxxx[&force=1]
 * Publishing a prototype: clone/pull the shell, the published-version gate,
 * rewrite the sources, the ESLint gate, a production build, commit and push. Whatever
 * hosting watches the remote serves the result under PROTO_PAGES_BASE_URL.
 *
 * `force=1` overrides ONLY the `stale-source` gate (see above) - never
 * the ESLint or build gates.
 *
 * The push is SKIPPED when PROTO_DEPLOY_DRY_RUN is set to '1'/'true'/'yes'
 * - the whole run can then be walked through without touching the remote repository.
 */
async function handlePrototypeDeployStream(req, res) {
  if (!checkOriginNoBody(req, res)) return;
  const url = new URL(req.url, `http://${req.headers.host}`);
  const id = url.searchParams.get('id') || '';
  const force = ['1', 'true', 'yes'].includes(String(url.searchParams.get('force') || '').toLowerCase());

  sseOpen(req, res);
  const keepAlive = setInterval(() => { if (!res.writableEnded) res.write(': ping\n\n'); }, 25000);
  const clearKeepAlive = () => clearInterval(keepAlive);
  req.on('close', clearKeepAlive);
  const log = (text) => { if (!res.writableEnded) sseEvent(res, 'log', { text }); };
  const progress = (pct, msg) => { if (!res.writableEnded) sseEvent(res, 'progress', { pct, msg }); };
  const fail = (message, error, extra) => { if (!res.writableEnded) sseEvent(res, 'error', { ...(extra || {}), error: error || 'error', message }); };
  sseEvent(res, 'start', { op: 'proto-deploy', id, force });

  try {
    if (IS_TEST_MODE) { fail('Publishing is disabled in test mode', 'test-mode'); return; }
    const dryRun = ['1', 'true', 'yes'].includes(String(process.env.PROTO_DEPLOY_DRY_RUN || '').toLowerCase());
    let pushedCommit = null;
    let madeCommit = false;
    if (!protoBuildRepoUrl()) {
      fail('Publishing is not configured - set PROTO_BUILD_REPO_URL (and PROTO_PAGES_BASE_URL) in .env', 'no-remote');
      return;
    }

    const src = await _protoLoadSourcesFor(id);
    if (src.error) { fail(src.error.message, 'invalid-source'); return; }
    const slug = src.slug;

    await withProtoBuildLock(async () => {
      // (a) 2-10% - the shell repository: clone or sync.
      progress(2, 'Syncing the build shell...');
      if (!_protoBuildCloned()) {
        const cloned = await _protoCloneBuildRepo(log);
        if (!cloned.ok) { fail(cloned.message, 'clone-failed'); return; }
      } else {
        // Without this a publish from a clone that fell behind would regenerate
        // registry.ts and prototype-codes.ts from an incomplete picture of src/prototypes/ -
        // silently deleting other people's prototypes from them before the push could
        // reject the stale history.
        // No autostash on files that come from origin - see
        // _protoShellSyncWithOrigin.
        const synced = await _protoShellSyncWithOrigin({ log });
        if (!synced.ok) {
          fail(`${synced.message} - try again; if the error returns, look into data-sub-repositories/data-prototypes/`, synced.error, synced.paths ? { paths: synced.paths } : undefined);
          return;
        }
        log('Synced with origin/main');
      }

      // (a2) 6-10% - gate: did the published copy pass through the shared
      // data repository (the comment block above _protoContentInMirrorHistory).
      // After the pull, because it compares with the shell HEAD; before writing, because it writes nothing.
      progress(6, 'Comparing with the published version...');
      const guard = await _protoPublishedGuard({ id, slug });
      if (!guard.ok) {
        const listed = [...guard.stale, ...guard.unknown];
        if (!force) {
          fail(protoStaleSourceMessage(guard), 'stale-source', { stale: guard.stale, unknown: guard.unknown, shallow: Boolean(guard.shallow) });
          return;
        }
        log(`Publish forced (force=1) despite ${listed.length} file(s) from outside the shared repository: ${listed.slice(0, 5).join(', ')}${listed.length > 5 ? ', …' : ''}`);
      } else {
        log(`Compared ${guard.compared} files with the published version - no objections`);
      }

      // (a3) The second half of the same rule: the hosting must not get ahead of
      // the shared data. No `force` - the only way on is to send the data
      // (the publish window has a button for it), because otherwise this machine becomes
      // "the computer that published and did not sync".
      const unsent = await _protoUnsentPublishFiles({ id, slug });
      if (unsent.files && unsent.files.length) {
        fail(protoUnsentSourceMessage(unsent.files), 'unsent-source', { files: unsent.files });
        return;
      }
      if (unsent.files === null) log('Cannot check whether the prototype files are sent (no clone or no team data key)');
      if (unsent.unresolved > 0) log(`Note: ${unsent.unresolved} team data file(s) are waiting to be sent, but their paths could not be read - check Sync`);

      // (b) 10-35% - the invitation code and the shared dependencies.
      progress(10, 'Preparing sources...');
      const code = _protoCanonicalCode(_readPrototypes(), id)
        || await _protoCodeForSlug(slug)
        || _protoPlaceholderCode(slug);
      progress(20, 'Syncing shared dependencies...');
      try {
        await _protoSyncSharedDeps();
        log('Synced ds/, components/ and prototypes/_shared/ from the team data');
      } catch (e) {
        fail(`Syncing the shared dependencies failed: ${e.message}`, 'sync-failed');
        return;
      }

      // (c) 35-55% - writing the prototype sources into the shell.
      progress(40, 'Writing files...');
      let staged;
      try {
        staged = await _protoStageSources({ id, slug, indexTsx: src.indexTsx, stylesCss: src.stylesCss, code });
      } catch (e) {
        fail(`Writing the files failed: ${e.message}`, 'write-failed');
        return;
      }
      log(`Wrote src/prototypes/${slug}/ (widths: ${staged.breakpoints.join(', ')})`);
      // Generated files from what the commit CARRIES, not from what lies in
      // the shell directory after local previews (see
      // _protoNarrowGeneratedForPublish). Before lint and build, because both
      // gates must check exactly the picture that will go to the pipeline.
      let narrowed;
      try {
        narrowed = await _protoNarrowGeneratedForPublish({ slug, code, breakpoints: staged.breakpoints });
      } catch (e) {
        fail(`Writing the generated files failed: ${e.message}`, 'write-failed');
        return;
      }
      log(`Updated prototype-codes.ts (${code} -> ${slug}) and registry.ts (${narrowed.slugs.length} published prototypes)`);
      progress(55, 'Files written');

      // (d) 55-70% - dependencies and the ESLint gate (exactly what the pipeline does).
      const heal = await _protoEnsureNodeModules();
      if (!heal.ok) { fail(`npm install failed: ${heal.message}`, 'install-failed'); return; }
      // The prototype libraries (audit R-05). The installed package.json entry and
      // package-lock.json travel in this commit (PROTO_PUBLISH_SHELL_FILES), because
      // the hosting build installs from the committed manifests.
      const libs = await _protoEnsureLibraryDeps(src.indexTsx, log);
      if (!libs.ok) { fail(libs.message, 'deps-missing', { missing: libs.missing }); return; }
      if (libs.installed.length) log(`Installed into the shell: ${libs.installed.join(', ')} (the package.json entry travels in this commit)`);
      progress(58, 'ESLint...');
      const buildEnv = _protoBuildEnv();
      const npmCmd = process.platform === 'win32' ? 'npm.cmd' : 'npm';
      let quarantine;
      try {
        quarantine = await _protoQuarantineUntracked({ slug, log });
      } catch (e) {
        fail(`Quarantining untracked previews failed: ${e.message}`, 'write-failed');
        return;
      }
      let gatesOk = false;
      try {
        const lint = await _protoSpawn(npmCmd, ['run', 'lint'], { cwd: PROTO_BUILD_DIR, env: buildEnv });
        if (lint.code !== 0) {
          log(_protoTail(`${lint.stdout}\n${lint.stderr}`));
          fail(`ESLint did not pass (code ${lint.code}) - fix the errors in the prototype sources. The whole shell project must be clean.${protoGateErrorHint(`${lint.stdout}\n${lint.stderr}`, slug).text}`, 'lint-failed');
          return;
        }
        log('ESLint OK');
        progress(70, 'ESLint OK');

        // (e) 70-90% - a production build as a gate.
        progress(75, 'Building...');
        const build = await _protoSpawn(npmCmd, ['run', 'build'], { cwd: PROTO_BUILD_DIR, env: buildEnv });
        if (build.code !== 0) {
          log(_protoTail(`${build.stdout}\n${build.stderr}`));
          fail(`The build failed (code ${build.code}) - the shell directory contents were left for inspection.${protoGateErrorHint(`${build.stdout}\n${build.stderr}`, slug).text}`, 'build-failed');
          return;
        }
        log(_protoTail(build.stdout, 10));
        progress(90, 'Build finished');
        gatesOk = true;
      } finally {
        // Also on a gate error and an exception: previews go back in place.
        quarantine.restore();
      }
      if (!gatesOk) return;

      // (f) 90-100% - commit and push, only in the shell directory.
      //
      // ONLY this prototype's paths, the generated files, the shared
      // dependencies and the shell manifests go into the commit (_protoPublishAddPaths) -
      // the hosting build installs from the COMMITTED package-lock.json, so
      // a lockfile changed only in the working copy ends in a build on the
      // server without the package that got installed here. Non-existent paths
      // are filtered out - `git add` on an unknown path ends in an error.
      progress(92, 'Sending changes...');
      const deployPaths = _protoPublishPathspec(_protoPublishAddPaths(slug), quarantine.files);
      const add = await _protoGitExec(['add', '--', ...deployPaths]);
      if (add.code !== 0) { fail(`git add failed: ${_protoTail(add.stderr)}`, 'git-failed'); return; }
      const status = await _protoGitExec(['status', '--porcelain', '--', ...deployPaths]);
      if (status.code === 0 && !status.stdout.trim()) {
        log('No changes to record (the result is identical to the previous publish)');
      } else {
        const commit = await _protoGitExec(['-c', 'user.name=cockpit-deploy', '-c', 'user.email=mission-deck-deploy@example.invalid',
          'commit', '-m', `deploy(${slug}): prototype from the cockpit`]);
        if (commit.code !== 0) { fail(`git commit failed: ${_protoTail(commit.stderr)}`, 'git-failed'); return; }
        log('Commit created');
        madeCommit = true;
      }

      if (dryRun) {
        log('Dry run: git push skipped (PROTO_DEPLOY_DRY_RUN)');
      } else {
        const push = await _protoGitExec(['push', 'origin', 'HEAD:main']);
        if (push.code !== 0) { fail(`git push failed: ${_protoTail(push.stderr)}`, 'git-failed'); return; }
        log('Pushed - the hosting that watches the remote rebuilds on its own; until then the address serves the previous version');
        // The commit the hosting will build. Without a new commit HEAD is
        // somebody else's / the previous publish.
        if (madeCommit) {
          const head = await _protoGitExec(['rev-parse', 'HEAD']);
          if (head.code === 0 && /^[0-9a-f]{40}$/.test(head.stdout.trim())) pushedCommit = head.stdout.trim();
        }
      }
      // The invitation code goes into the team data so every machine sees
      // the same code, including one without a token. Also in a dry run: the code
      // is already written into the shell's prototype-codes.ts and the local commit,
      // and without this write the details screen had nothing to show for
      // copying (the registry did not know the code, and the client reads only the registry).
      await _protoPersistCanonicalCode(id, code);
      log(`Invitation code ${code} saved in the team data`);

      // The prototype's own files are already sent (the unsent-source gate above), but
      // the publish does NOT send the team data, and the invitation code write
      // above and other people's changes in this source are still waiting - we count them and say
      // so outright (read-only, the same probe as the sync table).
      let unsynced = 0;
      try {
        const dp = _findDataRepo('data-tier-0');
        if (dp && dp.existsFn()) unsynced = (await _repoPendingSet(dp, { resolveNames: false })).size;
      } catch { /* a helper probe - its error does not invalidate the publish */ }
      if (unsynced > 0) log(`Note: the team data has ${unsynced} file(s) to send - the published version is not in the shared repository yet`);

      progress(100, 'Done');
      if (!res.writableEnded) {
        sseEvent(res, 'done', {
          ok: true,
          status: 'ok',
          code,
          url: protoPagesBaseUrl() + '/' + slug,
          unsynced,
          // The client shows by this whether the address still needs to wait for the
          // pipeline - a dry run sent nothing, so there is nothing to wait for.
          pushed: !dryRun,
          commit: pushedCommit,
          changed: madeCommit,
          message: dryRun ? 'Publish prepared (dry run - nothing sent)' : 'Publish started',
        });
      }
    });
  } catch (e) {
    fail(e.message);
  } finally {
    clearKeepAlive();
    req.removeListener('close', clearKeepAlive);
    if (!res.writableEnded) res.end();
  }
}

// ── Infra: routes for the strip under the top bar (register: Infrastructure: GitLab reachability) ──

/**
 * GET /api/infra/status
 * The reachability verdict for the strip under the top bar. A register read,
 * never a probe - see _infraNoteNetwork for why. Always 200.
 */
function handleInfraStatus(_req, res) {
  jsonResponse(res, 200, { ok: true, network: infraNetworkState(_infraNet) });
}

/**
 * POST /api/infra/recheck
 * The one ACTIVE probe, behind the strip's "Check again" button. Two
 * calls, both reporting to the register like every other call, the second
 * one LAST because the newest outcome is the verdict:
 *   1. the identity lookup past its memo (8 s) - it re-derives the person and
 *      catches a dead host, but GET /user is user-scoped and answers 200 to a
 *      machine the group's IP allowlist has locked out, so on its own it
 *      cannot tell "VPN on" from "VPN off" (_INFRA_FETCH_PROVES_ACCESS);
 *   2. `git ls-remote` on the APP repository (15 s), the same call
 *      check-update makes and the one that failed in the reported case -
 *      this is what can answer `refused`, and what can clear it.
 * Without a token there is nothing to ask with - the answer says so and the
 * register is untouched, because "no token" is the vault's story, not the
 * network's. Under IS_TEST_MODE the second call is skipped: _appRepoUrl()
 * resolves to this checkout's real origin and the suite must not reach it.
 */
async function handleInfraRecheck(req, res) {
  if (!checkOrigin(req, res)) return;
  try { await readBody(req, 1024); } catch { /* the body carries nothing */ }
  const token = resolveToken(process.env.COCKPIT_APP_TOKEN || '');
  if (!token) {
    jsonResponse(res, 200, { ok: true, probed: false, reason: 'no-token', network: infraNetworkState(_infraNet) });
    return;
  }
  _gitlabIdentityCache = { token: null, at: 0, data: null };
  await _gitlabIdentity();
  const authUrl = IS_TEST_MODE ? null : _appAuthUrl();
  if (authUrl) await _gitP(['ls-remote', authUrl, 'HEAD'], 15000);
  jsonResponse(res, 200, { ok: true, probed: true, network: infraNetworkState(_infraNet) });
}

// ── Feedback: reports from the app ──────────────────────────────────────────
// POST /api/feedback/submit turns one report (bug / idea / question - idea / question), typed
// in the modal behind the top bar's question-mark slot, into one directory
// under feedback/<stamp>-<type>-<slug>/ and sends it to THIS repository's own
// GitLab project through the REST API alone - branch, commit, merge request -
// exactly the sequence handleModulesPublish already proves (~line 14180),
// never a clone and never the `git` binary. No lock: nothing here writes a
// shared file on THIS disk, every write lands on the GitLab remote instead,
// so there is nothing a chain lock would serialize. checkOrigin and the
// dispatch-ladder's global checkRateLimit still cover the route; a client
// guards the double-submit case with `disabled` + `aria-busy`.
//
// See feedback/README.md for the full contract (YAML
// frontmatter fields, directory shape, branch/commit/MR naming).

// 3 MB/attachment mirrors TEAM_AVATAR_MAX_BYTES - a screenshot proven fine in
// practice by /api/team/avatar. 8 MB total mirrors MODULES_PUBLISH_MAX_BYTES,
// the proven ceiling of one GitLab commit body from this codebase. 12 MB on
// the request body: base64 inflates by about a third, and MAX_BODY_BYTES
// defaults to 1 MB, so without this explicit second readBody() argument the
// route would 413 on two screenshots with a "bad body" message rather than a
// size one. 90 s write timeout mirrors MODULES_CATALOG_WRITE_TIMEOUT_MS - the
// commit carries whole images, the same reason that helper needs more than
// the 8 s read budget that once answered HTTP 0 on a large module.
const FEEDBACK_MAX_ATTACHMENTS = 5;
const FEEDBACK_MAX_ATTACHMENT_BYTES = 3 * 1024 * 1024;
const FEEDBACK_MAX_TOTAL_BYTES = 8 * 1024 * 1024;
const FEEDBACK_MAX_BODY_BYTES = 12 * 1024 * 1024;
const FEEDBACK_WRITE_TIMEOUT_MS = 90000;
const FEEDBACK_MAX_CONSOLE_ENTRIES = 20;

// Attachment format, decided from magic bytes alone - never the client's
// Content-Type, never a file extension it sent. Same pattern as
// TEAM_AVATAR_TYPES (~line 10199), extended with GIF and WebP per the
// interview: a screenshot tool may reasonably produce either. Kept as its
// own table rather than parameterizing the team one, for the same reason
// _appRepoPostJson below is its own function rather than a parameterized
// _modulesCatalogPostJson - two small closed tables are cheaper to read than
// one shared table two unrelated features both depend on.
const FEEDBACK_IMAGE_TYPES = [
  { ext: '.png', test: b => b.length > 8 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47 },
  { ext: '.jpg', test: b => b.length > 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff },
  { ext: '.gif', test: b => b.length > 4 && b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x38 },
  { ext: '.webp', test: b => b.length > 12 && b.subarray(0, 4).toString('latin1') === 'RIFF' && b.subarray(8, 12).toString('latin1') === 'WEBP' },
];

function _feedbackImageExt(buf) {
  const hit = FEEDBACK_IMAGE_TYPES.find(t => t.test(buf));
  return hit ? hit.ext : '';
}

// A lazy, memoized import of js/feedback-helpers.mjs - the same pattern as
// _cocreateStages() (js/academy-stages.mjs) and _moduleUpdatesLib()
// (js/module-updates.mjs): the server and the browser read one logic, so
// slug/branch/markdown cannot drift apart. Returns null instead of throwing -
// a missing file degrades to an 'internal' answer, never a 500.
const FEEDBACK_HELPERS_PATH = path.join(ROOT, 'js', 'feedback-helpers.mjs');
let _feedbackLibCache = null;
async function _feedbackLib() {
  if (_feedbackLibCache) return _feedbackLibCache;
  try {
    _feedbackLibCache = await import(pathToFileURL(FEEDBACK_HELPERS_PATH).href);
  } catch (e) {
    console.warn('[feedback] js/feedback-helpers.mjs unavailable:', e.message);
    return null;
  }
  return _feedbackLibCache;
}

/**
 * One JSON write against THIS repository's GitLab project. Sibling of
 * _modulesCatalogPostJson (~line 13869), deliberately not a parameterized
 * version of it: that helper closes over MODULES_CATALOG_TOKEN as a module
 * variable so a token can never ride out inside an error object, and turning
 * the token into a parameter would carry it through every stack trace at
 * every one of that helper's five call sites. This one closes over
 * APP_UPDATE_TOKEN instead and additionally reports every outcome to the
 * infrastructure reachability register (_infraNoteFetch, ~line 4020): an
 * unreachable GitLab is the single most likely real-world failure here (no
 * VPN), and the register is what turns that into the top bar's "Turn on the
 * VPN" strip instead of an unexplained error.
 * @returns {Promise<{ok: boolean, status: number, text: string, json: object|null}>}
 */
async function _appRepoPostJson(url, body) {
  try {
    const r = await fetch(url, {
      method: 'POST',
      headers: { 'PRIVATE-TOKEN': APP_UPDATE_TOKEN, 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(FEEDBACK_WRITE_TIMEOUT_MS),
    });
    _infraNoteFetch(null, 'feedback', r.status);
    const text = await r.text().catch(() => '');
    let json = null;
    try { json = JSON.parse(text); } catch { /* non-JSON error page */ }
    return { ok: r.ok, status: r.status, text, json };
  } catch (e) {
    _infraNoteFetch(e, 'feedback');
    return { ok: false, status: 0, text: '', json: null };
  }
}

// The GitLab label every feedback merge request carries. It is what the
// top bar's feedback chip counts, and it is a label rather than a title prefix or
// a `report/` branch match for two reasons: GitLab's merge_requests API
// cannot filter by source-branch PREFIX at all, and a title match would break
// the moment somebody rewords feedbackMrTitle. ASCII, because it is
// an identifier compared on the wire and never shown to a person.
const FEEDBACK_MR_LABEL = 'feedback';

/**
 * One JSON read against THIS repository's GitLab project, shaped exactly like
 * _modulesCatalogGet (same `{ok, status, text, headers}`, `headers` included
 * because parseOpenMergeRequestCount reads `x-total` off it) and closing over
 * APP_UPDATE_TOKEN the way _appRepoPostJson does. Never throws; every outcome
 * reports to the reachability register under the same 'feedback' source.
 * @returns {Promise<{ok: boolean, status: number, text: string, headers?: object}>}
 */
async function _appRepoGet(url) {
  try {
    const r = await fetch(url, {
      headers: { 'PRIVATE-TOKEN': APP_UPDATE_TOKEN },
      signal: AbortSignal.timeout(MODULES_CATALOG_TIMEOUT_MS),
    });
    _infraNoteFetch(null, 'feedback', r.status);
    const text = await r.text().catch(() => '');
    return { ok: r.ok, status: r.status, text, headers: r.headers };
  } catch (e) {
    _infraNoteFetch(e, 'feedback');
    return { ok: false, status: 0, text: '' };
  }
}

/** Open feedback MRs on the app project: one item, counted from `x-total`. */
function _appRepoMergeRequestsUrl() {
  return `${_gitlabApiBase()}/projects/${encodeURIComponent(_gitlabPathFromRemote(_appRepoUrl()))}` +
    `/merge_requests?state=opened&labels=${encodeURIComponent(FEEDBACK_MR_LABEL)}` +
    `&per_page=${MR_COUNTS_PER_PAGE}`;
}

/** The browsable list a person opens from the chip, '' when unknown. */
function _appRepoMergeRequestsWebUrl() {
  const base = _gitlabWebUrl(_appRepoUrl(), _gitlabPathFromRemote(_appRepoUrl()));
  return base ? base + '/-/merge_requests?label_name=' + encodeURIComponent(FEEDBACK_MR_LABEL) : '';
}

/**
 * READ-ONLY: the HEAD commit sha of ROOT, for the `app_info.commit`
 * frontmatter field. `null` when ROOT has no `.git` yet (a source archive
 * before adoption, see _appRepoAdopt) - never a write, never a fallback that
 * invents a value.
 * @returns {string|null}
 */
function _feedbackHeadSha() {
  if (!_appRepoAdopt.hasGitDir(ROOT)) return null;
  try {
    const sha = execSync('git rev-parse HEAD', { cwd: ROOT, timeout: 3000, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
    return sha || null;
  } catch {
    return null;
  }
}

/**
 * READ-ONLY: the reporter's e-mail for the `reported_by.email`
 * frontmatter field. _resolveIdentity carries no e-mail (GitLab's /user
 * answer is reduced to name, slug, username and avatar), so this reads
 * `git config user.email` the same way _localIdentity's gitCfg reads
 * user.name - and deliberately without a hasGitDir guard: `git config`
 * falls through to the global config, which is exactly the value wanted on
 * an unadopted archive. `null` when unset or when git is unavailable.
 * @returns {string|null}
 */
function _feedbackAuthorEmail() {
  try {
    const v = execFileSync('git', ['-C', ROOT, 'config', 'user.email'], { timeout: 3000, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
    return v || null;
  } catch {
    return null;
  }
}

/**
 * POST /api/feedback/submit
 *
 * Gate order is deliberate and matches handleModulesPublish: origin, body,
 * VALIDATION (structure, magic bytes, decoded size), only THEN the
 * IS_TEST_MODE and no-token gates, and only then the network. Validation
 * before the test-mode gate is what makes it reachable from npm run test:api
 * at all - the other order would make every validation path untestable
 * without a live token. Every failure answers { ok: false, error, message }
 * with a user-facing message from feedbackErrorMessage(); this handler never
 * answers 500.
 */
async function handleFeedbackSubmit(req, res) {
  if (!checkOrigin(req, res)) return;

  let body;
  try {
    body = await readBody(req, FEEDBACK_MAX_BODY_BYTES);
  } catch (e) {
    // readBody rejects for two reasons and they deserve two codes: a body
    // that parsed as nothing is 'invalid-json' (the code
    // js/feedback-helpers.mjs already carries), everything else is the size
    // cap. _readRawBody calls req.destroy() before rejecting on oversize, so
    // this 413 protects the PROCESS - a client that actually crosses
    // FEEDBACK_MAX_BODY_BYTES sees a transport error, not this JSON body.
    // The testable size gate is the decoded-attachment check below, which
    // answers a real 413 because the request itself completed normally.
    if (e && e.message === 'Invalid JSON') {
      return jsonResponse(res, 400, { ok: false, error: 'invalid-json', message: 'Invalid feedback data.' });
    }
    return jsonResponse(res, 413, { ok: false, error: 'too-large', message: 'The feedback is too large. Reduce the number or size of the screenshots.' });
  }

  const lib = await _feedbackLib();
  const msg = (code) => (lib ? lib.feedbackErrorMessage(code) : 'An unexpected error occurred. Please try again.');

  const validated = lib ? lib.validateFeedbackInput(body) : { ok: false, error: 'internal' };
  if (!validated.ok) {
    return jsonResponse(res, 400, { ok: false, error: validated.error, message: msg(validated.error) });
  }

  // validateFeedbackInput already refused a 6th attachment above (its own
  // FEEDBACK_MAX_ATTACHMENTS, tested in isolation in
  // tests/test_feedback_helpers.mjs); this slice is defense in depth against
  // the byte-decoding loop below ever doing more work than the limit allows,
  // even if a future edit reordered the gates.
  const rawAttachments = (Array.isArray(body.attachments) ? body.attachments : []).slice(0, FEEDBACK_MAX_ATTACHMENTS);
  const attachments = [];
  let totalBytes = 0;
  for (const raw of rawAttachments) {
    let buf;
    try { buf = Buffer.from(String((raw && raw.data) || ''), 'base64'); } catch { buf = Buffer.alloc(0); }
    if (buf.length === 0) {
      return jsonResponse(res, 400, { ok: false, error: 'unsupported-format', message: msg('unsupported-format') });
    }
    if (buf.length > FEEDBACK_MAX_ATTACHMENT_BYTES) {
      return jsonResponse(res, 413, { ok: false, error: 'too-large', message: msg('too-large') });
    }
    totalBytes += buf.length;
    if (totalBytes > FEEDBACK_MAX_TOTAL_BYTES) {
      return jsonResponse(res, 413, { ok: false, error: 'too-large', message: msg('too-large') });
    }
    const ext = _feedbackImageExt(buf);
    if (!ext) {
      return jsonResponse(res, 400, { ok: false, error: 'unsupported-format', message: msg('unsupported-format') });
    }
    attachments.push({ buf, ext });
  }

  if (IS_TEST_MODE) return jsonResponse(res, 200, { ok: false, error: 'test-mode', message: msg('test-mode') });
  if (!APP_UPDATE_TOKEN) return jsonResponse(res, 200, { ok: false, error: 'no-token', message: msg('no-token') });

  // Server-resolved context: nothing past this point is read from the
  // request. Same identity path as GET /api/whoami.
  await _gitlabIdentity();
  const me = _localIdentity();
  const nowMs = Date.now();
  const { type, title, description } = validated.value;
  const steps = typeof body.steps === 'string' ? body.steps.slice(0, 4000) : '';
  const expected = typeof body.expected === 'string' ? body.expected.slice(0, 4000) : '';
  const slug = lib.feedbackSlug(title);
  const dirName = lib.feedbackDirName(nowMs, type, slug);
  const branch = lib.feedbackBranchName(nowMs, type, slug);
  const commitMessage = lib.feedbackCommitMessage(type, slug);
  const mrTitle = lib.feedbackMrTitle(type, title);
  const attachmentNames = attachments.map((a, i) => 'attachments/' + String(i + 1).padStart(2, '0') + '-screenshot' + a.ext);
  // Same defense-in-depth shape as the attachment slice above:
  // formatConsoleErrors caps at its own FEEDBACK_MAX_CONSOLE_ENTRIES too, this
  // slice just bounds what ever reaches it.
  const rawConsoleEntries = Array.isArray(body.console_errors) ? body.console_errors.slice(0, FEEDBACK_MAX_CONSOLE_ENTRIES) : [];
  const consoleEntries = lib.formatConsoleErrors(rawConsoleEntries);
  const context = (body.context && typeof body.context === 'object') ? body.context : {};

  const markdown = lib.buildFeedbackMarkdown({
    id: dirName, type, title, status: 'new',
    reportedBy: {
      slug: (me && me.person_slug) || null,
      name: (me && me.display_name) || null,
      email: _feedbackAuthorEmail(),
    },
    reportedAt: new Date(nowMs).toISOString(),
    app_info: { version: readAppSemver(), commit: _feedbackHeadSha(), platform: process.platform },
    context: {
      view: typeof context.view === 'string' ? context.view.slice(0, 200) : '',
      url: typeof context.url === 'string' ? context.url.slice(0, 500) : '',
      viewport: typeof context.viewport === 'string' ? context.viewport.slice(0, 40) : '',
      screen: typeof context.screen === 'string' ? context.screen.slice(0, 40) : '',
      userAgent: typeof context.user_agent === 'string' ? context.user_agent.slice(0, 300) : '',
      language: typeof context.language === 'string' ? context.language.slice(0, 20) : '',
    },
    description, steps, expected,
    attachments: attachmentNames,
    consoleErrors: consoleEntries,
  });

  const projectPath = _gitlabPathFromRemote(_appRepoUrl());
  if (!projectPath) return jsonResponse(res, 200, { ok: false, error: 'no-repo-url', message: msg('no-repo-url') });
  const projectApi = `${_gitlabApiBase()}/projects/${encodeURIComponent(projectPath)}`;

  const branchRes = await _appRepoPostJson(
    `${projectApi}/repository/branches?branch=${encodeURIComponent(branch)}&ref=main`, {});
  if (!branchRes.ok) {
    // Three shapes of failure, not two: status 0 is _appRepoPostJson's own
    // marker for "the fetch itself threw" (no VPN, DNS, timeout) and stays
    // 'unreachable'. 401/403 is the single most likely real-world failure -
    // a token minted before the scopes were widened, or a Reporter role -
    // same reasoning as handleModulesPublish's identical branch above.
    // Anything else is GitLab ANSWERING and refusing (400 branch-exists, 404
    // project, 429, 5xx): that is neither a network problem nor a
    // permissions problem, so it gets its own code with the numeric status
    // named in the message rather than being folded into "check your VPN".
    if (branchRes.status === 0) {
      return jsonResponse(res, 200, { ok: false, error: 'unreachable', message: msg('unreachable') });
    }
    if (branchRes.status === 401 || branchRes.status === 403) {
      return jsonResponse(res, 200, { ok: false, error: 'forbidden', message: msg('forbidden') });
    }
    return jsonResponse(res, 200, { ok: false, error: 'gitlab-error', message: msg('gitlab-error') + ' (HTTP ' + branchRes.status + ')' });
  }

  const actions = [
    { action: 'create', file_path: 'feedback/' + dirName + '/report.md', content: markdown, encoding: 'text' },
    ...attachments.map((a, i) => ({
      action: 'create',
      file_path: 'feedback/' + dirName + '/' + attachmentNames[i],
      content: a.buf.toString('base64'),
      encoding: 'base64',
    })),
  ];
  const commitRes = await _appRepoPostJson(`${projectApi}/repository/commits`, {
    branch, commit_message: commitMessage, actions,
  });
  if (!commitRes.ok) {
    // Same three-way split as the branch-create failure above.
    if (commitRes.status === 0) {
      return jsonResponse(res, 200, { ok: false, error: 'unreachable', message: msg('unreachable') });
    }
    if (commitRes.status === 401 || commitRes.status === 403) {
      return jsonResponse(res, 200, { ok: false, error: 'forbidden', message: msg('forbidden') });
    }
    return jsonResponse(res, 200, { ok: false, error: 'gitlab-error', message: msg('gitlab-error') + ' (HTTP ' + commitRes.status + ')' });
  }

  // Human-visible in GitLab's MR list; a
  // maintainer reads this line before opening the file, so it carries what
  // decides the triage: type, who, which view, how many screenshots, where.
  const typeLabel = { bug: 'bug', idea: 'idea', question: 'question' }[type] || type;
  const viewLabel = (typeof context.view === 'string' && context.view.trim()) ? context.view.trim().slice(0, 200) : 'unknown';
  const mrDescription = [
    'Feedback from the Mission Deck app.',
    '',
    '- Type: ' + typeLabel,
    '- Reported by: ' + ((me && me.display_name) || 'unknown person'),
    '- View: `' + viewLabel + '`',
    '- Screenshots: ' + attachments.length,
    '- Directory: `feedback/' + dirName + '/`',
  ].join('\n');

  const mrRes = await _appRepoPostJson(`${projectApi}/merge_requests`, {
    source_branch: branch,
    target_branch: 'main',
    title: mrTitle,
    description: mrDescription,
    // What the top bar's feedback chip counts - see FEEDBACK_MR_LABEL.
    labels: FEEDBACK_MR_LABEL,
    remove_source_branch: true,
  });
  if (!mrRes.ok) {
    // The commit already landed on the branch - say so instead of implying
    // the whole submission was lost, same as handleModulesPublish's
    // 'mr-failed' branch.
    return jsonResponse(res, 200, { ok: false, error: 'mr-failed', branch, message: msg('mr-failed') });
  }

  return jsonResponse(res, 200, {
    ok: true,
    mrUrl: (mrRes.json && mrRes.json.web_url) || null,
    mrIid: (mrRes.json && mrRes.json.iid) || null,
    branch,
    dir: 'feedback/' + dirName + '/',
  });
}

// ── Dashboard endpoints ────────────────────────────────────────────────────

const DASHBOARD_LAYOUT_FILE = process.env.DASHBOARD_LAYOUT_FILE || path.join(ROOT, 'data', 'dashboard-layout.json');

/** Reads the layout file, defaulting to an empty layout when missing or corrupt. */
function _readDashboardLayout() {
  try {
    const parsed = JSON.parse(fs.readFileSync(DASHBOARD_LAYOUT_FILE, 'utf8'));
    return parsed && typeof parsed === 'object' ? parsed : { version: 1, items: [] };
  } catch {
    return { version: 1, items: [] };
  }
}

/** tmp+rename write of the layout file - never a bare fs.writeFileSync on the final path. */
function _writeDashboardLayout(layout) {
  fs.mkdirSync(path.dirname(DASHBOARD_LAYOUT_FILE), { recursive: true });
  const tmp = DASHBOARD_LAYOUT_FILE + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(layout, null, 2));
  fs.renameSync(tmp, DASHBOARD_LAYOUT_FILE);
}

/**
 * Pure. Merge a submitted layout with the stored one: an item whose module is
 * not loaded right now (disabled, uninstalled, failed to boot) is invisible in
 * the browser, so the person could not have meant to remove it. It is kept at
 * its old position, so re-enabling the module brings the tile back where it was.
 * Items of loaded modules come only from the submission.
 * When the total would exceed DASHBOARD_LAYOUT_MAX, the preserved items of unloaded modules are the ones dropped.
 */
function mergeDashboardLayoutItems(submitted, stored, available) {
  const loaded = new Set((available || []).map((a) => a.module));
  const out = submitted.slice();
  const keys = new Set(out.map((it) => it.module + '/' + it.widget));
  const prev = Array.isArray(stored) ? stored : [];
  prev.forEach((it, i) => {
    if (!it || typeof it.module !== 'string' || typeof it.widget !== 'string' || typeof it.variant !== 'string') return;
    if (loaded.has(it.module)) return;
    const key = it.module + '/' + it.widget;
    if (keys.has(key) || out.length >= DASHBOARD_LAYOUT_MAX) return;
    keys.add(key);
    out.splice(Math.min(i, out.length), 0, { module: it.module, widget: it.widget, variant: it.variant });
  });
  return out;
}

/** Widget catalog from the BOOT snapshot: what the browser can really mount. */
function _dashboardAvailable() {
  return _loadedModules.modules.map((m) => moduleWidgets(m.manifest));
}

/**
 * GET /api/dashboard/layout
 * Read-only: a stored item whose module is gone or disabled is filtered from the
 * answer but NOT removed from the file, so re-enabling the module restores it.
 */
function handleDashboardLayoutGet(_req, res) {
  const available = _dashboardAvailable();
  const layout = normalizeDashboardLayout(_readDashboardLayout(), available);
  jsonResponse(res, 200, { hasModules: available.length > 0, layout, available });
}

/**
 * PUT /api/dashboard/layout   body: { items: [{ module, widget, variant }] }
 * Strict: the first invalid item answers 400 and nothing is written.
 */
async function handleDashboardLayoutPut(req, res) {
  if (!checkOrigin(req, res)) return;
  let body;
  try { body = await readBody(req, 64 * 1024); }
  catch (e) {
    return jsonResponse(res, 400, { error: 'invalid-layout', message: 'Invalid request data.', detail: String((e && e.message) || e) });
  }
  const bad = (message, index) => jsonResponse(res, 400, { error: 'invalid-layout', message, index });
  if (!body || typeof body !== 'object' || !Array.isArray(body.items)) {
    return bad('The "items" field must be an array.', null);
  }
  if (body.items.length > DASHBOARD_LAYOUT_MAX) {
    return bad('The dashboard may have at most ' + DASHBOARD_LAYOUT_MAX + ' tiles.', null);
  }
  const available = _dashboardAvailable();
  const seen = new Set();
  const items = [];
  for (let i = 0; i < body.items.length; i++) {
    const it = body.items[i];
    if (!it || typeof it !== 'object' || typeof it.module !== 'string'
      || typeof it.widget !== 'string' || typeof it.variant !== 'string') {
      return bad('The tile has an invalid shape.', i);
    }
    const mod = available.find((a) => a.module === it.module);
    if (!mod) return bad('Unknown tool: ' + it.module, i);
    const w = mod.widgets.find((x) => x.id === it.widget);
    if (!w) return bad('Unknown tile: ' + it.widget, i);
    if (!w.variants.some((v) => v.id === it.variant)) return bad('Unknown tile size: ' + it.variant, i);
    const key = it.module + '/' + it.widget;
    if (seen.has(key)) return bad('The tile appears more than once: ' + key, i);
    seen.add(key);
    items.push({ module: it.module, widget: it.widget, variant: it.variant });
  }
  let layout;
  await withDashboardLayoutLock(() => {
    const stored = _readDashboardLayout();
    const merged = mergeDashboardLayoutItems(items, stored && stored.items, available);
    layout = { version: 1, items: merged, updatedAt: new Date().toISOString() };
    _writeDashboardLayout(layout);
  });
  // The browser only ever sees the mountable part, same as GET.
  return jsonResponse(res, 200, { ok: true, layout: { ...layout, items } });
}

// -- Sample mode --------------------------------------------------------------
// GET  /api/sample-mode          -> { active, since, available, restartRequired }
// POST /api/sample-mode/enter    -> copies examples/sample-team/ds-data into
//                                   data/sample-team/ds-data, installs the catalog
//                                   modules that are not installed yet, writes the
//                                   marker LAST. Takes effect after a restart.
// POST /api/sample-mode/leave    -> removes the marker and the copy. Same restart.
// While the mode is active every data-tier-0 sync operation answers 409
// `sample-mode` (_sampleModeRefusesSync, called by the router before any
// dispatch): nothing reaches git or a remote. `status` and `check-update` stay
// open - they only read. The boot half (marker, paths) is near DATA_TIER_0_DIR.
// Detail: docs/architecture/sample-mode.md.

const withSampleModeLock = _makeChainLock();

/** True when the request is a data-tier-0 sync operation that must not run in sample mode. */
function _sampleModeRefusesSync(method, urlPath) {
  if (!SAMPLE_MODE_ACTIVE) return false;
  let op = null;
  const legacy = /^\/api\/data-tier-0\/([^/]+)$/.exec(urlPath);
  if (legacy) {
    op = legacy[1];
  } else {
    const parsed = _parseDataRepoPath(urlPath);
    if (parsed && parsed.repoId === 'data-tier-0') op = parsed.op;
  }
  if (op !== null && op !== 'status' && op !== 'check-update') return true;
  // Publishing a prototype pushes to a remote with the deploy token.
  return method === 'GET' && urlPath === '/api/prototypes/deploy-stream';
}

function _sampleModeRefusal(res) {
  jsonResponse(res, 409, {
    error: 'sample-mode',
    message: 'Sample data is on - nothing is synced. Leave sample mode to sync your real team data.',
  });
}

/**
 * The catalog modules of the LOCAL catalog folder as [{ id, area }] (null for a
 * hosted catalog). The area is the curated one of catalog.json: a manifest that
 * names none is installed under it, exactly as the Modules tab does.
 */
function _sampleModeCatalogModules() {
  if (!_modulesCatalogIsLocal()) return null;
  const root = modulesCatalogDir();
  const dir = path.join(root, 'modules');
  let names;
  try { names = fs.readdirSync(dir); } catch { return []; }
  let curated = [];
  try {
    const parsed = JSON.parse(fs.readFileSync(path.join(root, 'catalog.json'), 'utf8'));
    curated = Array.isArray(parsed && parsed.modules) ? parsed.modules : [];
  } catch { /* an uncurated folder is still a catalog */ }
  return names
    .filter((n) => MODULE_ID_RE.test(n) && fs.existsSync(path.join(dir, n, 'module.json')))
    .sort()
    .map((id) => {
      const entry = curated.find((c) => c && c.id === id);
      return { id, area: entry && typeof entry.area === 'string' ? entry.area : undefined };
    });
}

/** In the test suites the mode may only touch a throwaway folder (SAMPLE_DATA_DIR). */
function _sampleModeWritesAllowed(res) {
  if (IS_TEST_MODE && !process.env.SAMPLE_DATA_DIR) {
    jsonResponse(res, 409, { error: 'test-mode', message: 'Sample mode is not changed in test mode.' });
    return false;
  }
  return true;
}

function handleSampleModeStatus(_req, res) {
  const markerNow = _sampleModeReadMarker();
  // What the NEXT boot will do: marker present, no explicit data dir, copy there.
  const willBeActive = Boolean(markerNow && !SAMPLE_MODE_ENV_BLOCKED && fs.existsSync(SAMPLE_COPY_DS));
  jsonResponse(res, 200, {
    active: SAMPLE_MODE_ACTIVE,
    since: SAMPLE_MODE_SINCE,
    available: fs.existsSync(SAMPLE_SOURCE_DS),
    restartRequired: willBeActive !== SAMPLE_MODE_ACTIVE,
    blockedByEnv: SAMPLE_MODE_ENV_BLOCKED,
  });
}

async function handleSampleModeEnter(req, res) {
  if (!checkOrigin(req, res)) return;
  if (!_sampleModeWritesAllowed(res)) return;
  if (SAMPLE_MODE_ENV_BLOCKED) {
    return jsonResponse(res, 409, {
      error: 'explicit-data-dir',
      message: 'A data folder (DATA_TIER_0_DIR, DATA_SUB_REPOS_DIR or DATA_TIER_0_GIT_DIR) is set for this app, so it always uses that. Remove it to try the sample data.',
    });
  }
  if (SAMPLE_MODE_ACTIVE) {
    return jsonResponse(res, 409, { error: 'already-active', message: 'Sample mode is already on.' });
  }
  return withSampleModeLock(async () => {
    if (!fs.existsSync(SAMPLE_SOURCE_DS)) {
      return jsonResponse(res, 500, { error: 'sample-missing', message: 'The sample data is missing from this copy of Mission Deck (examples/sample-team).' });
    }
    // Copy beside the target, then swap: a failed copy never leaves a half
    // tree where a boot would look for the copy.
    const stage = SAMPLE_COPY_ROOT + '.tmp-' + process.pid;
    try {
      fs.rmSync(stage, { recursive: true, force: true });
      fs.mkdirSync(stage, { recursive: true });
      fs.cpSync(SAMPLE_SOURCE_DS, path.join(stage, 'ds-data'), { recursive: true });
      fs.rmSync(SAMPLE_COPY_ROOT, { recursive: true, force: true });
      fs.renameSync(stage, SAMPLE_COPY_ROOT);
    } catch (e) {
      try { fs.rmSync(stage, { recursive: true, force: true }); } catch { /* best effort */ }
      return jsonResponse(res, 500, { error: 'copy-failed', message: 'Could not copy the sample data: ' + e.message });
    }

    // Every catalog module the sample data has something to show for. A module
    // that cannot be installed is reported, it never stops the mode.
    const installed = [];
    const failed = [];
    const catalogModules = _sampleModeCatalogModules();
    if (catalogModules) {
      for (const { id, area } of catalogModules) {
        if (fs.existsSync(path.join(MODULES_DIR, id))) continue;
        try {
          const r = await fetch('http://127.0.0.1:' + PORT + '/api/modules/install', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(area ? { id, area } : { id }),
            signal: AbortSignal.timeout(60000),
          });
          const body = await r.json().catch(() => ({}));
          if (r.ok && body && body.ok !== false) installed.push(id);
          else failed.push({ id, error: (body && body.error) || ('http-' + r.status) });
        } catch (e) {
          failed.push({ id, error: e.name === 'TimeoutError' ? 'timeout' : 'request-failed' });
        }
      }
    }

    const since = new Date().toISOString();
    try {
      fs.mkdirSync(path.dirname(SAMPLE_MODE_FILE), { recursive: true });
      const tmp = SAMPLE_MODE_FILE + '.tmp-' + process.pid;
      fs.writeFileSync(tmp, JSON.stringify({ active: true, since }, null, 2) + '\n', 'utf8');
      fs.renameSync(tmp, SAMPLE_MODE_FILE);
    } catch (e) {
      return jsonResponse(res, 500, { error: 'marker-failed', message: 'Could not save the sample mode state: ' + e.message });
    }
    return jsonResponse(res, 200, {
      status: 'entered', since, restartRequired: true, installed, failed, catalog: catalogModules ? 'local' : 'hosted',
    });
  });
}

async function handleSampleModeLeave(req, res) {
  if (!checkOrigin(req, res)) return;
  if (!_sampleModeWritesAllowed(res)) return;
  return withSampleModeLock(async () => {
    try {
      fs.rmSync(SAMPLE_MODE_FILE, { force: true });
      // Only ever the folder this mode created, never a path built from input.
      if (path.basename(SAMPLE_COPY_ROOT) === 'sample-team') fs.rmSync(SAMPLE_COPY_ROOT, { recursive: true, force: true });
    } catch (e) {
      return jsonResponse(res, 500, { error: 'leave-failed', message: 'Could not leave sample mode: ' + e.message });
    }
    return jsonResponse(res, 200, { status: 'left', restartRequired: true });
  });
}

